insert into public.languages (id, code, name, native_name, writing_direction, tts_locale, is_available) values ('ar', 'ar', 'Arabe', 'العربية', 'rtl', 'ar-SA', true) on conflict (id) do update set name = excluded.name, native_name = excluded.native_name, writing_direction = excluded.writing_direction, tts_locale = excluded.tts_locale, is_available = excluded.is_available;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g01.letters1', 'ar', 'grammar', 'reading', 'Alif, bâ, tâ, thâ : ا ب ت ث', 1, '{}'::text[], 1, '{"rule": {"summary": "ا ب ت ث : un bâton et trois barques qui ne diffèrent que par leurs points.", "explanation": "L''arabe se lit de droite à gauche et compte 28 lettres. ا est un bâton sans point (le a long). ب, ت et ث ont le même corps de barque : ب a 1 point dessous (le b de bateau), ت a 2 points dessus (le t de table), ث a 3 points dessus (un t, parfois un s en Égypte).", "pattern": "ا = bâton ; ب = 1 point dessous ; ت = 2 points dessus ; ث = 3 points dessus", "examples": [{"text": "ا", "translation": "alif : le a long, un bâton sans point"}, {"text": "ب", "translation": "bâ : le b de bateau, 1 point dessous"}, {"text": "ت", "translation": "tâ : le t de table, 2 points dessus"}, {"text": "ث", "translation": "thâ : un t (parfois un s) en Égypte, 3 points dessus"}], "commonErrors": [{"wrong": "Lire ت quand il y a 1 point dessous", "right": "ب", "why": "Le point d''en bas fait la barque ب ; ت porte 2 points dessus."}, {"wrong": "Lire ث comme ت", "right": "ث", "why": "Compte les points : 3 points dessus font ث, 2 points dessus font ت."}, {"wrong": "Chercher un point sur ا", "right": "ا", "why": "ا est un bâton nu : aucun point."}], "tip": "Compte les points, puis regarde où ils sont : dessous ou dessus."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g02.letters2', 'ar', 'grammar', 'reading', 'Nûn, yâ et le jeu des points : ن ي', 1, array['ar.g01.letters1']::text[], 1, '{"rule": {"summary": "ن et ي complètent la famille des points : tout dépend de leur nombre et de leur place.", "explanation": "ن est un bol creux avec 1 point dessus (le n de nuit). ي plonge sous la ligne avec 2 points dessous (le y de yaourt ou un i long). Avec ب ت ث, tu as cinq lettres à points : ب 1 dessous, ت 2 dessus, ث 3 dessus, ن 1 dessus, ي 2 dessous.", "pattern": "ب 1 dessous ; ت 2 dessus ; ث 3 dessus ; ن 1 dessus ; ي 2 dessous", "examples": [{"text": "ن", "translation": "nûn : le n de nuit, 1 point dessus"}, {"text": "ي", "translation": "yâ : le y de yaourt, 2 points dessous"}, {"text": "ب", "translation": "bâ : 1 point dessous"}, {"text": "ت", "translation": "tâ : 2 points dessus"}], "commonErrors": [{"wrong": "Confondre ب et ن", "right": "ب = barque plate, point dessous ; ن = bol creux, point dessus", "why": "Le point est dessous pour ب et dessus pour ن."}, {"wrong": "Confondre ت et ي", "right": "ت = 2 points dessus ; ي = 2 points dessous", "why": "Même nombre de points, mais pas la même place."}, {"wrong": "Oublier la queue de ي", "right": "ي plonge sous la ligne", "why": "Aucune autre lettre à points ne descend ainsi."}], "tip": "Pose deux questions : combien de points ? dessus ou dessous ?"}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g03.letters3', 'ar', 'grammar', 'reading', 'Les trois crochets : ج ح خ', 1, array['ar.g02.letters2']::text[], 1, '{"rule": {"summary": "ج ح خ : le même crochet, et un point qui change le son.", "explanation": "ج, ح et خ ont la même forme de crochet. ج a 1 point dans le creux (dessous) et se dit g en Égypte, comme dans gâteau. ح n''a pas de point : c''est un h appuyé du fond de la gorge. خ a 1 point dessus : c''est le ch allemand de Bach.", "pattern": "ج = point dessous = g ; ح = pas de point = h appuyé ; خ = point dessus = ch de Bach", "examples": [{"text": "ج", "translation": "gîm : le g de gâteau, 1 point dessous"}, {"text": "ح", "translation": "ḥâ : un h appuyé, aucun point"}, {"text": "خ", "translation": "khâ : le ch allemand de Bach, 1 point dessus"}], "commonErrors": [{"wrong": "Lire ج comme dans l''arabe littéraire (dj)", "right": "En Égypte, ج se dit g", "why": "Au Caire, on dit g comme dans gâteau."}, {"wrong": "Confondre ح et ه", "right": "ح est un crochet appuyé ; ه est un petit nœud léger", "why": "Les deux sont des h, mais pas les mêmes."}, {"wrong": "Placer le point de خ dessous", "right": "خ a son point dessus", "why": "Dessous, c''est ج."}], "tip": "Dessous = ج, rien = ح, dessus = خ."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g04.letters4', 'ar', 'grammar', 'reading', 'Les petites jumelles : د ذ ر ز', 1, array['ar.g03.letters3']::text[], 1, '{"rule": {"summary": "د ذ ر ز : deux paires de jumelles, chacune distinguée par un seul point.", "explanation": "د (le d de dent) et ر (un r roulé) n''ont pas de point. En ajoutant 1 point dessus, on obtient ذ (un d, parfois un z en Égypte) et ز (le z de zèbre). د reste posée sur la ligne ; ر descend sous la ligne comme une virgule.", "pattern": "د → ذ et ر → ز : on ajoute 1 point dessus", "examples": [{"text": "د", "translation": "dâl : le d de dent, aucun point"}, {"text": "ذ", "translation": "dhâl : un d, parfois un z, 1 point dessus"}, {"text": "ر", "translation": "râ : un r roulé, aucun point"}, {"text": "ز", "translation": "zây : le z de zèbre, 1 point dessus"}], "commonErrors": [{"wrong": "Confondre د et ر", "right": "د reste sur la ligne ; ر descend", "why": "La virgule ر plonge sous la ligne."}, {"wrong": "Lire ذ comme le th anglais en Égypte", "right": "ذ se dit d, parfois z", "why": "L''arabe égyptien n''a pas le th de this."}, {"wrong": "Oublier le point de ز", "right": "ز = ر + 1 point dessus", "why": "Sans le point, c''est ر."}], "tip": "Un point dessus transforme ر en ز et د en ذ."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g05.letters5', 'ar', 'grammar', 'reading', 'Les dents et les boucles : س ش ص ض', 2, array['ar.g04.letters4']::text[], 1, '{"rule": {"summary": "س ش ص ض : les dents, leurs trois points, et leurs jumelles lourdes.", "explanation": "س (trois dents) se dit s comme dans soleil ; avec 3 points dessus, c''est ش (ch de chat). ص (une boucle fermée) est un s lourd ; avec 1 point dessus, c''est ض, un d lourd. Les lettres lourdes se disent plus profondément dans la gorge.", "pattern": "س → ش (+3 points) ; ص → ض (+1 point)", "examples": [{"text": "س", "translation": "sîn : le s de soleil, trois dents"}, {"text": "ش", "translation": "chîn : le ch de chat, 3 points dessus"}, {"text": "ص", "translation": "sâd : un s lourd, une boucle"}, {"text": "ض", "translation": "dâd : un d lourd, 1 point dessus"}], "commonErrors": [{"wrong": "Confondre س et ص", "right": "س a des dents ; ص a une boucle", "why": "Les dents sont légères, la boucle est lourde."}, {"wrong": "Confondre ش et ث", "right": "ش a trois dents ; ث est une barque", "why": "Les deux ont 3 points dessus mais pas le même corps."}, {"wrong": "Confondre ض et د", "right": "ض a une boucle ; د est un petit dos", "why": "ض est lourde, د est légère."}], "tip": "Dents = légère, boucle = lourde."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g06.letters6', 'ar', 'grammar', 'reading', 'Les lourdes et les gorges : ط ظ ع غ', 2, array['ar.g05.letters5']::text[], 1, '{"rule": {"summary": "ط ظ ع غ : la fin des lourdes, puis les deux lettres de gorge.", "explanation": "ط (une boucle avec un mât) est un t lourd ; avec 1 point dessus, ظ est un z lourd. ع (un petit 3 couché sur une queue) est un son de gorge serrée sans équivalent français ; avec 1 point dessus, غ se dit comme le r de rouge.", "pattern": "ط → ظ et ع → غ : on ajoute 1 point dessus", "examples": [{"text": "ط", "translation": "ṭâ : un t lourd, boucle et mât"}, {"text": "ظ", "translation": "ẓâ : un z lourd, 1 point dessus"}, {"text": "ع", "translation": "aïn : un son de gorge serrée"}, {"text": "غ", "translation": "ghaïn : le r de rouge, 1 point dessus"}], "commonErrors": [{"wrong": "Confondre ط et ص", "right": "ط a un mât ; ص n''en a pas", "why": "Le mât distingue la famille ط."}, {"wrong": "Lire ع comme un a ordinaire", "right": "ع est un son de gorge serrée", "why": "Elle serre la gorge, ce que ا ne fait pas."}, {"wrong": "Confondre غ et ر", "right": "غ est un r du fond de la gorge ; ر est roulé", "why": "Deux r différents."}], "tip": "ع est un œil, غ est l''œil avec une larme."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g07.letters7', 'ar', 'grammar', 'reading', 'Les têtes rondes et les bâtons : ف ق ك ل', 2, array['ar.g06.letters6']::text[], 1, '{"rule": {"summary": "ف ق ك ل : deux têtes rondes, un trait à zigzag et un bâton à pied.", "explanation": "ف (1 point dessus) se dit f comme dans feu ; ق (2 points dessus, queue profonde) est un coup de gorge au Caire. ك (un grand trait avec un zigzag) se dit k comme dans kilo. ل (un bâton à pied courbe) se dit l comme dans lune.", "pattern": "ف = 1 point dessus ; ق = 2 points dessus ; ك = zigzag ; ل = bâton à pied", "examples": [{"text": "ف", "translation": "fâ : le f de feu, 1 point dessus"}, {"text": "ق", "translation": "qâf : un coup de gorge au Caire, 2 points dessus"}, {"text": "ك", "translation": "kâf : le k de kilo, un zigzag"}, {"text": "ل", "translation": "lâm : le l de lune, un bâton à pied"}], "commonErrors": [{"wrong": "Confondre ف et ق", "right": "ف a 1 point, ق en a 2", "why": "Compte les points et regarde la queue."}, {"wrong": "Lire ق comme un k", "right": "Au Caire, ق est un coup de gorge", "why": "Le vrai k de l''arabe égyptien, c''est ك."}, {"wrong": "Confondre ل et ا", "right": "ل a un pied qui tourne", "why": "ا est un bâton nu."}], "tip": "Une tête ronde : 1 point = ف, 2 points = ق."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g08.letters8', 'ar', 'grammar', 'reading', 'Dernières lettres et grand bilan : م ه و ء ة ى', 2, array['ar.g07.letters7']::text[], 1, '{"rule": {"summary": "م ه و, puis ء ة ى : les dernières lettres et le bilan des 28.", "explanation": "م (une cerise à queue droite) se dit m comme dans mer ; ه (un petit nœud) est un h soufflé ; و (un petit 9) donne le ou de oui. ء est un coup de gorge ; ة est un ه coiffé de 2 points dessus, à la fin des mots féminins ; ى est un ي sans ses deux points, à la fin d''un mot.", "pattern": "م = cerise ; ه = nœud ; و = petit 9 ; ء = coup de gorge ; ة = ه + 2 points ; ى = ي sans points", "examples": [{"text": "م", "translation": "mîm : le m de mer, aucun point"}, {"text": "ه", "translation": "hâ : un h soufflé, aucun point"}, {"text": "و", "translation": "wâw : le ou de oui, aucun point"}, {"text": "ة", "translation": "tâ marbûta : ه avec 2 points dessus"}], "commonErrors": [{"wrong": "Confondre م et و", "right": "م a une queue droite ; و a une queue courbe", "why": "Regarde la queue."}, {"wrong": "Lire ة comme ه", "right": "ة a 2 points dessus", "why": "Les deux points ajoutent le ت."}, {"wrong": "Chercher 2 points sous ى", "right": "ى n''a aucun point", "why": "Avec 2 points dessous, c''est ي."}], "tip": "Sur les 28 lettres, 13 n''ont aucun point et 15 en ont ; seules ب, ج et ي ont leurs points dessous."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g09.forms_ba_family', 'ar', 'grammar', 'reading', 'Les formes d''une lettre dans le mot : ب ت ث ن ي', 1, array['ar.g08.letters8']::text[], 2, '{"rule": {"summary": "Dans un mot, une lettre change de forme selon sa place : isolée, début, milieu ou fin. Au milieu, ب ت ث ن ي sont la même dent : seuls les points les distinguent.", "explanation": "Dans un mot, les lettres s''attachent de droite à gauche. Une lettre attachée à la suivante prend la forme du début, attachée des deux côtés la forme du milieu, attachée à la précédente la forme de la fin ; seule, elle garde la forme isolée. Le tatweel ـ montre l''attache. ب ت ث ن ي ont la même dent, seuls les points changent : ب 1 dessous, ت 2 dessus, ث 3 dessus, ن 1 dessus, ي 2 dessous.", "pattern": "بـ (début)  ـبـ (milieu)  ـب (fin)  ب (isolée)", "examples": [{"text": "بيت", "translation": "maison : ب + ي + ت, trois lettres attachées"}, {"text": "بنت", "translation": "fille : même squelette, ـنـ au milieu"}, {"text": "تين", "translation": "figues : ت + ي + ن"}, {"text": "نبي", "translation": "prophète : ن + ب + ي"}], "commonErrors": [{"wrong": "بنت lu comme بيت", "right": "بنت = fille ; بيت = maison", "why": "ـنـ a un point dessus, ـيـ en a deux dessous."}, {"wrong": "ـب pris pour la forme du début", "right": "بـ est la forme du début", "why": "Le trait ـ est du côté de la lettre voisine : à gauche pour le début, à droite pour la fin."}, {"wrong": "ث lu avec deux points", "right": "ث a trois points dessus", "why": "Deux points dessus, c''est ت ; trois points dessus, c''est ث."}], "tip": "Devant une dent, compte les points avant de lire le mot."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g10.letters_that_do_not_connect', 'ar', 'grammar', 'reading', 'Les six lettres qui ne s''attachent pas : ا د ذ ر ز و', 2, array['ar.g09.forms_ba_family']::text[], 2, '{"rule": {"summary": "ا د ذ ر ز و ne s''attachent pas à la lettre suivante : elles coupent le mot en blocs, et la lettre suivante repart à neuf.", "explanation": "Un bloc est une suite de lettres attachées. Les six lettres ا د ذ ر ز و s''attachent à la lettre d''avant mais jamais à celle d''après : elles n''ont que la forme isolée et la forme de la fin. Après elles, le mot se coupe et la lettre suivante prend la forme du début (ou isolée). On lit plus vite bloc par bloc.", "pattern": "ا د ذ ر ز و : fin de bloc. Exemple : باب = با | ب", "examples": [{"text": "باب", "translation": "porte : با | ب, 2 blocs"}, {"text": "ورد", "translation": "fleurs : و | ر | د, 3 blocs"}, {"text": "زيت", "translation": "huile : ز | يت, 2 blocs"}, {"text": "أبونا", "translation": "notre père (le prêtre) : أ | بو | نا, 3 blocs"}], "commonErrors": [{"wrong": "باب lu en un seul bloc", "right": "با | ب : deux blocs", "why": "Le ا ne s''attache jamais à la lettre d''après."}, {"wrong": "ـبـ pour le deuxième ب de بابا", "right": "بـ (forme du début)", "why": "Après le ا, le ب repart à neuf et s''accroche au ا suivant : forme du début."}, {"wrong": "د pris pour ذ", "right": "ذ a un point dessus", "why": "Un point au-dessus du crochet, c''est ذ ; sans point, c''est د."}], "tip": "Cherche ا د ذ ر ز و : après chacune, un nouveau bloc commence."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g11.forms_jim_family', 'ar', 'grammar', 'reading', 'Les formes d''une lettre dans le mot : ج ح خ', 2, array['ar.g10.letters_that_do_not_connect']::text[], 2, '{"rule": {"summary": "ج ح خ ont la même tête et le même crochet : seul le point change (dessous, aucun, dessus). Au début et au milieu c''est une tête, à la fin le crochet revient.", "explanation": "ج, ح et خ se ressemblent comme ب ت ث : même corps, points différents. ج a un point dessous, ح n''en a pas, خ en a un dessus. Au début et au milieu d''un mot, la lettre est une petite tête (جـ ـجـ) ; à la fin, elle retrouve son crochet (ـج). Le point ne bouge jamais.", "pattern": "جـ ـجـ ـج ج  |  حـ ـحـ ـح ح  |  خـ ـخـ ـخ خ", "examples": [{"text": "حبيبي", "translation": "mon chéri : ح + ب + ي + ب + ي, 1 bloc"}, {"text": "خوخ", "translation": "pêches : خو | خ, 2 blocs"}, {"text": "جيب", "translation": "poche : ج + ي + ب, 1 bloc"}, {"text": "بخور", "translation": "encens : بخو | ر, 2 blocs"}], "commonErrors": [{"wrong": "خد lu comme حد", "right": "خد = prends ; حد = quelqu''un", "why": "خ a un point dessus ; ح n''en a aucun."}, {"wrong": "ج lu comme خ", "right": "ج : point dessous", "why": "Le point de ج est dessous, dans le creux ; celui de خ est dessus."}, {"wrong": "le deuxième خ de خوخ écrit avec un trait", "right": "خ isolé", "why": "Après un و, la lettre repart à neuf ; en fin de mot et seule, elle est isolée."}], "tip": "Devant une tête, cherche d''abord le point : dessous, rien, ou dessus."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g12.forms_sin_family', 'ar', 'grammar', 'reading', 'Les formes d''une lettre dans le mot : س ش ص ض', 2, array['ar.g11.forms_jim_family']::text[], 2, '{"rule": {"summary": "س ش ont trois dents, ص ض une boucle ; ش et ض sont س et ص avec des points. Les points ne bougent pas quand la forme change.", "explanation": "س et ش partagent trois dents (ش a 3 points dessus). ص et ض partagent une boucle (ض a 1 point dessus). Au début et au milieu, les dents se serrent et la boucle reste ; à la fin, la queue revient. Comme pour ب ت ث ن ي, le point fait la lettre : on le regarde avant de lire le mot.", "pattern": "سـ ـسـ ـس  |  شـ ـشـ ـش  |  صـ ـصـ ـص  |  ضـ ـضـ ـض", "examples": [{"text": "شاي", "translation": "thé : شا | ي"}, {"text": "صباح", "translation": "matin : صبا | ح"}, {"text": "أبيض", "translation": "blanc : أ | بيض"}, {"text": "جرس", "translation": "cloche : جر | س"}], "commonErrors": [{"wrong": "شاي lu ساي", "right": "ش a 3 points dessus", "why": "Sans ses 3 points, la lettre est س, et ساي n''existe pas."}, {"wrong": "ض lu ص", "right": "ض : boucle + 1 point dessus", "why": "ص n''a aucun point : le point de ض est ce qui les sépare."}, {"wrong": "ـضـ pour le ض de حاضر", "right": "ضـ (forme du début)", "why": "Le ا qui précède ne s''attache pas : le ض repart à neuf."}], "tip": "Dents ou boucle ? Puis compte les points : la lettre est là."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g13.forms_ayn_family', 'ar', 'grammar', 'reading', 'Les formes d''une lettre dans le mot : ط ظ ع غ', 3, array['ar.g12.forms_sin_family']::text[], 2, '{"rule": {"summary": "ط ظ ont une boucle et un mât, ع غ une œil ; ظ et غ sont ط et ع avec 1 point dessus. Le point fait la lettre.", "explanation": "ط et ظ partagent la boucle et le mât ; ع et غ partagent la œil. Dans chaque paire, le point dessus distingue la lettre (ظ, غ). Au début et au milieu on voit la boucle-mât ou la petite tête ; à la fin le crochet revient. Quand une lettre suit un و ou un ا, elle repart à neuf, comme le ع de يسوع qui est isolé.", "pattern": "طـ ـطـ ـط  |  ظـ ـظـ ـظ  |  عـ ـعـ ـع  |  غـ ـغـ ـغ", "examples": [{"text": "عيش", "translation": "pain : ع + ي + ش, 1 bloc"}, {"text": "جعان", "translation": "affamé : جعا | ن"}, {"text": "يسوع", "translation": "Jésus : يسو | ع, ع isolé"}, {"text": "حظ", "translation": "chance : ح + ظ, ظ à la fin"}], "commonErrors": [{"wrong": "غني lu comme عني", "right": "غ a un point dessus", "why": "Le point dessus fait la différence entre ع et غ."}, {"wrong": "طير lu comme طيب", "right": "طير finit par ر", "why": "ب a un point dessous ; ر n''en a aucun et descend sous la ligne."}, {"wrong": "ع de يسوع écrit avec un trait", "right": "ع isolé", "why": "Le و ne s''attache pas à la suivante : le ع repart à neuf, et seul il est isolé."}], "tip": "Cherche d''abord le mât ou la tête, puis le point dessus."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g14.forms_fa_lam', 'ar', 'grammar', 'reading', 'Les formes d''une lettre dans le mot : ف ق ك ل', 3, array['ar.g13.forms_ayn_family']::text[], 2, '{"rule": {"summary": "ف ق sont des têtes rondes (1 et 2 points dessus), ك ل sont des bâtons. ل s''attache à la suivante, contrairement à ا qui coupe le mot.", "explanation": "ف et ق ont la même tête ronde : ف avec 1 point dessus, ق avec 2 points dessus. ك et ل sont des bâtons : ك est un trait penché avec un petit zigzag, ل est un bâton avec un pied courbé. Au début et au milieu, on voit la boule ou le bâton ; à la fin, le pied revient. ل s''attache à la lettre suivante, alors que ا ne s''attache jamais : le bâton ل ne coupe pas le mot.", "pattern": "فـ ـفـ ـف  |  قـ ـقـ ـق  |  كـ ـكـ ـك  |  لـ ـلـ ـل", "examples": [{"text": "صليب", "translation": "croix : ص + ل + ي + ب, 1 bloc"}, {"text": "قداس", "translation": "liturgie : قد | ا | س, 3 blocs"}, {"text": "كرسي", "translation": "chaise : كر | سي, 2 blocs"}, {"text": "فول", "translation": "fèves : فو | ل, 2 blocs"}], "commonErrors": [{"wrong": "قلب lu فلب", "right": "ق a 2 points dessus", "why": "ف n''a qu''un seul point dessus."}, {"wrong": "ل pris pour ا dans صليب", "right": "ل s''attache : صليب = 1 bloc", "why": "ا coupe le mot, ل non : le ل est attaché des deux côtés."}, {"wrong": "ك pris pour ل", "right": "ك a un petit zigzag", "why": "ل est un bâton sans zigzag ; ك porte un petit zigzag dans l''angle."}], "tip": "Boule : compte les points (1 ou 2). Bâton : lisse, ou un trait avec un zigzag ?"}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g15.forms_mim_ha', 'ar', 'grammar', 'reading', 'Les formes d''une lettre dans le mot : م ه و ة', 3, array['ar.g14.forms_fa_lam']::text[], 2, '{"rule": {"summary": "م est une boucle fermée, ه une lettre aux quatre visages très différents, و ne s''attache pas, et ة n''existe qu''à la fin d''un mot (ـة attachée ou ة isolée).", "explanation": "م garde sa boucle au début et au milieu, sa queue revient à la fin. ه change complètement de dessin selon sa place : ه هـ ـهـ ـه. و fait partie des lettres qui ne s''attachent pas. ة, un ه avec 2 points dessus, ne s''écrit qu''en fin de mot : ـة si la lettre d''avant s''attache (كنيسة), ة isolée si elle ne s''attache pas (قهوة).", "pattern": "مـ ـمـ ـم  |  هـ ـهـ ـه  |  ـو  |  ـة ة", "examples": [{"text": "مية", "translation": "eau : م + ي + ة, 1 bloc"}, {"text": "قهوة", "translation": "café : قهو | ة, ة isolé"}, {"text": "كنيسة", "translation": "église : 1 bloc, ـة attaché"}, {"text": "ترابيزة", "translation": "table : تر | ا | بيز | ة, 4 blocs"}], "commonErrors": [{"wrong": "ة finale écrite ه", "right": "ة a 2 points dessus", "why": "Sans ses 2 points, la lettre serait un ه."}, {"wrong": "ـة attachée après و dans قهوة", "right": "ة isolée", "why": "Le و ne s''attache pas à la suivante : le ة reste seul."}, {"wrong": "م confondu avec ن", "right": "م n''a aucun point", "why": "ن a un point dessus et une forme de bol ; م est une boucle fermée sans point."}], "tip": "ة = ه + 2 points, toujours à la fin du mot."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('ar.g16.article_and_ligature', 'ar', 'grammar', 'reading', 'L''article ال, la ligature لا et le bilan de lecture', 3, array['ar.g15.forms_mim_ha']::text[], 2, '{"rule": {"summary": "ال devant un nom veut dire le / la et ajoute un bloc au début ; ل suivi de ا s''écrit avec la ligature لا, qui ferme le bloc comme un ا.", "explanation": "L''article ال (ا puis ل) se place devant le nom : الكنيسة, البيت. Le ا ne s''attache pas, donc ال forme un bloc à lui seul et le ل s''accroche au nom (forme du début). Quand ل est suivi de ا, les deux se fondent en un seul signe, la ligature لا, qui ferme le bloc. Pour lire un mot : repère ال, coupe en blocs, lis chaque bloc lettre par lettre, assemble.", "pattern": "ال + nom = le / la + nom   |   ل + ا = لا", "examples": [{"text": "الكنيسة", "translation": "l''église : ا | لكنيسة, 2 blocs"}, {"text": "المسيح", "translation": "le Christ : ا | لمسيح"}, {"text": "صلاة", "translation": "prière : صلا | ة, avec la ligature لا"}, {"text": "العدرا", "translation": "la Vierge Marie : ا | لعد | ر | ا, 4 blocs"}], "commonErrors": [{"wrong": "لكنيسة pour « l''église »", "right": "الكنيسة", "why": "L''article commence par le ا : ال = ا puis ل."}, {"wrong": "ل et ا écrits côte à côte dans صلاة", "right": "la ligature لا", "why": "ل suivi de ا se fond en un seul signe."}, {"wrong": "ال lu comme une partie du nom", "right": "ال = le / la", "why": "ال est un mot-outil : cache-le, lis le nom, puis ajoute « le / la »."}], "tip": "Cache ال avec le doigt, lis le nom, puis ajoute « le / la »."}, "functionWords": []}'::jsonb, '3.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
