insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l01', 'ar', 1, 'Le bâton et la barque', 'Découvre ا ب ت ث : le bâton, la barque et ses points.', 1, 1, 'ar.g01.letters1', array['ar.g01.letters1','ar.v.alif','ar.v.ba','ar.v.ta','ar.v.tha']::text[], '{}'::text[], '3.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l02', 'ar', 1, 'Le bol, la queue et les points', 'Ajoute ن et ي, puis maîtrise le jeu des points dessus et dessous.', 1, 2, 'ar.g02.letters2', array['ar.g02.letters2','ar.v.nun','ar.v.ya']::text[], array['ar.g01.letters1']::text[], '3.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l03', 'ar', 1, 'Trois crochets, trois sons', 'Reconnais ج ح خ : le même crochet, trois sons, un point qui change tout.', 1, 3, 'ar.g03.letters3', array['ar.g03.letters3','ar.v.jim','ar.v.ha','ar.v.kha']::text[], array['ar.g01.letters1','ar.g02.letters2']::text[], '3.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l04', 'ar', 1, 'Les jumelles d, z, r', 'Découvre د ذ ر ز : deux paires de jumelles qui ne diffèrent que d''un point.', 1, 4, 'ar.g04.letters4', array['ar.g04.letters4','ar.v.dal','ar.v.dhal','ar.v.ra','ar.v.zay']::text[], array['ar.g02.letters2','ar.g03.letters3']::text[], '3.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l05', 'ar', 1, 'Dents, boucles et lourdeur', 'Apprends س ش ص ض : les dents, les trois points et les lettres lourdes.', 2, 5, 'ar.g05.letters5', array['ar.g05.letters5','ar.v.sin','ar.v.shin','ar.v.sad','ar.v.dad']::text[], array['ar.g03.letters3','ar.g04.letters4']::text[], '3.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l06', 'ar', 1, 'Lourdes et gorges profondes', 'Termine les lourdes avec ط ظ, puis plonge dans la gorge avec ع et غ.', 2, 6, 'ar.g06.letters6', array['ar.g06.letters6','ar.v.tah','ar.v.zah','ar.v.ayn','ar.v.ghayn']::text[], array['ar.g04.letters4','ar.g05.letters5']::text[], '3.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l07', 'ar', 1, 'Têtes rondes et bâtons', 'Distingue ف ق par leurs points, puis ك et ل, le K et le L de l''arabe.', 2, 7, 'ar.g07.letters7', array['ar.g07.letters7','ar.v.fa','ar.v.qaf','ar.v.kaf','ar.v.lam']::text[], array['ar.g05.letters5','ar.g06.letters6']::text[], '3.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l08', 'ar', 1, 'Les dernières lettres et le grand bilan', 'Apprends م ه و ء ة ى, puis fais le bilan des 28 lettres et de leurs points.', 2, 8, 'ar.g08.letters8', array['ar.g08.letters8','ar.v.mim','ar.v.heh','ar.v.waw','ar.v.hamza','ar.v.ta_marbuta','ar.v.alif_maqsura']::text[], array['ar.g06.letters6','ar.g07.letters7']::text[], '3.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l09', 'ar', 2, 'Une lettre, quatre visages', 'Début, milieu, fin : comment ب ت ث ن ي changent de forme dans un mot, et comment les points les distinguent.', 1, 9, 'ar.g09.forms_ba_family', array['ar.g09.forms_ba_family','ar.v.bayt','ar.v.bint','ar.v.tin','ar.v.nabi','ar.v.bunn','ar.v.bayna','ar.v.tinnin']::text[], array['ar.v.ba','ar.v.ta','ar.v.tha','ar.v.nun','ar.v.ya','ar.v.alif']::text[], '3.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l10', 'ar', 2, 'Les lettres qui lâchent la main', 'ا د ذ ر ز و ne s''attachent pas à la lettre suivante : elles coupent le mot en blocs. Tu apprends à compter les blocs et à lire bloc par bloc.', 2, 10, 'ar.g10.letters_that_do_not_connect', array['ar.g10.letters_that_do_not_connect','ar.v.bab','ar.v.baba','ar.v.ruzz','ar.v.zayt','ar.v.ward','ar.v.dayr','ar.v.abouna','ar.v.nabawat','ar.v.dhanb','ar.v.rabbina']::text[], array['ar.v.alif','ar.v.dal','ar.v.dhal','ar.v.ra','ar.v.zay','ar.v.waw','ar.g09.forms_ba_family']::text[], '3.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l11', 'ar', 2, 'Le crochet : ج ح خ', 'ج ح خ ont la même tête et le même crochet : seul le point change. Tu les lis au début, au milieu et à la fin des mots.', 2, 11, 'ar.g11.forms_jim_family', array['ar.g11.forms_jim_family','ar.v.habibi','ar.v.khabar','ar.v.jazar','ar.v.khawkh','ar.v.bakhur','ar.v.jayb','ar.v.jiddu','ar.v.khud','ar.v.hadd']::text[], array['ar.v.jim','ar.v.ha','ar.v.kha','ar.g10.letters_that_do_not_connect']::text[], '3.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l12', 'ar', 2, 'Les dents et les boucles : س ش ص ض', 'س ش ont trois dents, ص ض une boucle : seuls les points les séparent. Tu les lis dans des mots du quotidien et de l''église.', 2, 12, 'ar.g12.forms_sin_family', array['ar.g12.forms_sin_family','ar.v.shay','ar.v.sabah','ar.v.abyad','ar.v.hadir','ar.v.nuss','ar.v.sabt','ar.v.jaras','ar.v.sayyad','ar.v.sirr','ar.v.ahsan']::text[], array['ar.v.sin','ar.v.shin','ar.v.sad','ar.v.dad','ar.g11.forms_jim_family']::text[], '3.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l13', 'ar', 2, 'Les lourdes et les gorges : ط ظ ع غ', 'ط ظ (boucle et mât) et ع غ (œil) dans les mots : عيش, عيد, يسوع… Un point dessus fait la différence.', 3, 13, 'ar.g13.forms_ayn_family', array['ar.g13.forms_ayn_family','ar.v.eish','ar.v.ayiz','ar.v.eid','ar.v.jaan','ar.v.ghada','ar.v.ghani','ar.v.tayyib','ar.v.tayr','ar.v.hazz','ar.v.yasou']::text[], array['ar.v.tah','ar.v.zah','ar.v.ayn','ar.v.ghayn','ar.g12.forms_sin_family']::text[], '3.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l14', 'ar', 2, 'Têtes rondes et bâtons : ف ق ك ل', 'ف ق ك ل dans les mots : sucre, lait, chaise, mais aussi قداس, صليب et إنجيل. Tu apprends à ne pas confondre le bâton ل avec le ا qui coupe le mot.', 3, 14, 'ar.g14.forms_fa_lam', array['ar.g14.forms_fa_lam','ar.v.sukkar','ar.v.laban','ar.v.kursi','ar.v.foul','ar.v.kitab','ar.v.qalb','ar.v.quddas','ar.v.qurban','ar.v.salib','ar.v.injil']::text[], array['ar.v.fa','ar.v.qaf','ar.v.kaf','ar.v.lam','ar.g13.forms_ayn_family']::text[], '3.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l15', 'ar', 2, 'Boule, caméléon et ة finale : م ه و ة', 'م ه و ة dans les mots de tous les jours (مية, قهوة, عربية) et d''église (كنيسة, شماس, مزمور) : ة n''apparaît qu''à la fin.', 3, 15, 'ar.g15.forms_mim_ha', array['ar.g15.forms_mim_ha','ar.v.mayya','ar.v.qahwa','ar.v.arabiyya','ar.v.tarabeza','ar.v.oda','ar.v.bukra','ar.v.mish','ar.v.kanisa','ar.v.shammas','ar.v.mazmur']::text[], array['ar.v.mim','ar.v.heh','ar.v.waw','ar.v.ta_marbuta','ar.g14.forms_fa_lam']::text[], '3.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.lessons (id, language_id, module, title, description, difficulty, sequence_order, grammar_unit_id, introduces, reviews, content_version, deprecated) values ('ar.l16', 'ar', 2, 'ال, لا et ta méthode de lecture', 'ال devant un nom, la ligature لا dans صلاة et سلام, puis un grand bilan : tu lis des mots entiers, bloc par bloc.', 3, 16, 'ar.g16.article_and_ligature', array['ar.g16.article_and_ligature','ar.v.la','ar.v.salat','ar.v.kalam','ar.v.salam','ar.v.balash','ar.v.talata','ar.v.malak','ar.v.masih','ar.v.adra','ar.v.amin']::text[], array['ar.v.alif','ar.v.lam','ar.g15.forms_mim_ha']::text[], '3.0.0', false) on conflict (id) do update set module = excluded.module, title = excluded.title, description = excluded.description, difficulty = excluded.difficulty, sequence_order = excluded.sequence_order, grammar_unit_id = excluded.grammar_unit_id, introduces = excluded.introduces, reviews = excluded.reviews, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e01', 'ar', 'ar.l01', 'ar.g01.letters1', array['ar.g01.letters1','ar.v.alif']::text[], 'mcq', 'lesson', 'Quelle lettre est un simple bâton droit, sans aucun point ?', array['ا']::text[], 'ا (alif) est le poteau de l''alphabet : un trait droit et nu. Les trois autres sont des barques à points.', 1, '{"id": "ar.l01.e01", "unitIds": ["ar.g01.letters1", "ar.v.alif"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre est un simple bâton droit, sans aucun point ?", "promptLanguage": "fr", "options": ["ا", "ب", "ت", "ث"], "answer": "ا", "acceptedAnswers": ["ا"], "explanation": "ا (alif) est le poteau de l''alphabet : un trait droit et nu. Les trois autres sont des barques à points.", "tip": "Un poteau droit, sans point : c''est alif.", "extraExample": {"text": "ا", "translation": "alif : le a long de pâte, aucun point."}, "errorPatterns": [{"equals": "ب", "category": "word_confusion", "feedback": "ب est une barque avec 1 point dessous, pas un bâton."}], "pool": "lesson", "lessonId": "ar.l01", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e02', 'ar', 'ar.l01', 'ar.g01.letters1', array['ar.g01.letters1','ar.v.ba']::text[], 'mcq', 'lesson', 'Quelle lettre fait le son b, comme dans bateau ?', array['ب']::text[], 'ب se lit comme le b de bateau, et sa forme est justement une barque avec son ancre (1 point dessous).', 1, '{"id": "ar.l01.e02", "unitIds": ["ar.g01.letters1", "ar.v.ba"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre fait le son b, comme dans bateau ?", "promptLanguage": "fr", "options": ["ب", "ث", "ا", "ت"], "answer": "ب", "acceptedAnswers": ["ب"], "explanation": "ب se lit comme le b de bateau, et sa forme est justement une barque avec son ancre (1 point dessous).", "tip": "Une barque, et son ancre en dessous.", "extraExample": {"text": "ب", "translation": "bâ : le b de bateau, 1 point dessous."}, "errorPatterns": [{"equals": "ت", "category": "word_confusion", "feedback": "ت est la barque aux deux mouettes (2 points dessus) : elle fait t."}], "pool": "lesson", "lessonId": "ar.l01", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e03', 'ar', 'ar.l01', 'ar.g01.letters1', array['ar.g01.letters1','ar.v.ta']::text[], 'mcq', 'lesson', 'Quelle lettre fait le son t, comme dans table ?', array['ت']::text[], 'ت se lit comme le t de table. Retiens ses 2 points dessus, deux mouettes sur la barque.', 1, '{"id": "ar.l01.e03", "unitIds": ["ar.g01.letters1", "ar.v.ta"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre fait le son t, comme dans table ?", "promptLanguage": "fr", "options": ["ت", "ب", "ا"], "answer": "ت", "acceptedAnswers": ["ت"], "explanation": "ت se lit comme le t de table. Retiens ses 2 points dessus, deux mouettes sur la barque.", "tip": "Deux mouettes sur la barque.", "extraExample": {"text": "ت", "translation": "tâ : le t de table, 2 points dessus."}, "errorPatterns": [{"equals": "ب", "category": "word_confusion", "feedback": "ب fait b, comme bateau : son point est dessous."}], "pool": "lesson", "lessonId": "ar.l01", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e04', 'ar', 'ar.l01', 'ar.g01.letters1', array['ar.g01.letters1','ar.v.tha']::text[], 'mcq', 'lesson', 'Combien de points a la lettre ث ?', array['3']::text[], 'ث porte 3 points dessus, trois mouettes en triangle sur la barque.', 1, '{"id": "ar.l01.e04", "unitIds": ["ar.g01.letters1", "ar.v.tha"], "type": "mcq", "difficulty": 1, "instruction": "Choisis le bon nombre.", "prompt": "Combien de points a la lettre ث ?", "promptLanguage": "fr", "options": ["2", "1", "3"], "answer": "3", "acceptedAnswers": ["3"], "explanation": "ث porte 3 points dessus, trois mouettes en triangle sur la barque.", "tip": "Trois mouettes en triangle sur la barque.", "extraExample": {"text": "ث", "translation": "thâ : un t, parfois un s, 3 points dessus."}, "errorPatterns": [{"equals": "2", "category": "word_confusion", "feedback": "2 points dessus, c''est ت. ث en a un de plus : 3."}], "pool": "lesson", "lessonId": "ar.l01", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e05', 'ar', 'ar.l01', 'ar.g01.letters1', array['ar.g01.letters1','ar.v.alif','ar.v.ba','ar.v.ta','ar.v.tha']::text[], 'match', 'lesson', 'Relie chaque lettre de ا ب ت ث à son nom.', '{}'::text[], 'Les quatre premières lettres s''appellent alif, bâ, tâ, thâ : le nom commence par le son de la lettre (b pour bâ, t pour tâ).', 1, '{"id": "ar.l01.e05", "unitIds": ["ar.g01.letters1", "ar.v.alif", "ar.v.ba", "ar.v.ta", "ar.v.tha"], "type": "match", "difficulty": 1, "instruction": "Relie chaque élément à son associé.", "prompt": "Relie chaque lettre de ا ب ت ث à son nom.", "promptLanguage": "fr", "pairs": [{"left": "ا", "right": "alif"}, {"left": "ب", "right": "bâ"}, {"left": "ت", "right": "tâ"}, {"left": "ث", "right": "thâ"}], "acceptedAnswers": [], "explanation": "Les quatre premières lettres s''appellent alif, bâ, tâ, thâ : le nom commence par le son de la lettre (b pour bâ, t pour tâ).", "pool": "lesson", "lessonId": "ar.l01", "skill": "recognition", "answer": "ا = alif ; ب = bâ ; ت = tâ ; ث = thâ"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e06', 'ar', 'ar.l01', 'ar.g01.letters1', array['ar.g01.letters1','ar.v.ba']::text[], 'mcq', 'lesson', 'Quelle lettre a 1 point dessous ?', array['ب']::text[], 'Seul ب a son point en dessous, comme une ancre. ت et ث ont leurs points dessus.', 2, '{"id": "ar.l01.e06", "unitIds": ["ar.g01.letters1", "ar.v.ba"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre a 1 point dessous ?", "promptLanguage": "fr", "options": ["ت", "ب", "ث", "ا"], "answer": "ب", "acceptedAnswers": ["ب"], "explanation": "Seul ب a son point en dessous, comme une ancre. ت et ث ont leurs points dessus.", "tip": "Une barque, et son ancre en dessous.", "extraExample": {"text": "ب", "translation": "bâ : le b de bateau, 1 point dessous."}, "errorPatterns": [{"equals": "ت", "category": "word_confusion", "feedback": "ت a 2 points, et ils sont dessus."}], "pool": "lesson", "lessonId": "ar.l01", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e07', 'ar', 'ar.l01', 'ar.g01.letters1', array['ar.g01.letters1','ar.v.ta']::text[], 'mcq', 'lesson', 'Quelle lettre a 2 points dessus ?', array['ت']::text[], 'ت a 2 points dessus, comme deux mouettes. ث en a 3, et ب en a un seul, dessous.', 2, '{"id": "ar.l01.e07", "unitIds": ["ar.g01.letters1", "ar.v.ta"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre a 2 points dessus ?", "promptLanguage": "fr", "options": ["ث", "ب", "ا", "ت"], "answer": "ت", "acceptedAnswers": ["ت"], "explanation": "ت a 2 points dessus, comme deux mouettes. ث en a 3, et ب en a un seul, dessous.", "tip": "Deux mouettes sur la barque.", "extraExample": {"text": "ت", "translation": "tâ : le t de table, 2 points dessus."}, "errorPatterns": [{"equals": "ث", "category": "word_confusion", "feedback": "ث en a 3 : compte bien, il y en a un de trop."}], "pool": "lesson", "lessonId": "ar.l01", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e08', 'ar', 'ar.l01', 'ar.g01.letters1', array['ar.g01.letters1','ar.v.ta']::text[], 'fill_blank', 'lesson', 'ت a ___ points dessus, comme deux mouettes sur la barque.', array['2']::text[], 'ت a 2 points dessus. Avec 1 point dessous c''est ب, avec 3 points dessus c''est ث.', 2, '{"id": "ar.l01.e08", "unitIds": ["ar.g01.letters1", "ar.v.ta"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le bon nombre.", "prompt": "ت a ___ points dessus, comme deux mouettes sur la barque.", "promptLanguage": "fr", "options": ["2", "3", "1"], "answer": "2", "acceptedAnswers": ["2"], "explanation": "ت a 2 points dessus. Avec 1 point dessous c''est ب, avec 3 points dessus c''est ث.", "tip": "Deux mouettes sur la barque.", "extraExample": {"text": "ت", "translation": "tâ : le t de table, 2 points dessus."}, "pool": "lesson", "lessonId": "ar.l01", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e09', 'ar', 'ar.l01', 'ar.g01.letters1', array['ar.g01.letters1','ar.v.alif','ar.v.ba','ar.v.ta','ar.v.tha']::text[], 'mcq', 'lesson', 'Trois de ces lettres sont des barques. Laquelle est l''intruse ?', array['ا']::text[], 'ب, ت et ث partagent le même corps de barque. ا est un bâton droit sans point : c''est l''intruse.', 2, '{"id": "ar.l01.e09", "unitIds": ["ar.g01.letters1", "ar.v.alif", "ar.v.ba", "ar.v.ta", "ar.v.tha"], "type": "mcq", "difficulty": 2, "instruction": "Trouve l''intruse.", "prompt": "Trois de ces lettres sont des barques. Laquelle est l''intruse ?", "promptLanguage": "fr", "options": ["ث", "ت", "ب", "ا"], "answer": "ا", "acceptedAnswers": ["ا"], "explanation": "ب, ت et ث partagent le même corps de barque. ا est un bâton droit sans point : c''est l''intruse.", "tip": "Un poteau droit, sans point : c''est alif.", "extraExample": {"text": "ا", "translation": "alif : le a long de pâte, aucun point."}, "pool": "lesson", "lessonId": "ar.l01", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e10', 'ar', 'ar.l01', 'ar.g01.letters1', array['ar.g01.letters1','ar.v.alif','ar.v.ba','ar.v.ta','ar.v.tha']::text[], 'match', 'lesson', 'Relie chaque lettre de ا ب ت ث à ses points.', '{}'::text[], 'Les points sont la carte d''identité de la barque : 1 dessous pour ب, 2 dessus pour ت, 3 dessus pour ث. ا n''en a aucun.', 2, '{"id": "ar.l01.e10", "unitIds": ["ar.g01.letters1", "ar.v.alif", "ar.v.ba", "ar.v.ta", "ar.v.tha"], "type": "match", "difficulty": 2, "instruction": "Relie chaque élément à son associé.", "prompt": "Relie chaque lettre de ا ب ت ث à ses points.", "promptLanguage": "fr", "pairs": [{"left": "ا", "right": "aucun point"}, {"left": "ب", "right": "1 point dessous"}, {"left": "ت", "right": "2 points dessus"}, {"left": "ث", "right": "3 points dessus"}], "acceptedAnswers": [], "explanation": "Les points sont la carte d''identité de la barque : 1 dessous pour ب, 2 dessus pour ت, 3 dessus pour ث. ا n''en a aucun.", "pool": "lesson", "lessonId": "ar.l01", "skill": "recognition", "answer": "ا = aucun point ; ب = 1 point dessous ; ت = 2 points dessus ; ث = 3 points dessus"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e11', 'ar', 'ar.l01', 'ar.g01.letters1', array['ar.g01.letters1','ar.v.tha']::text[], 'mcq', 'lesson', 'Quel est le nom de la lettre ث ?', array['thâ']::text[], 'ث s''appelle thâ. Son nom ressemble à celui de ت (tâ) comme son dessin ressemble au sien.', 2, '{"id": "ar.l01.e11", "unitIds": ["ar.g01.letters1", "ar.v.tha"], "type": "mcq", "difficulty": 2, "instruction": "Choisis le bon nom.", "prompt": "Quel est le nom de la lettre ث ?", "promptLanguage": "fr", "options": ["thâ", "bâ", "alif", "tâ"], "answer": "thâ", "acceptedAnswers": ["thâ"], "explanation": "ث s''appelle thâ. Son nom ressemble à celui de ت (tâ) comme son dessin ressemble au sien.", "tip": "Trois mouettes en triangle sur la barque.", "extraExample": {"text": "ث", "translation": "thâ : un t, parfois un s, 3 points dessus."}, "errorPatterns": [{"equals": "tâ", "category": "word_confusion", "feedback": "tâ est le nom de ت (2 points). ث, avec 3 points, s''appelle thâ."}], "pool": "lesson", "lessonId": "ar.l01", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e12', 'ar', 'ar.l01', 'ar.g01.letters1', array['ar.g01.letters1','ar.v.ta']::text[], 'fill_blank', 'lesson', 'ا ب ___ ث', array['ت']::text[], 'L''alphabet suit un ordre fixe : ا, ب, ت, ث. La lettre qui manque entre ب et ث est ت.', 2, '{"id": "ar.l01.e12", "unitIds": ["ar.g01.letters1", "ar.v.ta"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète l''ordre de l''alphabet.", "prompt": "ا ب ___ ث", "promptLanguage": "ar", "options": ["ت", "ا", "ث"], "answer": "ت", "acceptedAnswers": ["ت"], "hint": "Dans l''ordre : le bâton, puis trois barques.", "explanation": "L''alphabet suit un ordre fixe : ا, ب, ت, ث. La lettre qui manque entre ب et ث est ت.", "tip": "Deux mouettes sur la barque.", "extraExample": {"text": "ت", "translation": "tâ : le t de table, 2 points dessus."}, "pool": "lesson", "lessonId": "ar.l01", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e13', 'ar', 'ar.l01', 'ar.g01.letters1', array['ar.g01.letters1','ar.v.ba']::text[], 'fill_blank', 'lesson', 'Le point de ب est ___ la barque.', array['dessous']::text[], 'Le point de ب est dessous, comme l''ancre d''un bateau. C''est ce qui la distingue de ت et ث.', 2, '{"id": "ar.l01.e13", "unitIds": ["ar.g01.letters1", "ar.v.ba"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le bon mot.", "prompt": "Le point de ب est ___ la barque.", "promptLanguage": "fr", "options": ["dessous", "dessus", "dedans"], "answer": "dessous", "acceptedAnswers": ["dessous"], "explanation": "Le point de ب est dessous, comme l''ancre d''un bateau. C''est ce qui la distingue de ت et ث.", "tip": "Une barque, et son ancre en dessous.", "extraExample": {"text": "ب", "translation": "bâ : le b de bateau, 1 point dessous."}, "errorPatterns": [{"equals": "dessus", "category": "word_confusion", "feedback": "Dessus, ce sont les mouettes de ت et ث. L''ancre de ب est en dessous."}], "pool": "lesson", "lessonId": "ar.l01", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e14', 'ar', 'ar.l01', 'ar.g01.letters1', array['ar.g01.letters1','ar.v.tha']::text[], 'mcq', 'lesson', 'En Égypte, comment dit-on le plus souvent la lettre ث ?', array['un t, parfois un s']::text[], 'En arabe littéraire, ث est le th de think, mais en Égypte on la dit comme un t, parfois un s.', 3, '{"id": "ar.l01.e14", "unitIds": ["ar.g01.letters1", "ar.v.tha"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "En Égypte, comment dit-on le plus souvent la lettre ث ?", "promptLanguage": "fr", "options": ["le b de bateau", "le n de nuit", "un t, parfois un s", "le a long de pâte"], "answer": "un t, parfois un s", "acceptedAnswers": ["un t, parfois un s"], "explanation": "En arabe littéraire, ث est le th de think, mais en Égypte on la dit comme un t, parfois un s.", "tip": "ث sonne comme ت en Égypte : seuls les points les séparent à l''écrit.", "extraExample": {"text": "ث", "translation": "thâ : un t, parfois un s, 3 points dessus."}, "pool": "lesson", "lessonId": "ar.l01", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e15', 'ar', 'ar.l01', 'ar.g01.letters1', array['ar.g01.letters1','ar.v.ba']::text[], 'mcq', 'lesson', 'Qui suis-je ? « Je suis une barque. Mon ancre pend en dessous. »', array['ب']::text[], 'L''ancre en dessous est le point unique de ب : le b de bateau.', 3, '{"id": "ar.l01.e15", "unitIds": ["ar.g01.letters1", "ar.v.ba"], "type": "mcq", "difficulty": 3, "instruction": "Devine la lettre.", "prompt": "Qui suis-je ? « Je suis une barque. Mon ancre pend en dessous. »", "promptLanguage": "fr", "options": ["ت", "ا", "ب", "ث"], "answer": "ب", "acceptedAnswers": ["ب"], "explanation": "L''ancre en dessous est le point unique de ب : le b de bateau.", "tip": "Une barque, et son ancre en dessous.", "extraExample": {"text": "ب", "translation": "bâ : le b de bateau, 1 point dessous."}, "pool": "lesson", "lessonId": "ar.l01", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e16', 'ar', 'ar.l01', 'ar.g01.letters1', array['ar.g01.letters1','ar.v.tha','ar.v.ta']::text[], 'mcq', 'lesson', 'Quelle lettre vient juste après ت dans l''alphabet ?', array['ث']::text[], 'L''ordre est ا, ب, ت, ث : ث suit ت.', 3, '{"id": "ar.l01.e16", "unitIds": ["ar.g01.letters1", "ar.v.tha", "ar.v.ta"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre vient juste après ت dans l''alphabet ?", "promptLanguage": "fr", "options": ["ث", "ا", "ب"], "answer": "ث", "acceptedAnswers": ["ث"], "explanation": "L''ordre est ا, ب, ت, ث : ث suit ت.", "tip": "Trois mouettes en triangle sur la barque.", "extraExample": {"text": "ث", "translation": "thâ : un t, parfois un s, 3 points dessus."}, "pool": "lesson", "lessonId": "ar.l01", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l01.e17', 'ar', 'ar.l01', 'ar.g01.letters1', array['ar.g01.letters1','ar.v.ta']::text[], 'free_answer', 'lesson', 'Combien de points a la lettre ت ? Réponds avec un chiffre.', array['2','deux']::text[], 'ت a 2 points dessus, comme deux mouettes sur la barque.', 2, '{"id": "ar.l01.e17", "unitIds": ["ar.g01.letters1", "ar.v.ta"], "type": "free_answer", "difficulty": 2, "instruction": "Écris le nombre.", "prompt": "Combien de points a la lettre ت ? Réponds avec un chiffre.", "promptLanguage": "fr", "answer": "2", "acceptedAnswers": ["2", "deux"], "explanation": "ت a 2 points dessus, comme deux mouettes sur la barque.", "tip": "Deux mouettes sur la barque.", "extraExample": {"text": "ت", "translation": "tâ : le t de table, 2 points dessus."}, "pool": "lesson", "lessonId": "ar.l01", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
