insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e05', 'ar', 'ar.l02', 'ar.g02.letters2', array['ar.g02.letters2','ar.v.nun']::text[], 'mcq', 'lesson', 'Quelle lettre est un bol creux avec 1 point dessus ?', array['ن']::text[], 'ن est le bol à cerise : creux, avec son point dessus. ب est une barque plate dont le point est dessous.', 2, '{"id": "ar.l02.e05", "unitIds": ["ar.g02.letters2", "ar.v.nun"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre est un bol creux avec 1 point dessus ?", "promptLanguage": "fr", "options": ["ب", "ن", "ث", "ت"], "answer": "ن", "acceptedAnswers": ["ن"], "explanation": "ن est le bol à cerise : creux, avec son point dessus. ب est une barque plate dont le point est dessous.", "tip": "Un bol avec une cerise dessus.", "extraExample": {"text": "ن", "translation": "nûn : le n de nuit, 1 point dessus."}, "errorPatterns": [{"equals": "ب", "category": "word_confusion", "feedback": "ب a son point dessous, et sa forme est plate."}], "pool": "lesson", "lessonId": "ar.l02", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e06', 'ar', 'ar.l02', 'ar.g02.letters2', array['ar.g02.letters2','ar.v.ya']::text[], 'mcq', 'lesson', 'Quelle lettre a 2 points dessous ?', array['ي']::text[], 'ي a 2 points dessous, au bout de sa queue. ت a aussi 2 points, mais dessus.', 2, '{"id": "ar.l02.e06", "unitIds": ["ar.g02.letters2", "ar.v.ya"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre a 2 points dessous ?", "promptLanguage": "fr", "options": ["ت", "ث", "ب", "ي"], "answer": "ي", "acceptedAnswers": ["ي"], "explanation": "ي a 2 points dessous, au bout de sa queue. ت a aussi 2 points, mais dessus.", "tip": "Une queue qui plonge, deux points dessous.", "extraExample": {"text": "ي", "translation": "yâ : le y de yaourt, 2 points dessous."}, "errorPatterns": [{"equals": "ت", "category": "word_confusion", "feedback": "ت a bien 2 points, mais dessus. Ici, il faut 2 points dessous."}], "pool": "lesson", "lessonId": "ar.l02", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e07', 'ar', 'ar.l02', 'ar.g02.letters2', array['ar.g02.letters2','ar.v.nun']::text[], 'fill_blank', 'lesson', 'La lettre ن a 1 point ___, comme une cerise sur un bol.', array['dessus']::text[], 'Le point de ن est dessus, alors que celui de ب est dessous : c''est la place qui les distingue.', 2, '{"id": "ar.l02.e07", "unitIds": ["ar.g02.letters2", "ar.v.nun"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le bon mot.", "prompt": "La lettre ن a 1 point ___, comme une cerise sur un bol.", "promptLanguage": "fr", "options": ["dessous", "dessus", "dedans"], "answer": "dessus", "acceptedAnswers": ["dessus"], "explanation": "Le point de ن est dessus, alors que celui de ب est dessous : c''est la place qui les distingue.", "tip": "Un bol avec une cerise dessus.", "extraExample": {"text": "ن", "translation": "nûn : le n de nuit, 1 point dessus."}, "errorPatterns": [{"equals": "dessous", "category": "word_confusion", "feedback": "Dessous, c''est ب. Pour ن, la cerise est posée dessus."}], "pool": "lesson", "lessonId": "ar.l02", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e08', 'ar', 'ar.l02', 'ar.v.alif', array['ar.v.alif','ar.g02.letters2']::text[], 'mcq', 'lesson', 'Quelle lettre ne porte aucun point ?', array['ا']::text[], 'ا est un bâton nu. ب, ن et ي portent chacune des points.', 2, '{"id": "ar.l02.e08", "unitIds": ["ar.v.alif", "ar.g02.letters2"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre ne porte aucun point ?", "promptLanguage": "fr", "options": ["ب", "ي", "ا", "ن"], "answer": "ا", "acceptedAnswers": ["ا"], "explanation": "ا est un bâton nu. ب, ن et ي portent chacune des points.", "tip": "Un poteau droit, sans point : c''est alif.", "extraExample": {"text": "ا", "translation": "alif : le a long de pâte, aucun point."}, "pool": "lesson", "lessonId": "ar.l02", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e09', 'ar', 'ar.l02', 'ar.g02.letters2', array['ar.g02.letters2','ar.v.ba','ar.v.nun','ar.v.ya','ar.v.ta']::text[], 'match', 'lesson', 'Relie ب, ن, ي et ت à leurs points.', '{}'::text[], 'Le nombre ET la place font la lettre : ب et ن n''ont qu''un point, ت et ي en ont deux, mais dessus ou dessous.', 2, '{"id": "ar.l02.e09", "unitIds": ["ar.g02.letters2", "ar.v.ba", "ar.v.nun", "ar.v.ya", "ar.v.ta"], "type": "match", "difficulty": 2, "instruction": "Relie chaque élément à son associé.", "prompt": "Relie ب, ن, ي et ت à leurs points.", "promptLanguage": "fr", "pairs": [{"left": "ب", "right": "1 point dessous"}, {"left": "ن", "right": "1 point dessus"}, {"left": "ي", "right": "2 points dessous"}, {"left": "ت", "right": "2 points dessus"}], "acceptedAnswers": [], "explanation": "Le nombre ET la place font la lettre : ب et ن n''ont qu''un point, ت et ي en ont deux, mais dessus ou dessous.", "pool": "lesson", "lessonId": "ar.l02", "skill": "recognition", "answer": "ب = 1 point dessous ; ن = 1 point dessus ; ي = 2 points dessous ; ت = 2 points dessus"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e10', 'ar', 'ar.l02', 'ar.g02.letters2', array['ar.g02.letters2','ar.v.ya','ar.v.ta','ar.v.tha','ar.v.nun']::text[], 'mcq', 'lesson', 'Trois de ces lettres ont leurs points dessus. Laquelle est l''intruse ?', array['ي']::text[], 'ت, ث et ن ont leurs points dessus. ي est l''intruse : ses 2 points sont dessous.', 2, '{"id": "ar.l02.e10", "unitIds": ["ar.g02.letters2", "ar.v.ya", "ar.v.ta", "ar.v.tha", "ar.v.nun"], "type": "mcq", "difficulty": 2, "instruction": "Trouve l''intruse.", "prompt": "Trois de ces lettres ont leurs points dessus. Laquelle est l''intruse ?", "promptLanguage": "fr", "options": ["ي", "ت", "ث", "ن"], "answer": "ي", "acceptedAnswers": ["ي"], "explanation": "ت, ث et ن ont leurs points dessus. ي est l''intruse : ses 2 points sont dessous.", "tip": "Une queue qui plonge, deux points dessous.", "extraExample": {"text": "ي", "translation": "yâ : le y de yaourt, 2 points dessous."}, "pool": "lesson", "lessonId": "ar.l02", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
