insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e14', 'ar', 'ar.l02', 'ar.v.tha', array['ar.v.tha','ar.g02.letters2']::text[], 'mcq', 'lesson', 'Quel son fait la lettre ث en Égypte ?', array['un t, parfois un s']::text[], 'En Égypte, ث se dit comme un t, parfois comme un s. Les 3 points dessus la distinguent de ت à l''écrit.', 3, '{"id": "ar.l02.e14", "unitIds": ["ar.v.tha", "ar.g02.letters2"], "type": "mcq", "difficulty": 3, "instruction": "Choisis le bon son.", "prompt": "Quel son fait la lettre ث en Égypte ?", "promptLanguage": "fr", "options": ["le y de yaourt", "un t, parfois un s", "le b de bateau", "le n de nuit"], "answer": "un t, parfois un s", "acceptedAnswers": ["un t, parfois un s"], "explanation": "En Égypte, ث se dit comme un t, parfois comme un s. Les 3 points dessus la distinguent de ت à l''écrit.", "tip": "Trois mouettes en triangle sur la barque.", "extraExample": {"text": "ث", "translation": "thâ : un t, parfois un s, 3 points dessus."}, "pool": "lesson", "lessonId": "ar.l02", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
