insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l02.e20', 'ar', 'ar.l02', 'ar.v.ba', array['ar.v.ba','ar.v.ta','ar.v.nun','ar.v.ya','ar.g02.letters2']::text[], 'match', 'lesson', 'Relie ن, ي, ب et ت à leur son.', '{}'::text[], 'Quatre lettres, quatre sons : n, y, b, t. Les noms nûn, yâ, bâ et tâ les rappellent.', 3, '{"id": "ar.l02.e20", "unitIds": ["ar.v.ba", "ar.v.ta", "ar.v.nun", "ar.v.ya", "ar.g02.letters2"], "type": "match", "difficulty": 3, "instruction": "Relie chaque élément à son associé.", "prompt": "Relie ن, ي, ب et ت à leur son.", "promptLanguage": "fr", "pairs": [{"left": "ن", "right": "le n de nuit"}, {"left": "ي", "right": "le y de yaourt"}, {"left": "ب", "right": "le b de bateau"}, {"left": "ت", "right": "le t de table"}], "acceptedAnswers": [], "explanation": "Quatre lettres, quatre sons : n, y, b, t. Les noms nûn, yâ, bâ et tâ les rappellent.", "pool": "lesson", "lessonId": "ar.l02", "skill": "recognition", "answer": "ن = le n de nuit ; ي = le y de yaourt ; ب = le b de bateau ; ت = le t de table"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e01', 'ar', 'ar.l03', 'ar.g03.letters3', array['ar.g03.letters3','ar.v.jim']::text[], 'mcq', 'lesson', 'Quelle lettre fait le son g, comme dans gâteau, en Égypte ?', array['ج']::text[], 'En Égypte, ج se dit g comme dans gâteau. Son point est dans le creux du crochet.', 1, '{"id": "ar.l03.e01", "unitIds": ["ar.g03.letters3", "ar.v.jim"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre fait le son g, comme dans gâteau, en Égypte ?", "promptLanguage": "fr", "options": ["ن", "ب", "ج", "ي"], "answer": "ج", "acceptedAnswers": ["ج"], "explanation": "En Égypte, ج se dit g comme dans gâteau. Son point est dans le creux du crochet.", "tip": "Un hameçon avec une bille dans le creux.", "extraExample": {"text": "ج", "translation": "gîm : le g de gâteau, 1 point dessous."}, "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e02', 'ar', 'ar.l03', 'ar.g03.letters3', array['ar.g03.letters3','ar.v.ha']::text[], 'mcq', 'lesson', 'Quelle lettre est un crochet sans aucun point ?', array['ح']::text[], 'ح est le crochet vide : ni bille dans le creux (ج), ni chapeau dessus (خ).', 1, '{"id": "ar.l03.e02", "unitIds": ["ar.g03.letters3", "ar.v.ha"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre est un crochet sans aucun point ?", "promptLanguage": "fr", "options": ["ت", "ج", "ح", "خ"], "answer": "ح", "acceptedAnswers": ["ح"], "explanation": "ح est le crochet vide : ni bille dans le creux (ج), ni chapeau dessus (خ).", "tip": "Le crochet vide : rien dedans, rien dessus.", "extraExample": {"text": "ح", "translation": "ḥâ : un h appuyé, aucun point."}, "errorPatterns": [{"equals": "ج", "category": "word_confusion", "feedback": "ج a 1 point dans le creux."}, {"equals": "خ", "category": "word_confusion", "feedback": "خ a 1 point dessus."}], "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e03', 'ar', 'ar.l03', 'ar.g03.letters3', array['ar.g03.letters3','ar.v.kha']::text[], 'mcq', 'lesson', 'Quelle lettre fait un raclement de gorge, comme le ch allemand de Bach ?', array['خ']::text[], 'خ se lit comme le ch allemand de Bach. Elle porte 1 point dessus, comme un chapeau.', 1, '{"id": "ar.l03.e03", "unitIds": ["ar.g03.letters3", "ar.v.kha"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre fait un raclement de gorge, comme le ch allemand de Bach ?", "promptLanguage": "fr", "options": ["ج", "ح", "خ", "ث"], "answer": "خ", "acceptedAnswers": ["خ"], "explanation": "خ se lit comme le ch allemand de Bach. Elle porte 1 point dessus, comme un chapeau.", "tip": "Le crochet avec un chapeau (le point dessus).", "extraExample": {"text": "خ", "translation": "khâ : le ch allemand de Bach, 1 point dessus."}, "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e04', 'ar', 'ar.l03', 'ar.g03.letters3', array['ar.g03.letters3','ar.v.jim','ar.v.ha','ar.v.kha']::text[], 'match', 'lesson', 'Relie ج, ح et خ à leurs points.', '{}'::text[], 'Même crochet, trois places pour le point : dessous (ج), nulle part (ح), dessus (خ).', 1, '{"id": "ar.l03.e04", "unitIds": ["ar.g03.letters3", "ar.v.jim", "ar.v.ha", "ar.v.kha"], "type": "match", "difficulty": 1, "instruction": "Relie chaque élément à son associé.", "prompt": "Relie ج, ح et خ à leurs points.", "promptLanguage": "fr", "pairs": [{"left": "ج", "right": "1 point dessous"}, {"left": "ح", "right": "aucun point"}, {"left": "خ", "right": "1 point dessus"}], "acceptedAnswers": [], "explanation": "Même crochet, trois places pour le point : dessous (ج), nulle part (ح), dessus (خ).", "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition", "answer": "ج = 1 point dessous ; ح = aucun point ; خ = 1 point dessus"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e05', 'ar', 'ar.l03', 'ar.g03.letters3', array['ar.g03.letters3','ar.v.kha']::text[], 'mcq', 'lesson', 'Quelle lettre a 1 point dessus, sur un crochet ?', array['خ']::text[], 'Le crochet à chapeau est خ. ن a aussi 1 point dessus, mais c''est un bol, pas un crochet.', 2, '{"id": "ar.l03.e05", "unitIds": ["ar.g03.letters3", "ar.v.kha"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre a 1 point dessus, sur un crochet ?", "promptLanguage": "fr", "options": ["ح", "ن", "خ", "ج"], "answer": "خ", "acceptedAnswers": ["خ"], "explanation": "Le crochet à chapeau est خ. ن a aussi 1 point dessus, mais c''est un bol, pas un crochet.", "tip": "Le crochet avec un chapeau (le point dessus).", "extraExample": {"text": "خ", "translation": "khâ : le ch allemand de Bach, 1 point dessus."}, "errorPatterns": [{"equals": "ن", "category": "word_confusion", "feedback": "ن a bien 1 point dessus, mais sa forme est un bol creux."}], "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
