insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e10', 'ar', 'ar.l03', 'ar.g03.letters3', array['ar.g03.letters3','ar.v.jim','ar.v.ha','ar.v.kha','ar.v.ba']::text[], 'mcq', 'lesson', 'Trois de ces lettres sont des crochets. Laquelle est l''intruse ?', array['ب']::text[], 'ج, ح et خ sont des crochets. ب est une barque plate : c''est l''intruse.', 2, '{"id": "ar.l03.e10", "unitIds": ["ar.g03.letters3", "ar.v.jim", "ar.v.ha", "ar.v.kha", "ar.v.ba"], "type": "mcq", "difficulty": 2, "instruction": "Trouve l''intruse.", "prompt": "Trois de ces lettres sont des crochets. Laquelle est l''intruse ?", "promptLanguage": "fr", "options": ["خ", "ج", "ح", "ب"], "answer": "ب", "acceptedAnswers": ["ب"], "explanation": "ج, ح et خ sont des crochets. ب est une barque plate : c''est l''intruse.", "tip": "Un hameçon avec une bille dans le creux.", "extraExample": {"text": "ج", "translation": "gîm : le g de gâteau, 1 point dessous."}, "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e11', 'ar', 'ar.l03', 'ar.g03.letters3', array['ar.g03.letters3','ar.v.ha']::text[], 'fill_blank', 'lesson', 'ح est le crochet sans point : elle se lit comme ___.', array['un h appuyé']::text[], 'ح se lit comme un h appuyé, soufflé du fond de la gorge, alors que ج se dit g.', 2, '{"id": "ar.l03.e11", "unitIds": ["ar.g03.letters3", "ar.v.ha"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le bon son.", "prompt": "ح est le crochet sans point : elle se lit comme ___.", "promptLanguage": "fr", "options": ["un h appuyé", "le g de gâteau", "le n de nuit"], "answer": "un h appuyé", "acceptedAnswers": ["un h appuyé"], "explanation": "ح se lit comme un h appuyé, soufflé du fond de la gorge, alors que ج se dit g.", "tip": "Le crochet vide : rien dedans, rien dessus.", "extraExample": {"text": "ح", "translation": "ḥâ : un h appuyé, aucun point."}, "pool": "lesson", "lessonId": "ar.l03", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e12', 'ar', 'ar.l03', 'ar.g03.letters3', array['ar.g03.letters3','ar.v.jim']::text[], 'mcq', 'lesson', 'En Égypte, comment dit-on la lettre ج ?', array['le g de gâteau']::text[], 'En arabe littéraire, ج se dit dj, mais en Égypte on la dit g, comme dans gâteau.', 3, '{"id": "ar.l03.e12", "unitIds": ["ar.g03.letters3", "ar.v.jim"], "type": "mcq", "difficulty": 3, "instruction": "Choisis le bon son.", "prompt": "En Égypte, comment dit-on la lettre ج ?", "promptLanguage": "fr", "options": ["le n de nuit", "le ch allemand de Bach", "le g de gâteau", "le b de bateau"], "answer": "le g de gâteau", "acceptedAnswers": ["le g de gâteau"], "explanation": "En arabe littéraire, ج se dit dj, mais en Égypte on la dit g, comme dans gâteau.", "tip": "Tu dis déjà ce g tous les jours : relie-le au crochet à bille.", "extraExample": {"text": "ج", "translation": "gîm : le g de gâteau, 1 point dessous."}, "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e13', 'ar', 'ar.l03', 'ar.v.ta', array['ar.v.ta','ar.g03.letters3']::text[], 'mcq', 'lesson', 'Quels points porte la lettre ت ?', array['2 points dessus']::text[], 'ت porte 2 points dessus, comme deux mouettes. Avec 2 points dessous, ce serait ي.', 3, '{"id": "ar.l03.e13", "unitIds": ["ar.v.ta", "ar.g03.letters3"], "type": "mcq", "difficulty": 3, "instruction": "Choisis les bons points.", "prompt": "Quels points porte la lettre ت ?", "promptLanguage": "fr", "options": ["3 points dessus", "2 points dessus", "1 point dessous", "2 points dessous"], "answer": "2 points dessus", "acceptedAnswers": ["2 points dessus"], "explanation": "ت porte 2 points dessus, comme deux mouettes. Avec 2 points dessous, ce serait ي.", "tip": "Deux mouettes sur la barque.", "extraExample": {"text": "ت", "translation": "tâ : le t de table, 2 points dessus."}, "errorPatterns": [{"equals": "2 points dessous", "category": "word_confusion", "feedback": "2 points dessous, c''est ي, la lettre à queue."}], "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e14', 'ar', 'ar.l03', 'ar.v.tha', array['ar.v.tha','ar.g03.letters3']::text[], 'mcq', 'lesson', 'Qui suis-je ? « Je suis une barque avec trois mouettes sur ma coque. »', array['ث']::text[], 'Trois mouettes, ce sont 3 points dessus : c''est ث.', 3, '{"id": "ar.l03.e14", "unitIds": ["ar.v.tha", "ar.g03.letters3"], "type": "mcq", "difficulty": 3, "instruction": "Devine la lettre.", "prompt": "Qui suis-je ? « Je suis une barque avec trois mouettes sur ma coque. »", "promptLanguage": "fr", "options": ["ث", "ت", "ن", "ب"], "answer": "ث", "acceptedAnswers": ["ث"], "explanation": "Trois mouettes, ce sont 3 points dessus : c''est ث.", "tip": "Trois mouettes en triangle sur la barque.", "extraExample": {"text": "ث", "translation": "thâ : un t, parfois un s, 3 points dessus."}, "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e15', 'ar', 'ar.l03', 'ar.g03.letters3', array['ar.g03.letters3','ar.v.kha']::text[], 'mcq', 'lesson', 'Qui suis-je ? « Je suis un crochet coiffé d''un point, et je racle la gorge. »', array['خ']::text[], 'Un crochet avec un point dessus, qui racle la gorge comme le ch de Bach : c''est خ.', 3, '{"id": "ar.l03.e15", "unitIds": ["ar.g03.letters3", "ar.v.kha"], "type": "mcq", "difficulty": 3, "instruction": "Devine la lettre.", "prompt": "Qui suis-je ? « Je suis un crochet coiffé d''un point, et je racle la gorge. »", "promptLanguage": "fr", "options": ["ن", "ج", "خ", "ح"], "answer": "خ", "acceptedAnswers": ["خ"], "explanation": "Un crochet avec un point dessus, qui racle la gorge comme le ch de Bach : c''est خ.", "tip": "Le crochet avec un chapeau (le point dessus).", "extraExample": {"text": "خ", "translation": "khâ : le ch allemand de Bach, 1 point dessus."}, "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e16', 'ar', 'ar.l03', 'ar.g03.letters3', array['ar.g03.letters3','ar.v.jim']::text[], 'mcq', 'lesson', 'Quel est le nom de la lettre ج ?', array['gîm']::text[], 'ج s''appelle gîm en Égypte. Son nom commence par son son, le g de gâteau.', 3, '{"id": "ar.l03.e16", "unitIds": ["ar.g03.letters3", "ar.v.jim"], "type": "mcq", "difficulty": 3, "instruction": "Choisis le bon nom.", "prompt": "Quel est le nom de la lettre ج ?", "promptLanguage": "fr", "options": ["tâ", "gîm", "nûn", "bâ"], "answer": "gîm", "acceptedAnswers": ["gîm"], "explanation": "ج s''appelle gîm en Égypte. Son nom commence par son son, le g de gâteau.", "tip": "Un hameçon avec une bille dans le creux.", "extraExample": {"text": "ج", "translation": "gîm : le g de gâteau, 1 point dessous."}, "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e17', 'ar', 'ar.l03', 'ar.v.ba', array['ar.v.ba','ar.v.ta','ar.v.tha','ar.v.nun','ar.v.ya','ar.g03.letters3']::text[], 'match', 'lesson', 'Relie ب, ت, ث, ن et ي à leurs points.', '{}'::text[], 'Cinq lettres de la famille des points : le nombre ET la place les distinguent.', 3, '{"id": "ar.l03.e17", "unitIds": ["ar.v.ba", "ar.v.ta", "ar.v.tha", "ar.v.nun", "ar.v.ya", "ar.g03.letters3"], "type": "match", "difficulty": 3, "instruction": "Relie chaque élément à son associé.", "prompt": "Relie ب, ت, ث, ن et ي à leurs points.", "promptLanguage": "fr", "pairs": [{"left": "ب", "right": "1 point dessous"}, {"left": "ت", "right": "2 points dessus"}, {"left": "ث", "right": "3 points dessus"}, {"left": "ن", "right": "1 point dessus"}, {"left": "ي", "right": "2 points dessous"}], "acceptedAnswers": [], "explanation": "Cinq lettres de la famille des points : le nombre ET la place les distinguent.", "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition", "answer": "ب = 1 point dessous ; ت = 2 points dessus ; ث = 3 points dessus ; ن = 1 point dessus ; ي = 2 points dessous"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l03.e18', 'ar', 'ar.l03', 'ar.g03.letters3', array['ar.g03.letters3','ar.v.jim','ar.v.ha','ar.v.kha','ar.v.nun']::text[], 'match', 'lesson', 'Relie ج, ح, خ et ن à leur son.', '{}'::text[], 'Trois crochets, trois sons de gorge ou de bouche : g, h appuyé, ch de Bach. ن est le n de nuit.', 3, '{"id": "ar.l03.e18", "unitIds": ["ar.g03.letters3", "ar.v.jim", "ar.v.ha", "ar.v.kha", "ar.v.nun"], "type": "match", "difficulty": 3, "instruction": "Relie chaque élément à son associé.", "prompt": "Relie ج, ح, خ et ن à leur son.", "promptLanguage": "fr", "pairs": [{"left": "ج", "right": "le g de gâteau"}, {"left": "ح", "right": "un h appuyé"}, {"left": "خ", "right": "le ch allemand de Bach"}, {"left": "ن", "right": "le n de nuit"}], "acceptedAnswers": [], "explanation": "Trois crochets, trois sons de gorge ou de bouche : g, h appuyé, ch de Bach. ن est le n de nuit.", "pool": "lesson", "lessonId": "ar.l03", "skill": "recognition", "answer": "ج = le g de gâteau ; ح = un h appuyé ; خ = le ch allemand de Bach ; ن = le n de nuit"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
