insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e02', 'ar', 'ar.l04', 'ar.g04.letters4', array['ar.g04.letters4','ar.v.zay']::text[], 'mcq', 'lesson', 'Quelle lettre fait le son z, comme dans zèbre ?', array['ز']::text[], 'ز se lit comme le z de zèbre. C''est la virgule ر, coiffée d''un point dessus.', 1, '{"id": "ar.l04.e02", "unitIds": ["ar.g04.letters4", "ar.v.zay"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre fait le son z, comme dans zèbre ?", "promptLanguage": "fr", "options": ["ر", "ز", "ن", "د"], "answer": "ز", "acceptedAnswers": ["ز"], "explanation": "ز se lit comme le z de zèbre. C''est la virgule ر, coiffée d''un point dessus.", "tip": "La virgule avec un point : zzz.", "extraExample": {"text": "ز", "translation": "zây : le z de zèbre, 1 point dessus."}, "errorPatterns": [{"equals": "ر", "category": "word_confusion", "feedback": "ر est le r roulé : c''est la même virgule, mais sans point."}], "pool": "lesson", "lessonId": "ar.l04", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e03', 'ar', 'ar.l04', 'ar.g04.letters4', array['ar.g04.letters4','ar.v.ra']::text[], 'mcq', 'lesson', 'Quelle lettre est une virgule qui descend sous la ligne, sans point ?', array['ر']::text[], 'ر descend sous la ligne comme une virgule. ز lui ressemble, mais elle porte un point dessus.', 1, '{"id": "ar.l04.e03", "unitIds": ["ar.g04.letters4", "ar.v.ra"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre est une virgule qui descend sous la ligne, sans point ?", "promptLanguage": "fr", "options": ["ا", "ر", "ز", "د"], "answer": "ر", "acceptedAnswers": ["ر"], "explanation": "ر descend sous la ligne comme une virgule. ز lui ressemble, mais elle porte un point dessus.", "tip": "Une virgule qui descend sous la ligne.", "extraExample": {"text": "ر", "translation": "râ : un r roulé, aucun point."}, "errorPatterns": [{"equals": "ز", "category": "word_confusion", "feedback": "ز a la même forme, mais avec 1 point dessus."}], "pool": "lesson", "lessonId": "ar.l04", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e04', 'ar', 'ar.l04', 'ar.g04.letters4', array['ar.g04.letters4','ar.v.dal','ar.v.dhal','ar.v.ra','ar.v.zay']::text[], 'match', 'lesson', 'Relie د, ذ, ر et ز à leur nom.', '{}'::text[], 'Quatre noms pour deux paires : dâl et dhâl, râ et zây. Le nom commence par le son de la lettre.', 1, '{"id": "ar.l04.e04", "unitIds": ["ar.g04.letters4", "ar.v.dal", "ar.v.dhal", "ar.v.ra", "ar.v.zay"], "type": "match", "difficulty": 1, "instruction": "Relie chaque élément à son associé.", "prompt": "Relie د, ذ, ر et ز à leur nom.", "promptLanguage": "fr", "pairs": [{"left": "د", "right": "dâl"}, {"left": "ذ", "right": "dhâl"}, {"left": "ر", "right": "râ"}, {"left": "ز", "right": "zây"}], "acceptedAnswers": [], "explanation": "Quatre noms pour deux paires : dâl et dhâl, râ et zây. Le nom commence par le son de la lettre.", "pool": "lesson", "lessonId": "ar.l04", "skill": "recognition", "answer": "د = dâl ; ذ = dhâl ; ر = râ ; ز = zây"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e05', 'ar', 'ar.l04', 'ar.g04.letters4', array['ar.g04.letters4','ar.v.dhal']::text[], 'mcq', 'lesson', 'Quelle lettre est un petit dos arrondi avec 1 point dessus ?', array['ذ']::text[], 'ذ est le dos de د coiffé d''un point dessus.', 2, '{"id": "ar.l04.e05", "unitIds": ["ar.g04.letters4", "ar.v.dhal"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre est un petit dos arrondi avec 1 point dessus ?", "promptLanguage": "fr", "options": ["د", "ز", "ذ", "ر"], "answer": "ذ", "acceptedAnswers": ["ذ"], "explanation": "ذ est le dos de د coiffé d''un point dessus.", "tip": "Le dos arrondi avec un chapeau.", "extraExample": {"text": "ذ", "translation": "dhâl : un d, parfois un z, 1 point dessus."}, "errorPatterns": [{"equals": "د", "category": "word_confusion", "feedback": "د est le même dos, mais sans aucun point."}], "pool": "lesson", "lessonId": "ar.l04", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e06', 'ar', 'ar.l04', 'ar.g04.letters4', array['ar.g04.letters4','ar.v.zay']::text[], 'mcq', 'lesson', 'Quelle lettre est une virgule avec 1 point dessus ?', array['ز']::text[], 'ز est la virgule ر avec un point dessus. ذ a bien un point dessus aussi, mais c''est un dos arrondi.', 2, '{"id": "ar.l04.e06", "unitIds": ["ar.g04.letters4", "ar.v.zay"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre est une virgule avec 1 point dessus ?", "promptLanguage": "fr", "options": ["د", "ذ", "ز", "ر"], "answer": "ز", "acceptedAnswers": ["ز"], "explanation": "ز est la virgule ر avec un point dessus. ذ a bien un point dessus aussi, mais c''est un dos arrondi.", "tip": "La virgule avec un point : zzz.", "extraExample": {"text": "ز", "translation": "zây : le z de zèbre, 1 point dessus."}, "errorPatterns": [{"equals": "ذ", "category": "word_confusion", "feedback": "ذ a un point dessus, mais sa forme est un dos arrondi, pas une virgule."}], "pool": "lesson", "lessonId": "ar.l04", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
