insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e09', 'ar', 'ar.l04', 'ar.g04.letters4', array['ar.g04.letters4','ar.v.ra','ar.v.dal']::text[], 'fill_blank', 'lesson', 'ر est une virgule qui descend ___ la ligne, alors que د reste posée dessus.', array['sous']::text[], 'ر descend sous la ligne comme une virgule, alors que د reste posée sur la ligne.', 2, '{"id": "ar.l04.e09", "unitIds": ["ar.g04.letters4", "ar.v.ra", "ar.v.dal"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le bon mot.", "prompt": "ر est une virgule qui descend ___ la ligne, alors que د reste posée dessus.", "promptLanguage": "fr", "options": ["au bout de", "sous", "sur"], "answer": "sous", "acceptedAnswers": ["sous"], "explanation": "ر descend sous la ligne comme une virgule, alors que د reste posée sur la ligne.", "tip": "Une virgule qui descend sous la ligne.", "extraExample": {"text": "ر", "translation": "râ : un r roulé, aucun point."}, "pool": "lesson", "lessonId": "ar.l04", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e10', 'ar', 'ar.l04', 'ar.g04.letters4', array['ar.g04.letters4','ar.v.dal','ar.v.dhal','ar.v.zay','ar.v.kha']::text[], 'mcq', 'lesson', 'Trois de ces lettres ont 1 point dessus. Laquelle est l''intruse ?', array['د']::text[], 'ذ, ز et خ portent chacune 1 point dessus. د n''en porte aucun : c''est l''intruse.', 2, '{"id": "ar.l04.e10", "unitIds": ["ar.g04.letters4", "ar.v.dal", "ar.v.dhal", "ar.v.zay", "ar.v.kha"], "type": "mcq", "difficulty": 2, "instruction": "Trouve l''intruse.", "prompt": "Trois de ces lettres ont 1 point dessus. Laquelle est l''intruse ?", "promptLanguage": "fr", "options": ["د", "ذ", "خ", "ز"], "answer": "د", "acceptedAnswers": ["د"], "explanation": "ذ, ز et خ portent chacune 1 point dessus. د n''en porte aucun : c''est l''intruse.", "tip": "Un petit dos arrondi posé sur la ligne.", "extraExample": {"text": "د", "translation": "dâl : le d de dent, aucun point."}, "pool": "lesson", "lessonId": "ar.l04", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e11', 'ar', 'ar.l04', 'ar.v.jim', array['ar.v.jim','ar.g04.letters4']::text[], 'mcq', 'lesson', 'Quelle lettre est un crochet avec 1 point dans le creux ?', array['ج']::text[], 'ج est le crochet à bille : 1 point dans le creux, donc dessous. Elle se dit g en Égypte.', 2, '{"id": "ar.l04.e11", "unitIds": ["ar.v.jim", "ar.g04.letters4"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre est un crochet avec 1 point dans le creux ?", "promptLanguage": "fr", "options": ["خ", "ذ", "ح", "ج"], "answer": "ج", "acceptedAnswers": ["ج"], "explanation": "ج est le crochet à bille : 1 point dans le creux, donc dessous. Elle se dit g en Égypte.", "tip": "Un hameçon avec une bille dans le creux.", "extraExample": {"text": "ج", "translation": "gîm : le g de gâteau, 1 point dessous."}, "errorPatterns": [{"equals": "خ", "category": "word_confusion", "feedback": "خ a son point dessus (le chapeau), pas dans le creux."}], "pool": "lesson", "lessonId": "ar.l04", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e12', 'ar', 'ar.l04', 'ar.v.ha', array['ar.v.ha','ar.g04.letters4']::text[], 'mcq', 'lesson', 'Parmi ces lettres, laquelle se lit comme un h appuyé ?', array['ح']::text[], 'ح est le crochet vide, un h appuyé soufflé du fond de la gorge.', 2, '{"id": "ar.l04.e12", "unitIds": ["ar.v.ha", "ar.g04.letters4"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Parmi ces lettres, laquelle se lit comme un h appuyé ?", "promptLanguage": "fr", "options": ["ر", "ح", "ج", "خ"], "answer": "ح", "acceptedAnswers": ["ح"], "explanation": "ح est le crochet vide, un h appuyé soufflé du fond de la gorge.", "tip": "Le crochet vide : rien dedans, rien dessus.", "extraExample": {"text": "ح", "translation": "ḥâ : un h appuyé, aucun point."}, "pool": "lesson", "lessonId": "ar.l04", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e13', 'ar', 'ar.l04', 'ar.g04.letters4', array['ar.g04.letters4','ar.v.dhal']::text[], 'mcq', 'lesson', 'En Égypte, comment dit-on le plus souvent la lettre ذ ?', array['un d, parfois un z']::text[], 'En arabe littéraire, ذ est le th de this, mais en Égypte on la dit comme un d, parfois un z.', 3, '{"id": "ar.l04.e13", "unitIds": ["ar.g04.letters4", "ar.v.dhal"], "type": "mcq", "difficulty": 3, "instruction": "Choisis le bon son.", "prompt": "En Égypte, comment dit-on le plus souvent la lettre ذ ?", "promptLanguage": "fr", "options": ["le b de bateau", "le r de rouge", "le ch de chat", "un d, parfois un z"], "answer": "un d, parfois un z", "acceptedAnswers": ["un d, parfois un z"], "explanation": "En arabe littéraire, ذ est le th de this, mais en Égypte on la dit comme un d, parfois un z.", "tip": "Comme ث se dit t, ذ se dit d : les sons « th » n''existent pas en égyptien.", "extraExample": {"text": "ذ", "translation": "dhâl : un d, parfois un z, 1 point dessus."}, "pool": "lesson", "lessonId": "ar.l04", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e14', 'ar', 'ar.l04', 'ar.g04.letters4', array['ar.g04.letters4','ar.v.ra']::text[], 'mcq', 'lesson', 'Quel son fait la lettre ر ?', array['un r roulé']::text[], 'ر est un r roulé du bout de la langue, comme en espagnol.', 3, '{"id": "ar.l04.e14", "unitIds": ["ar.g04.letters4", "ar.v.ra"], "type": "mcq", "difficulty": 3, "instruction": "Choisis le bon son.", "prompt": "Quel son fait la lettre ر ?", "promptLanguage": "fr", "options": ["un r roulé", "le n de nuit", "le d de dent", "le z de zèbre"], "answer": "un r roulé", "acceptedAnswers": ["un r roulé"], "explanation": "ر est un r roulé du bout de la langue, comme en espagnol.", "tip": "Une virgule qui descend sous la ligne.", "extraExample": {"text": "ر", "translation": "râ : un r roulé, aucun point."}, "pool": "lesson", "lessonId": "ar.l04", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
