insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e16', 'ar', 'ar.l04', 'ar.v.nun', array['ar.v.nun','ar.g04.letters4']::text[], 'mcq', 'lesson', 'Quels points porte la lettre ن ?', array['1 point dessus']::text[], 'ن porte 1 point dessus, la cerise sur le bol. Avec 1 point dessous, ce serait ب.', 3, '{"id": "ar.l04.e16", "unitIds": ["ar.v.nun", "ar.g04.letters4"], "type": "mcq", "difficulty": 3, "instruction": "Choisis les bons points.", "prompt": "Quels points porte la lettre ن ?", "promptLanguage": "fr", "options": ["2 points dessous", "1 point dessous", "2 points dessus", "1 point dessus"], "answer": "1 point dessus", "acceptedAnswers": ["1 point dessus"], "explanation": "ن porte 1 point dessus, la cerise sur le bol. Avec 1 point dessous, ce serait ب.", "tip": "Un bol avec une cerise dessus.", "extraExample": {"text": "ن", "translation": "nûn : le n de nuit, 1 point dessus."}, "errorPatterns": [{"equals": "1 point dessous", "category": "word_confusion", "feedback": "1 point dessous, c''est ب, la barque."}], "pool": "lesson", "lessonId": "ar.l04", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e17', 'ar', 'ar.l04', 'ar.v.jim', array['ar.v.jim','ar.v.ha','ar.v.kha','ar.v.ya','ar.g04.letters4']::text[], 'match', 'lesson', 'Relie ج, ح, خ et ي à leurs points.', '{}'::text[], 'Trois crochets distingués par la place du point (dessous, aucun, dessus), et ي avec ses 2 points dessous.', 3, '{"id": "ar.l04.e17", "unitIds": ["ar.v.jim", "ar.v.ha", "ar.v.kha", "ar.v.ya", "ar.g04.letters4"], "type": "match", "difficulty": 3, "instruction": "Relie chaque élément à son associé.", "prompt": "Relie ج, ح, خ et ي à leurs points.", "promptLanguage": "fr", "pairs": [{"left": "ج", "right": "1 point dessous"}, {"left": "ح", "right": "aucun point"}, {"left": "خ", "right": "1 point dessus"}, {"left": "ي", "right": "2 points dessous"}], "acceptedAnswers": [], "explanation": "Trois crochets distingués par la place du point (dessous, aucun, dessus), et ي avec ses 2 points dessous.", "pool": "lesson", "lessonId": "ar.l04", "skill": "recognition", "answer": "ج = 1 point dessous ; ح = aucun point ; خ = 1 point dessus ; ي = 2 points dessous"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l04.e18', 'ar', 'ar.l04', 'ar.g04.letters4', array['ar.g04.letters4','ar.v.dal','ar.v.dhal','ar.v.ra','ar.v.zay']::text[], 'match', 'lesson', 'Relie د, ذ, ر et ز à leur son.', '{}'::text[], 'Deux paires de jumelles : d et d/z, r et z. Le point dessus ajoute le son plus « bourdonnant ».', 3, '{"id": "ar.l04.e18", "unitIds": ["ar.g04.letters4", "ar.v.dal", "ar.v.dhal", "ar.v.ra", "ar.v.zay"], "type": "match", "difficulty": 3, "instruction": "Relie chaque élément à son associé.", "prompt": "Relie د, ذ, ر et ز à leur son.", "promptLanguage": "fr", "pairs": [{"left": "د", "right": "le d de dent"}, {"left": "ذ", "right": "un d, parfois un z"}, {"left": "ر", "right": "un r roulé"}, {"left": "ز", "right": "le z de zèbre"}], "acceptedAnswers": [], "explanation": "Deux paires de jumelles : d et d/z, r et z. Le point dessus ajoute le son plus « bourdonnant ».", "pool": "lesson", "lessonId": "ar.l04", "skill": "recognition", "answer": "د = le d de dent ; ذ = un d, parfois un z ; ر = un r roulé ; ز = le z de zèbre"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
