insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l05.e17', 'ar', 'ar.l05', 'ar.v.dhal', array['ar.v.dhal','ar.v.ra','ar.v.zay','ar.v.kha','ar.g05.letters5']::text[], 'match', 'lesson', 'Relie ذ, ر, ز et خ à leur son.', '{}'::text[], 'Quatre sons à relier : ذ (d ou z), ر (r roulé), ز (z) et خ (ch de Bach).', 3, '{"id": "ar.l05.e17", "unitIds": ["ar.v.dhal", "ar.v.ra", "ar.v.zay", "ar.v.kha", "ar.g05.letters5"], "type": "match", "difficulty": 3, "instruction": "Relie chaque élément à son associé.", "prompt": "Relie ذ, ر, ز et خ à leur son.", "promptLanguage": "fr", "pairs": [{"left": "ذ", "right": "un d, parfois un z"}, {"left": "ر", "right": "un r roulé"}, {"left": "ز", "right": "le z de zèbre"}, {"left": "خ", "right": "le ch allemand de Bach"}], "acceptedAnswers": [], "explanation": "Quatre sons à relier : ذ (d ou z), ر (r roulé), ز (z) et خ (ch de Bach).", "pool": "lesson", "lessonId": "ar.l05", "skill": "recognition", "answer": "ذ = un d, parfois un z ; ر = un r roulé ; ز = le z de zèbre ; خ = le ch allemand de Bach"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
