insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l05.e20', 'ar', 'ar.l05', 'ar.g05.letters5', array['ar.g05.letters5','ar.v.shin']::text[], 'free_answer', 'lesson', 'Comment s''appelle la lettre qui fait le son ch, comme dans chat ?', array['chîn','chin','chiin','shin']::text[], 'ش s''appelle chîn : son nom commence par son son, ch.', 3, '{"id": "ar.l05.e20", "unitIds": ["ar.g05.letters5", "ar.v.shin"], "type": "free_answer", "difficulty": 3, "instruction": "Écris le nom de la lettre.", "prompt": "Comment s''appelle la lettre qui fait le son ch, comme dans chat ?", "promptLanguage": "fr", "answer": "chîn", "acceptedAnswers": ["chîn", "chin", "chiin", "shin"], "explanation": "ش s''appelle chîn : son nom commence par son son, ch.", "tip": "Les trois dents et trois points de vapeur : chhh.", "extraExample": {"text": "ش", "translation": "chîn : le ch de chat, 3 points dessus."}, "pool": "lesson", "lessonId": "ar.l05", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e01', 'ar', 'ar.l06', 'ar.g06.letters6', array['ar.g06.letters6','ar.v.tah']::text[], 'mcq', 'lesson', 'Quelle lettre est une boucle fermée avec un mât, sans aucun point ?', array['ط']::text[], 'ط est la boucle au mât, sans point : un t lourd. ظ a le même mât, avec 1 point dessus.', 1, '{"id": "ar.l06.e01", "unitIds": ["ar.g06.letters6", "ar.v.tah"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre est une boucle fermée avec un mât, sans aucun point ?", "promptLanguage": "fr", "options": ["ط", "ظ", "ض", "ص"], "answer": "ط", "acceptedAnswers": ["ط"], "explanation": "ط est la boucle au mât, sans point : un t lourd. ظ a le même mât, avec 1 point dessus.", "tip": "Une boucle avec un mât : un drapeau.", "extraExample": {"text": "ط", "translation": "ṭâ : un t lourd, aucun point."}, "errorPatterns": [{"equals": "ظ", "category": "word_confusion", "feedback": "ظ a bien un mât, mais aussi 1 point dessus."}], "pool": "lesson", "lessonId": "ar.l06", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e02', 'ar', 'ar.l06', 'ar.g06.letters6', array['ar.g06.letters6','ar.v.ayn']::text[], 'mcq', 'lesson', 'Quelle lettre est un œil de profil, sans point ?', array['ع']::text[], 'ع est l''œil de profil. Avec une larme (1 point dessus), ce serait غ.', 1, '{"id": "ar.l06.e02", "unitIds": ["ar.g06.letters6", "ar.v.ayn"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre est un œil de profil, sans point ?", "promptLanguage": "fr", "options": ["غ", "ع", "ط", "ح"], "answer": "ع", "acceptedAnswers": ["ع"], "explanation": "ع est l''œil de profil. Avec une larme (1 point dessus), ce serait غ.", "tip": "Un œil de profil : aïn veut dire œil.", "extraExample": {"text": "ع", "translation": "aïn : un son de gorge serrée, aucun point."}, "errorPatterns": [{"equals": "غ", "category": "word_confusion", "feedback": "غ est l''œil avec une larme : elle a 1 point dessus."}], "pool": "lesson", "lessonId": "ar.l06", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e03', 'ar', 'ar.l06', 'ar.g06.letters6', array['ar.g06.letters6','ar.v.ghayn']::text[], 'mcq', 'lesson', 'Quelle lettre fait le r de rouge, au fond de la gorge ?', array['غ']::text[], 'غ se lit comme le r de rouge, le r du fond de la gorge. Le r roulé, c''est ر.', 1, '{"id": "ar.l06.e03", "unitIds": ["ar.g06.letters6", "ar.v.ghayn"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre fait le r de rouge, au fond de la gorge ?", "promptLanguage": "fr", "options": ["ر", "غ", "ظ", "ع"], "answer": "غ", "acceptedAnswers": ["غ"], "explanation": "غ se lit comme le r de rouge, le r du fond de la gorge. Le r roulé, c''est ر.", "tip": "L''œil avec une larme dessus.", "extraExample": {"text": "غ", "translation": "ghaïn : le r de rouge, 1 point dessus."}, "errorPatterns": [{"equals": "ر", "category": "word_confusion", "feedback": "ر est le r roulé du bout de la langue, pas celui de rouge."}], "pool": "lesson", "lessonId": "ar.l06", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
