insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e11', 'ar', 'ar.l06', 'ar.v.sad', array['ar.v.sad','ar.g06.letters6']::text[], 'mcq', 'lesson', 'Quelle lettre est une boucle fermée sans mât et sans point ?', array['ص']::text[], 'ص est la boucle sans mât ni point. ط a un mât, ض a un point, س a des dents.', 2, '{"id": "ar.l06.e11", "unitIds": ["ar.v.sad", "ar.g06.letters6"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre est une boucle fermée sans mât et sans point ?", "promptLanguage": "fr", "options": ["ض", "ص", "ط", "س"], "answer": "ص", "acceptedAnswers": ["ص"], "explanation": "ص est la boucle sans mât ni point. ط a un mât, ض a un point, س a des dents.", "tip": "Une boucle fermée, comme un œil qui se ferme.", "extraExample": {"text": "ص", "translation": "sâd : un s lourd, aucun point."}, "pool": "lesson", "lessonId": "ar.l06", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e12', 'ar', 'ar.l06', 'ar.v.dad', array['ar.v.dad','ar.g06.letters6']::text[], 'mcq', 'lesson', 'Quelle lettre est un d lourd ?', array['ض']::text[], 'ض est le d lourd : une boucle avec 1 point dessus. Le d léger de dent, c''est د.', 2, '{"id": "ar.l06.e12", "unitIds": ["ar.v.dad", "ar.g06.letters6"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre est un d lourd ?", "promptLanguage": "fr", "options": ["ص", "ض", "د", "ظ"], "answer": "ض", "acceptedAnswers": ["ض"], "explanation": "ض est le d lourd : une boucle avec 1 point dessus. Le d léger de dent, c''est د.", "tip": "La boucle avec un point dessus.", "extraExample": {"text": "ض", "translation": "dâd : un d lourd, 1 point dessus."}, "errorPatterns": [{"equals": "د", "category": "word_confusion", "feedback": "د est le d léger, un petit dos sans boucle."}], "pool": "lesson", "lessonId": "ar.l06", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e13', 'ar', 'ar.l06', 'ar.v.shin', array['ar.v.shin','ar.g06.letters6']::text[], 'mcq', 'lesson', 'Laquelle de ces lettres dit « ch » comme dans chat ?', array['ش']::text[], 'ش dit ch comme dans chat. خ est un raclement de gorge, ce n''est pas le même son.', 3, '{"id": "ar.l06.e13", "unitIds": ["ar.v.shin", "ar.g06.letters6"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne lettre.", "prompt": "Laquelle de ces lettres dit « ch » comme dans chat ?", "promptLanguage": "fr", "options": ["ش", "س", "خ", "ص"], "answer": "ش", "acceptedAnswers": ["ش"], "explanation": "ش dit ch comme dans chat. خ est un raclement de gorge, ce n''est pas le même son.", "tip": "Les trois dents et trois points de vapeur : chhh.", "extraExample": {"text": "ش", "translation": "chîn : le ch de chat, 3 points dessus."}, "pool": "lesson", "lessonId": "ar.l06", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e14', 'ar', 'ar.l06', 'ar.v.sad', array['ar.v.sad','ar.g06.letters6']::text[], 'mcq', 'lesson', 'Quel est le nom de la lettre ص ?', array['sâd']::text[], 'ص s''appelle sâd. Ne la confonds pas avec ض, qui s''appelle dâd.', 3, '{"id": "ar.l06.e14", "unitIds": ["ar.v.sad", "ar.g06.letters6"], "type": "mcq", "difficulty": 3, "instruction": "Choisis le bon nom.", "prompt": "Quel est le nom de la lettre ص ?", "promptLanguage": "fr", "options": ["dâd", "sâd", "sîn", "chîn"], "answer": "sâd", "acceptedAnswers": ["sâd"], "explanation": "ص s''appelle sâd. Ne la confonds pas avec ض, qui s''appelle dâd.", "tip": "Une boucle fermée, comme un œil qui se ferme.", "extraExample": {"text": "ص", "translation": "sâd : un s lourd, aucun point."}, "errorPatterns": [{"equals": "dâd", "category": "word_confusion", "feedback": "dâd est le nom de ض, la boucle avec un point."}], "pool": "lesson", "lessonId": "ar.l06", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e15', 'ar', 'ar.l06', 'ar.g06.letters6', array['ar.g06.letters6','ar.v.zah']::text[], 'mcq', 'lesson', 'Quel son fait la lettre ظ en Égypte ?', array['un z lourd']::text[], 'En Égypte, ظ se dit comme un z lourd. Le z léger de zèbre, c''est ز.', 3, '{"id": "ar.l06.e15", "unitIds": ["ar.g06.letters6", "ar.v.zah"], "type": "mcq", "difficulty": 3, "instruction": "Choisis le bon son.", "prompt": "Quel son fait la lettre ظ en Égypte ?", "promptLanguage": "fr", "options": ["le d de dent", "un t lourd", "un z lourd", "le z de zèbre"], "answer": "un z lourd", "acceptedAnswers": ["un z lourd"], "explanation": "En Égypte, ظ se dit comme un z lourd. Le z léger de zèbre, c''est ز.", "tip": "Le drapeau avec un point.", "extraExample": {"text": "ظ", "translation": "ẓâ : un z lourd, 1 point dessus."}, "errorPatterns": [{"equals": "le z de zèbre", "category": "word_confusion", "feedback": "Le z léger, c''est ز. ظ est lourde, dite au fond de la gorge."}], "pool": "lesson", "lessonId": "ar.l06", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e16', 'ar', 'ar.l06', 'ar.g06.letters6', array['ar.g06.letters6','ar.v.zah']::text[], 'mcq', 'lesson', 'Qui suis-je ? « Je suis un drapeau avec un point, lourd, et je dis z. »', array['ظ']::text[], 'Un mât et 1 point dessus, avec un z lourd : c''est ظ.', 3, '{"id": "ar.l06.e16", "unitIds": ["ar.g06.letters6", "ar.v.zah"], "type": "mcq", "difficulty": 3, "instruction": "Devine la lettre.", "prompt": "Qui suis-je ? « Je suis un drapeau avec un point, lourd, et je dis z. »", "promptLanguage": "fr", "options": ["ط", "ض", "ظ", "ز"], "answer": "ظ", "acceptedAnswers": ["ظ"], "explanation": "Un mât et 1 point dessus, avec un z lourd : c''est ظ.", "tip": "Le drapeau avec un point.", "extraExample": {"text": "ظ", "translation": "ẓâ : un z lourd, 1 point dessus."}, "errorPatterns": [{"equals": "ز", "category": "word_confusion", "feedback": "ز est légère et n''a pas de mât."}], "pool": "lesson", "lessonId": "ar.l06", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e17', 'ar', 'ar.l06', 'ar.g06.letters6', array['ar.g06.letters6','ar.v.sad','ar.v.dad','ar.v.tah','ar.v.zah']::text[], 'match', 'lesson', 'Relie ص, ض, ط et ظ à leur son.', '{}'::text[], 'Les quatre lourdes sont les jumelles lourdes de س, د, ت et ز : s, d, t, z, dits au fond de la gorge.', 3, '{"id": "ar.l06.e17", "unitIds": ["ar.g06.letters6", "ar.v.sad", "ar.v.dad", "ar.v.tah", "ar.v.zah"], "type": "match", "difficulty": 3, "instruction": "Relie chaque élément à son associé.", "prompt": "Relie ص, ض, ط et ظ à leur son.", "promptLanguage": "fr", "pairs": [{"left": "ص", "right": "un s lourd"}, {"left": "ض", "right": "un d lourd"}, {"left": "ط", "right": "un t lourd"}, {"left": "ظ", "right": "un z lourd"}], "acceptedAnswers": [], "explanation": "Les quatre lourdes sont les jumelles lourdes de س, د, ت et ز : s, d, t, z, dits au fond de la gorge.", "pool": "lesson", "lessonId": "ar.l06", "skill": "recognition", "answer": "ص = un s lourd ; ض = un d lourd ; ط = un t lourd ; ظ = un z lourd"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e18', 'ar', 'ar.l06', 'ar.v.sin', array['ar.v.sin','ar.v.shin','ar.v.dad','ar.v.tah','ar.g06.letters6']::text[], 'match', 'lesson', 'Relie chaque forme à sa lettre.', '{}'::text[], 'Dents ou boucle ? Mât ou pas ? Points ou pas ? Ces trois questions suffisent pour classer س ش ض ط.', 3, '{"id": "ar.l06.e18", "unitIds": ["ar.v.sin", "ar.v.shin", "ar.v.dad", "ar.v.tah", "ar.g06.letters6"], "type": "match", "difficulty": 3, "instruction": "Relie chaque élément à son associé.", "prompt": "Relie chaque forme à sa lettre.", "promptLanguage": "fr", "pairs": [{"left": "trois dents", "right": "س"}, {"left": "trois dents et 3 points dessus", "right": "ش"}, {"left": "boucle fermée et 1 point dessus", "right": "ض"}, {"left": "boucle fermée avec un mât", "right": "ط"}], "acceptedAnswers": [], "explanation": "Dents ou boucle ? Mât ou pas ? Points ou pas ? Ces trois questions suffisent pour classer س ش ض ط.", "pool": "lesson", "lessonId": "ar.l06", "skill": "recognition", "answer": "trois dents = س ; trois dents et 3 points dessus = ش ; boucle fermée et 1 point dessus = ض ; boucle fermée avec un mât = ط"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e19', 'ar', 'ar.l06', 'ar.g06.letters6', array['ar.g06.letters6','ar.v.ghayn']::text[], 'free_answer', 'lesson', 'Combien de points a la lettre غ ? Réponds avec un chiffre.', array['1','un']::text[], 'غ a 1 point dessus : la larme de l''œil. ع n''en a pas.', 2, '{"id": "ar.l06.e19", "unitIds": ["ar.g06.letters6", "ar.v.ghayn"], "type": "free_answer", "difficulty": 2, "instruction": "Écris le nombre.", "prompt": "Combien de points a la lettre غ ? Réponds avec un chiffre.", "promptLanguage": "fr", "answer": "1", "acceptedAnswers": ["1", "un"], "explanation": "غ a 1 point dessus : la larme de l''œil. ع n''en a pas.", "tip": "L''œil avec une larme dessus.", "extraExample": {"text": "غ", "translation": "ghaïn : le r de rouge, 1 point dessus."}, "pool": "lesson", "lessonId": "ar.l06", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l06.e20', 'ar', 'ar.l06', 'ar.g06.letters6', array['ar.g06.letters6','ar.v.ayn']::text[], 'free_answer', 'lesson', 'Comment s''appelle la lettre qui est un œil de profil, sans point ?', array['aïn','ain','ayn','aine']::text[], 'ع s''appelle aïn, ce qui veut dire « œil » en arabe.', 3, '{"id": "ar.l06.e20", "unitIds": ["ar.g06.letters6", "ar.v.ayn"], "type": "free_answer", "difficulty": 3, "instruction": "Écris le nom de la lettre.", "prompt": "Comment s''appelle la lettre qui est un œil de profil, sans point ?", "promptLanguage": "fr", "answer": "aïn", "acceptedAnswers": ["aïn", "ain", "ayn", "aine"], "explanation": "ع s''appelle aïn, ce qui veut dire « œil » en arabe.", "tip": "Un œil de profil : aïn veut dire œil.", "extraExample": {"text": "ع", "translation": "aïn : un son de gorge serrée, aucun point."}, "pool": "lesson", "lessonId": "ar.l06", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e01', 'ar', 'ar.l07', 'ar.g07.letters7', array['ar.g07.letters7','ar.v.fa']::text[], 'mcq', 'lesson', 'Quelle lettre fait le son f, comme dans feu ?', array['ف']::text[], 'ف se lit comme le f de feu : une tête ronde avec 1 point dessus, le petit fantôme.', 1, '{"id": "ar.l07.e01", "unitIds": ["ar.g07.letters7", "ar.v.fa"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre fait le son f, comme dans feu ?", "promptLanguage": "fr", "options": ["ف", "ب", "ن", "ق"], "answer": "ف", "acceptedAnswers": ["ف"], "explanation": "ف se lit comme le f de feu : une tête ronde avec 1 point dessus, le petit fantôme.", "tip": "Une tête ronde avec un point dessus.", "extraExample": {"text": "ف", "translation": "fâ : le f de feu, 1 point dessus."}, "errorPatterns": [{"equals": "ق", "category": "word_confusion", "feedback": "ق a 2 points et se dit comme un coup de gorge au Caire."}], "pool": "lesson", "lessonId": "ar.l07", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e02', 'ar', 'ar.l07', 'ar.g07.letters7', array['ar.g07.letters7','ar.v.kaf']::text[], 'mcq', 'lesson', 'Quelle lettre fait le son k, comme dans kilo ?', array['ك']::text[], 'ك se lit comme le k de kilo : un grand trait avec un petit zigzag dans l''angle.', 1, '{"id": "ar.l07.e02", "unitIds": ["ar.g07.letters7", "ar.v.kaf"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre fait le son k, comme dans kilo ?", "promptLanguage": "fr", "options": ["ل", "ك", "ن", "ا"], "answer": "ك", "acceptedAnswers": ["ك"], "explanation": "ك se lit comme le k de kilo : un grand trait avec un petit zigzag dans l''angle.", "tip": "Un grand trait avec un petit zigzag dans l''angle.", "extraExample": {"text": "ك", "translation": "kâf : le k de kilo, aucun point."}, "errorPatterns": [{"equals": "ل", "category": "word_confusion", "feedback": "ل fait l, comme lune : un bâton avec un pied."}], "pool": "lesson", "lessonId": "ar.l07", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e03', 'ar', 'ar.l07', 'ar.g07.letters7', array['ar.g07.letters7','ar.v.fa','ar.v.qaf','ar.v.kaf','ar.v.lam']::text[], 'match', 'lesson', 'Relie ف, ق, ك et ل à leur nom.', '{}'::text[], 'fâ pour f, kâf pour k, lâm pour l. Le nom de ق est qâf : on le dit presque comme un coup de gorge au Caire.', 1, '{"id": "ar.l07.e03", "unitIds": ["ar.g07.letters7", "ar.v.fa", "ar.v.qaf", "ar.v.kaf", "ar.v.lam"], "type": "match", "difficulty": 1, "instruction": "Relie chaque élément à son associé.", "prompt": "Relie ف, ق, ك et ل à leur nom.", "promptLanguage": "fr", "pairs": [{"left": "ف", "right": "fâ"}, {"left": "ق", "right": "qâf"}, {"left": "ك", "right": "kâf"}, {"left": "ل", "right": "lâm"}], "acceptedAnswers": [], "explanation": "fâ pour f, kâf pour k, lâm pour l. Le nom de ق est qâf : on le dit presque comme un coup de gorge au Caire.", "pool": "lesson", "lessonId": "ar.l07", "skill": "recognition", "answer": "ف = fâ ; ق = qâf ; ك = kâf ; ل = lâm"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e04', 'ar', 'ar.l07', 'ar.g07.letters7', array['ar.g07.letters7','ar.v.fa']::text[], 'mcq', 'lesson', 'Quelle lettre est une tête ronde avec 1 point dessus ?', array['ف']::text[], 'ف est la tête ronde à un point. ق en a deux, et ن est un bol, pas une tête ronde.', 2, '{"id": "ar.l07.e04", "unitIds": ["ar.g07.letters7", "ar.v.fa"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre est une tête ronde avec 1 point dessus ?", "promptLanguage": "fr", "options": ["ف", "ن", "ك", "ق"], "answer": "ف", "acceptedAnswers": ["ف"], "explanation": "ف est la tête ronde à un point. ق en a deux, et ن est un bol, pas une tête ronde.", "tip": "Une tête ronde avec un point dessus.", "extraExample": {"text": "ف", "translation": "fâ : le f de feu, 1 point dessus."}, "errorPatterns": [{"equals": "ن", "category": "word_confusion", "feedback": "ن a 1 point dessus, mais c''est un bol creux, pas une tête ronde."}], "pool": "lesson", "lessonId": "ar.l07", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e05', 'ar', 'ar.l07', 'ar.g07.letters7', array['ar.g07.letters7','ar.v.qaf']::text[], 'mcq', 'lesson', 'Quelle lettre a une tête ronde, 2 points dessus et une queue profonde ?', array['ق']::text[], 'ق a 2 points dessus et une queue qui plonge. ت a aussi 2 points dessus, mais c''est une barque plate.', 2, '{"id": "ar.l07.e05", "unitIds": ["ar.g07.letters7", "ar.v.qaf"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre a une tête ronde, 2 points dessus et une queue profonde ?", "promptLanguage": "fr", "options": ["ن", "ف", "ت", "ق"], "answer": "ق", "acceptedAnswers": ["ق"], "explanation": "ق a 2 points dessus et une queue qui plonge. ت a aussi 2 points dessus, mais c''est une barque plate.", "tip": "Une tête ronde, deux points et une queue profonde.", "extraExample": {"text": "ق", "translation": "qâf : un coup de gorge, 2 points dessus."}, "errorPatterns": [{"equals": "ت", "category": "word_confusion", "feedback": "ت a bien 2 points dessus, mais c''est une barque plate."}], "pool": "lesson", "lessonId": "ar.l07", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e06', 'ar', 'ar.l07', 'ar.g07.letters7', array['ar.g07.letters7','ar.v.lam']::text[], 'mcq', 'lesson', 'Quelle lettre est un bâton avec un pied courbé, comme un L dans un miroir ?', array['ل']::text[], 'ل est un bâton avec un pied. ا est un bâton nu, sans pied.', 2, '{"id": "ar.l07.e06", "unitIds": ["ar.g07.letters7", "ar.v.lam"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre est un bâton avec un pied courbé, comme un L dans un miroir ?", "promptLanguage": "fr", "options": ["ل", "ك", "ر", "ا"], "answer": "ل", "acceptedAnswers": ["ل"], "explanation": "ل est un bâton avec un pied. ا est un bâton nu, sans pied.", "tip": "Un L dans un miroir : un bâton avec un pied.", "extraExample": {"text": "ل", "translation": "lâm : le l de lune, aucun point."}, "errorPatterns": [{"equals": "ا", "category": "word_confusion", "feedback": "ا est un bâton sans pied."}], "pool": "lesson", "lessonId": "ar.l07", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e07', 'ar', 'ar.l07', 'ar.g07.letters7', array['ar.g07.letters7','ar.v.kaf']::text[], 'mcq', 'lesson', 'Quelle lettre est un grand trait avec un petit zigzag dans l''angle, sans point ?', array['ك']::text[], 'ك a un zigzag dans l''angle, mais aucun point. Le zigzag fait partie de la lettre.', 2, '{"id": "ar.l07.e07", "unitIds": ["ar.g07.letters7", "ar.v.kaf"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre est un grand trait avec un petit zigzag dans l''angle, sans point ?", "promptLanguage": "fr", "options": ["ل", "ك", "ف", "ا"], "answer": "ك", "acceptedAnswers": ["ك"], "explanation": "ك a un zigzag dans l''angle, mais aucun point. Le zigzag fait partie de la lettre.", "tip": "Un grand trait avec un petit zigzag dans l''angle.", "extraExample": {"text": "ك", "translation": "kâf : le k de kilo, aucun point."}, "pool": "lesson", "lessonId": "ar.l07", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e08', 'ar', 'ar.l07', 'ar.g07.letters7', array['ar.g07.letters7','ar.v.qaf']::text[], 'fill_blank', 'lesson', 'ق a ___ points dessus, et une queue profonde.', array['2']::text[], 'ق a 2 points dessus. Avec 1 point dessus et une queue courte, ce serait ف.', 2, '{"id": "ar.l07.e08", "unitIds": ["ar.g07.letters7", "ar.v.qaf"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète avec le bon nombre.", "prompt": "ق a ___ points dessus, et une queue profonde.", "promptLanguage": "fr", "options": ["3", "2", "1"], "answer": "2", "acceptedAnswers": ["2"], "explanation": "ق a 2 points dessus. Avec 1 point dessus et une queue courte, ce serait ف.", "tip": "Une tête ronde, deux points et une queue profonde.", "extraExample": {"text": "ق", "translation": "qâf : un coup de gorge, 2 points dessus."}, "pool": "lesson", "lessonId": "ar.l07", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
