insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e11', 'ar', 'ar.l07', 'ar.v.ta', array['ar.v.ta','ar.g07.letters7']::text[], 'mcq', 'lesson', 'Parmi ces lettres, laquelle a 2 points dessus sur une barque plate ?', array['ت']::text[], 'ت a 2 points dessus et un corps de barque plate. ق a aussi 2 points dessus, mais une tête ronde et une queue profonde.', 2, '{"id": "ar.l07.e11", "unitIds": ["ar.v.ta", "ar.g07.letters7"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Parmi ces lettres, laquelle a 2 points dessus sur une barque plate ?", "promptLanguage": "fr", "options": ["ن", "ت", "ف", "ق"], "answer": "ت", "acceptedAnswers": ["ت"], "explanation": "ت a 2 points dessus et un corps de barque plate. ق a aussi 2 points dessus, mais une tête ronde et une queue profonde.", "tip": "Deux mouettes sur la barque.", "extraExample": {"text": "ت", "translation": "tâ : le t de table, 2 points dessus."}, "errorPatterns": [{"equals": "ق", "category": "word_confusion", "feedback": "ق a bien 2 points dessus, mais sa tête est ronde et sa queue profonde."}], "pool": "lesson", "lessonId": "ar.l07", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
