insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e14', 'ar', 'ar.l07', 'ar.v.ghayn', array['ar.v.ghayn','ar.g07.letters7']::text[], 'mcq', 'lesson', 'Quel son fait la lettre غ ?', array['le r de rouge']::text[], 'غ se lit comme le r de rouge, le r du fond de la gorge. Le r roulé, c''est ر.', 3, '{"id": "ar.l07.e14", "unitIds": ["ar.v.ghayn", "ar.g07.letters7"], "type": "mcq", "difficulty": 3, "instruction": "Choisis le bon son.", "prompt": "Quel son fait la lettre غ ?", "promptLanguage": "fr", "options": ["un son de gorge serrée", "un r roulé", "le ch allemand de Bach", "le r de rouge"], "answer": "le r de rouge", "acceptedAnswers": ["le r de rouge"], "explanation": "غ se lit comme le r de rouge, le r du fond de la gorge. Le r roulé, c''est ر.", "tip": "L''œil avec une larme dessus.", "extraExample": {"text": "غ", "translation": "ghaïn : le r de rouge, 1 point dessus."}, "errorPatterns": [{"equals": "un r roulé", "category": "word_confusion", "feedback": "Le r roulé, c''est ر. غ est le r de rouge."}], "pool": "lesson", "lessonId": "ar.l07", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e15', 'ar', 'ar.l07', 'ar.g07.letters7', array['ar.g07.letters7','ar.v.qaf']::text[], 'mcq', 'lesson', 'Au Caire, comment dit-on le plus souvent la lettre ق ?', array['un coup de gorge']::text[], 'Au Caire, ق se dit comme un coup de gorge, un petit arrêt dans la voix. Le vrai k, c''est ك.', 3, '{"id": "ar.l07.e15", "unitIds": ["ar.g07.letters7", "ar.v.qaf"], "type": "mcq", "difficulty": 3, "instruction": "Choisis le bon son.", "prompt": "Au Caire, comment dit-on le plus souvent la lettre ق ?", "promptLanguage": "fr", "options": ["un coup de gorge", "le r de rouge", "le k de kilo", "le f de feu"], "answer": "un coup de gorge", "acceptedAnswers": ["un coup de gorge"], "explanation": "Au Caire, ق se dit comme un coup de gorge, un petit arrêt dans la voix. Le vrai k, c''est ك.", "tip": "Écoute-toi dire le mot « stylo » en égyptien : le premier son, c''est ق.", "extraExample": {"text": "ق", "translation": "qâf : un coup de gorge, 2 points dessus."}, "errorPatterns": [{"equals": "le k de kilo", "category": "word_confusion", "feedback": "Le k de kilo, c''est ك. Au Caire, ق est un coup de gorge."}], "pool": "lesson", "lessonId": "ar.l07", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e16', 'ar', 'ar.l07', 'ar.g07.letters7', array['ar.g07.letters7','ar.v.fa','ar.v.qaf','ar.v.kaf','ar.v.lam']::text[], 'match', 'lesson', 'Relie ف, ق, ك et ل à leur son.', '{}'::text[], 'f, coup de gorge, k, l : quatre sons très différents pour quatre dessins très différents.', 3, '{"id": "ar.l07.e16", "unitIds": ["ar.g07.letters7", "ar.v.fa", "ar.v.qaf", "ar.v.kaf", "ar.v.lam"], "type": "match", "difficulty": 3, "instruction": "Relie chaque élément à son associé.", "prompt": "Relie ف, ق, ك et ل à leur son.", "promptLanguage": "fr", "pairs": [{"left": "ف", "right": "le f de feu"}, {"left": "ق", "right": "un coup de gorge"}, {"left": "ك", "right": "le k de kilo"}, {"left": "ل", "right": "le l de lune"}], "acceptedAnswers": [], "explanation": "f, coup de gorge, k, l : quatre sons très différents pour quatre dessins très différents.", "pool": "lesson", "lessonId": "ar.l07", "skill": "recognition", "answer": "ف = le f de feu ; ق = un coup de gorge ; ك = le k de kilo ; ل = le l de lune"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e17', 'ar', 'ar.l07', 'ar.v.ayn', array['ar.v.ayn','ar.v.ghayn','ar.v.tah','ar.v.zah','ar.g07.letters7']::text[], 'match', 'lesson', 'Relie ع, غ, ط et ظ à leur forme.', '{}'::text[], 'ع et غ sont des yeux (غ pleure), ط et ظ sont des boucles à mât (ظ a un point).', 3, '{"id": "ar.l07.e17", "unitIds": ["ar.v.ayn", "ar.v.ghayn", "ar.v.tah", "ar.v.zah", "ar.g07.letters7"], "type": "match", "difficulty": 3, "instruction": "Relie chaque élément à son associé.", "prompt": "Relie ع, غ, ط et ظ à leur forme.", "promptLanguage": "fr", "pairs": [{"left": "ع", "right": "un œil de profil"}, {"left": "غ", "right": "un œil avec une larme"}, {"left": "ط", "right": "une boucle avec un mât"}, {"left": "ظ", "right": "un mât et 1 point dessus"}], "acceptedAnswers": [], "explanation": "ع et غ sont des yeux (غ pleure), ط et ظ sont des boucles à mât (ظ a un point).", "pool": "lesson", "lessonId": "ar.l07", "skill": "recognition", "answer": "ع = un œil de profil ; غ = un œil avec une larme ; ط = une boucle avec un mât ; ظ = un mât et 1 point dessus"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e18', 'ar', 'ar.l07', 'ar.g07.letters7', array['ar.g07.letters7','ar.v.nun','ar.v.fa','ar.v.ta','ar.v.qaf']::text[], 'match', 'lesson', 'Relie ن, ف, ت et ق à leur forme.', '{}'::text[], 'Nombre de points et forme du corps : les deux indices ensemble t''évitent les confusions.', 3, '{"id": "ar.l07.e18", "unitIds": ["ar.g07.letters7", "ar.v.nun", "ar.v.fa", "ar.v.ta", "ar.v.qaf"], "type": "match", "difficulty": 3, "instruction": "Relie chaque élément à son associé.", "prompt": "Relie ن, ف, ت et ق à leur forme.", "promptLanguage": "fr", "pairs": [{"left": "ن", "right": "un bol, 1 point dessus"}, {"left": "ف", "right": "une tête ronde, 1 point dessus"}, {"left": "ت", "right": "une barque, 2 points dessus"}, {"left": "ق", "right": "une tête ronde, 2 points dessus"}], "acceptedAnswers": [], "explanation": "Nombre de points et forme du corps : les deux indices ensemble t''évitent les confusions.", "pool": "lesson", "lessonId": "ar.l07", "skill": "recognition", "answer": "ن = un bol, 1 point dessus ; ف = une tête ronde, 1 point dessus ; ت = une barque, 2 points dessus ; ق = une tête ronde, 2 points dessus"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e19', 'ar', 'ar.l07', 'ar.g07.letters7', array['ar.g07.letters7','ar.v.fa']::text[], 'free_answer', 'lesson', 'Combien de points a la lettre ف ? Réponds avec un chiffre.', array['1','un']::text[], 'ف a 1 point dessus, et une queue courte. ق en a 2.', 2, '{"id": "ar.l07.e19", "unitIds": ["ar.g07.letters7", "ar.v.fa"], "type": "free_answer", "difficulty": 2, "instruction": "Écris le nombre.", "prompt": "Combien de points a la lettre ف ? Réponds avec un chiffre.", "promptLanguage": "fr", "answer": "1", "acceptedAnswers": ["1", "un"], "explanation": "ف a 1 point dessus, et une queue courte. ق en a 2.", "tip": "Une tête ronde avec un point dessus.", "extraExample": {"text": "ف", "translation": "fâ : le f de feu, 1 point dessus."}, "pool": "lesson", "lessonId": "ar.l07", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l07.e20', 'ar', 'ar.l07', 'ar.g07.letters7', array['ar.g07.letters7','ar.v.lam']::text[], 'free_answer', 'lesson', 'Comment s''appelle la lettre qui fait le son l, comme dans lune ?', array['lâm','lam','laam']::text[], 'ل s''appelle lâm : son nom commence par son son, l.', 3, '{"id": "ar.l07.e20", "unitIds": ["ar.g07.letters7", "ar.v.lam"], "type": "free_answer", "difficulty": 3, "instruction": "Écris le nom de la lettre.", "prompt": "Comment s''appelle la lettre qui fait le son l, comme dans lune ?", "promptLanguage": "fr", "answer": "lâm", "acceptedAnswers": ["lâm", "lam", "laam"], "explanation": "ل s''appelle lâm : son nom commence par son son, l.", "tip": "Un L dans un miroir : un bâton avec un pied.", "extraExample": {"text": "ل", "translation": "lâm : le l de lune, aucun point."}, "pool": "lesson", "lessonId": "ar.l07", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e01', 'ar', 'ar.l08', 'ar.g08.letters8', array['ar.g08.letters8','ar.v.waw']::text[], 'mcq', 'lesson', 'Quelle lettre est un petit 9, qui se lit comme le ou de oui ?', array['و']::text[], 'و est le petit 9 à queue courbe : le ou de oui. م a une queue droite.', 1, '{"id": "ar.l08.e01", "unitIds": ["ar.g08.letters8", "ar.v.waw"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre est un petit 9, qui se lit comme le ou de oui ?", "promptLanguage": "fr", "options": ["ر", "م", "و", "ف"], "answer": "و", "acceptedAnswers": ["و"], "explanation": "و est le petit 9 à queue courbe : le ou de oui. م a une queue droite.", "tip": "Un petit 9 : une tête et une queue qui pend.", "extraExample": {"text": "و", "translation": "wâw : le ou de oui, aucun point."}, "errorPatterns": [{"equals": "م", "category": "word_confusion", "feedback": "م a une queue droite, et se dit m comme dans mer."}], "pool": "lesson", "lessonId": "ar.l08", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e02', 'ar', 'ar.l08', 'ar.g08.letters8', array['ar.g08.letters8','ar.v.mim','ar.v.heh','ar.v.waw','ar.v.hamza','ar.v.ta_marbuta']::text[], 'match', 'lesson', 'Relie م, ه, و, ء et ة à leur nom.', '{}'::text[], 'mîm pour m, wâw pour w/ou, hâ pour le h soufflé. ء s''appelle hamza, ة s''appelle tâ marbûta, « ta attaché ».', 1, '{"id": "ar.l08.e02", "unitIds": ["ar.g08.letters8", "ar.v.mim", "ar.v.heh", "ar.v.waw", "ar.v.hamza", "ar.v.ta_marbuta"], "type": "match", "difficulty": 1, "instruction": "Relie chaque élément à son associé.", "prompt": "Relie م, ه, و, ء et ة à leur nom.", "promptLanguage": "fr", "pairs": [{"left": "م", "right": "mîm"}, {"left": "ه", "right": "hâ"}, {"left": "و", "right": "wâw"}, {"left": "ء", "right": "hamza"}, {"left": "ة", "right": "tâ marbûta"}], "acceptedAnswers": [], "explanation": "mîm pour m, wâw pour w/ou, hâ pour le h soufflé. ء s''appelle hamza, ة s''appelle tâ marbûta, « ta attaché ».", "pool": "lesson", "lessonId": "ar.l08", "skill": "recognition", "answer": "م = mîm ; ه = hâ ; و = wâw ; ء = hamza ; ة = tâ marbûta"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
