insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e04', 'ar', 'ar.l08', 'ar.g08.letters8', array['ar.g08.letters8','ar.v.ta_marbuta']::text[], 'mcq', 'lesson', 'Quelle lettre est un ه coiffé de 2 points dessus, à la fin des mots féminins ?', array['ة']::text[], 'ة est le ه couronné des 2 points de ت : tâ marbûta, « ta attaché », qui se dit a à la fin du mot.', 2, '{"id": "ar.l08.e04", "unitIds": ["ar.g08.letters8", "ar.v.ta_marbuta"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre est un ه coiffé de 2 points dessus, à la fin des mots féminins ?", "promptLanguage": "fr", "options": ["ة", "ت", "ق", "ه"], "answer": "ة", "acceptedAnswers": ["ة"], "explanation": "ة est le ه couronné des 2 points de ت : tâ marbûta, « ta attaché », qui se dit a à la fin du mot.", "tip": "Un ه coiffé des deux points de ت.", "extraExample": {"text": "ة", "translation": "tâ marbûta : un a à la fin du mot, 2 points dessus."}, "errorPatterns": [{"equals": "ه", "category": "word_confusion", "feedback": "ه n''a pas de point : il lui manque la couronne de 2 points."}], "pool": "lesson", "lessonId": "ar.l08", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
