insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e08', 'ar', 'ar.l08', 'ar.g08.letters8', array['ar.g08.letters8','ar.v.hamza','ar.v.ayn']::text[], 'fill_blank', 'lesson', 'ء est une toute petite tête de ___, posée seule.', array['ع']::text[], 'ء est une petite tête de ع, sans queue. Elle marque un coup de gorge.', 3, '{"id": "ar.l08.e08", "unitIds": ["ar.g08.letters8", "ar.v.hamza", "ar.v.ayn"], "type": "fill_blank", "difficulty": 3, "instruction": "Choisis la lettre qui manque.", "prompt": "ء est une toute petite tête de ___, posée seule.", "promptLanguage": "fr", "options": ["ع", "م", "ف"], "answer": "ع", "acceptedAnswers": ["ع"], "explanation": "ء est une petite tête de ع, sans queue. Elle marque un coup de gorge.", "tip": "Une toute petite tête de ع, posée seule.", "extraExample": {"text": "ء", "translation": "hamza : un coup de gorge, aucun point."}, "pool": "lesson", "lessonId": "ar.l08", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e09', 'ar', 'ar.l08', 'ar.g08.letters8', array['ar.g08.letters8','ar.v.heh','ar.v.ha']::text[], 'fill_blank', 'lesson', 'ه est un h ___ : un simple souffle, plus léger que ح.', array['soufflé']::text[], 'ه est un h soufflé, léger. ح, au contraire, est un h appuyé, du fond de la gorge.', 3, '{"id": "ar.l08.e09", "unitIds": ["ar.g08.letters8", "ar.v.heh", "ar.v.ha"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète avec le bon mot.", "prompt": "ه est un h ___ : un simple souffle, plus léger que ح.", "promptLanguage": "fr", "options": ["roulé", "appuyé", "soufflé"], "answer": "soufflé", "acceptedAnswers": ["soufflé"], "explanation": "ه est un h soufflé, léger. ح, au contraire, est un h appuyé, du fond de la gorge.", "tip": "Un petit nœud à deux boucles.", "extraExample": {"text": "ه", "translation": "hâ : un h soufflé, aucun point."}, "pool": "lesson", "lessonId": "ar.l08", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e10', 'ar', 'ar.l08', 'ar.g08.letters8', array['ar.g08.letters8','ar.v.hamza']::text[], 'mcq', 'lesson', 'Quel son fait la lettre ء ?', array['un coup de gorge']::text[], 'ء marque un coup de gorge, un petit arrêt dans la voix. ع serre la gorge, ه souffle.', 3, '{"id": "ar.l08.e10", "unitIds": ["ar.g08.letters8", "ar.v.hamza"], "type": "mcq", "difficulty": 3, "instruction": "Choisis le bon son.", "prompt": "Quel son fait la lettre ء ?", "promptLanguage": "fr", "options": ["le m de mer", "un coup de gorge", "un son de gorge serrée", "un h soufflé"], "answer": "un coup de gorge", "acceptedAnswers": ["un coup de gorge"], "explanation": "ء marque un coup de gorge, un petit arrêt dans la voix. ع serre la gorge, ه souffle.", "tip": "Une toute petite tête de ع, posée seule.", "extraExample": {"text": "ء", "translation": "hamza : un coup de gorge, aucun point."}, "errorPatterns": [{"equals": "un h soufflé", "category": "word_confusion", "feedback": "Le h soufflé, c''est ه. ء est un arrêt net dans la voix."}], "pool": "lesson", "lessonId": "ar.l08", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
