insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e13', 'ar', 'ar.l08', 'ar.g08.letters8', array['ar.g08.letters8','ar.v.ta_marbuta']::text[], 'free_answer', 'lesson', 'Combien de points a la lettre ة ? Réponds avec un chiffre.', array['2','deux']::text[], 'ة a 2 points dessus, ceux de ت : c''est le ت attaché au ه.', 3, '{"id": "ar.l08.e13", "unitIds": ["ar.g08.letters8", "ar.v.ta_marbuta"], "type": "free_answer", "difficulty": 3, "instruction": "Écris le nombre.", "prompt": "Combien de points a la lettre ة ? Réponds avec un chiffre.", "promptLanguage": "fr", "answer": "2", "acceptedAnswers": ["2", "deux"], "explanation": "ة a 2 points dessus, ceux de ت : c''est le ت attaché au ه.", "tip": "Un ه coiffé des deux points de ت.", "extraExample": {"text": "ة", "translation": "tâ marbûta : un a à la fin du mot, 2 points dessus."}, "pool": "lesson", "lessonId": "ar.l08", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e14', 'ar', 'ar.l08', 'ar.g08.letters8', array['ar.g08.letters8','ar.v.alif','ar.v.mim']::text[], 'mcq', 'lesson', 'Parmi les 28 lettres, combien n''ont aucun point ?', array['13']::text[], '13 lettres n''ont aucun point, 15 en ont. Le bâton ا, les dents س, les boucles ص ط, l''œil ع, la cerise م... en font partie.', 3, '{"id": "ar.l08.e14", "unitIds": ["ar.g08.letters8", "ar.v.alif", "ar.v.mim"], "type": "mcq", "difficulty": 3, "instruction": "Choisis le bon nombre.", "prompt": "Parmi les 28 lettres, combien n''ont aucun point ?", "promptLanguage": "fr", "options": ["12", "13", "10", "15"], "answer": "13", "acceptedAnswers": ["13"], "explanation": "13 lettres n''ont aucun point, 15 en ont. Le bâton ا, les dents س, les boucles ص ط, l''œil ع, la cerise م... en font partie.", "tip": "Un poteau droit, sans point : c''est alif.", "extraExample": {"text": "ا", "translation": "alif : un bâton, une des 13 lettres sans point."}, "pool": "lesson", "lessonId": "ar.l08", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
