insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e16', 'ar', 'ar.l08', 'ar.v.ba', array['ar.v.ba','ar.v.jim','ar.v.ya','ar.g08.letters8']::text[], 'mcq', 'lesson', 'Quelles sont les seules lettres qui ont des points dessous ?', array['ب ج ي']::text[], 'Seules trois lettres ont des points dessous : ب (1), ج (1) et ي (2). Tout le reste est dessus ou sans point.', 3, '{"id": "ar.l08.e16", "unitIds": ["ar.v.ba", "ar.v.jim", "ar.v.ya", "ar.g08.letters8"], "type": "mcq", "difficulty": 3, "instruction": "Choisis le bon groupe.", "prompt": "Quelles sont les seules lettres qui ont des points dessous ?", "promptLanguage": "fr", "options": ["ج ح خ", "ب ت ث", "ب ج ي", "ن ي ت"], "answer": "ب ج ي", "acceptedAnswers": ["ب ج ي"], "explanation": "Seules trois lettres ont des points dessous : ب (1), ج (1) et ي (2). Tout le reste est dessus ou sans point.", "tip": "Une barque, et son ancre en dessous.", "extraExample": {"text": "ب ج ي", "translation": "les trois lettres aux points dessous."}, "errorPatterns": [{"equals": "ب ت ث", "category": "word_confusion", "feedback": "ت et ث ont leurs points dessus."}], "pool": "lesson", "lessonId": "ar.l08", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e17', 'ar', 'ar.l08', 'ar.v.ra', array['ar.v.ra','ar.g08.letters8']::text[], 'mcq', 'lesson', 'Quelle lettre est un r roulé, dessiné comme une virgule qui descend ?', array['ر']::text[], 'ر est le r roulé : une virgule qui descend. غ est l''autre r, celui de rouge, dessiné comme un œil.', 3, '{"id": "ar.l08.e17", "unitIds": ["ar.v.ra", "ar.g08.letters8"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre est un r roulé, dessiné comme une virgule qui descend ?", "promptLanguage": "fr", "options": ["ر", "د", "غ", "ز"], "answer": "ر", "acceptedAnswers": ["ر"], "explanation": "ر est le r roulé : une virgule qui descend. غ est l''autre r, celui de rouge, dessiné comme un œil.", "tip": "Une virgule qui descend sous la ligne.", "extraExample": {"text": "ر", "translation": "râ : un r roulé, aucun point."}, "errorPatterns": [{"equals": "غ", "category": "word_confusion", "feedback": "غ est le r de rouge, au fond de la gorge. Le r roulé est dessiné comme une virgule."}], "pool": "lesson", "lessonId": "ar.l08", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e18', 'ar', 'ar.l08', 'ar.v.tha', array['ar.v.tha','ar.g08.letters8']::text[], 'mcq', 'lesson', 'Quelle lettre s''appelle thâ ?', array['ث']::text[], 'ث s''appelle thâ : une barque avec 3 points dessus. ش a aussi 3 points, mais sur trois dents.', 3, '{"id": "ar.l08.e18", "unitIds": ["ar.v.tha", "ar.g08.letters8"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre s''appelle thâ ?", "promptLanguage": "fr", "options": ["س", "ت", "ش", "ث"], "answer": "ث", "acceptedAnswers": ["ث"], "explanation": "ث s''appelle thâ : une barque avec 3 points dessus. ش a aussi 3 points, mais sur trois dents.", "tip": "Trois mouettes en triangle sur la barque.", "extraExample": {"text": "ث", "translation": "thâ : un t, parfois un s, 3 points dessus."}, "errorPatterns": [{"equals": "ش", "category": "word_confusion", "feedback": "ش a 3 points aussi, mais sur trois dents. Elle s''appelle chîn."}], "pool": "lesson", "lessonId": "ar.l08", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e19', 'ar', 'ar.l08', 'ar.v.sad', array['ar.v.sad','ar.g08.letters8']::text[], 'mcq', 'lesson', 'Laquelle de ces lettres est un s lourd, une boucle fermée sans point ?', array['ص']::text[], 'ص est le s lourd : une boucle fermée sans point ni mât. ض a un point, ط a un mât.', 3, '{"id": "ar.l08.e19", "unitIds": ["ar.v.sad", "ar.g08.letters8"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne lettre.", "prompt": "Laquelle de ces lettres est un s lourd, une boucle fermée sans point ?", "promptLanguage": "fr", "options": ["ص", "ط", "ض", "س"], "answer": "ص", "acceptedAnswers": ["ص"], "explanation": "ص est le s lourd : une boucle fermée sans point ni mât. ض a un point, ط a un mât.", "tip": "Une boucle fermée, comme un œil qui se ferme.", "extraExample": {"text": "ص", "translation": "sâd : un s lourd, aucun point."}, "pool": "lesson", "lessonId": "ar.l08", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e20', 'ar', 'ar.l08', 'ar.v.kha', array['ar.v.kha','ar.v.ha','ar.g08.letters8']::text[], 'fill_blank', 'lesson', 'ح est le crochet sans point ; si tu lui ajoutes 1 point dessus, tu obtiens ___.', array['خ']::text[], 'ح + 1 point dessus = خ : le h appuyé devient le ch de Bach. Avec 1 point dessous, ce serait ج.', 3, '{"id": "ar.l08.e20", "unitIds": ["ar.v.kha", "ar.v.ha", "ar.g08.letters8"], "type": "fill_blank", "difficulty": 3, "instruction": "Choisis la lettre qui manque.", "prompt": "ح est le crochet sans point ; si tu lui ajoutes 1 point dessus, tu obtiens ___.", "promptLanguage": "fr", "options": ["خ", "غ", "ج", "ذ"], "answer": "خ", "acceptedAnswers": ["خ"], "explanation": "ح + 1 point dessus = خ : le h appuyé devient le ch de Bach. Avec 1 point dessous, ce serait ج.", "tip": "Le crochet avec un chapeau (le point dessus).", "extraExample": {"text": "خ", "translation": "khâ : le ch allemand de Bach, 1 point dessus."}, "errorPatterns": [{"equals": "ج", "category": "word_confusion", "feedback": "ج a son point dans le creux, donc dessous."}], "pool": "lesson", "lessonId": "ar.l08", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e21', 'ar', 'ar.l08', 'ar.v.ha', array['ar.v.ha','ar.v.kha','ar.v.jim','ar.v.ya','ar.v.shin','ar.g08.letters8']::text[], 'match', 'lesson', 'Relie chaque lettre à son nombre de points.', '{}'::text[], 'Cinq lettres, cinq cartes d''identité : le nombre ET la place des points décident.', 3, '{"id": "ar.l08.e21", "unitIds": ["ar.v.ha", "ar.v.kha", "ar.v.jim", "ar.v.ya", "ar.v.shin", "ar.g08.letters8"], "type": "match", "difficulty": 3, "instruction": "Relie chaque élément à son associé.", "prompt": "Relie chaque lettre à son nombre de points.", "promptLanguage": "fr", "pairs": [{"left": "ح", "right": "aucun point"}, {"left": "خ", "right": "1 point dessus"}, {"left": "ج", "right": "1 point dessous"}, {"left": "ي", "right": "2 points dessous"}, {"left": "ش", "right": "3 points dessus"}], "acceptedAnswers": [], "explanation": "Cinq lettres, cinq cartes d''identité : le nombre ET la place des points décident.", "pool": "lesson", "lessonId": "ar.l08", "skill": "recognition", "answer": "ح = aucun point ; خ = 1 point dessus ; ج = 1 point dessous ; ي = 2 points dessous ; ش = 3 points dessus"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e22', 'ar', 'ar.l08', 'ar.v.dal', array['ar.v.dal','ar.v.ra','ar.v.sin','ar.v.sad','ar.v.ayn','ar.g08.letters8']::text[], 'match', 'lesson', 'Relie chaque lettre à sa jumelle à points.', '{}'::text[], 'Dans chaque paire, on ajoute des points : 1 point dessus pour ذ ز ض غ, 3 points dessus pour ش.', 4, '{"id": "ar.l08.e22", "unitIds": ["ar.v.dal", "ar.v.ra", "ar.v.sin", "ar.v.sad", "ar.v.ayn", "ar.g08.letters8"], "type": "match", "difficulty": 4, "instruction": "Relie chaque élément à son associé.", "prompt": "Relie chaque lettre à sa jumelle à points.", "promptLanguage": "fr", "pairs": [{"left": "د", "right": "ذ"}, {"left": "ر", "right": "ز"}, {"left": "س", "right": "ش"}, {"left": "ص", "right": "ض"}, {"left": "ع", "right": "غ"}], "acceptedAnswers": [], "explanation": "Dans chaque paire, on ajoute des points : 1 point dessus pour ذ ز ض غ, 3 points dessus pour ش.", "pool": "lesson", "lessonId": "ar.l08", "skill": "recognition", "answer": "د = ذ ; ر = ز ; س = ش ; ص = ض ; ع = غ"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e23', 'ar', 'ar.l08', 'ar.v.jim', array['ar.v.jim','ar.v.ha','ar.v.tah','ar.v.ayn','ar.v.ghayn','ar.g08.letters8']::text[], 'match', 'lesson', 'Relie ج, ح, ط, ع et غ à leur son.', '{}'::text[], 'g, h appuyé, t lourd, gorge serrée, r de rouge : les sons les plus exotiques de l''arabe, déjà dans ton oreille égyptienne.', 4, '{"id": "ar.l08.e23", "unitIds": ["ar.v.jim", "ar.v.ha", "ar.v.tah", "ar.v.ayn", "ar.v.ghayn", "ar.g08.letters8"], "type": "match", "difficulty": 4, "instruction": "Relie chaque élément à son associé.", "prompt": "Relie ج, ح, ط, ع et غ à leur son.", "promptLanguage": "fr", "pairs": [{"left": "ج", "right": "le g de gâteau"}, {"left": "ح", "right": "un h appuyé"}, {"left": "ط", "right": "un t lourd"}, {"left": "ع", "right": "un son de gorge serrée"}, {"left": "غ", "right": "le r de rouge"}], "acceptedAnswers": [], "explanation": "g, h appuyé, t lourd, gorge serrée, r de rouge : les sons les plus exotiques de l''arabe, déjà dans ton oreille égyptienne.", "pool": "lesson", "lessonId": "ar.l08", "skill": "recognition", "answer": "ج = le g de gâteau ; ح = un h appuyé ; ط = un t lourd ; ع = un son de gorge serrée ; غ = le r de rouge"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l08.e24', 'ar', 'ar.l08', 'ar.v.ba', array['ar.v.ba','ar.v.nun','ar.v.kha','ar.v.qaf','ar.v.lam','ar.g08.letters8']::text[], 'match', 'lesson', 'Dernier défi : relie chaque forme à sa lettre.', '{}'::text[], 'Forme d''abord, points ensuite : c''est la méthode pour lire vite, lettre par lettre.', 4, '{"id": "ar.l08.e24", "unitIds": ["ar.v.ba", "ar.v.nun", "ar.v.kha", "ar.v.qaf", "ar.v.lam", "ar.g08.letters8"], "type": "match", "difficulty": 4, "instruction": "Relie chaque élément à son associé.", "prompt": "Dernier défi : relie chaque forme à sa lettre.", "promptLanguage": "fr", "pairs": [{"left": "une barque avec 1 point dessous", "right": "ب"}, {"left": "un bol avec 1 point dessus", "right": "ن"}, {"left": "un crochet coiffé d''un chapeau", "right": "خ"}, {"left": "une tête ronde et 2 points dessus", "right": "ق"}, {"left": "un bâton avec un pied", "right": "ل"}], "acceptedAnswers": [], "explanation": "Forme d''abord, points ensuite : c''est la méthode pour lire vite, lettre par lettre.", "pool": "lesson", "lessonId": "ar.l08", "skill": "recognition", "answer": "une barque avec 1 point dessous = ب ; un bol avec 1 point dessus = ن ; un crochet coiffé d''un chapeau = خ ; une tête ronde et 2 points dessus = ق ; un bâton avec un pied = ل"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e01', 'ar', 'ar.l09', 'ar.g09.forms_ba_family', array['ar.g09.forms_ba_family','ar.v.ba']::text[], 'mcq', 'lesson', 'Laquelle de ces formes est la forme du début de ب ?', array['بـ']::text[], 'La forme du début s''accroche à la lettre qui suit, donc le trait ـ est à gauche : بـ.', 1, '{"id": "ar.l09.e01", "type": "mcq", "unitIds": ["ar.g09.forms_ba_family", "ar.v.ba"], "difficulty": 1, "instruction": "Choisis la bonne forme.", "prompt": "Laquelle de ces formes est la forme du début de ب ?", "promptLanguage": "fr", "answer": "بـ", "acceptedAnswers": ["بـ"], "explanation": "La forme du début s''accroche à la lettre qui suit, donc le trait ـ est à gauche : بـ.", "tip": "Début = trait à gauche, fin = trait à droite.", "extraExample": {"text": "بيت", "translation": "maison"}, "errorPatterns": [{"equals": "ـبـ", "category": "instruction", "feedback": "ـبـ a le trait des deux côtés : c''est la forme du milieu."}, {"equals": "ـب", "category": "instruction", "feedback": "ـب a le trait à droite : c''est la forme de la fin."}, {"equals": "ب", "category": "instruction", "feedback": "ب sans trait est la forme isolée."}], "options": ["بـ", "ـبـ", "ـب", "ب"], "pool": "lesson", "lessonId": "ar.l09", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e02', 'ar', 'ar.l09', 'ar.g09.forms_ba_family', array['ar.g09.forms_ba_family','ar.v.ba']::text[], 'mcq', 'lesson', 'Quelle forme de ب vois-tu ici : ـبـ ?', array['forme du milieu']::text[], 'Le trait ـ de chaque côté montre que la lettre s''accroche à gauche et à droite : c''est la forme du milieu.', 1, '{"id": "ar.l09.e02", "type": "mcq", "unitIds": ["ar.g09.forms_ba_family", "ar.v.ba"], "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle forme de ب vois-tu ici : ـبـ ?", "promptLanguage": "fr", "answer": "forme du milieu", "acceptedAnswers": ["forme du milieu"], "explanation": "Le trait ـ de chaque côté montre que la lettre s''accroche à gauche et à droite : c''est la forme du milieu.", "tip": "Deux traits = milieu.", "extraExample": {"text": "نبي", "translation": "prophète"}, "errorPatterns": [{"equals": "forme isolée", "category": "instruction", "feedback": "Sans trait ـ, la lettre est seule : c''est la forme isolée."}, {"equals": "forme du début", "category": "instruction", "feedback": "Le trait ـ est à gauche, vers la lettre suivante : c''est la forme du début."}, {"equals": "forme de la fin", "category": "instruction", "feedback": "Le trait ـ est à droite, vers la lettre précédente : c''est la forme de la fin."}], "options": ["forme isolée", "forme du début", "forme du milieu", "forme de la fin"], "pool": "lesson", "lessonId": "ar.l09", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e03', 'ar', 'ar.l09', 'ar.g09.forms_ba_family', array['ar.g09.forms_ba_family','ar.v.bayt']::text[], 'mcq', 'lesson', 'بيت', array['maison']::text[], 'Lettre par lettre : ب (1 point dessous), ي (2 points dessous), ت (2 points dessus) donne بيت, « maison ». Les deux points sous le ي du milieu séparent بيت de بنت.', 2, '{"id": "ar.l09.e03", "type": "mcq", "unitIds": ["ar.g09.forms_ba_family", "ar.v.bayt"], "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "بيت", "promptLanguage": "ar", "answer": "maison", "acceptedAnswers": ["maison"], "explanation": "Lettre par lettre : ب (1 point dessous), ي (2 points dessous), ت (2 points dessus) donne بيت, « maison ». Les deux points sous le ي du milieu séparent بيت de بنت.", "tip": "Lis de droite à gauche, lettre après lettre, puis dis le mot à voix haute.", "extraExample": {"text": "بيتنا قريب من الكنيسة.", "translation": "Notre maison est près de l''église."}, "errorPatterns": [{"equals": "fille", "category": "word_confusion", "feedback": "« fille » s''écrit بنت (ب + ن + ت). Ici tu lis ب + ي + ت : بيت veut dire « maison »."}, {"equals": "figues", "category": "word_confusion", "feedback": "« figues » s''écrit تين (ت + ي + ن). Ici tu lis ب + ي + ت : بيت veut dire « maison »."}, {"equals": "entre", "category": "word_confusion", "feedback": "« entre » s''écrit بين (ب + ي + ن). Ici tu lis ب + ي + ت : بيت veut dire « maison »."}], "options": ["maison", "fille", "figues", "entre"], "pool": "lesson", "lessonId": "ar.l09", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e04', 'ar', 'ar.l09', 'ar.g09.forms_ba_family', array['ar.g09.forms_ba_family','ar.v.bint']::text[], 'mcq', 'lesson', 'بنت', array['fille']::text[], 'Lettre par lettre : ب (1 point dessous), ن (1 point dessus), ت (2 points dessus) donne بنت, « fille ». Au milieu, un seul point dessus : ـنـ.', 2, '{"id": "ar.l09.e04", "type": "mcq", "unitIds": ["ar.g09.forms_ba_family", "ar.v.bint"], "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "بنت", "promptLanguage": "ar", "answer": "fille", "acceptedAnswers": ["fille"], "explanation": "Lettre par lettre : ب (1 point dessous), ن (1 point dessus), ت (2 points dessus) donne بنت, « fille ». Au milieu, un seul point dessus : ـنـ.", "tip": "Lis de droite à gauche, lettre après lettre, puis dis le mot à voix haute.", "extraExample": {"text": "البنت دي شاطرة.", "translation": "Cette fille est douée."}, "hint": "Regarde les points de la lettre du milieu.", "errorPatterns": [{"equals": "maison", "category": "word_confusion", "feedback": "« maison » s''écrit بيت (ب + ي + ت). Ici tu lis ب + ن + ت : بنت veut dire « fille »."}, {"equals": "prophète", "category": "word_confusion", "feedback": "« prophète » s''écrit نبي (ن + ب + ي). Ici tu lis ب + ن + ت : بنت veut dire « fille »."}, {"equals": "dragon", "category": "word_confusion", "feedback": "« dragon » s''écrit تنين (ت + ن + ي + ن). Ici tu lis ب + ن + ت : بنت veut dire « fille »."}], "options": ["fille", "maison", "prophète", "dragon"], "pool": "lesson", "lessonId": "ar.l09", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e05', 'ar', 'ar.l09', 'ar.g09.forms_ba_family', array['ar.g09.forms_ba_family','ar.v.tin']::text[], 'mcq', 'lesson', 'Quel mot veut dire « figues » ?', array['تين']::text[], '« figues » s''écrit ت + ي + ن : تين. Trois dents de suite : ت (2 points dessus), ي (2 points dessous), ن (1 point dessus).', 2, '{"id": "ar.l09.e05", "type": "mcq", "unitIds": ["ar.g09.forms_ba_family", "ar.v.tin"], "difficulty": 2, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « figues » ?", "promptLanguage": "fr", "answer": "تين", "acceptedAnswers": ["تين"], "explanation": "« figues » s''écrit ت + ي + ن : تين. Trois dents de suite : ت (2 points dessus), ي (2 points dessous), ن (1 point dessus).", "tip": "Compare les points et les attaches, lettre par lettre.", "extraExample": {"text": "عايز كيلو تين.", "translation": "Je voudrais un kilo de figues."}, "errorPatterns": [{"equals": "بين", "category": "word_confusion", "feedback": "بين (ب + ي + ن) veut dire « entre ». Pour « figues », il faut ت + ي + ن : تين."}, {"equals": "بنت", "category": "word_confusion", "feedback": "بنت (ب + ن + ت) veut dire « fille ». Pour « figues », il faut ت + ي + ن : تين."}, {"equals": "تنين", "category": "word_confusion", "feedback": "تنين (ت + ن + ي + ن) veut dire « dragon ». Pour « figues », il faut ت + ي + ن : تين."}], "options": ["تين", "بين", "بنت", "تنين"], "pool": "lesson", "lessonId": "ar.l09", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e06', 'ar', 'ar.l09', 'ar.g09.forms_ba_family', array['ar.g09.forms_ba_family','ar.v.bayt']::text[], 'mcq', 'lesson', 'Dans بيت, quelle forme prend la lettre ي ?', array['forme du milieu']::text[], 'Le ي est entre le ب et le ت : il s''accroche des deux côtés, donc il prend la forme du milieu ـيـ.', 3, '{"id": "ar.l09.e06", "type": "mcq", "unitIds": ["ar.g09.forms_ba_family", "ar.v.bayt"], "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Dans بيت, quelle forme prend la lettre ي ?", "promptLanguage": "fr", "answer": "forme du milieu", "acceptedAnswers": ["forme du milieu"], "explanation": "Le ي est entre le ب et le ت : il s''accroche des deux côtés, donc il prend la forme du milieu ـيـ.", "tip": "Une lettre entourée de deux lettres attachées prend la forme du milieu.", "extraExample": {"text": "بنت", "translation": "fille"}, "errorPatterns": [{"equals": "forme isolée", "category": "instruction", "feedback": "Sans trait ـ, la lettre est seule : c''est la forme isolée."}, {"equals": "forme du début", "category": "instruction", "feedback": "Le trait ـ est à gauche, vers la lettre suivante : c''est la forme du début."}, {"equals": "forme de la fin", "category": "instruction", "feedback": "Le trait ـ est à droite, vers la lettre précédente : c''est la forme de la fin."}], "options": ["forme isolée", "forme du début", "forme du milieu", "forme de la fin"], "pool": "lesson", "lessonId": "ar.l09", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e07', 'ar', 'ar.l09', 'ar.g09.forms_ba_family', array['ar.g09.forms_ba_family','ar.v.bint']::text[], 'mcq', 'lesson', 'Dans بنت, quelle forme prend la dernière lettre, ت ?', array['forme de la fin']::text[], 'Le ت termine le mot et s''accroche seulement à la lettre d''avant : c''est la forme de la fin ـت.', 3, '{"id": "ar.l09.e07", "type": "mcq", "unitIds": ["ar.g09.forms_ba_family", "ar.v.bint"], "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Dans بنت, quelle forme prend la dernière lettre, ت ?", "promptLanguage": "fr", "answer": "forme de la fin", "acceptedAnswers": ["forme de la fin"], "explanation": "Le ت termine le mot et s''accroche seulement à la lettre d''avant : c''est la forme de la fin ـت.", "tip": "La dernière lettre d''un bloc attaché prend la forme de la fin.", "extraExample": {"text": "بيت", "translation": "maison"}, "errorPatterns": [{"equals": "forme isolée", "category": "instruction", "feedback": "Sans trait ـ, la lettre est seule : c''est la forme isolée."}, {"equals": "forme du début", "category": "instruction", "feedback": "Le trait ـ est à gauche, vers la lettre suivante : c''est la forme du début."}, {"equals": "forme du milieu", "category": "instruction", "feedback": "Un trait ـ de chaque côté : c''est la forme du milieu."}], "options": ["forme isolée", "forme du début", "forme du milieu", "forme de la fin"], "pool": "lesson", "lessonId": "ar.l09", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e08', 'ar', 'ar.l09', 'ar.g09.forms_ba_family', array['ar.g09.forms_ba_family','ar.v.ya']::text[], 'mcq', 'lesson', 'Au milieu d''un mot, laquelle de ces dents a deux points dessous ?', array['ـيـ']::text[], 'Deux points dessous : c''est le ي. ـبـ en a un seul dessous, ـتـ en a deux mais dessus, ـنـ en a un dessus.', 3, '{"id": "ar.l09.e08", "type": "mcq", "unitIds": ["ar.g09.forms_ba_family", "ar.v.ya"], "difficulty": 3, "instruction": "Choisis la bonne dent.", "prompt": "Au milieu d''un mot, laquelle de ces dents a deux points dessous ?", "promptLanguage": "fr", "answer": "ـيـ", "acceptedAnswers": ["ـيـ"], "explanation": "Deux points dessous : c''est le ي. ـبـ en a un seul dessous, ـتـ en a deux mais dessus, ـنـ en a un dessus.", "tip": "Dessous ou dessus ? Un, deux ou trois ? Compte toujours.", "extraExample": {"text": "بيت", "translation": "maison"}, "errorPatterns": [{"equals": "ـبـ", "category": "spelling", "feedback": "ـبـ n''a qu''un point dessous."}, {"equals": "ـتـ", "category": "spelling", "feedback": "ـتـ a deux points, mais dessus."}, {"equals": "ـنـ", "category": "spelling", "feedback": "ـنـ n''a qu''un point, dessus."}], "options": ["ـبـ", "ـتـ", "ـنـ", "ـيـ"], "pool": "lesson", "lessonId": "ar.l09", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e09', 'ar', 'ar.l09', 'ar.g09.forms_ba_family', array['ar.g09.forms_ba_family','ar.v.bayt']::text[], 'fill_blank', 'lesson', 'بـ___ـت', array['ي']::text[], 'Pour « maison », il faut deux points dessous au milieu : ب + ي + ت = بيت. Avec ن on lirait بنت (fille).', 2, '{"id": "ar.l09.e09", "type": "fill_blank", "unitIds": ["ar.g09.forms_ba_family", "ar.v.bayt"], "difficulty": 2, "instruction": "Quelle lettre manque pour écrire « maison » ?", "prompt": "بـ___ـت", "promptLanguage": "ar", "answer": "ي", "acceptedAnswers": ["ي"], "explanation": "Pour « maison », il faut deux points dessous au milieu : ب + ي + ت = بيت. Avec ن on lirait بنت (fille).", "tip": "Maison : deux points dessous. Fille : un point dessus.", "extraExample": {"text": "بيت", "translation": "maison"}, "errorPatterns": [{"equals": "ن", "category": "word_confusion", "feedback": "بنت veut dire « fille ». Pour « maison », le milieu a deux points dessous : ي."}], "options": ["ي", "ن", "ث", "ب"], "pool": "lesson", "lessonId": "ar.l09", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e10', 'ar', 'ar.l09', 'ar.g09.forms_ba_family', array['ar.g09.forms_ba_family','ar.v.nabi']::text[], 'fill_blank', 'lesson', 'نـ___ـي', array['ب']::text[], 'نبي s''écrit ن + ب + ي : au milieu, la dent ـبـ n''a qu''un seul point, dessous.', 3, '{"id": "ar.l09.e10", "type": "fill_blank", "unitIds": ["ar.g09.forms_ba_family", "ar.v.nabi"], "difficulty": 3, "instruction": "Complète « prophète ».", "prompt": "نـ___ـي", "promptLanguage": "ar", "answer": "ب", "acceptedAnswers": ["ب"], "explanation": "نبي s''écrit ن + ب + ي : au milieu, la dent ـبـ n''a qu''un seul point, dessous.", "tip": "Compte les points de la dent du milieu.", "extraExample": {"text": "نبي", "translation": "prophète"}, "errorPatterns": [{"equals": "ت", "category": "spelling", "feedback": "ت a deux points dessus ; ici il y a un seul point dessous : ب."}], "options": ["ب", "ت", "ن", "ث"], "pool": "lesson", "lessonId": "ar.l09", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e11', 'ar', 'ar.l09', 'ar.g09.forms_ba_family', array['ar.g09.forms_ba_family','ar.v.bint']::text[], 'fill_blank', 'lesson', 'بـنـ___', array['ت']::text[], 'بنت finit par ت : deux points dessus. ث en aurait trois, ي deux mais dessous.', 3, '{"id": "ar.l09.e11", "type": "fill_blank", "unitIds": ["ar.g09.forms_ba_family", "ar.v.bint"], "difficulty": 3, "instruction": "Complète « fille » : quelle est la dernière lettre ?", "prompt": "بـنـ___", "promptLanguage": "ar", "answer": "ت", "acceptedAnswers": ["ت"], "explanation": "بنت finit par ت : deux points dessus. ث en aurait trois, ي deux mais dessous.", "tip": "À la fin, ت a deux points dessus.", "extraExample": {"text": "بنت", "translation": "fille"}, "errorPatterns": [{"equals": "ث", "category": "spelling", "feedback": "ث a trois points dessus, ت en a deux."}, {"equals": "ي", "category": "spelling", "feedback": "ي a deux points dessous, ت deux points dessus."}], "options": ["ت", "ث", "ي", "ن"], "pool": "lesson", "lessonId": "ar.l09", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e12', 'ar', 'ar.l09', 'ar.g09.forms_ba_family', array['ar.g09.forms_ba_family','ar.v.bayt','ar.v.bint','ar.v.tin','ar.v.nabi','ar.v.bunn']::text[], 'match', 'lesson', 'Mots de la leçon', '{}'::text[], 'Lis chaque mot lettre par lettre : les points te disent qui est qui, comme بيت (maison) et بنت (fille).', 2, '{"id": "ar.l09.e12", "type": "match", "unitIds": ["ar.g09.forms_ba_family", "ar.v.bayt", "ar.v.bint", "ar.v.tin", "ar.v.nabi", "ar.v.bunn"], "difficulty": 2, "instruction": "Associe chaque mot à son sens.", "prompt": "Mots de la leçon", "promptLanguage": "fr", "answer": "بيت = maison ; بنت = fille ; تين = figues ; نبي = prophète ; بن = café (grains)", "acceptedAnswers": [], "explanation": "Lis chaque mot lettre par lettre : les points te disent qui est qui, comme بيت (maison) et بنت (fille).", "pairs": [{"left": "بيت", "right": "maison"}, {"left": "بنت", "right": "fille"}, {"left": "تين", "right": "figues"}, {"left": "نبي", "right": "prophète"}, {"left": "بن", "right": "café (grains)"}], "pool": "lesson", "lessonId": "ar.l09", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e13', 'ar', 'ar.l09', 'ar.g09.forms_ba_family', array['ar.g09.forms_ba_family','ar.v.ba','ar.v.ta','ar.v.tha','ar.v.nun','ar.v.ya']::text[], 'match', 'lesson', 'Lettre isolée et forme du début', '{}'::text[], 'La forme du début garde la lettre et ses points, et ajoute le trait ـ à gauche.', 2, '{"id": "ar.l09.e13", "type": "match", "unitIds": ["ar.g09.forms_ba_family", "ar.v.ba", "ar.v.ta", "ar.v.tha", "ar.v.nun", "ar.v.ya"], "difficulty": 2, "instruction": "Associe chaque lettre isolée à sa forme du début.", "prompt": "Lettre isolée et forme du début", "promptLanguage": "fr", "answer": "ب = بـ ; ت = تـ ; ث = ثـ ; ن = نـ ; ي = يـ", "acceptedAnswers": [], "explanation": "La forme du début garde la lettre et ses points, et ajoute le trait ـ à gauche.", "pairs": [{"left": "ب", "right": "بـ"}, {"left": "ت", "right": "تـ"}, {"left": "ث", "right": "ثـ"}, {"left": "ن", "right": "نـ"}, {"left": "ي", "right": "يـ"}], "pool": "lesson", "lessonId": "ar.l09", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e14', 'ar', 'ar.l09', 'ar.g09.forms_ba_family', array['ar.g09.forms_ba_family','ar.v.bayt','ar.v.bint','ar.v.nabi']::text[], 'match', 'lesson', 'La lettre du milieu', '{}'::text[], 'Au milieu, c''est la dent qui compte : بيت a ـيـ (2 points dessous), بنت a ـنـ (1 point dessus), نبي a ـبـ (1 point dessous).', 3, '{"id": "ar.l09.e14", "type": "match", "unitIds": ["ar.g09.forms_ba_family", "ar.v.bayt", "ar.v.bint", "ar.v.nabi"], "difficulty": 3, "instruction": "Associe chaque mot à la lettre de son milieu.", "prompt": "La lettre du milieu", "promptLanguage": "fr", "answer": "بيت = ي ; بنت = ن ; نبي = ب", "acceptedAnswers": [], "explanation": "Au milieu, c''est la dent qui compte : بيت a ـيـ (2 points dessous), بنت a ـنـ (1 point dessus), نبي a ـبـ (1 point dessous).", "pairs": [{"left": "بيت", "right": "ي"}, {"left": "بنت", "right": "ن"}, {"left": "نبي", "right": "ب"}], "pool": "lesson", "lessonId": "ar.l09", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e15', 'ar', 'ar.l09', 'ar.g09.forms_ba_family', array['ar.g09.forms_ba_family','ar.v.tinnin']::text[], 'translation', 'lesson', 'تنين', array['dragon','un dragon','le dragon']::text[], 'تنين = ت + ن + ي + ن : quatre dents, c''est le dragon. Ne le confonds pas avec تين (figues), qui a une dent de moins.', 3, '{"id": "ar.l09.e15", "type": "translation", "unitIds": ["ar.g09.forms_ba_family", "ar.v.tinnin"], "difficulty": 3, "instruction": "Écris le sens en français.", "prompt": "تنين", "promptLanguage": "ar", "answer": "dragon", "acceptedAnswers": ["dragon", "un dragon", "le dragon"], "explanation": "تنين = ت + ن + ي + ن : quatre dents, c''est le dragon. Ne le confonds pas avec تين (figues), qui a une dent de moins.", "tip": "Compte les dents : quatre pour le dragon, trois pour les figues.", "extraExample": {"text": "تنين", "translation": "dragon"}, "errorPatterns": [{"equals": "figues", "category": "word_confusion", "feedback": "تين (figues) a trois lettres ; تنين en a quatre."}], "pool": "lesson", "lessonId": "ar.l09", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e16', 'ar', 'ar.l09', 'ar.g09.forms_ba_family', array['ar.g09.forms_ba_family','ar.v.bayna']::text[], 'translation', 'lesson', 'بين', array['entre']::text[], 'بين = ب + ي + ن. Même squelette que بيت, mais avec ن à la fin : c''est « entre ».', 2, '{"id": "ar.l09.e16", "type": "translation", "unitIds": ["ar.g09.forms_ba_family", "ar.v.bayna"], "difficulty": 2, "instruction": "Écris le sens en français.", "prompt": "بين", "promptLanguage": "ar", "answer": "entre", "acceptedAnswers": ["entre"], "explanation": "بين = ب + ي + ن. Même squelette que بيت, mais avec ن à la fin : c''est « entre ».", "tip": "بين finit par ن (1 point dessus), بيت par ت (2 points dessus).", "extraExample": {"text": "بين", "translation": "entre"}, "errorPatterns": [{"equals": "maison", "category": "word_confusion", "feedback": "بيت (maison) finit par ت ; بين finit par ن."}], "pool": "lesson", "lessonId": "ar.l09", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e17', 'ar', 'ar.l09', 'ar.g09.forms_ba_family', array['ar.g09.forms_ba_family','ar.v.nabi']::text[], 'free_answer', 'lesson', 'Que veut dire نبي ?', array['prophète','prophete','un prophète','le prophète','un prophete','le prophete']::text[], 'نبي = ن + ب + ي : un prophète. Les trois lettres sont attachées en un seul bloc.', 3, '{"id": "ar.l09.e17", "type": "free_answer", "unitIds": ["ar.g09.forms_ba_family", "ar.v.nabi"], "difficulty": 3, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire نبي ?", "promptLanguage": "fr", "answer": "prophète", "acceptedAnswers": ["prophète", "prophete", "un prophète", "le prophète", "un prophete", "le prophete"], "explanation": "نبي = ن + ب + ي : un prophète. Les trois lettres sont attachées en un seul bloc.", "tip": "Lis de droite à gauche : ن, puis ب, puis ي.", "extraExample": {"text": "النبي داود كتب المزامير.", "translation": "Le prophète David a écrit les psaumes."}, "pool": "lesson", "lessonId": "ar.l09", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e18', 'ar', 'ar.l09', 'ar.g09.forms_ba_family', array['ar.g09.forms_ba_family','ar.v.bint']::text[], 'free_answer', 'lesson', 'Que veut dire بنت ?', array['fille','une fille','la fille','petite fille']::text[], 'بنت = ب + ن + ت : une fille. Le milieu ـنـ a un point dessus, pas deux points dessous.', 3, '{"id": "ar.l09.e18", "type": "free_answer", "unitIds": ["ar.g09.forms_ba_family", "ar.v.bint"], "difficulty": 3, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire بنت ?", "promptLanguage": "fr", "answer": "fille", "acceptedAnswers": ["fille", "une fille", "la fille", "petite fille"], "explanation": "بنت = ب + ن + ت : une fille. Le milieu ـنـ a un point dessus, pas deux points dessous.", "tip": "Un point dessus au milieu : c''est بنت.", "extraExample": {"text": "عندي بنتين.", "translation": "J''ai deux filles."}, "errorPatterns": [{"equals": "maison", "category": "word_confusion", "feedback": "maison = بيت : deux points dessous au milieu. Ici le milieu a un point dessus."}], "pool": "lesson", "lessonId": "ar.l09", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e19', 'ar', 'ar.l09', 'ar.v.ya', array['ar.v.ya']::text[], 'mcq', 'lesson', 'Laquelle de ces lettres a ses deux points sous la barque ?', array['ي']::text[], 'ي a deux points sous sa courbe. ب n''en a qu''un dessous, ت en a deux mais dessus, ن un seul dessus.', 1, '{"id": "ar.l09.e19", "type": "mcq", "unitIds": ["ar.v.ya"], "difficulty": 1, "instruction": "Choisis la bonne lettre.", "prompt": "Laquelle de ces lettres a ses deux points sous la barque ?", "promptLanguage": "fr", "answer": "ي", "acceptedAnswers": ["ي"], "explanation": "ي a deux points sous sa courbe. ب n''en a qu''un dessous, ت en a deux mais dessus, ن un seul dessus.", "tip": "Dessous ou dessus, un, deux ou trois : compte toujours.", "extraExample": {"text": "بيت", "translation": "maison"}, "errorPatterns": [{"equals": "ب", "category": "spelling", "feedback": "ب n''a qu''un point, dessous."}, {"equals": "ت", "category": "spelling", "feedback": "ت a deux points, mais dessus."}, {"equals": "ن", "category": "spelling", "feedback": "ن n''a qu''un point, dessus."}], "options": ["ب", "ت", "ي", "ن"], "pool": "lesson", "lessonId": "ar.l09", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e20', 'ar', 'ar.l09', 'ar.v.tha', array['ar.v.tha']::text[], 'mcq', 'lesson', 'Laquelle de ces lettres est coiffée de trois points ?', array['ث']::text[], 'ث porte trois points au-dessus : c''est la seule de la famille ب ت ث ن ي à en avoir trois.', 1, '{"id": "ar.l09.e20", "type": "mcq", "unitIds": ["ar.v.tha"], "difficulty": 1, "instruction": "Choisis la bonne lettre.", "prompt": "Laquelle de ces lettres est coiffée de trois points ?", "promptLanguage": "fr", "answer": "ث", "acceptedAnswers": ["ث"], "explanation": "ث porte trois points au-dessus : c''est la seule de la famille ب ت ث ن ي à en avoir trois.", "tip": "Trois points dessus = ث.", "extraExample": {"text": "ثلاثة", "translation": "trois"}, "errorPatterns": [{"equals": "ت", "category": "spelling", "feedback": "ت n''a que deux points."}, {"equals": "ن", "category": "spelling", "feedback": "ن n''a qu''un point."}, {"equals": "ي", "category": "spelling", "feedback": "ي a deux points, dessous."}], "options": ["ث", "ت", "ن", "ي"], "pool": "lesson", "lessonId": "ar.l09", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e21', 'ar', 'ar.l09', 'ar.v.alif', array['ar.v.alif']::text[], 'mcq', 'lesson', 'Parmi ces lettres, laquelle n''a aucun point ?', array['ا']::text[], 'ا (alif) est un simple bâton, sans point. ب, ث et ي portent des points.', 1, '{"id": "ar.l09.e21", "type": "mcq", "unitIds": ["ar.v.alif"], "difficulty": 1, "instruction": "Choisis la bonne lettre.", "prompt": "Parmi ces lettres, laquelle n''a aucun point ?", "promptLanguage": "fr", "answer": "ا", "acceptedAnswers": ["ا"], "explanation": "ا (alif) est un simple bâton, sans point. ب, ث et ي portent des points.", "tip": "Un bâton tout droit, sans point : c''est l''alif.", "extraExample": {"text": "باب", "translation": "porte"}, "errorPatterns": [{"equals": "ب", "category": "spelling", "feedback": "ب a un point dessous."}, {"equals": "ث", "category": "spelling", "feedback": "ث a trois points dessus."}, {"equals": "ي", "category": "spelling", "feedback": "ي a deux points dessous."}], "options": ["ب", "ا", "ث", "ي"], "pool": "lesson", "lessonId": "ar.l09", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l09.e22', 'ar', 'ar.l09', 'ar.v.ba', array['ar.v.ba','ar.v.ta','ar.v.tha','ar.v.nun','ar.v.ya']::text[], 'match', 'lesson', 'Les points des lettres ب ت ث ن ي', '{}'::text[], 'Les points font la différence entre ces cinq lettres qui ont la même dent.', 2, '{"id": "ar.l09.e22", "type": "match", "unitIds": ["ar.v.ba", "ar.v.ta", "ar.v.tha", "ar.v.nun", "ar.v.ya"], "difficulty": 2, "instruction": "Associe chaque lettre à ses points.", "prompt": "Les points des lettres ب ت ث ن ي", "promptLanguage": "fr", "answer": "ب = 1 point dessous ; ت = 2 points dessus ; ث = 3 points dessus ; ن = 1 point dessus ; ي = 2 points dessous", "acceptedAnswers": [], "explanation": "Les points font la différence entre ces cinq lettres qui ont la même dent.", "pairs": [{"left": "ب", "right": "1 point dessous"}, {"left": "ت", "right": "2 points dessus"}, {"left": "ث", "right": "3 points dessus"}, {"left": "ن", "right": "1 point dessus"}, {"left": "ي", "right": "2 points dessous"}], "pool": "lesson", "lessonId": "ar.l09", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e01', 'ar', 'ar.l10', 'ar.g10.letters_that_do_not_connect', array['ar.g10.letters_that_do_not_connect','ar.v.alif']::text[], 'mcq', 'lesson', 'Laquelle de ces lettres ne s''attache jamais à la lettre suivante ?', array['ا']::text[], 'ا fait partie des six lettres ا د ذ ر ز و qui lâchent la main : le mot se coupe après elle. ب, ت et ن, elles, s''attachent.', 1, '{"id": "ar.l10.e01", "type": "mcq", "unitIds": ["ar.g10.letters_that_do_not_connect", "ar.v.alif"], "difficulty": 1, "instruction": "Choisis la bonne lettre.", "prompt": "Laquelle de ces lettres ne s''attache jamais à la lettre suivante ?", "promptLanguage": "fr", "answer": "ا", "acceptedAnswers": ["ا"], "explanation": "ا fait partie des six lettres ا د ذ ر ز و qui lâchent la main : le mot se coupe après elle. ب, ت et ن, elles, s''attachent.", "tip": "ا د ذ ر ز و : six lettres à retenir.", "extraExample": {"text": "باب", "translation": "porte"}, "errorPatterns": [{"equals": "ب", "category": "instruction", "feedback": "ب s''attache à la lettre suivante (بـ)."}, {"equals": "ت", "category": "instruction", "feedback": "ت s''attache à la lettre suivante (تـ)."}, {"equals": "ن", "category": "instruction", "feedback": "ن s''attache à la lettre suivante (نـ)."}], "options": ["ا", "ب", "ت", "ن"], "pool": "lesson", "lessonId": "ar.l10", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e02', 'ar', 'ar.l10', 'ar.g10.letters_that_do_not_connect', array['ar.g10.letters_that_do_not_connect','ar.v.dal']::text[], 'mcq', 'lesson', 'Laquelle de ces formes n''existe pas pour la lettre د ?', array['forme du début']::text[], 'د ne s''accroche pas à la lettre suivante : elle n''a donc pas de forme du début (ni du milieu). Il lui reste la forme isolée د et la forme de la fin ـد.', 2, '{"id": "ar.l10.e02", "type": "mcq", "unitIds": ["ar.g10.letters_that_do_not_connect", "ar.v.dal"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Laquelle de ces formes n''existe pas pour la lettre د ?", "promptLanguage": "fr", "answer": "forme du début", "acceptedAnswers": ["forme du début"], "explanation": "د ne s''accroche pas à la lettre suivante : elle n''a donc pas de forme du début (ni du milieu). Il lui reste la forme isolée د et la forme de la fin ـد.", "tip": "Pas d''attache vers la suivante = pas de forme du début.", "extraExample": {"text": "ورد", "translation": "fleurs"}, "errorPatterns": [{"equals": "forme isolée", "category": "instruction", "feedback": "د existe seule : c''est sa forme isolée."}, {"equals": "forme de la fin", "category": "instruction", "feedback": "ـد existe : c''est la forme de la fin, attachée à la lettre d''avant."}], "options": ["forme isolée", "forme du début", "forme de la fin"], "pool": "lesson", "lessonId": "ar.l10", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e03', 'ar', 'ar.l10', 'ar.g10.letters_that_do_not_connect', array['ar.g10.letters_that_do_not_connect','ar.v.bab']::text[], 'mcq', 'lesson', 'Combien de blocs compte باب ?', array['2 blocs']::text[], 'باب = با | ب : 2 blocs. Le mot se coupe après ا.', 2, '{"id": "ar.l10.e03", "type": "mcq", "unitIds": ["ar.g10.letters_that_do_not_connect", "ar.v.bab"], "difficulty": 2, "instruction": "Compte les blocs.", "prompt": "Combien de blocs compte باب ?", "promptLanguage": "fr", "answer": "2 blocs", "acceptedAnswers": ["2 blocs"], "explanation": "باب = با | ب : 2 blocs. Le mot se coupe après ا.", "tip": "Après chaque ا د ذ ر ز و, un nouveau bloc commence.", "extraExample": {"text": "باب", "translation": "porte"}, "errorPatterns": [{"equals": "1 bloc", "category": "instruction", "feedback": "Tu as oublié une coupure : seules ا د ذ ر ز و ne s''attachent pas à la suivante. Ici : با | ب."}, {"equals": "3 blocs", "category": "instruction", "feedback": "Tu as coupé trop de fois : seules ا د ذ ر ز و ne s''attachent pas à la suivante. Ici : با | ب."}, {"equals": "4 blocs", "category": "instruction", "feedback": "Tu as coupé trop de fois : seules ا د ذ ر ز و ne s''attachent pas à la suivante. Ici : با | ب."}], "options": ["1 bloc", "2 blocs", "3 blocs", "4 blocs"], "pool": "lesson", "lessonId": "ar.l10", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e04', 'ar', 'ar.l10', 'ar.g10.letters_that_do_not_connect', array['ar.g10.letters_that_do_not_connect','ar.v.bab']::text[], 'mcq', 'lesson', 'Dans باب, quelle forme prend la lettre ا ?', array['forme de la fin']::text[], 'Dans باب (blocs : با | ب), la lettre ا s''accroche seulement à la lettre d''avant : c''est la forme de la fin. Le ا est la dernière lettre de son bloc : forme de la fin ـا.', 2, '{"id": "ar.l10.e04", "type": "mcq", "unitIds": ["ar.g10.letters_that_do_not_connect", "ar.v.bab"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Dans باب, quelle forme prend la lettre ا ?", "promptLanguage": "fr", "answer": "forme de la fin", "acceptedAnswers": ["forme de la fin"], "explanation": "Dans باب (blocs : با | ب), la lettre ا s''accroche seulement à la lettre d''avant : c''est la forme de la fin. Le ا est la dernière lettre de son bloc : forme de la fin ـا.", "tip": "Regarde si la lettre s''accroche à celle d''avant (à droite) et à celle d''après (à gauche).", "extraExample": {"text": "باب", "translation": "porte"}, "errorPatterns": [{"equals": "forme isolée", "category": "instruction", "feedback": "Sans trait ـ, la lettre est seule : c''est la forme isolée."}, {"equals": "forme du début", "category": "instruction", "feedback": "Le trait ـ est à gauche, vers la lettre suivante : c''est la forme du début."}, {"equals": "forme du milieu", "category": "instruction", "feedback": "Un trait ـ de chaque côté : c''est la forme du milieu."}], "options": ["forme isolée", "forme du début", "forme du milieu", "forme de la fin"], "pool": "lesson", "lessonId": "ar.l10", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e05', 'ar', 'ar.l10', 'ar.g10.letters_that_do_not_connect', array['ar.g10.letters_that_do_not_connect','ar.v.baba']::text[], 'mcq', 'lesson', 'Dans بابا, quelle forme prend le deuxième ب ?', array['forme du début']::text[], 'Dans بابا (blocs : با | با), le deuxième ب s''accroche à la lettre qui la suit, pas à celle d''avant : c''est la forme du début. Il repart à neuf après le premier ا et s''accroche au dernier : forme du début بـ.', 3, '{"id": "ar.l10.e05", "type": "mcq", "unitIds": ["ar.g10.letters_that_do_not_connect", "ar.v.baba"], "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Dans بابا, quelle forme prend le deuxième ب ?", "promptLanguage": "fr", "answer": "forme du début", "acceptedAnswers": ["forme du début"], "explanation": "Dans بابا (blocs : با | با), le deuxième ب s''accroche à la lettre qui la suit, pas à celle d''avant : c''est la forme du début. Il repart à neuf après le premier ا et s''accroche au dernier : forme du début بـ.", "tip": "Regarde si la lettre s''accroche à celle d''avant (à droite) et à celle d''après (à gauche).", "extraExample": {"text": "بابا", "translation": "papa"}, "errorPatterns": [{"equals": "forme isolée", "category": "instruction", "feedback": "Sans trait ـ, la lettre est seule : c''est la forme isolée."}, {"equals": "forme du milieu", "category": "instruction", "feedback": "Un trait ـ de chaque côté : c''est la forme du milieu."}, {"equals": "forme de la fin", "category": "instruction", "feedback": "Le trait ـ est à droite, vers la lettre précédente : c''est la forme de la fin."}], "options": ["forme isolée", "forme du début", "forme du milieu", "forme de la fin"], "pool": "lesson", "lessonId": "ar.l10", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e06', 'ar', 'ar.l10', 'ar.g10.letters_that_do_not_connect', array['ar.g10.letters_that_do_not_connect','ar.v.baba']::text[], 'mcq', 'lesson', 'بابا', array['papa']::text[], 'Lettre par lettre : ب (1 point dessous), ا (sans point), ب (1 point dessous), ا (sans point) donne بابا, « papa ». Deux fois ب + ا : 2 blocs, با | با.', 2, '{"id": "ar.l10.e06", "type": "mcq", "unitIds": ["ar.g10.letters_that_do_not_connect", "ar.v.baba"], "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "بابا", "promptLanguage": "ar", "answer": "papa", "acceptedAnswers": ["papa"], "explanation": "Lettre par lettre : ب (1 point dessous), ا (sans point), ب (1 point dessous), ا (sans point) donne بابا, « papa ». Deux fois ب + ا : 2 blocs, با | با.", "tip": "Lis de droite à gauche, lettre après lettre, puis dis le mot à voix haute.", "extraExample": {"text": "بابا راجع من الشغل.", "translation": "Papa rentre du travail."}, "errorPatterns": [{"equals": "porte", "category": "word_confusion", "feedback": "« porte » s''écrit باب (ب + ا + ب). Ici tu lis ب + ا + ب + ا : بابا veut dire « papa »."}, {"equals": "prophète", "category": "word_confusion", "feedback": "« prophète » s''écrit نبي (ن + ب + ي). Ici tu lis ب + ا + ب + ا : بابا veut dire « papa »."}, {"equals": "fille", "category": "word_confusion", "feedback": "« fille » s''écrit بنت (ب + ن + ت). Ici tu lis ب + ا + ب + ا : بابا veut dire « papa »."}], "options": ["papa", "porte", "prophète", "fille"], "pool": "lesson", "lessonId": "ar.l10", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e07', 'ar', 'ar.l10', 'ar.g10.letters_that_do_not_connect', array['ar.g10.letters_that_do_not_connect','ar.v.nabawat']::text[], 'mcq', 'lesson', 'نبوات', array['prophéties']::text[], 'Lettre par lettre : ن (1 point dessus), ب (1 point dessous), و (sans point), ا (sans point), ت (2 points dessus) donne نبوات, « prophéties ». 3 blocs : نبو | ا | ت. Le ت repart seul après le ا.', 3, '{"id": "ar.l10.e07", "type": "mcq", "unitIds": ["ar.g10.letters_that_do_not_connect", "ar.v.nabawat"], "difficulty": 3, "instruction": "Lis le mot et choisis son sens.", "prompt": "نبوات", "promptLanguage": "ar", "answer": "prophéties", "acceptedAnswers": ["prophéties"], "explanation": "Lettre par lettre : ن (1 point dessus), ب (1 point dessous), و (sans point), ا (sans point), ت (2 points dessus) donne نبوات, « prophéties ». 3 blocs : نبو | ا | ت. Le ت repart seul après le ا.", "tip": "Lis de droite à gauche, lettre après lettre, puis dis le mot à voix haute.", "extraExample": {"text": "النبوات بتتقرا في الجمعة العظيمة.", "translation": "Les prophéties sont lues le Vendredi saint."}, "hint": "Trois blocs : نبو | ا | ت.", "errorPatterns": [{"equals": "prophète", "category": "word_confusion", "feedback": "« prophète » s''écrit نبي (ن + ب + ي). Ici tu lis ن + ب + و + ا + ت : نبوات veut dire « prophéties »."}, {"equals": "fleurs", "category": "word_confusion", "feedback": "« fleurs » s''écrit ورد (و + ر + د). Ici tu lis ن + ب + و + ا + ت : نبوات veut dire « prophéties »."}, {"equals": "faute", "category": "word_confusion", "feedback": "« faute » s''écrit ذنب (ذ + ن + ب). Ici tu lis ن + ب + و + ا + ت : نبوات veut dire « prophéties »."}], "options": ["prophéties", "prophète", "fleurs", "faute"], "pool": "lesson", "lessonId": "ar.l10", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e08', 'ar', 'ar.l10', 'ar.g10.letters_that_do_not_connect', array['ar.g10.letters_that_do_not_connect','ar.v.abouna']::text[], 'mcq', 'lesson', 'Quel mot veut dire « notre père (le prêtre) » ?', array['أبونا']::text[], '« notre père (le prêtre) » s''écrit أ + ب + و + ن + ا : أبونا. Le ا du début porte un petit ء : on le lit comme un alif. 3 blocs : أ | بو | نا.', 3, '{"id": "ar.l10.e08", "type": "mcq", "unitIds": ["ar.g10.letters_that_do_not_connect", "ar.v.abouna"], "difficulty": 3, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « notre père (le prêtre) » ?", "promptLanguage": "fr", "answer": "أبونا", "acceptedAnswers": ["أبونا"], "explanation": "« notre père (le prêtre) » s''écrit أ + ب + و + ن + ا : أبونا. Le ا du début porte un petit ء : on le lit comme un alif. 3 blocs : أ | بو | نا.", "tip": "Compare les points et les attaches, lettre par lettre.", "extraExample": {"text": "صلي عشاني يا أبونا.", "translation": "Prie pour moi, mon père."}, "errorPatterns": [{"equals": "ربنا", "category": "word_confusion", "feedback": "ربنا (ر + ب + ن + ا) veut dire « notre Seigneur ». Pour « notre père (le prêtre) », il faut أ + ب + و + ن + ا : أبونا."}, {"equals": "نبوات", "category": "word_confusion", "feedback": "نبوات (ن + ب + و + ا + ت) veut dire « prophéties ». Pour « notre père (le prêtre) », il faut أ + ب + و + ن + ا : أبونا."}, {"equals": "ورد", "category": "word_confusion", "feedback": "ورد (و + ر + د) veut dire « fleurs ». Pour « notre père (le prêtre) », il faut أ + ب + و + ن + ا : أبونا."}], "options": ["أبونا", "ربنا", "نبوات", "ورد"], "pool": "lesson", "lessonId": "ar.l10", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e09', 'ar', 'ar.l10', 'ar.v.bayt', array['ar.v.bayt']::text[], 'mcq', 'lesson', 'Quel mot veut dire « maison » ?', array['بيت']::text[], '« maison » s''écrit ب + ي + ت : بيت. بنت (fille) a un point dessus au milieu ; باب (porte) a un ا qui coupe le mot.', 1, '{"id": "ar.l10.e09", "type": "mcq", "unitIds": ["ar.v.bayt"], "difficulty": 1, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « maison » ?", "promptLanguage": "fr", "answer": "بيت", "acceptedAnswers": ["بيت"], "explanation": "« maison » s''écrit ب + ي + ت : بيت. بنت (fille) a un point dessus au milieu ; باب (porte) a un ا qui coupe le mot.", "tip": "Deux points dessous au milieu : la maison.", "extraExample": {"text": "بيتنا قريب من الكنيسة.", "translation": "Notre maison est près de l''église."}, "errorPatterns": [{"equals": "بنت", "category": "word_confusion", "feedback": "بنت veut dire « fille » : ـنـ a un point dessus."}, {"equals": "بين", "category": "word_confusion", "feedback": "بين veut dire « entre » : elle finit par ن."}, {"equals": "باب", "category": "word_confusion", "feedback": "باب veut dire « porte » : le ا coupe le mot."}], "options": ["بيت", "بنت", "بين", "باب"], "pool": "lesson", "lessonId": "ar.l10", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e10', 'ar', 'ar.l10', 'ar.v.tinnin', array['ar.v.tinnin']::text[], 'mcq', 'lesson', 'Quel mot veut dire « dragon » ?', array['تنين']::text[], 'Le dragon a quatre dents : ت + ن + ي + ن. تين (figues) en a trois.', 2, '{"id": "ar.l10.e10", "type": "mcq", "unitIds": ["ar.v.tinnin"], "difficulty": 2, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « dragon » ?", "promptLanguage": "fr", "answer": "تنين", "acceptedAnswers": ["تنين"], "explanation": "Le dragon a quatre dents : ت + ن + ي + ن. تين (figues) en a trois.", "tip": "Compte les dents.", "extraExample": {"text": "مارجرجس قتل التنين.", "translation": "Saint Georges a tué le dragon."}, "errorPatterns": [{"equals": "تين", "category": "word_confusion", "feedback": "تين veut dire « figues » : il y a une dent de moins."}, {"equals": "بين", "category": "word_confusion", "feedback": "بين veut dire « entre »."}, {"equals": "نبي", "category": "word_confusion", "feedback": "نبي veut dire « prophète »."}], "options": ["تنين", "تين", "بين", "نبي"], "pool": "lesson", "lessonId": "ar.l10", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e11', 'ar', 'ar.l10', 'ar.v.ta', array['ar.v.ta']::text[], 'mcq', 'lesson', 'Laquelle de ces formes est la forme de la fin de ت ?', array['ـت']::text[], 'La forme de la fin s''accroche à la lettre d''avant : le trait ـ est à droite. ت garde ses deux points dessus.', 2, '{"id": "ar.l10.e11", "type": "mcq", "unitIds": ["ar.v.ta"], "difficulty": 2, "instruction": "Choisis la bonne forme.", "prompt": "Laquelle de ces formes est la forme de la fin de ت ?", "promptLanguage": "fr", "answer": "ـت", "acceptedAnswers": ["ـت"], "explanation": "La forme de la fin s''accroche à la lettre d''avant : le trait ـ est à droite. ت garde ses deux points dessus.", "tip": "Fin = trait à droite.", "extraExample": {"text": "بنت", "translation": "fille"}, "errorPatterns": [{"equals": "تـ", "category": "instruction", "feedback": "تـ a le trait à gauche : c''est la forme du début."}, {"equals": "ـتـ", "category": "instruction", "feedback": "ـتـ a un trait de chaque côté : forme du milieu."}, {"equals": "ت", "category": "instruction", "feedback": "ت sans trait : forme isolée."}], "options": ["ـت", "تـ", "ـتـ", "ت"], "pool": "lesson", "lessonId": "ar.l10", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e12', 'ar', 'ar.l10', 'ar.v.nabi', array['ar.v.nabi']::text[], 'mcq', 'lesson', 'Dans نبي, quelle forme prend la lettre ب ?', array['forme du milieu']::text[], 'Dans نبي, la lettre ب s''accroche des deux côtés : c''est la forme du milieu. Au milieu, la dent ـبـ n''a qu''un point dessous.', 2, '{"id": "ar.l10.e12", "type": "mcq", "unitIds": ["ar.v.nabi"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Dans نبي, quelle forme prend la lettre ب ?", "promptLanguage": "fr", "answer": "forme du milieu", "acceptedAnswers": ["forme du milieu"], "explanation": "Dans نبي, la lettre ب s''accroche des deux côtés : c''est la forme du milieu. Au milieu, la dent ـبـ n''a qu''un point dessous.", "tip": "Regarde si la lettre s''accroche à celle d''avant (à droite) et à celle d''après (à gauche).", "extraExample": {"text": "نبي", "translation": "prophète"}, "errorPatterns": [{"equals": "forme isolée", "category": "instruction", "feedback": "Sans trait ـ, la lettre est seule : c''est la forme isolée."}, {"equals": "forme du début", "category": "instruction", "feedback": "Le trait ـ est à gauche, vers la lettre suivante : c''est la forme du début."}, {"equals": "forme de la fin", "category": "instruction", "feedback": "Le trait ـ est à droite, vers la lettre précédente : c''est la forme de la fin."}], "options": ["forme isolée", "forme du début", "forme du milieu", "forme de la fin"], "pool": "lesson", "lessonId": "ar.l10", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e13', 'ar', 'ar.l10', 'ar.g10.letters_that_do_not_connect', array['ar.g10.letters_that_do_not_connect','ar.v.ward']::text[], 'fill_blank', 'lesson', 'و___د', array['ر']::text[], 'ورد s''écrit و + ر + د : trois lettres qui ne s''attachent pas. ز aurait un point dessus ; د n''a pas la même place.', 3, '{"id": "ar.l10.e13", "type": "fill_blank", "unitIds": ["ar.g10.letters_that_do_not_connect", "ar.v.ward"], "difficulty": 3, "instruction": "Quelle lettre manque pour écrire « fleurs » ?", "prompt": "و___د", "promptLanguage": "ar", "answer": "ر", "acceptedAnswers": ["ر"], "explanation": "ورد s''écrit و + ر + د : trois lettres qui ne s''attachent pas. ز aurait un point dessus ; د n''a pas la même place.", "tip": "ر descend sous la ligne, sans point.", "extraExample": {"text": "الورد ريحته حلوة.", "translation": "Les fleurs sentent bon."}, "errorPatterns": [{"equals": "ز", "category": "spelling", "feedback": "ز a un point dessus. Ici il n''y en a pas : ر."}, {"equals": "د", "category": "spelling", "feedback": "د reste sur la ligne ; ر descend un peu sous la ligne."}], "options": ["ر", "ز", "د", "ذ"], "pool": "lesson", "lessonId": "ar.l10", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e14', 'ar', 'ar.l10', 'ar.g10.letters_that_do_not_connect', array['ar.g10.letters_that_do_not_connect','ar.v.dhanb']::text[], 'fill_blank', 'lesson', '___نـب', array['ذ']::text[], 'ذنب commence par ذ : un د avec 1 point dessus. Après elle, نب repart à neuf.', 3, '{"id": "ar.l10.e14", "type": "fill_blank", "unitIds": ["ar.g10.letters_that_do_not_connect", "ar.v.dhanb"], "difficulty": 3, "instruction": "Quelle lettre manque pour écrire « faute » ?", "prompt": "___نـب", "promptLanguage": "ar", "answer": "ذ", "acceptedAnswers": ["ذ"], "explanation": "ذنب commence par ذ : un د avec 1 point dessus. Après elle, نب repart à neuf.", "tip": "ذ = د + 1 point dessus.", "extraExample": {"text": "ده مش ذنبي.", "translation": "Ce n''est pas ma faute."}, "errorPatterns": [{"equals": "د", "category": "spelling", "feedback": "د n''a pas de point ; il en faut un dessus : ذ."}], "options": ["ذ", "د", "ز", "ر"], "pool": "lesson", "lessonId": "ar.l10", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e15', 'ar', 'ar.l10', 'ar.g10.letters_that_do_not_connect', array['ar.g10.letters_that_do_not_connect','ar.v.zayt']::text[], 'fill_blank', 'lesson', '___يـت', array['ز']::text[], 'زيت commence par ز : un ر avec 1 point dessus. Le ز se détache, puis يت reste attaché.', 3, '{"id": "ar.l10.e15", "type": "fill_blank", "unitIds": ["ar.g10.letters_that_do_not_connect", "ar.v.zayt"], "difficulty": 3, "instruction": "Quelle lettre manque pour écrire « huile » ?", "prompt": "___يـت", "promptLanguage": "ar", "answer": "ز", "acceptedAnswers": ["ز"], "explanation": "زيت commence par ز : un ر avec 1 point dessus. Le ز se détache, puis يت reste attaché.", "tip": "ز = ر + 1 point dessus.", "extraExample": {"text": "زيت الزيتون.", "translation": "L''huile d''olive."}, "errorPatterns": [{"equals": "ر", "category": "spelling", "feedback": "ر n''a pas de point ; il en faut un dessus : ز."}, {"equals": "ذ", "category": "spelling", "feedback": "ذ est un د avec un point ; ici la lettre descend sous la ligne : ز."}], "options": ["ز", "ر", "ن", "ذ"], "pool": "lesson", "lessonId": "ar.l10", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e16', 'ar', 'ar.l10', 'ar.g10.letters_that_do_not_connect', array['ar.g10.letters_that_do_not_connect','ar.v.bab','ar.v.ruzz','ar.v.zayt','ar.v.ward','ar.v.dayr']::text[], 'match', 'lesson', 'Mots des lettres qui ne s''attachent pas', '{}'::text[], 'Lis bloc par bloc : با | ب, ر | ز, ز | يت, و | ر | د, د | ير.', 2, '{"id": "ar.l10.e16", "type": "match", "unitIds": ["ar.g10.letters_that_do_not_connect", "ar.v.bab", "ar.v.ruzz", "ar.v.zayt", "ar.v.ward", "ar.v.dayr"], "difficulty": 2, "instruction": "Associe chaque mot à son sens.", "prompt": "Mots des lettres qui ne s''attachent pas", "promptLanguage": "fr", "answer": "باب = porte ; رز = riz ; زيت = huile ; ورد = fleurs ; دير = monastère", "acceptedAnswers": [], "explanation": "Lis bloc par bloc : با | ب, ر | ز, ز | يت, و | ر | د, د | ير.", "pairs": [{"left": "باب", "right": "porte"}, {"left": "رز", "right": "riz"}, {"left": "زيت", "right": "huile"}, {"left": "ورد", "right": "fleurs"}, {"left": "دير", "right": "monastère"}], "pool": "lesson", "lessonId": "ar.l10", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e17', 'ar', 'ar.l10', 'ar.g10.letters_that_do_not_connect', array['ar.g10.letters_that_do_not_connect','ar.v.bayt','ar.v.bab','ar.v.ward']::text[], 'match', 'lesson', 'Compter les blocs', '{}'::text[], 'بيت : tout est attaché (1 bloc). باب : le ا coupe (2 blocs). ورد : و, ر, د coupent (3 blocs). راديو = ر | ا | د | يو (4 blocs).', 3, '{"id": "ar.l10.e17", "type": "match", "unitIds": ["ar.g10.letters_that_do_not_connect", "ar.v.bayt", "ar.v.bab", "ar.v.ward"], "difficulty": 3, "instruction": "Associe chaque mot à son nombre de blocs.", "prompt": "Compter les blocs", "promptLanguage": "fr", "answer": "بيت = 1 bloc ; باب = 2 blocs ; ورد = 3 blocs ; راديو = 4 blocs", "acceptedAnswers": [], "explanation": "بيت : tout est attaché (1 bloc). باب : le ا coupe (2 blocs). ورد : و, ر, د coupent (3 blocs). راديو = ر | ا | د | يو (4 blocs).", "pairs": [{"left": "بيت", "right": "1 bloc"}, {"left": "باب", "right": "2 blocs"}, {"left": "ورد", "right": "3 blocs"}, {"left": "راديو", "right": "4 blocs"}], "pool": "lesson", "lessonId": "ar.l10", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e18', 'ar', 'ar.l10', 'ar.g10.letters_that_do_not_connect', array['ar.g10.letters_that_do_not_connect','ar.v.alif','ar.v.dal','ar.v.ra','ar.v.zay','ar.v.waw']::text[], 'match', 'lesson', 'Lettre isolée et forme de la fin', '{}'::text[], 'La forme de la fin garde la lettre et ajoute le trait ـ à droite, du côté de la lettre d''avant.', 2, '{"id": "ar.l10.e18", "type": "match", "unitIds": ["ar.g10.letters_that_do_not_connect", "ar.v.alif", "ar.v.dal", "ar.v.ra", "ar.v.zay", "ar.v.waw"], "difficulty": 2, "instruction": "Associe chaque lettre à sa forme de la fin.", "prompt": "Lettre isolée et forme de la fin", "promptLanguage": "fr", "answer": "ا = ـا ; د = ـد ; ر = ـر ; ز = ـز ; و = ـو", "acceptedAnswers": [], "explanation": "La forme de la fin garde la lettre et ajoute le trait ـ à droite, du côté de la lettre d''avant.", "pairs": [{"left": "ا", "right": "ـا"}, {"left": "د", "right": "ـد"}, {"left": "ر", "right": "ـر"}, {"left": "ز", "right": "ـز"}, {"left": "و", "right": "ـو"}], "pool": "lesson", "lessonId": "ar.l10", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e19', 'ar', 'ar.l10', 'ar.v.tinnin', array['ar.v.tinnin','ar.v.bayna','ar.v.bunn','ar.v.nabi']::text[], 'match', 'lesson', 'Mots de la leçon 9', '{}'::text[], 'Ces quatre mots n''utilisent que ب ت ث ن ي : compte les points pour les reconnaître.', 2, '{"id": "ar.l10.e19", "type": "match", "unitIds": ["ar.v.tinnin", "ar.v.bayna", "ar.v.bunn", "ar.v.nabi"], "difficulty": 2, "instruction": "Révision : associe chaque mot à son sens.", "prompt": "Mots de la leçon 9", "promptLanguage": "fr", "answer": "تنين = dragon ; بين = entre ; بن = café (grains) ; نبي = prophète", "acceptedAnswers": [], "explanation": "Ces quatre mots n''utilisent que ب ت ث ن ي : compte les points pour les reconnaître.", "pairs": [{"left": "تنين", "right": "dragon"}, {"left": "بين", "right": "entre"}, {"left": "بن", "right": "café (grains)"}, {"left": "نبي", "right": "prophète"}], "pool": "lesson", "lessonId": "ar.l10", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e20', 'ar', 'ar.l10', 'ar.g10.letters_that_do_not_connect', array['ar.g10.letters_that_do_not_connect','ar.v.rabbina']::text[], 'translation', 'lesson', 'ربنا', array['notre seigneur','seigneur','dieu','notre dieu']::text[], 'ربنا = ر | بنا : le ر se détache, puis بنا reste attaché. C''est « notre Seigneur », le mot de tous les jours pour parler de Dieu.', 3, '{"id": "ar.l10.e20", "type": "translation", "unitIds": ["ar.g10.letters_that_do_not_connect", "ar.v.rabbina"], "difficulty": 3, "instruction": "Écris le sens en français.", "prompt": "ربنا", "promptLanguage": "ar", "answer": "notre seigneur", "acceptedAnswers": ["notre seigneur", "seigneur", "dieu", "notre dieu"], "explanation": "ربنا = ر | بنا : le ر se détache, puis بنا reste attaché. C''est « notre Seigneur », le mot de tous les jours pour parler de Dieu.", "tip": "ر + بنا : 2 blocs.", "extraExample": {"text": "ربنا يباركك.", "translation": "Que Dieu te bénisse."}, "pool": "lesson", "lessonId": "ar.l10", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e21', 'ar', 'ar.l10', 'ar.g10.letters_that_do_not_connect', array['ar.g10.letters_that_do_not_connect','ar.v.dayr']::text[], 'translation', 'lesson', 'دير', array['monastère','monastere','un monastère','le monastère']::text[], 'دير = د | ير : le د se détache. C''est un monastère.', 2, '{"id": "ar.l10.e21", "type": "translation", "unitIds": ["ar.g10.letters_that_do_not_connect", "ar.v.dayr"], "difficulty": 2, "instruction": "Écris le sens en français.", "prompt": "دير", "promptLanguage": "ar", "answer": "monastère", "acceptedAnswers": ["monastère", "monastere", "un monastère", "le monastère"], "explanation": "دير = د | ير : le د se détache. C''est un monastère.", "tip": "د coupe le mot : 2 blocs.", "extraExample": {"text": "رحنا الدير يوم الجمعة.", "translation": "Nous sommes allés au monastère vendredi."}, "errorPatterns": [{"equals": "porte", "category": "word_confusion", "feedback": "باب (porte) a un ا ; دير commence par د."}], "pool": "lesson", "lessonId": "ar.l10", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e22', 'ar', 'ar.l10', 'ar.g10.letters_that_do_not_connect', array['ar.g10.letters_that_do_not_connect','ar.v.dhanb']::text[], 'free_answer', 'lesson', 'Que veut dire ذنب ?', array['faute','une faute','la faute','péché','peche','un péché']::text[], 'ذنب = ذ + نب : le ذ (د avec un point dessus) se détache. C''est une faute, ou un péché dans la prière.', 3, '{"id": "ar.l10.e22", "type": "free_answer", "unitIds": ["ar.g10.letters_that_do_not_connect", "ar.v.dhanb"], "difficulty": 3, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire ذنب ?", "promptLanguage": "fr", "answer": "faute", "acceptedAnswers": ["faute", "une faute", "la faute", "péché", "peche", "un péché"], "explanation": "ذنب = ذ + نب : le ذ (د avec un point dessus) se détache. C''est une faute, ou un péché dans la prière.", "tip": "ذ = د + 1 point dessus.", "extraExample": {"text": "اغفر لنا ذنوبنا.", "translation": "Pardonne-nous nos fautes."}, "pool": "lesson", "lessonId": "ar.l10", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l10.e23', 'ar', 'ar.l10', 'ar.g10.letters_that_do_not_connect', array['ar.g10.letters_that_do_not_connect','ar.v.ruzz']::text[], 'free_answer', 'lesson', 'Que veut dire رز ?', array['riz','du riz','le riz']::text[], 'رز = ر + ز : deux lettres qui ne s''attachent pas, donc 2 blocs. C''est le riz.', 2, '{"id": "ar.l10.e23", "type": "free_answer", "unitIds": ["ar.g10.letters_that_do_not_connect", "ar.v.ruzz"], "difficulty": 2, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire رز ?", "promptLanguage": "fr", "answer": "riz", "acceptedAnswers": ["riz", "du riz", "le riz"], "explanation": "رز = ر + ز : deux lettres qui ne s''attachent pas, donc 2 blocs. C''est le riz.", "tip": "ر sans point, ز avec un point dessus.", "extraExample": {"text": "الرز بالفراخ.", "translation": "Du riz au poulet."}, "errorPatterns": [{"equals": "fleurs", "category": "word_confusion", "feedback": "ورد (fleurs) a trois lettres : و ر د."}], "pool": "lesson", "lessonId": "ar.l10", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e01', 'ar', 'ar.l11', 'ar.g11.forms_jim_family', array['ar.g11.forms_jim_family','ar.v.jim']::text[], 'mcq', 'lesson', 'Laquelle de ces formes est la forme du début de ج ?', array['جـ']::text[], 'La forme du début s''accroche à la lettre qui suit : le trait ـ est à gauche. ج garde son point dessous.', 1, '{"id": "ar.l11.e01", "type": "mcq", "unitIds": ["ar.g11.forms_jim_family", "ar.v.jim"], "difficulty": 1, "instruction": "Choisis la bonne forme.", "prompt": "Laquelle de ces formes est la forme du début de ج ?", "promptLanguage": "fr", "answer": "جـ", "acceptedAnswers": ["جـ"], "explanation": "La forme du début s''accroche à la lettre qui suit : le trait ـ est à gauche. ج garde son point dessous.", "tip": "Début = trait à gauche.", "extraExample": {"text": "جيب", "translation": "poche"}, "errorPatterns": [{"equals": "ـجـ", "category": "instruction", "feedback": "ـجـ a un trait de chaque côté : forme du milieu."}, {"equals": "ـج", "category": "instruction", "feedback": "ـج a le trait à droite : forme de la fin."}, {"equals": "ج", "category": "instruction", "feedback": "ج sans trait : forme isolée."}], "options": ["جـ", "ـجـ", "ـج", "ج"], "pool": "lesson", "lessonId": "ar.l11", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e02', 'ar', 'ar.l11', 'ar.g11.forms_jim_family', array['ar.g11.forms_jim_family','ar.v.jim']::text[], 'mcq', 'lesson', 'Dans la famille du crochet, quelle lettre a un point dessous ?', array['ج']::text[], 'ج a un point dessous, dans le creux du crochet. ح n''en a aucun, خ en a un dessus.', 1, '{"id": "ar.l11.e02", "type": "mcq", "unitIds": ["ar.g11.forms_jim_family", "ar.v.jim"], "difficulty": 1, "instruction": "Choisis la bonne lettre.", "prompt": "Dans la famille du crochet, quelle lettre a un point dessous ?", "promptLanguage": "fr", "answer": "ج", "acceptedAnswers": ["ج"], "explanation": "ج a un point dessous, dans le creux du crochet. ح n''en a aucun, خ en a un dessus.", "tip": "Dessous = ج, dessus = خ, rien = ح.", "extraExample": {"text": "جزر", "translation": "carottes"}, "errorPatterns": [{"equals": "ح", "category": "spelling", "feedback": "ح n''a aucun point."}, {"equals": "خ", "category": "spelling", "feedback": "خ a son point dessus."}], "options": ["ج", "ح", "خ"], "pool": "lesson", "lessonId": "ar.l11", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e03', 'ar', 'ar.l11', 'ar.g11.forms_jim_family', array['ar.g11.forms_jim_family','ar.v.habibi']::text[], 'mcq', 'lesson', 'حبيبي', array['mon chéri']::text[], 'Lettre par lettre : ح (sans point), ب (1 point dessous), ي (2 points dessous), ب (1 point dessous), ي (2 points dessous) donne حبيبي, « mon chéri ». Tout est attaché : 1 bloc, ح + ب + ي + ب + ي.', 2, '{"id": "ar.l11.e03", "type": "mcq", "unitIds": ["ar.g11.forms_jim_family", "ar.v.habibi"], "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "حبيبي", "promptLanguage": "ar", "answer": "mon chéri", "acceptedAnswers": ["mon chéri"], "explanation": "Lettre par lettre : ح (sans point), ب (1 point dessous), ي (2 points dessous), ب (1 point dessous), ي (2 points dessous) donne حبيبي, « mon chéri ». Tout est attaché : 1 bloc, ح + ب + ي + ب + ي.", "tip": "Lis de droite à gauche, lettre après lettre, puis dis le mot à voix haute.", "extraExample": {"text": "تعالى يا حبيبي.", "translation": "Viens, mon chéri."}, "errorPatterns": [{"equals": "papy", "category": "word_confusion", "feedback": "« papy » s''écrit جدو (ج + د + و). Ici tu lis ح + ب + ي + ب + ي : حبيبي veut dire « mon chéri »."}, {"equals": "poche", "category": "word_confusion", "feedback": "« poche » s''écrit جيب (ج + ي + ب). Ici tu lis ح + ب + ي + ب + ي : حبيبي veut dire « mon chéri »."}, {"equals": "nouvelle", "category": "word_confusion", "feedback": "« nouvelle » s''écrit خبر (خ + ب + ر). Ici tu lis ح + ب + ي + ب + ي : حبيبي veut dire « mon chéri »."}], "options": ["mon chéri", "papy", "poche", "nouvelle"], "pool": "lesson", "lessonId": "ar.l11", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e04', 'ar', 'ar.l11', 'ar.g11.forms_jim_family', array['ar.g11.forms_jim_family','ar.v.khabar']::text[], 'mcq', 'lesson', 'خبر', array['nouvelle']::text[], 'Lettre par lettre : خ (1 point dessus), ب (1 point dessous), ر (sans point) donne خبر, « nouvelle ». خ : un point dessus ; puis ب et ر attachés : 1 bloc.', 2, '{"id": "ar.l11.e04", "type": "mcq", "unitIds": ["ar.g11.forms_jim_family", "ar.v.khabar"], "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "خبر", "promptLanguage": "ar", "answer": "nouvelle", "acceptedAnswers": ["nouvelle"], "explanation": "Lettre par lettre : خ (1 point dessus), ب (1 point dessous), ر (sans point) donne خبر, « nouvelle ». خ : un point dessus ; puis ب et ر attachés : 1 bloc.", "tip": "Lis de droite à gauche, lettre après lettre, puis dis le mot à voix haute.", "extraExample": {"text": "الخبر ده حلو.", "translation": "Cette nouvelle est bonne."}, "errorPatterns": [{"equals": "encens", "category": "word_confusion", "feedback": "« encens » s''écrit بخور (ب + خ + و + ر). Ici tu lis خ + ب + ر : خبر veut dire « nouvelle »."}, {"equals": "poche", "category": "word_confusion", "feedback": "« poche » s''écrit جيب (ج + ي + ب). Ici tu lis خ + ب + ر : خبر veut dire « nouvelle »."}, {"equals": "carottes", "category": "word_confusion", "feedback": "« carottes » s''écrit جزر (ج + ز + ر). Ici tu lis خ + ب + ر : خبر veut dire « nouvelle »."}], "options": ["nouvelle", "encens", "poche", "carottes"], "pool": "lesson", "lessonId": "ar.l11", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e05', 'ar', 'ar.l11', 'ar.g11.forms_jim_family', array['ar.g11.forms_jim_family','ar.v.bakhur']::text[], 'mcq', 'lesson', 'Quel mot veut dire « encens » ?', array['بخور']::text[], '« encens » s''écrit ب + خ + و + ر : بخور. ب + خ + و s''attachent, puis le و ferme le bloc : بخو | ر.', 3, '{"id": "ar.l11.e05", "type": "mcq", "unitIds": ["ar.g11.forms_jim_family", "ar.v.bakhur"], "difficulty": 3, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « encens » ?", "promptLanguage": "fr", "answer": "بخور", "acceptedAnswers": ["بخور"], "explanation": "« encens » s''écrit ب + خ + و + ر : بخور. ب + خ + و s''attachent, puis le و ferme le bloc : بخو | ر.", "tip": "Compare les points et les attaches, lettre par lettre.", "extraExample": {"text": "أبونا بيرفع البخور.", "translation": "Le prêtre fait monter l''encens."}, "errorPatterns": [{"equals": "خبر", "category": "word_confusion", "feedback": "خبر (خ + ب + ر) veut dire « nouvelle ». Pour « encens », il faut ب + خ + و + ر : بخور."}, {"equals": "جزر", "category": "word_confusion", "feedback": "جزر (ج + ز + ر) veut dire « carottes ». Pour « encens », il faut ب + خ + و + ر : بخور."}, {"equals": "خوخ", "category": "word_confusion", "feedback": "خوخ (خ + و + خ) veut dire « pêches ». Pour « encens », il faut ب + خ + و + ر : بخور."}], "options": ["بخور", "خبر", "جزر", "خوخ"], "pool": "lesson", "lessonId": "ar.l11", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e06', 'ar', 'ar.l11', 'ar.g11.forms_jim_family', array['ar.g11.forms_jim_family','ar.v.khud']::text[], 'mcq', 'lesson', 'Quel mot veut dire « prends » ?', array['خد']::text[], '« prends » s''écrit خ + د : خد. Un point dessus : خ. Sans point, ce serait حد.', 3, '{"id": "ar.l11.e06", "type": "mcq", "unitIds": ["ar.g11.forms_jim_family", "ar.v.khud"], "difficulty": 3, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « prends » ?", "promptLanguage": "fr", "answer": "خد", "acceptedAnswers": ["خد"], "explanation": "« prends » s''écrit خ + د : خد. Un point dessus : خ. Sans point, ce serait حد.", "tip": "Compare les points et les attaches, lettre par lettre.", "extraExample": {"text": "خد بالك.", "translation": "Fais attention."}, "hint": "Un point dessus, ou aucun ?", "errorPatterns": [{"equals": "حد", "category": "word_confusion", "feedback": "حد (ح + د) veut dire « quelqu''un ». Pour « prends », il faut خ + د : خد."}, {"equals": "جدو", "category": "word_confusion", "feedback": "جدو (ج + د + و) veut dire « papy ». Pour « prends », il faut خ + د : خد."}, {"equals": "خبر", "category": "word_confusion", "feedback": "خبر (خ + ب + ر) veut dire « nouvelle ». Pour « prends », il faut خ + د : خد."}], "options": ["خد", "حد", "جدو", "خبر"], "pool": "lesson", "lessonId": "ar.l11", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e07', 'ar', 'ar.l11', 'ar.g11.forms_jim_family', array['ar.g11.forms_jim_family','ar.v.khawkh']::text[], 'mcq', 'lesson', 'Dans خوخ, quelle forme prend le deuxième خ ?', array['forme isolée']::text[], 'Dans خوخ (blocs : خو | خ), le deuxième خ ne s''accroche à aucune voisine : c''est la forme isolée. Il suit un و qui ne s''attache pas : il est seul.', 3, '{"id": "ar.l11.e07", "type": "mcq", "unitIds": ["ar.g11.forms_jim_family", "ar.v.khawkh"], "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Dans خوخ, quelle forme prend le deuxième خ ?", "promptLanguage": "fr", "answer": "forme isolée", "acceptedAnswers": ["forme isolée"], "explanation": "Dans خوخ (blocs : خو | خ), le deuxième خ ne s''accroche à aucune voisine : c''est la forme isolée. Il suit un و qui ne s''attache pas : il est seul.", "tip": "Regarde si la lettre s''accroche à celle d''avant (à droite) et à celle d''après (à gauche).", "extraExample": {"text": "خوخ", "translation": "pêches"}, "errorPatterns": [{"equals": "forme du début", "category": "instruction", "feedback": "Le trait ـ est à gauche, vers la lettre suivante : c''est la forme du début."}, {"equals": "forme du milieu", "category": "instruction", "feedback": "Un trait ـ de chaque côté : c''est la forme du milieu."}, {"equals": "forme de la fin", "category": "instruction", "feedback": "Le trait ـ est à droite, vers la lettre précédente : c''est la forme de la fin."}], "options": ["forme isolée", "forme du début", "forme du milieu", "forme de la fin"], "pool": "lesson", "lessonId": "ar.l11", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e08', 'ar', 'ar.l11', 'ar.g11.forms_jim_family', array['ar.g11.forms_jim_family','ar.v.bakhur']::text[], 'mcq', 'lesson', 'Dans بخور, quelle forme prend la lettre خ ?', array['forme du milieu']::text[], 'Dans بخور (blocs : بخو | ر), la lettre خ s''accroche des deux côtés : c''est la forme du milieu. Il est entre le ب et le و, attaché des deux côtés : ـخـ.', 3, '{"id": "ar.l11.e08", "type": "mcq", "unitIds": ["ar.g11.forms_jim_family", "ar.v.bakhur"], "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Dans بخور, quelle forme prend la lettre خ ?", "promptLanguage": "fr", "answer": "forme du milieu", "acceptedAnswers": ["forme du milieu"], "explanation": "Dans بخور (blocs : بخو | ر), la lettre خ s''accroche des deux côtés : c''est la forme du milieu. Il est entre le ب et le و, attaché des deux côtés : ـخـ.", "tip": "Regarde si la lettre s''accroche à celle d''avant (à droite) et à celle d''après (à gauche).", "extraExample": {"text": "بخور", "translation": "encens"}, "errorPatterns": [{"equals": "forme isolée", "category": "instruction", "feedback": "Sans trait ـ, la lettre est seule : c''est la forme isolée."}, {"equals": "forme du début", "category": "instruction", "feedback": "Le trait ـ est à gauche, vers la lettre suivante : c''est la forme du début."}, {"equals": "forme de la fin", "category": "instruction", "feedback": "Le trait ـ est à droite, vers la lettre précédente : c''est la forme de la fin."}], "options": ["forme isolée", "forme du début", "forme du milieu", "forme de la fin"], "pool": "lesson", "lessonId": "ar.l11", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e09', 'ar', 'ar.l11', 'ar.g11.forms_jim_family', array['ar.g11.forms_jim_family','ar.v.khawkh']::text[], 'mcq', 'lesson', 'Combien de blocs compte خوخ ?', array['2 blocs']::text[], 'خوخ = خو | خ : 2 blocs. Le mot se coupe après و.', 3, '{"id": "ar.l11.e09", "type": "mcq", "unitIds": ["ar.g11.forms_jim_family", "ar.v.khawkh"], "difficulty": 3, "instruction": "Compte les blocs.", "prompt": "Combien de blocs compte خوخ ?", "promptLanguage": "fr", "answer": "2 blocs", "acceptedAnswers": ["2 blocs"], "explanation": "خوخ = خو | خ : 2 blocs. Le mot se coupe après و.", "tip": "Après chaque ا د ذ ر ز و, un nouveau bloc commence.", "extraExample": {"text": "خوخ", "translation": "pêches"}, "errorPatterns": [{"equals": "1 bloc", "category": "instruction", "feedback": "Tu as oublié une coupure : seules ا د ذ ر ز و ne s''attachent pas à la suivante. Ici : خو | خ."}, {"equals": "3 blocs", "category": "instruction", "feedback": "Tu as coupé trop de fois : seules ا د ذ ر ز و ne s''attachent pas à la suivante. Ici : خو | خ."}, {"equals": "4 blocs", "category": "instruction", "feedback": "Tu as coupé trop de fois : seules ا د ذ ر ز و ne s''attachent pas à la suivante. Ici : خو | خ."}], "options": ["1 bloc", "2 blocs", "3 blocs", "4 blocs"], "pool": "lesson", "lessonId": "ar.l11", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e10', 'ar', 'ar.l11', 'ar.v.waw', array['ar.v.waw']::text[], 'mcq', 'lesson', 'Quelle lettre ferme toujours son bloc ?', array['و']::text[], 'و fait partie des six lettres qui ne s''attachent pas à la suivante : le bloc se ferme après elle. ج ح خ, elles, s''attachent.', 1, '{"id": "ar.l11.e10", "type": "mcq", "unitIds": ["ar.v.waw"], "difficulty": 1, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre ferme toujours son bloc ?", "promptLanguage": "fr", "answer": "و", "acceptedAnswers": ["و"], "explanation": "و fait partie des six lettres qui ne s''attachent pas à la suivante : le bloc se ferme après elle. ج ح خ, elles, s''attachent.", "tip": "ا د ذ ر ز و ferment le bloc.", "extraExample": {"text": "خوخ", "translation": "pêches"}, "errorPatterns": [{"equals": "ج", "category": "instruction", "feedback": "ج s''attache à la lettre suivante (جـ)."}, {"equals": "ح", "category": "instruction", "feedback": "ح s''attache à la lettre suivante (حـ)."}, {"equals": "خ", "category": "instruction", "feedback": "خ s''attache à la lettre suivante (خـ)."}], "options": ["و", "ج", "ح", "خ"], "pool": "lesson", "lessonId": "ar.l11", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e11', 'ar', 'ar.l11', 'ar.v.abouna', array['ar.v.abouna']::text[], 'mcq', 'lesson', 'Combien de blocs compte أبونا ?', array['3 blocs']::text[], 'أبونا = أ | بو | نا : 3 blocs. Le mot se coupe après أ et après و.', 3, '{"id": "ar.l11.e11", "type": "mcq", "unitIds": ["ar.v.abouna"], "difficulty": 3, "instruction": "Compte les blocs.", "prompt": "Combien de blocs compte أبونا ?", "promptLanguage": "fr", "answer": "3 blocs", "acceptedAnswers": ["3 blocs"], "explanation": "أبونا = أ | بو | نا : 3 blocs. Le mot se coupe après أ et après و.", "tip": "Après chaque ا د ذ ر ز و, un nouveau bloc commence.", "extraExample": {"text": "أبونا", "translation": "notre père (le prêtre)"}, "errorPatterns": [{"equals": "1 bloc", "category": "instruction", "feedback": "Tu as oublié une coupure : seules ا د ذ ر ز و ne s''attachent pas à la suivante. Ici : أ | بو | نا."}, {"equals": "2 blocs", "category": "instruction", "feedback": "Tu as oublié une coupure : seules ا د ذ ر ز و ne s''attachent pas à la suivante. Ici : أ | بو | نا."}, {"equals": "4 blocs", "category": "instruction", "feedback": "Tu as coupé trop de fois : seules ا د ذ ر ز و ne s''attachent pas à la suivante. Ici : أ | بو | نا."}], "options": ["1 bloc", "2 blocs", "3 blocs", "4 blocs"], "pool": "lesson", "lessonId": "ar.l11", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e12', 'ar', 'ar.l11', 'ar.v.bint', array['ar.v.bint']::text[], 'mcq', 'lesson', 'Quel mot veut dire « fille » ?', array['بنت']::text[], '« fille » s''écrit ب + ن + ت : بنت. Au milieu, un seul point dessus : ـنـ.', 1, '{"id": "ar.l11.e12", "type": "mcq", "unitIds": ["ar.v.bint"], "difficulty": 1, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « fille » ?", "promptLanguage": "fr", "answer": "بنت", "acceptedAnswers": ["بنت"], "explanation": "« fille » s''écrit ب + ن + ت : بنت. Au milieu, un seul point dessus : ـنـ.", "tip": "Compare les points et les attaches, lettre par lettre.", "extraExample": {"text": "عندي بنتين.", "translation": "J''ai deux filles."}, "errorPatterns": [{"equals": "بيت", "category": "word_confusion", "feedback": "بيت (ب + ي + ت) veut dire « maison ». Pour « fille », il faut ب + ن + ت : بنت."}, {"equals": "بين", "category": "word_confusion", "feedback": "بين (ب + ي + ن) veut dire « entre ». Pour « fille », il faut ب + ن + ت : بنت."}, {"equals": "بن", "category": "word_confusion", "feedback": "بن (ب + ن) veut dire « café (grains) ». Pour « fille », il faut ب + ن + ت : بنت."}], "options": ["بنت", "بيت", "بين", "بن"], "pool": "lesson", "lessonId": "ar.l11", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e13', 'ar', 'ar.l11', 'ar.g11.forms_jim_family', array['ar.g11.forms_jim_family','ar.v.jayb']::text[], 'fill_blank', 'lesson', '___ـيـب', array['ج']::text[], 'جيب commence par ج : le point est dessous, dans le creux. ح n''a pas de point, خ l''a dessus.', 2, '{"id": "ar.l11.e13", "type": "fill_blank", "unitIds": ["ar.g11.forms_jim_family", "ar.v.jayb"], "difficulty": 2, "instruction": "Quelle lettre manque pour écrire « poche » ?", "prompt": "___ـيـب", "promptLanguage": "ar", "answer": "ج", "acceptedAnswers": ["ج"], "explanation": "جيب commence par ج : le point est dessous, dans le creux. ح n''a pas de point, خ l''a dessus.", "tip": "Point dessous : ج.", "extraExample": {"text": "الفلوس في الجيب.", "translation": "L''argent est dans la poche."}, "errorPatterns": [{"equals": "ح", "category": "spelling", "feedback": "ح n''a aucun point ; il en faut un dessous."}, {"equals": "خ", "category": "spelling", "feedback": "خ a son point dessus ; ici il est dessous."}], "options": ["ج", "ح", "خ"], "pool": "lesson", "lessonId": "ar.l11", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e14', 'ar', 'ar.l11', 'ar.g11.forms_jim_family', array['ar.g11.forms_jim_family','ar.v.khabar']::text[], 'fill_blank', 'lesson', '___ـبـر', array['خ']::text[], 'خبر commence par خ : un point dessus. Puis ب et ر restent attachés.', 2, '{"id": "ar.l11.e14", "type": "fill_blank", "unitIds": ["ar.g11.forms_jim_family", "ar.v.khabar"], "difficulty": 2, "instruction": "Quelle lettre manque pour écrire « nouvelle » ?", "prompt": "___ـبـر", "promptLanguage": "ar", "answer": "خ", "acceptedAnswers": ["خ"], "explanation": "خبر commence par خ : un point dessus. Puis ب et ر restent attachés.", "tip": "Point dessus : خ.", "extraExample": {"text": "سمعت الخبر؟", "translation": "Tu as entendu la nouvelle ?"}, "errorPatterns": [{"equals": "ح", "category": "spelling", "feedback": "ح n''a aucun point ; il en faut un dessus."}, {"equals": "ج", "category": "spelling", "feedback": "ج a son point dessous ; ici il est dessus."}], "options": ["خ", "ح", "ج"], "pool": "lesson", "lessonId": "ar.l11", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e15', 'ar', 'ar.l11', 'ar.g11.forms_jim_family', array['ar.g11.forms_jim_family','ar.v.hadd']::text[], 'fill_blank', 'lesson', '___ـد', array['ح']::text[], 'حد n''a aucun point. Avec un point dessus, ce serait خد (prends).', 3, '{"id": "ar.l11.e15", "type": "fill_blank", "unitIds": ["ar.g11.forms_jim_family", "ar.v.hadd"], "difficulty": 3, "instruction": "Quelle lettre manque pour écrire « quelqu''un » ?", "prompt": "___ـد", "promptLanguage": "ar", "answer": "ح", "acceptedAnswers": ["ح"], "explanation": "حد n''a aucun point. Avec un point dessus, ce serait خد (prends).", "tip": "Aucun point : ح.", "extraExample": {"text": "فيه حد هنا؟", "translation": "Il y a quelqu''un ici ?"}, "errorPatterns": [{"equals": "خ", "category": "word_confusion", "feedback": "خد veut dire « prends ». « quelqu''un » n''a aucun point."}], "options": ["ح", "خ", "ج"], "pool": "lesson", "lessonId": "ar.l11", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e16', 'ar', 'ar.l11', 'ar.g11.forms_jim_family', array['ar.g11.forms_jim_family','ar.v.habibi','ar.v.khabar','ar.v.jazar','ar.v.khawkh','ar.v.jayb']::text[], 'match', 'lesson', 'Mots du crochet', '{}'::text[], 'Cherche le point : dessous pour ج, dessus pour خ, aucun pour ح.', 2, '{"id": "ar.l11.e16", "type": "match", "unitIds": ["ar.g11.forms_jim_family", "ar.v.habibi", "ar.v.khabar", "ar.v.jazar", "ar.v.khawkh", "ar.v.jayb"], "difficulty": 2, "instruction": "Associe chaque mot à son sens.", "prompt": "Mots du crochet", "promptLanguage": "fr", "answer": "حبيبي = mon chéri ; خبر = nouvelle ; جزر = carottes ; خوخ = pêches ; جيب = poche", "acceptedAnswers": [], "explanation": "Cherche le point : dessous pour ج, dessus pour خ, aucun pour ح.", "pairs": [{"left": "حبيبي", "right": "mon chéri"}, {"left": "خبر", "right": "nouvelle"}, {"left": "جزر", "right": "carottes"}, {"left": "خوخ", "right": "pêches"}, {"left": "جيب", "right": "poche"}], "pool": "lesson", "lessonId": "ar.l11", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e17', 'ar', 'ar.l11', 'ar.g11.forms_jim_family', array['ar.g11.forms_jim_family','ar.v.jim','ar.v.ha','ar.v.kha']::text[], 'match', 'lesson', 'Les points de ج ح خ', '{}'::text[], 'ج, ح, خ ont le même corps : seul le point les distingue.', 2, '{"id": "ar.l11.e17", "type": "match", "unitIds": ["ar.g11.forms_jim_family", "ar.v.jim", "ar.v.ha", "ar.v.kha"], "difficulty": 2, "instruction": "Associe chaque lettre à son point.", "prompt": "Les points de ج ح خ", "promptLanguage": "fr", "answer": "ج = 1 point dessous ; ح = aucun point ; خ = 1 point dessus", "acceptedAnswers": [], "explanation": "ج, ح, خ ont le même corps : seul le point les distingue.", "pairs": [{"left": "ج", "right": "1 point dessous"}, {"left": "ح", "right": "aucun point"}, {"left": "خ", "right": "1 point dessus"}], "pool": "lesson", "lessonId": "ar.l11", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e18', 'ar', 'ar.l11', 'ar.g11.forms_jim_family', array['ar.g11.forms_jim_family','ar.v.jim','ar.v.ha','ar.v.kha','ar.v.ba','ar.v.nun']::text[], 'match', 'lesson', 'Les formes du début de ج ح خ ب ن', '{}'::text[], 'La forme du début garde la lettre et ses points, avec le trait ـ à gauche.', 3, '{"id": "ar.l11.e18", "type": "match", "unitIds": ["ar.g11.forms_jim_family", "ar.v.jim", "ar.v.ha", "ar.v.kha", "ar.v.ba", "ar.v.nun"], "difficulty": 3, "instruction": "Associe chaque lettre isolée à sa forme du début.", "prompt": "Les formes du début de ج ح خ ب ن", "promptLanguage": "fr", "answer": "ج = جـ ; ح = حـ ; خ = خـ ; ب = بـ ; ن = نـ", "acceptedAnswers": [], "explanation": "La forme du début garde la lettre et ses points, avec le trait ـ à gauche.", "pairs": [{"left": "ج", "right": "جـ"}, {"left": "ح", "right": "حـ"}, {"left": "خ", "right": "خـ"}, {"left": "ب", "right": "بـ"}, {"left": "ن", "right": "نـ"}], "pool": "lesson", "lessonId": "ar.l11", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e19', 'ar', 'ar.l11', 'ar.v.bab', array['ar.v.bab','ar.v.zayt','ar.v.ward','ar.v.dayr','ar.v.dhanb']::text[], 'match', 'lesson', 'Mots de la leçon 10', '{}'::text[], 'Lis bloc par bloc : با | ب, ز | يت, و | ر | د, د | ير, ذ | نب.', 2, '{"id": "ar.l11.e19", "type": "match", "unitIds": ["ar.v.bab", "ar.v.zayt", "ar.v.ward", "ar.v.dayr", "ar.v.dhanb"], "difficulty": 2, "instruction": "Révision : associe chaque mot à son sens.", "prompt": "Mots de la leçon 10", "promptLanguage": "fr", "answer": "باب = porte ; زيت = huile ; ورد = fleurs ; دير = monastère ; ذنب = faute", "acceptedAnswers": [], "explanation": "Lis bloc par bloc : با | ب, ز | يت, و | ر | د, د | ير, ذ | نب.", "pairs": [{"left": "باب", "right": "porte"}, {"left": "زيت", "right": "huile"}, {"left": "ورد", "right": "fleurs"}, {"left": "دير", "right": "monastère"}, {"left": "ذنب", "right": "faute"}], "pool": "lesson", "lessonId": "ar.l11", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e20', 'ar', 'ar.l11', 'ar.g11.forms_jim_family', array['ar.g11.forms_jim_family','ar.v.jiddu']::text[], 'translation', 'lesson', 'جدو', array['papy','papi','grand-père','grand père','mon grand-père','grand-pere']::text[], 'جدو = جد | و : le د ferme le premier bloc, puis le و reste seul. C''est papy, le grand-père.', 3, '{"id": "ar.l11.e20", "type": "translation", "unitIds": ["ar.g11.forms_jim_family", "ar.v.jiddu"], "difficulty": 3, "instruction": "Écris le sens en français.", "prompt": "جدو", "promptLanguage": "ar", "answer": "papy", "acceptedAnswers": ["papy", "papi", "grand-père", "grand père", "mon grand-père", "grand-pere"], "explanation": "جدو = جد | و : le د ferme le premier bloc, puis le و reste seul. C''est papy, le grand-père.", "tip": "Pense au crochet ج, puis د et و.", "extraExample": {"text": "رحنا نزور جدو.", "translation": "Nous sommes allés rendre visite à papy."}, "pool": "lesson", "lessonId": "ar.l11", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e21', 'ar', 'ar.l11', 'ar.g11.forms_jim_family', array['ar.g11.forms_jim_family','ar.v.khawkh']::text[], 'translation', 'lesson', 'خوخ', array['pêches','peches','des pêches','pêche','peche','les pêches']::text[], 'خوخ = خو | خ : deux خ avec un point dessus, séparés par un و. Ce sont les pêches.', 3, '{"id": "ar.l11.e21", "type": "translation", "unitIds": ["ar.g11.forms_jim_family", "ar.v.khawkh"], "difficulty": 3, "instruction": "Écris le sens en français.", "prompt": "خوخ", "promptLanguage": "ar", "answer": "pêches", "acceptedAnswers": ["pêches", "peches", "des pêches", "pêche", "peche", "les pêches"], "explanation": "خوخ = خو | خ : deux خ avec un point dessus, séparés par un و. Ce sont les pêches.", "tip": "Deux points dessus, un à chaque extrémité.", "extraExample": {"text": "اشتريت خوخ من السوق.", "translation": "J''ai acheté des pêches au marché."}, "errorPatterns": [{"equals": "carottes", "category": "word_confusion", "feedback": "جزر (carottes) commence par ج, point dessous."}], "pool": "lesson", "lessonId": "ar.l11", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e22', 'ar', 'ar.l11', 'ar.g11.forms_jim_family', array['ar.g11.forms_jim_family','ar.v.hadd']::text[], 'free_answer', 'lesson', 'Que veut dire حد ?', array['quelqu''un','quelquun','quelque un','une personne']::text[], 'حد = ح + د, sans aucun point. C''est « quelqu''un » (et « personne » dans une phrase négative).', 3, '{"id": "ar.l11.e22", "type": "free_answer", "unitIds": ["ar.g11.forms_jim_family", "ar.v.hadd"], "difficulty": 3, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire حد ?", "promptLanguage": "fr", "answer": "quelqu''un", "acceptedAnswers": ["quelqu''un", "quelquun", "quelque un", "une personne"], "explanation": "حد = ح + د, sans aucun point. C''est « quelqu''un » (et « personne » dans une phrase négative).", "tip": "Aucun point : ح. Un point dessus : خد (prends).", "extraExample": {"text": "مفيش حد في البيت.", "translation": "Il n''y a personne à la maison."}, "errorPatterns": [{"equals": "prends", "category": "word_confusion", "feedback": "خد (prends) a un point dessus. حد n''en a aucun."}], "pool": "lesson", "lessonId": "ar.l11", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l11.e23', 'ar', 'ar.l11', 'ar.g11.forms_jim_family', array['ar.g11.forms_jim_family','ar.v.jazar']::text[], 'free_answer', 'lesson', 'Que veut dire جزر ?', array['carottes','carotte','des carottes','les carottes']::text[], 'جزر = جز | ر : ج (1 point dessous), ز (1 point dessus), ر (aucun). Ce sont les carottes.', 2, '{"id": "ar.l11.e23", "type": "free_answer", "unitIds": ["ar.g11.forms_jim_family", "ar.v.jazar"], "difficulty": 2, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire جزر ?", "promptLanguage": "fr", "answer": "carottes", "acceptedAnswers": ["carottes", "carotte", "des carottes", "les carottes"], "explanation": "جزر = جز | ر : ج (1 point dessous), ز (1 point dessus), ر (aucun). Ce sont les carottes.", "tip": "ج puis ز puis ر : lis de droite à gauche.", "extraExample": {"text": "عايز كيلو جزر.", "translation": "Je voudrais un kilo de carottes."}, "pool": "lesson", "lessonId": "ar.l11", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e01', 'ar', 'ar.l12', 'ar.g12.forms_sin_family', array['ar.g12.forms_sin_family','ar.v.shin']::text[], 'mcq', 'lesson', 'Laquelle de ces formes est la forme du milieu de ش ?', array['ـشـ']::text[], 'La forme du milieu s''accroche des deux côtés : un trait ـ de chaque côté. ش garde ses 3 points dessus.', 1, '{"id": "ar.l12.e01", "type": "mcq", "unitIds": ["ar.g12.forms_sin_family", "ar.v.shin"], "difficulty": 1, "instruction": "Choisis la bonne forme.", "prompt": "Laquelle de ces formes est la forme du milieu de ش ?", "promptLanguage": "fr", "answer": "ـشـ", "acceptedAnswers": ["ـشـ"], "explanation": "La forme du milieu s''accroche des deux côtés : un trait ـ de chaque côté. ش garde ses 3 points dessus.", "tip": "Milieu = trait des deux côtés.", "extraExample": {"text": "شاي", "translation": "thé"}, "errorPatterns": [{"equals": "شـ", "category": "instruction", "feedback": "شـ a le trait à gauche seulement : forme du début."}, {"equals": "ـش", "category": "instruction", "feedback": "ـش a le trait à droite seulement : forme de la fin."}, {"equals": "ش", "category": "instruction", "feedback": "ش sans trait : forme isolée."}], "options": ["ـشـ", "شـ", "ـش", "ش"], "pool": "lesson", "lessonId": "ar.l12", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e02', 'ar', 'ar.l12', 'ar.g12.forms_sin_family', array['ar.g12.forms_sin_family','ar.v.shin']::text[], 'mcq', 'lesson', 'Laquelle de ces lettres a trois dents et trois points dessus ?', array['ش']::text[], 'ش a trois dents et 3 points dessus. س a les mêmes dents sans point ; ث a 3 points mais pas de dents ; ص a une boucle.', 2, '{"id": "ar.l12.e02", "type": "mcq", "unitIds": ["ar.g12.forms_sin_family", "ar.v.shin"], "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Laquelle de ces lettres a trois dents et trois points dessus ?", "promptLanguage": "fr", "answer": "ش", "acceptedAnswers": ["ش"], "explanation": "ش a trois dents et 3 points dessus. س a les mêmes dents sans point ; ث a 3 points mais pas de dents ; ص a une boucle.", "tip": "Dents + 3 points = ش.", "extraExample": {"text": "شاي", "translation": "thé"}, "errorPatterns": [{"equals": "س", "category": "spelling", "feedback": "س a trois dents, mais aucun point."}, {"equals": "ث", "category": "spelling", "feedback": "ث a 3 points dessus mais n''a pas de dents : c''est une barque."}, {"equals": "ص", "category": "spelling", "feedback": "ص a une boucle, pas des dents."}], "options": ["ش", "س", "ث", "ص"], "pool": "lesson", "lessonId": "ar.l12", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e03', 'ar', 'ar.l12', 'ar.g12.forms_sin_family', array['ar.g12.forms_sin_family','ar.v.shay']::text[], 'mcq', 'lesson', 'شاي', array['thé']::text[], 'Lettre par lettre : ش (3 points dessus), ا (sans point), ي (2 points dessous) donne شاي, « thé ». ش : 3 dents et 3 points dessus. Le ا ferme le premier bloc : شا | ي.', 2, '{"id": "ar.l12.e03", "type": "mcq", "unitIds": ["ar.g12.forms_sin_family", "ar.v.shay"], "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "شاي", "promptLanguage": "ar", "answer": "thé", "acceptedAnswers": ["thé"], "explanation": "Lettre par lettre : ش (3 points dessus), ا (sans point), ي (2 points dessous) donne شاي, « thé ». ش : 3 dents et 3 points dessus. Le ا ferme le premier bloc : شا | ي.", "tip": "Lis de droite à gauche, lettre après lettre, puis dis le mot à voix haute.", "extraExample": {"text": "عايز كوباية شاي.", "translation": "Je voudrais un verre de thé."}, "errorPatterns": [{"equals": "matin", "category": "word_confusion", "feedback": "« matin » s''écrit صباح (ص + ب + ا + ح). Ici tu lis ش + ا + ي : شاي veut dire « thé »."}, {"equals": "blanc", "category": "word_confusion", "feedback": "« blanc » s''écrit أبيض (أ + ب + ي + ض). Ici tu lis ش + ا + ي : شاي veut dire « thé »."}, {"equals": "cloche", "category": "word_confusion", "feedback": "« cloche » s''écrit جرس (ج + ر + س). Ici tu lis ش + ا + ي : شاي veut dire « thé »."}], "options": ["thé", "matin", "blanc", "cloche"], "pool": "lesson", "lessonId": "ar.l12", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e04', 'ar', 'ar.l12', 'ar.g12.forms_sin_family', array['ar.g12.forms_sin_family','ar.v.sabah']::text[], 'mcq', 'lesson', 'صباح', array['matin']::text[], 'Lettre par lettre : ص (sans point), ب (1 point dessous), ا (sans point), ح (sans point) donne صباح, « matin ». ص : une boucle, aucun point. Le ا ferme le bloc : صبا | ح.', 2, '{"id": "ar.l12.e04", "type": "mcq", "unitIds": ["ar.g12.forms_sin_family", "ar.v.sabah"], "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "صباح", "promptLanguage": "ar", "answer": "matin", "acceptedAnswers": ["matin"], "explanation": "Lettre par lettre : ص (sans point), ب (1 point dessous), ا (sans point), ح (sans point) donne صباح, « matin ». ص : une boucle, aucun point. Le ا ferme le bloc : صبا | ح.", "tip": "Lis de droite à gauche, lettre après lettre, puis dis le mot à voix haute.", "extraExample": {"text": "صباح الخير يا أبونا.", "translation": "Bonjour, mon père."}, "errorPatterns": [{"equals": "thé", "category": "word_confusion", "feedback": "« thé » s''écrit شاي (ش + ا + ي). Ici tu lis ص + ب + ا + ح : صباح veut dire « matin »."}, {"equals": "samedi", "category": "word_confusion", "feedback": "« samedi » s''écrit سبت (س + ب + ت). Ici tu lis ص + ب + ا + ح : صباح veut dire « matin »."}, {"equals": "pêcheur", "category": "word_confusion", "feedback": "« pêcheur » s''écrit صياد (ص + ي + ا + د). Ici tu lis ص + ب + ا + ح : صباح veut dire « matin »."}], "options": ["matin", "thé", "samedi", "pêcheur"], "pool": "lesson", "lessonId": "ar.l12", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e05', 'ar', 'ar.l12', 'ar.g12.forms_sin_family', array['ar.g12.forms_sin_family','ar.v.sayyad']::text[], 'mcq', 'lesson', 'Quel mot veut dire « pêcheur » ?', array['صياد']::text[], '« pêcheur » s''écrit ص + ي + ا + د : صياد. Le ا ferme le bloc صيا, puis le د reste seul : صيا | د.', 3, '{"id": "ar.l12.e05", "type": "mcq", "unitIds": ["ar.g12.forms_sin_family", "ar.v.sayyad"], "difficulty": 3, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « pêcheur » ?", "promptLanguage": "fr", "answer": "صياد", "acceptedAnswers": ["صياد"], "explanation": "« pêcheur » s''écrit ص + ي + ا + د : صياد. Le ا ferme le bloc صيا, puis le د reste seul : صيا | د.", "tip": "Compare les points et les attaches, lettre par lettre.", "extraExample": {"text": "بطرس كان صياد.", "translation": "Pierre était pêcheur."}, "errorPatterns": [{"equals": "صباح", "category": "word_confusion", "feedback": "صباح (ص + ب + ا + ح) veut dire « matin ». Pour « pêcheur », il faut ص + ي + ا + د : صياد."}, {"equals": "سبت", "category": "word_confusion", "feedback": "سبت (س + ب + ت) veut dire « samedi ». Pour « pêcheur », il faut ص + ي + ا + د : صياد."}, {"equals": "شاي", "category": "word_confusion", "feedback": "شاي (ش + ا + ي) veut dire « thé ». Pour « pêcheur », il faut ص + ي + ا + د : صياد."}], "options": ["صياد", "صباح", "سبت", "شاي"], "pool": "lesson", "lessonId": "ar.l12", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e06', 'ar', 'ar.l12', 'ar.g12.forms_sin_family', array['ar.g12.forms_sin_family','ar.v.hadir']::text[], 'mcq', 'lesson', 'Quel mot veut dire « entendu » ?', array['حاضر']::text[], '« entendu » s''écrit ح + ا + ض + ر : حاضر. Après le ا, le ض repart à neuf : forme du début ضـ. Blocs : حا | ضر.', 3, '{"id": "ar.l12.e06", "type": "mcq", "unitIds": ["ar.g12.forms_sin_family", "ar.v.hadir"], "difficulty": 3, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « entendu » ?", "promptLanguage": "fr", "answer": "حاضر", "acceptedAnswers": ["حاضر"], "explanation": "« entendu » s''écrit ح + ا + ض + ر : حاضر. Après le ا, le ض repart à neuf : forme du début ضـ. Blocs : حا | ضر.", "tip": "Compare les points et les attaches, lettre par lettre.", "extraExample": {"text": "حاضر، هعمله دلوقتي.", "translation": "Entendu, je le fais tout de suite."}, "errorPatterns": [{"equals": "صباح", "category": "word_confusion", "feedback": "صباح (ص + ب + ا + ح) veut dire « matin ». Pour « entendu », il faut ح + ا + ض + ر : حاضر."}, {"equals": "أبيض", "category": "word_confusion", "feedback": "أبيض (أ + ب + ي + ض) veut dire « blanc ». Pour « entendu », il faut ح + ا + ض + ر : حاضر."}, {"equals": "أحسن", "category": "word_confusion", "feedback": "أحسن (أ + ح + س + ن) veut dire « mieux ». Pour « entendu », il faut ح + ا + ض + ر : حاضر."}], "options": ["حاضر", "صباح", "أبيض", "أحسن"], "pool": "lesson", "lessonId": "ar.l12", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e07', 'ar', 'ar.l12', 'ar.g12.forms_sin_family', array['ar.g12.forms_sin_family','ar.v.hadir']::text[], 'mcq', 'lesson', 'Dans حاضر, quelle forme prend la lettre ض ?', array['forme du début']::text[], 'Dans حاضر (blocs : حا | ضر), la lettre ض s''accroche à la lettre qui la suit, pas à celle d''avant : c''est la forme du début. Le ا ne s''attache pas au ض : celui-ci repart à neuf.', 3, '{"id": "ar.l12.e07", "type": "mcq", "unitIds": ["ar.g12.forms_sin_family", "ar.v.hadir"], "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Dans حاضر, quelle forme prend la lettre ض ?", "promptLanguage": "fr", "answer": "forme du début", "acceptedAnswers": ["forme du début"], "explanation": "Dans حاضر (blocs : حا | ضر), la lettre ض s''accroche à la lettre qui la suit, pas à celle d''avant : c''est la forme du début. Le ا ne s''attache pas au ض : celui-ci repart à neuf.", "tip": "Regarde si la lettre s''accroche à celle d''avant (à droite) et à celle d''après (à gauche).", "extraExample": {"text": "حاضر", "translation": "entendu"}, "errorPatterns": [{"equals": "forme isolée", "category": "instruction", "feedback": "Sans trait ـ, la lettre est seule : c''est la forme isolée."}, {"equals": "forme du milieu", "category": "instruction", "feedback": "Un trait ـ de chaque côté : c''est la forme du milieu."}, {"equals": "forme de la fin", "category": "instruction", "feedback": "Le trait ـ est à droite, vers la lettre précédente : c''est la forme de la fin."}], "options": ["forme isolée", "forme du début", "forme du milieu", "forme de la fin"], "pool": "lesson", "lessonId": "ar.l12", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e08', 'ar', 'ar.l12', 'ar.g12.forms_sin_family', array['ar.g12.forms_sin_family','ar.v.abyad']::text[], 'mcq', 'lesson', 'Dans أبيض, quelle forme prend la lettre ض ?', array['forme de la fin']::text[], 'Dans أبيض (blocs : أ | بيض), la lettre ض s''accroche seulement à la lettre d''avant : c''est la forme de la fin. Le ض est attaché au ي qui le précède, et rien ne le suit.', 3, '{"id": "ar.l12.e08", "type": "mcq", "unitIds": ["ar.g12.forms_sin_family", "ar.v.abyad"], "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Dans أبيض, quelle forme prend la lettre ض ?", "promptLanguage": "fr", "answer": "forme de la fin", "acceptedAnswers": ["forme de la fin"], "explanation": "Dans أبيض (blocs : أ | بيض), la lettre ض s''accroche seulement à la lettre d''avant : c''est la forme de la fin. Le ض est attaché au ي qui le précède, et rien ne le suit.", "tip": "Regarde si la lettre s''accroche à celle d''avant (à droite) et à celle d''après (à gauche).", "extraExample": {"text": "أبيض", "translation": "blanc"}, "errorPatterns": [{"equals": "forme isolée", "category": "instruction", "feedback": "Sans trait ـ, la lettre est seule : c''est la forme isolée."}, {"equals": "forme du début", "category": "instruction", "feedback": "Le trait ـ est à gauche, vers la lettre suivante : c''est la forme du début."}, {"equals": "forme du milieu", "category": "instruction", "feedback": "Un trait ـ de chaque côté : c''est la forme du milieu."}], "options": ["forme isolée", "forme du début", "forme du milieu", "forme de la fin"], "pool": "lesson", "lessonId": "ar.l12", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e09', 'ar', 'ar.l12', 'ar.g12.forms_sin_family', array['ar.g12.forms_sin_family','ar.v.sayyad']::text[], 'mcq', 'lesson', 'Combien de blocs compte صياد ?', array['2 blocs']::text[], 'صياد = صيا | د : 2 blocs. Le mot se coupe après ا.', 2, '{"id": "ar.l12.e09", "type": "mcq", "unitIds": ["ar.g12.forms_sin_family", "ar.v.sayyad"], "difficulty": 2, "instruction": "Compte les blocs.", "prompt": "Combien de blocs compte صياد ?", "promptLanguage": "fr", "answer": "2 blocs", "acceptedAnswers": ["2 blocs"], "explanation": "صياد = صيا | د : 2 blocs. Le mot se coupe après ا.", "tip": "Après chaque ا د ذ ر ز و, un nouveau bloc commence.", "extraExample": {"text": "صياد", "translation": "pêcheur"}, "errorPatterns": [{"equals": "1 bloc", "category": "instruction", "feedback": "Tu as oublié une coupure : seules ا د ذ ر ز و ne s''attachent pas à la suivante. Ici : صيا | د."}, {"equals": "3 blocs", "category": "instruction", "feedback": "Tu as coupé trop de fois : seules ا د ذ ر ز و ne s''attachent pas à la suivante. Ici : صيا | د."}, {"equals": "4 blocs", "category": "instruction", "feedback": "Tu as coupé trop de fois : seules ا د ذ ر ز و ne s''attachent pas à la suivante. Ici : صيا | د."}], "options": ["1 bloc", "2 blocs", "3 blocs", "4 blocs"], "pool": "lesson", "lessonId": "ar.l12", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e10', 'ar', 'ar.l12', 'ar.v.jiddu', array['ar.v.jiddu']::text[], 'mcq', 'lesson', 'Quel mot veut dire « papy » ?', array['جدو']::text[], '« papy » s''écrit ج + د + و : جدو. Le د ferme le premier bloc : جد | و.', 1, '{"id": "ar.l12.e10", "type": "mcq", "unitIds": ["ar.v.jiddu"], "difficulty": 1, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « papy » ?", "promptLanguage": "fr", "answer": "جدو", "acceptedAnswers": ["جدو"], "explanation": "« papy » s''écrit ج + د + و : جدو. Le د ferme le premier bloc : جد | و.", "tip": "Compare les points et les attaches, lettre par lettre.", "extraExample": {"text": "رحنا نزور جدو.", "translation": "Nous sommes allés rendre visite à papy."}, "errorPatterns": [{"equals": "حد", "category": "word_confusion", "feedback": "حد (ح + د) veut dire « quelqu''un ». Pour « papy », il faut ج + د + و : جدو."}, {"equals": "خد", "category": "word_confusion", "feedback": "خد (خ + د) veut dire « prends ». Pour « papy », il faut ج + د + و : جدو."}, {"equals": "جيب", "category": "word_confusion", "feedback": "جيب (ج + ي + ب) veut dire « poche ». Pour « papy », il faut ج + د + و : جدو."}], "options": ["جدو", "حد", "خد", "جيب"], "pool": "lesson", "lessonId": "ar.l12", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e11', 'ar', 'ar.l12', 'ar.v.jim', array['ar.v.jim']::text[], 'mcq', 'lesson', 'Dans جيب, quelle forme prend la lettre ج ?', array['forme du début']::text[], 'Dans جيب, la lettre ج s''accroche à la lettre qui la suit, pas à celle d''avant : c''est la forme du début. Le ج s''attache au ي qui le suit : forme du début جـ.', 2, '{"id": "ar.l12.e11", "type": "mcq", "unitIds": ["ar.v.jim"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Dans جيب, quelle forme prend la lettre ج ?", "promptLanguage": "fr", "answer": "forme du début", "acceptedAnswers": ["forme du début"], "explanation": "Dans جيب, la lettre ج s''accroche à la lettre qui la suit, pas à celle d''avant : c''est la forme du début. Le ج s''attache au ي qui le suit : forme du début جـ.", "tip": "Regarde si la lettre s''accroche à celle d''avant (à droite) et à celle d''après (à gauche).", "extraExample": {"text": "جيب", "translation": "poche"}, "errorPatterns": [{"equals": "forme isolée", "category": "instruction", "feedback": "Sans trait ـ, la lettre est seule : c''est la forme isolée."}, {"equals": "forme du milieu", "category": "instruction", "feedback": "Un trait ـ de chaque côté : c''est la forme du milieu."}, {"equals": "forme de la fin", "category": "instruction", "feedback": "Le trait ـ est à droite, vers la lettre précédente : c''est la forme de la fin."}], "options": ["forme isolée", "forme du début", "forme du milieu", "forme de la fin"], "pool": "lesson", "lessonId": "ar.l12", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e12', 'ar', 'ar.l12', 'ar.v.rabbina', array['ar.v.rabbina']::text[], 'mcq', 'lesson', 'Combien de blocs compte ربنا ?', array['2 blocs']::text[], 'ربنا = ر | بنا : 2 blocs. Le mot se coupe après ر.', 2, '{"id": "ar.l12.e12", "type": "mcq", "unitIds": ["ar.v.rabbina"], "difficulty": 2, "instruction": "Compte les blocs.", "prompt": "Combien de blocs compte ربنا ?", "promptLanguage": "fr", "answer": "2 blocs", "acceptedAnswers": ["2 blocs"], "explanation": "ربنا = ر | بنا : 2 blocs. Le mot se coupe après ر.", "tip": "Après chaque ا د ذ ر ز و, un nouveau bloc commence.", "extraExample": {"text": "ربنا", "translation": "notre Seigneur"}, "errorPatterns": [{"equals": "1 bloc", "category": "instruction", "feedback": "Tu as oublié une coupure : seules ا د ذ ر ز و ne s''attachent pas à la suivante. Ici : ر | بنا."}, {"equals": "3 blocs", "category": "instruction", "feedback": "Tu as coupé trop de fois : seules ا د ذ ر ز و ne s''attachent pas à la suivante. Ici : ر | بنا."}, {"equals": "4 blocs", "category": "instruction", "feedback": "Tu as coupé trop de fois : seules ا د ذ ر ز و ne s''attachent pas à la suivante. Ici : ر | بنا."}], "options": ["1 bloc", "2 blocs", "3 blocs", "4 blocs"], "pool": "lesson", "lessonId": "ar.l12", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e13', 'ar', 'ar.l12', 'ar.g12.forms_sin_family', array['ar.g12.forms_sin_family','ar.v.shay']::text[], 'fill_blank', 'lesson', '___ـاي', array['ش']::text[], 'شاي commence par ش : trois dents et 3 points dessus. Sans les points, ce serait س.', 2, '{"id": "ar.l12.e13", "type": "fill_blank", "unitIds": ["ar.g12.forms_sin_family", "ar.v.shay"], "difficulty": 2, "instruction": "Quelle lettre manque pour écrire « thé » ?", "prompt": "___ـاي", "promptLanguage": "ar", "answer": "ش", "acceptedAnswers": ["ش"], "explanation": "شاي commence par ش : trois dents et 3 points dessus. Sans les points, ce serait س.", "tip": "3 dents + 3 points = ش.", "extraExample": {"text": "الشاي بالنعناع.", "translation": "Le thé à la menthe."}, "errorPatterns": [{"equals": "س", "category": "spelling", "feedback": "س a les mêmes dents mais aucun point."}, {"equals": "ث", "category": "spelling", "feedback": "ث a 3 points mais pas de dents."}], "options": ["ش", "س", "ث"], "pool": "lesson", "lessonId": "ar.l12", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e14', 'ar', 'ar.l12', 'ar.g12.forms_sin_family', array['ar.g12.forms_sin_family','ar.v.sabt']::text[], 'fill_blank', 'lesson', '___ـبـت', array['س']::text[], 'سبت commence par س : trois dents, aucun point. ش aurait 3 points, ص une boucle.', 2, '{"id": "ar.l12.e14", "type": "fill_blank", "unitIds": ["ar.g12.forms_sin_family", "ar.v.sabt"], "difficulty": 2, "instruction": "Quelle lettre manque pour écrire « samedi » ?", "prompt": "___ـبـت", "promptLanguage": "ar", "answer": "س", "acceptedAnswers": ["س"], "explanation": "سبت commence par س : trois dents, aucun point. ش aurait 3 points, ص une boucle.", "tip": "Trois dents sans point : س.", "extraExample": {"text": "السبت ده إجازة.", "translation": "Ce samedi est un jour de congé."}, "errorPatterns": [{"equals": "ش", "category": "spelling", "feedback": "ش a 3 points dessus ; ici il n''y en a aucun."}, {"equals": "ص", "category": "spelling", "feedback": "ص a une boucle, pas des dents."}, {"equals": "ض", "category": "spelling", "feedback": "ض a une boucle et un point."}], "options": ["س", "ش", "ص", "ض"], "pool": "lesson", "lessonId": "ar.l12", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e15', 'ar', 'ar.l12', 'ar.g12.forms_sin_family', array['ar.g12.forms_sin_family','ar.v.abyad']::text[], 'fill_blank', 'lesson', 'أبـيـ___', array['ض']::text[], 'أبيض finit par ض : une boucle et 1 point dessus. ص aurait une boucle sans point.', 3, '{"id": "ar.l12.e15", "type": "fill_blank", "unitIds": ["ar.g12.forms_sin_family", "ar.v.abyad"], "difficulty": 3, "instruction": "Quelle lettre manque pour écrire « blanc » ?", "prompt": "أبـيـ___", "promptLanguage": "ar", "answer": "ض", "acceptedAnswers": ["ض"], "explanation": "أبيض finit par ض : une boucle et 1 point dessus. ص aurait une boucle sans point.", "tip": "Boucle + 1 point : ض.", "extraExample": {"text": "اللبن لونه أبيض.", "translation": "Le lait est blanc."}, "errorPatterns": [{"equals": "ص", "category": "spelling", "feedback": "ص n''a pas de point ; il en faut un dessus : ض."}], "options": ["ض", "ص", "س", "ش"], "pool": "lesson", "lessonId": "ar.l12", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e16', 'ar', 'ar.l12', 'ar.g12.forms_sin_family', array['ar.g12.forms_sin_family','ar.v.shay','ar.v.sabah','ar.v.jaras','ar.v.sabt','ar.v.abyad']::text[], 'match', 'lesson', 'Mots des dents et des boucles', '{}'::text[], 'Compte les dents et cherche les points : ش (3 points), ص (boucle), س (dents sans point).', 2, '{"id": "ar.l12.e16", "type": "match", "unitIds": ["ar.g12.forms_sin_family", "ar.v.shay", "ar.v.sabah", "ar.v.jaras", "ar.v.sabt", "ar.v.abyad"], "difficulty": 2, "instruction": "Associe chaque mot à son sens.", "prompt": "Mots des dents et des boucles", "promptLanguage": "fr", "answer": "شاي = thé ; صباح = matin ; جرس = cloche ; سبت = samedi ; أبيض = blanc", "acceptedAnswers": [], "explanation": "Compte les dents et cherche les points : ش (3 points), ص (boucle), س (dents sans point).", "pairs": [{"left": "شاي", "right": "thé"}, {"left": "صباح", "right": "matin"}, {"left": "جرس", "right": "cloche"}, {"left": "سبت", "right": "samedi"}, {"left": "أبيض", "right": "blanc"}], "pool": "lesson", "lessonId": "ar.l12", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e17', 'ar', 'ar.l12', 'ar.g12.forms_sin_family', array['ar.g12.forms_sin_family','ar.v.sin','ar.v.shin','ar.v.sad','ar.v.dad']::text[], 'match', 'lesson', 'Les formes du début de س ش ص ض', '{}'::text[], 'La forme du début garde les dents (ou la boucle) et les points, avec le trait ـ à gauche.', 2, '{"id": "ar.l12.e17", "type": "match", "unitIds": ["ar.g12.forms_sin_family", "ar.v.sin", "ar.v.shin", "ar.v.sad", "ar.v.dad"], "difficulty": 2, "instruction": "Associe chaque lettre isolée à sa forme du début.", "prompt": "Les formes du début de س ش ص ض", "promptLanguage": "fr", "answer": "س = سـ ; ش = شـ ; ص = صـ ; ض = ضـ", "acceptedAnswers": [], "explanation": "La forme du début garde les dents (ou la boucle) et les points, avec le trait ـ à gauche.", "pairs": [{"left": "س", "right": "سـ"}, {"left": "ش", "right": "شـ"}, {"left": "ص", "right": "صـ"}, {"left": "ض", "right": "ضـ"}], "pool": "lesson", "lessonId": "ar.l12", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e18', 'ar', 'ar.l12', 'ar.g12.forms_sin_family', array['ar.g12.forms_sin_family','ar.v.sin','ar.v.shin','ar.v.sad','ar.v.dad']::text[], 'match', 'lesson', 'Dents ou boucle, points ou non', '{}'::text[], 'Deux questions : des dents ou une boucle ? Combien de points ?', 3, '{"id": "ar.l12.e18", "type": "match", "unitIds": ["ar.g12.forms_sin_family", "ar.v.sin", "ar.v.shin", "ar.v.sad", "ar.v.dad"], "difficulty": 3, "instruction": "Associe chaque lettre à son dessin.", "prompt": "Dents ou boucle, points ou non", "promptLanguage": "fr", "answer": "س = 3 dents, aucun point ; ش = 3 dents, 3 points dessus ; ص = boucle, aucun point ; ض = boucle, 1 point dessus", "acceptedAnswers": [], "explanation": "Deux questions : des dents ou une boucle ? Combien de points ?", "pairs": [{"left": "س", "right": "3 dents, aucun point"}, {"left": "ش", "right": "3 dents, 3 points dessus"}, {"left": "ص", "right": "boucle, aucun point"}, {"left": "ض", "right": "boucle, 1 point dessus"}], "pool": "lesson", "lessonId": "ar.l12", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e19', 'ar', 'ar.l12', 'ar.v.bakhur', array['ar.v.bakhur','ar.v.jazar','ar.v.khawkh','ar.v.khud','ar.v.jiddu']::text[], 'match', 'lesson', 'Mots de la leçon 11', '{}'::text[], 'Cherche la tête et son point : dessous pour ج, aucun pour ح, dessus pour خ.', 2, '{"id": "ar.l12.e19", "type": "match", "unitIds": ["ar.v.bakhur", "ar.v.jazar", "ar.v.khawkh", "ar.v.khud", "ar.v.jiddu"], "difficulty": 2, "instruction": "Révision : associe chaque mot à son sens.", "prompt": "Mots de la leçon 11", "promptLanguage": "fr", "answer": "بخور = encens ; جزر = carottes ; خوخ = pêches ; خد = prends ; جدو = papy", "acceptedAnswers": [], "explanation": "Cherche la tête et son point : dessous pour ج, aucun pour ح, dessus pour خ.", "pairs": [{"left": "بخور", "right": "encens"}, {"left": "جزر", "right": "carottes"}, {"left": "خوخ", "right": "pêches"}, {"left": "خد", "right": "prends"}, {"left": "جدو", "right": "papy"}], "pool": "lesson", "lessonId": "ar.l12", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e20', 'ar', 'ar.l12', 'ar.g12.forms_sin_family', array['ar.g12.forms_sin_family','ar.v.hadir']::text[], 'translation', 'lesson', 'حاضر', array['entendu','d''accord','dac','ok','oui','à vos ordres','bien','présent','tout de suite']::text[], 'حاضر = حا | ضر : le ا ferme le premier bloc et le ض repart à neuf. C''est la réponse « entendu ! ».', 3, '{"id": "ar.l12.e20", "type": "translation", "unitIds": ["ar.g12.forms_sin_family", "ar.v.hadir"], "difficulty": 3, "instruction": "Écris le sens en français.", "prompt": "حاضر", "promptLanguage": "ar", "answer": "entendu", "acceptedAnswers": ["entendu", "d''accord", "dac", "ok", "oui", "à vos ordres", "bien", "présent", "tout de suite"], "explanation": "حاضر = حا | ضر : le ا ferme le premier bloc et le ض repart à neuf. C''est la réponse « entendu ! ».", "tip": "Retiens حاضر comme le « oui, tout de suite » égyptien.", "extraExample": {"text": "حاضر يا ماما.", "translation": "Entendu, maman."}, "pool": "lesson", "lessonId": "ar.l12", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e21', 'ar', 'ar.l12', 'ar.g12.forms_sin_family', array['ar.g12.forms_sin_family','ar.v.ahsan']::text[], 'translation', 'lesson', 'أحسن', array['mieux','meilleur','le meilleur','le mieux']::text[], 'أحسن = أ | حسن : le س du milieu est entre ح et ن (ـسـ). C''est « mieux », « le meilleur ».', 3, '{"id": "ar.l12.e21", "type": "translation", "unitIds": ["ar.g12.forms_sin_family", "ar.v.ahsan"], "difficulty": 3, "instruction": "Écris le sens en français.", "prompt": "أحسن", "promptLanguage": "ar", "answer": "mieux", "acceptedAnswers": ["mieux", "meilleur", "le meilleur", "le mieux"], "explanation": "أحسن = أ | حسن : le س du milieu est entre ح et ن (ـسـ). C''est « mieux », « le meilleur ».", "tip": "Compte les dents du milieu : ح + س + ن.", "extraExample": {"text": "ده أحسن واحد.", "translation": "C''est le meilleur."}, "pool": "lesson", "lessonId": "ar.l12", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e22', 'ar', 'ar.l12', 'ar.g12.forms_sin_family', array['ar.g12.forms_sin_family','ar.v.sirr']::text[], 'free_answer', 'lesson', 'Que veut dire سر ?', array['secret','un secret','le secret','sacrement','un sacrement']::text[], 'سر = س + ر, sans aucun point : un secret, et dans l''Église un sacrement.', 3, '{"id": "ar.l12.e22", "type": "free_answer", "unitIds": ["ar.g12.forms_sin_family", "ar.v.sirr"], "difficulty": 3, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire سر ?", "promptLanguage": "fr", "answer": "secret", "acceptedAnswers": ["secret", "un secret", "le secret", "sacrement", "un sacrement"], "explanation": "سر = س + ر, sans aucun point : un secret, et dans l''Église un sacrement.", "tip": "Deux lettres, un seul bloc.", "extraExample": {"text": "المعمودية سر من أسرار الكنيسة.", "translation": "Le baptême est un sacrement de l''Église."}, "pool": "lesson", "lessonId": "ar.l12", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l12.e23', 'ar', 'ar.l12', 'ar.g12.forms_sin_family', array['ar.g12.forms_sin_family','ar.v.nuss']::text[], 'free_answer', 'lesson', 'Que veut dire نص ?', array['moitié','moitie','la moitié','demi','une moitié']::text[], 'نص = ن + ص : le ص a une boucle sans point. C''est la moitié, comme dans « une demi-heure ».', 3, '{"id": "ar.l12.e23", "type": "free_answer", "unitIds": ["ar.g12.forms_sin_family", "ar.v.nuss"], "difficulty": 3, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire نص ?", "promptLanguage": "fr", "answer": "moitié", "acceptedAnswers": ["moitié", "moitie", "la moitié", "demi", "une moitié"], "explanation": "نص = ن + ص : le ص a une boucle sans point. C''est la moitié, comme dans « une demi-heure ».", "tip": "ن (1 point dessus) puis ص (boucle).", "extraExample": {"text": "نص ساعة.", "translation": "Une demi-heure."}, "pool": "lesson", "lessonId": "ar.l12", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e01', 'ar', 'ar.l13', 'ar.g13.forms_ayn_family', array['ar.g13.forms_ayn_family','ar.v.ayn']::text[], 'mcq', 'lesson', 'Laquelle de ces formes est la forme du début de ع ?', array['عـ']::text[], 'La forme du début s''accroche à la lettre suivante : le trait ـ est à gauche.', 1, '{"id": "ar.l13.e01", "type": "mcq", "unitIds": ["ar.g13.forms_ayn_family", "ar.v.ayn"], "difficulty": 1, "instruction": "Choisis la bonne forme.", "prompt": "Laquelle de ces formes est la forme du début de ع ?", "promptLanguage": "fr", "answer": "عـ", "acceptedAnswers": ["عـ"], "explanation": "La forme du début s''accroche à la lettre suivante : le trait ـ est à gauche.", "tip": "Début = trait à gauche.", "extraExample": {"text": "عيش", "translation": "pain"}, "errorPatterns": [{"equals": "ـعـ", "category": "instruction", "feedback": "ـعـ a un trait de chaque côté : forme du milieu."}, {"equals": "ـع", "category": "instruction", "feedback": "ـع a le trait à droite : forme de la fin."}, {"equals": "ع", "category": "instruction", "feedback": "ع sans trait : forme isolée."}], "options": ["عـ", "ـعـ", "ـع", "ع"], "pool": "lesson", "lessonId": "ar.l13", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e02', 'ar', 'ar.l13', 'ar.g13.forms_ayn_family', array['ar.g13.forms_ayn_family','ar.v.zah']::text[], 'mcq', 'lesson', 'Quelle lettre est une boucle avec un mât et 1 point dessus ?', array['ظ']::text[], 'ظ est ط (boucle + mât) avec 1 point dessus. ط n''a pas de point ; ع et غ n''ont pas de mât.', 2, '{"id": "ar.l13.e02", "type": "mcq", "unitIds": ["ar.g13.forms_ayn_family", "ar.v.zah"], "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre est une boucle avec un mât et 1 point dessus ?", "promptLanguage": "fr", "answer": "ظ", "acceptedAnswers": ["ظ"], "explanation": "ظ est ط (boucle + mât) avec 1 point dessus. ط n''a pas de point ; ع et غ n''ont pas de mât.", "tip": "Bâton + point dessus : ظ.", "extraExample": {"text": "حظ", "translation": "chance"}, "errorPatterns": [{"equals": "ط", "category": "spelling", "feedback": "ط a le même dessin mais aucun point."}, {"equals": "ع", "category": "spelling", "feedback": "ع n''a pas de mât : c''est une œil."}, {"equals": "غ", "category": "spelling", "feedback": "غ n''a pas de mât : c''est une œil avec un point."}], "options": ["ظ", "ط", "ع", "غ"], "pool": "lesson", "lessonId": "ar.l13", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e03', 'ar', 'ar.l13', 'ar.g13.forms_ayn_family', array['ar.g13.forms_ayn_family','ar.v.eish']::text[], 'mcq', 'lesson', 'عيش', array['pain']::text[], 'Lettre par lettre : ع (sans point), ي (2 points dessous), ش (3 points dessus) donne عيش, « pain ». ع (tête) + ي + ش (3 dents, 3 points) : 1 bloc.', 2, '{"id": "ar.l13.e03", "type": "mcq", "unitIds": ["ar.g13.forms_ayn_family", "ar.v.eish"], "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "عيش", "promptLanguage": "ar", "answer": "pain", "acceptedAnswers": ["pain"], "explanation": "Lettre par lettre : ع (sans point), ي (2 points dessous), ش (3 points dessus) donne عيش, « pain ». ع (tête) + ي + ش (3 dents, 3 points) : 1 bloc.", "tip": "Lis de droite à gauche, lettre après lettre, puis dis le mot à voix haute.", "extraExample": {"text": "عايز عيش وجبنة.", "translation": "Je voudrais du pain et du fromage."}, "errorPatterns": [{"equals": "thé", "category": "word_confusion", "feedback": "« thé » s''écrit شاي (ش + ا + ي). Ici tu lis ع + ي + ش : عيش veut dire « pain »."}, {"equals": "fête", "category": "word_confusion", "feedback": "« fête » s''écrit عيد (ع + ي + د). Ici tu lis ع + ي + ش : عيش veut dire « pain »."}, {"equals": "chance", "category": "word_confusion", "feedback": "« chance » s''écrit حظ (ح + ظ). Ici tu lis ع + ي + ش : عيش veut dire « pain »."}], "options": ["pain", "thé", "fête", "chance"], "pool": "lesson", "lessonId": "ar.l13", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e04', 'ar', 'ar.l13', 'ar.g13.forms_ayn_family', array['ar.g13.forms_ayn_family','ar.v.ghani']::text[], 'mcq', 'lesson', 'غني', array['riche']::text[], 'Lettre par lettre : غ (1 point dessus), ن (1 point dessus), ي (2 points dessous) donne غني, « riche ». غ (1 point dessus) + ن + ي : 1 bloc.', 2, '{"id": "ar.l13.e04", "type": "mcq", "unitIds": ["ar.g13.forms_ayn_family", "ar.v.ghani"], "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "غني", "promptLanguage": "ar", "answer": "riche", "acceptedAnswers": ["riche"], "explanation": "Lettre par lettre : غ (1 point dessus), ن (1 point dessus), ي (2 points dessous) donne غني, « riche ». غ (1 point dessus) + ن + ي : 1 bloc.", "tip": "Lis de droite à gauche, lettre après lettre, puis dis le mot à voix haute.", "extraExample": {"text": "الراجل ده غني.", "translation": "Cet homme est riche."}, "hint": "Le point dessus change ع en غ.", "errorPatterns": [{"equals": "affamé", "category": "word_confusion", "feedback": "« affamé » s''écrit جعان (ج + ع + ا + ن). Ici tu lis غ + ن + ي : غني veut dire « riche »."}, {"equals": "pain", "category": "word_confusion", "feedback": "« pain » s''écrit عيش (ع + ي + ش). Ici tu lis غ + ن + ي : غني veut dire « riche »."}, {"equals": "oiseau", "category": "word_confusion", "feedback": "« oiseau » s''écrit طير (ط + ي + ر). Ici tu lis غ + ن + ي : غني veut dire « riche »."}], "options": ["riche", "affamé", "pain", "oiseau"], "pool": "lesson", "lessonId": "ar.l13", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e05', 'ar', 'ar.l13', 'ar.g13.forms_ayn_family', array['ar.g13.forms_ayn_family','ar.v.tayyib']::text[], 'mcq', 'lesson', 'طيب', array['bon']::text[], 'Lettre par lettre : ط (sans point), ي (2 points dessous), ب (1 point dessous) donne طيب, « bon ». ط : boucle et mât, aucun point. 1 bloc.', 3, '{"id": "ar.l13.e05", "type": "mcq", "unitIds": ["ar.g13.forms_ayn_family", "ar.v.tayyib"], "difficulty": 3, "instruction": "Lis le mot et choisis son sens.", "prompt": "طيب", "promptLanguage": "ar", "answer": "bon", "acceptedAnswers": ["bon"], "explanation": "Lettre par lettre : ط (sans point), ي (2 points dessous), ب (1 point dessous) donne طيب, « bon ». ط : boucle et mât, aucun point. 1 bloc.", "tip": "Lis de droite à gauche, lettre après lettre, puis dis le mot à voix haute.", "extraExample": {"text": "إنت إنسان طيب.", "translation": "Tu es quelqu''un de bon."}, "hint": "Regarde la dernière lettre.", "errorPatterns": [{"equals": "oiseau", "category": "word_confusion", "feedback": "« oiseau » s''écrit طير (ط + ي + ر). Ici tu lis ط + ي + ب : طيب veut dire « bon »."}, {"equals": "riche", "category": "word_confusion", "feedback": "« riche » s''écrit غني (غ + ن + ي). Ici tu lis ط + ي + ب : طيب veut dire « bon »."}, {"equals": "pain", "category": "word_confusion", "feedback": "« pain » s''écrit عيش (ع + ي + ش). Ici tu lis ط + ي + ب : طيب veut dire « bon »."}], "options": ["bon", "oiseau", "riche", "pain"], "pool": "lesson", "lessonId": "ar.l13", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e06', 'ar', 'ar.l13', 'ar.g13.forms_ayn_family', array['ar.g13.forms_ayn_family','ar.v.tayr']::text[], 'mcq', 'lesson', 'Quel mot veut dire « oiseau » ?', array['طير']::text[], '« oiseau » s''écrit ط + ي + ر : طير. ط + ي + ر : 1 bloc. La dernière lettre est ر, pas ب.', 3, '{"id": "ar.l13.e06", "type": "mcq", "unitIds": ["ar.g13.forms_ayn_family", "ar.v.tayr"], "difficulty": 3, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « oiseau » ?", "promptLanguage": "fr", "answer": "طير", "acceptedAnswers": ["طير"], "explanation": "« oiseau » s''écrit ط + ي + ر : طير. ط + ي + ر : 1 bloc. La dernière lettre est ر, pas ب.", "tip": "Compare les points et les attaches, lettre par lettre.", "extraExample": {"text": "طيور السما.", "translation": "Les oiseaux du ciel."}, "hint": "La dernière lettre n''a aucun point.", "errorPatterns": [{"equals": "طيب", "category": "word_confusion", "feedback": "طيب (ط + ي + ب) veut dire « bon ». Pour « oiseau », il faut ط + ي + ر : طير."}, {"equals": "عيد", "category": "word_confusion", "feedback": "عيد (ع + ي + د) veut dire « fête ». Pour « oiseau », il faut ط + ي + ر : طير."}, {"equals": "غني", "category": "word_confusion", "feedback": "غني (غ + ن + ي) veut dire « riche ». Pour « oiseau », il faut ط + ي + ر : طير."}], "options": ["طير", "طيب", "عيد", "غني"], "pool": "lesson", "lessonId": "ar.l13", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e07', 'ar', 'ar.l13', 'ar.g13.forms_ayn_family', array['ar.g13.forms_ayn_family','ar.v.yasou']::text[], 'mcq', 'lesson', 'Quel mot veut dire « Jésus » ?', array['يسوع']::text[], '« Jésus » s''écrit ي + س + و + ع : يسوع. Le و ferme le bloc يسو ; le ع reste seul : forme isolée. Blocs : يسو | ع.', 2, '{"id": "ar.l13.e07", "type": "mcq", "unitIds": ["ar.g13.forms_ayn_family", "ar.v.yasou"], "difficulty": 2, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « Jésus » ?", "promptLanguage": "fr", "answer": "يسوع", "acceptedAnswers": ["يسوع"], "explanation": "« Jésus » s''écrit ي + س + و + ع : يسوع. Le و ferme le bloc يسو ; le ع reste seul : forme isolée. Blocs : يسو | ع.", "tip": "Compare les points et les attaches, lettre par lettre.", "extraExample": {"text": "اسم يسوع حلو.", "translation": "Le nom de Jésus est doux."}, "errorPatterns": [{"equals": "عيد", "category": "word_confusion", "feedback": "عيد (ع + ي + د) veut dire « fête ». Pour « Jésus », il faut ي + س + و + ع : يسوع."}, {"equals": "عيش", "category": "word_confusion", "feedback": "عيش (ع + ي + ش) veut dire « pain ». Pour « Jésus », il faut ي + س + و + ع : يسوع."}, {"equals": "عايز", "category": "word_confusion", "feedback": "عايز (ع + ا + ي + ز) veut dire « je veux ». Pour « Jésus », il faut ي + س + و + ع : يسوع."}], "options": ["يسوع", "عيد", "عيش", "عايز"], "pool": "lesson", "lessonId": "ar.l13", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e08', 'ar', 'ar.l13', 'ar.g13.forms_ayn_family', array['ar.g13.forms_ayn_family','ar.v.jaan']::text[], 'mcq', 'lesson', 'Dans جعان, quelle forme prend la lettre ع ?', array['forme du milieu']::text[], 'Dans جعان (blocs : جعا | ن), la lettre ع s''accroche des deux côtés : c''est la forme du milieu. Le ع est entre le ج et le ا : attaché des deux côtés.', 3, '{"id": "ar.l13.e08", "type": "mcq", "unitIds": ["ar.g13.forms_ayn_family", "ar.v.jaan"], "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Dans جعان, quelle forme prend la lettre ع ?", "promptLanguage": "fr", "answer": "forme du milieu", "acceptedAnswers": ["forme du milieu"], "explanation": "Dans جعان (blocs : جعا | ن), la lettre ع s''accroche des deux côtés : c''est la forme du milieu. Le ع est entre le ج et le ا : attaché des deux côtés.", "tip": "Regarde si la lettre s''accroche à celle d''avant (à droite) et à celle d''après (à gauche).", "extraExample": {"text": "جعان", "translation": "affamé"}, "errorPatterns": [{"equals": "forme isolée", "category": "instruction", "feedback": "Sans trait ـ, la lettre est seule : c''est la forme isolée."}, {"equals": "forme du début", "category": "instruction", "feedback": "Le trait ـ est à gauche, vers la lettre suivante : c''est la forme du début."}, {"equals": "forme de la fin", "category": "instruction", "feedback": "Le trait ـ est à droite, vers la lettre précédente : c''est la forme de la fin."}], "options": ["forme isolée", "forme du début", "forme du milieu", "forme de la fin"], "pool": "lesson", "lessonId": "ar.l13", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e09', 'ar', 'ar.l13', 'ar.g13.forms_ayn_family', array['ar.g13.forms_ayn_family','ar.v.yasou']::text[], 'mcq', 'lesson', 'Dans يسوع, quelle forme prend la lettre ع ?', array['forme isolée']::text[], 'Dans يسوع (blocs : يسو | ع), la lettre ع ne s''accroche à aucune voisine : c''est la forme isolée. Le و qui précède ne s''attache pas : le ع est seul, donc isolé.', 3, '{"id": "ar.l13.e09", "type": "mcq", "unitIds": ["ar.g13.forms_ayn_family", "ar.v.yasou"], "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Dans يسوع, quelle forme prend la lettre ع ?", "promptLanguage": "fr", "answer": "forme isolée", "acceptedAnswers": ["forme isolée"], "explanation": "Dans يسوع (blocs : يسو | ع), la lettre ع ne s''accroche à aucune voisine : c''est la forme isolée. Le و qui précède ne s''attache pas : le ع est seul, donc isolé.", "tip": "Regarde si la lettre s''accroche à celle d''avant (à droite) et à celle d''après (à gauche).", "extraExample": {"text": "يسوع", "translation": "Jésus"}, "errorPatterns": [{"equals": "forme du début", "category": "instruction", "feedback": "Le trait ـ est à gauche, vers la lettre suivante : c''est la forme du début."}, {"equals": "forme du milieu", "category": "instruction", "feedback": "Un trait ـ de chaque côté : c''est la forme du milieu."}, {"equals": "forme de la fin", "category": "instruction", "feedback": "Le trait ـ est à droite, vers la lettre précédente : c''est la forme de la fin."}], "options": ["forme isolée", "forme du début", "forme du milieu", "forme de la fin"], "pool": "lesson", "lessonId": "ar.l13", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e10', 'ar', 'ar.l13', 'ar.v.shay', array['ar.v.shay']::text[], 'mcq', 'lesson', 'Quel mot veut dire « thé » ?', array['شاي']::text[], '« thé » s''écrit ش + ا + ي : شاي. ش : 3 dents et 3 points dessus. Le ا ferme le premier bloc : شا | ي.', 1, '{"id": "ar.l13.e10", "type": "mcq", "unitIds": ["ar.v.shay"], "difficulty": 1, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « thé » ?", "promptLanguage": "fr", "answer": "شاي", "acceptedAnswers": ["شاي"], "explanation": "« thé » s''écrit ش + ا + ي : شاي. ش : 3 dents et 3 points dessus. Le ا ferme le premier bloc : شا | ي.", "tip": "Compare les points et les attaches, lettre par lettre.", "extraExample": {"text": "الشاي بالنعناع.", "translation": "Le thé à la menthe."}, "errorPatterns": [{"equals": "سر", "category": "word_confusion", "feedback": "سر (س + ر) veut dire « secret ». Pour « thé », il faut ش + ا + ي : شاي."}, {"equals": "صباح", "category": "word_confusion", "feedback": "صباح (ص + ب + ا + ح) veut dire « matin ». Pour « thé », il faut ش + ا + ي : شاي."}, {"equals": "سبت", "category": "word_confusion", "feedback": "سبت (س + ب + ت) veut dire « samedi ». Pour « thé », il faut ش + ا + ي : شاي."}], "options": ["شاي", "سر", "صباح", "سبت"], "pool": "lesson", "lessonId": "ar.l13", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e11', 'ar', 'ar.l13', 'ar.v.sad', array['ar.v.sad']::text[], 'mcq', 'lesson', 'Dans صباح, quelle forme prend la lettre ص ?', array['forme du début']::text[], 'Dans صباح (blocs : صبا | ح), la lettre ص s''accroche à la lettre qui la suit, pas à celle d''avant : c''est la forme du début. Le ص s''attache au ب qui le suit : forme du début صـ.', 2, '{"id": "ar.l13.e11", "type": "mcq", "unitIds": ["ar.v.sad"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Dans صباح, quelle forme prend la lettre ص ?", "promptLanguage": "fr", "answer": "forme du début", "acceptedAnswers": ["forme du début"], "explanation": "Dans صباح (blocs : صبا | ح), la lettre ص s''accroche à la lettre qui la suit, pas à celle d''avant : c''est la forme du début. Le ص s''attache au ب qui le suit : forme du début صـ.", "tip": "Regarde si la lettre s''accroche à celle d''avant (à droite) et à celle d''après (à gauche).", "extraExample": {"text": "صباح", "translation": "matin"}, "errorPatterns": [{"equals": "forme isolée", "category": "instruction", "feedback": "Sans trait ـ, la lettre est seule : c''est la forme isolée."}, {"equals": "forme du milieu", "category": "instruction", "feedback": "Un trait ـ de chaque côté : c''est la forme du milieu."}, {"equals": "forme de la fin", "category": "instruction", "feedback": "Le trait ـ est à droite, vers la lettre précédente : c''est la forme de la fin."}], "options": ["forme isolée", "forme du début", "forme du milieu", "forme de la fin"], "pool": "lesson", "lessonId": "ar.l13", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e12', 'ar', 'ar.l13', 'ar.v.khud', array['ar.v.khud']::text[], 'mcq', 'lesson', 'Lis ce mot : خد', array['prends']::text[], 'Lettre par lettre : خ (1 point dessus), د (sans point) donne خد, « prends ». Un point dessus : خ. Sans point, ce serait حد.', 2, '{"id": "ar.l13.e12", "type": "mcq", "unitIds": ["ar.v.khud"], "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "Lis ce mot : خد", "promptLanguage": "fr", "answer": "prends", "acceptedAnswers": ["prends"], "explanation": "Lettre par lettre : خ (1 point dessus), د (sans point) donne خد, « prends ». Un point dessus : خ. Sans point, ce serait حد.", "tip": "Lis de droite à gauche, lettre après lettre, puis dis le mot à voix haute.", "extraExample": {"text": "خد الكتاب ده.", "translation": "Prends ce livre."}, "errorPatterns": [{"equals": "quelqu''un", "category": "word_confusion", "feedback": "« quelqu''un » s''écrit حد (ح + د). Ici tu lis خ + د : خد veut dire « prends »."}, {"equals": "poche", "category": "word_confusion", "feedback": "« poche » s''écrit جيب (ج + ي + ب). Ici tu lis خ + د : خد veut dire « prends »."}, {"equals": "nouvelle", "category": "word_confusion", "feedback": "« nouvelle » s''écrit خبر (خ + ب + ر). Ici tu lis خ + د : خد veut dire « prends »."}], "options": ["prends", "quelqu''un", "poche", "nouvelle"], "pool": "lesson", "lessonId": "ar.l13", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e13', 'ar', 'ar.l13', 'ar.g13.forms_ayn_family', array['ar.g13.forms_ayn_family','ar.v.eish']::text[], 'fill_blank', 'lesson', '___ـيـش', array['ع']::text[], 'عيش commence par ع : une œil, sans point. غ aurait un point dessus.', 2, '{"id": "ar.l13.e13", "type": "fill_blank", "unitIds": ["ar.g13.forms_ayn_family", "ar.v.eish"], "difficulty": 2, "instruction": "Quelle lettre manque pour écrire « pain » ?", "prompt": "___ـيـش", "promptLanguage": "ar", "answer": "ع", "acceptedAnswers": ["ع"], "explanation": "عيش commence par ع : une œil, sans point. غ aurait un point dessus.", "tip": "Aucun point : ع.", "extraExample": {"text": "عايز عيش وجبنة.", "translation": "Je voudrais du pain et du fromage."}, "errorPatterns": [{"equals": "غ", "category": "spelling", "feedback": "غ a un point dessus ; ici il n''y en a pas."}, {"equals": "ح", "category": "spelling", "feedback": "ح est un crochet, pas une œil."}], "options": ["ع", "غ", "ح"], "pool": "lesson", "lessonId": "ar.l13", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e14', 'ar', 'ar.l13', 'ar.g13.forms_ayn_family', array['ar.g13.forms_ayn_family','ar.v.tayr']::text[], 'fill_blank', 'lesson', '___ـيـر', array['ط']::text[], 'طير commence par ط : boucle et mât, sans point. ظ aurait un point dessus.', 3, '{"id": "ar.l13.e14", "type": "fill_blank", "unitIds": ["ar.g13.forms_ayn_family", "ar.v.tayr"], "difficulty": 3, "instruction": "Quelle lettre manque pour écrire « oiseau » ?", "prompt": "___ـيـر", "promptLanguage": "ar", "answer": "ط", "acceptedAnswers": ["ط"], "explanation": "طير commence par ط : boucle et mât, sans point. ظ aurait un point dessus.", "tip": "Boucle + mât, aucun point : ط.", "extraExample": {"text": "طيور السما.", "translation": "Les oiseaux du ciel."}, "errorPatterns": [{"equals": "ظ", "category": "spelling", "feedback": "ظ a un point dessus ; ici il n''y en a pas."}], "options": ["ط", "ظ", "ع", "غ"], "pool": "lesson", "lessonId": "ar.l13", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e15', 'ar', 'ar.l13', 'ar.g13.forms_ayn_family', array['ar.g13.forms_ayn_family','ar.v.hazz']::text[], 'fill_blank', 'lesson', 'حـ___', array['ظ']::text[], 'حظ finit par ظ : boucle, mât et 1 point dessus. ط n''aurait pas de point.', 3, '{"id": "ar.l13.e15", "type": "fill_blank", "unitIds": ["ar.g13.forms_ayn_family", "ar.v.hazz"], "difficulty": 3, "instruction": "Quelle lettre manque pour écrire « chance » ?", "prompt": "حـ___", "promptLanguage": "ar", "answer": "ظ", "acceptedAnswers": ["ظ"], "explanation": "حظ finit par ظ : boucle, mât et 1 point dessus. ط n''aurait pas de point.", "tip": "Bâton + 1 point : ظ.", "extraExample": {"text": "حظ سعيد!", "translation": "Bonne chance !"}, "errorPatterns": [{"equals": "ط", "category": "spelling", "feedback": "ط n''a pas de point ; il en faut un dessus."}, {"equals": "ض", "category": "spelling", "feedback": "ض n''a pas de mât."}], "options": ["ظ", "ط", "ض", "غ"], "pool": "lesson", "lessonId": "ar.l13", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e16', 'ar', 'ar.l13', 'ar.g13.forms_ayn_family', array['ar.g13.forms_ayn_family','ar.v.eish','ar.v.eid','ar.v.ghada','ar.v.ghani','ar.v.tayr']::text[], 'match', 'lesson', 'Mots des lourdes et des gorges', '{}'::text[], 'Cherche la tête ع, le point de غ, la boucle de ط.', 2, '{"id": "ar.l13.e16", "type": "match", "unitIds": ["ar.g13.forms_ayn_family", "ar.v.eish", "ar.v.eid", "ar.v.ghada", "ar.v.ghani", "ar.v.tayr"], "difficulty": 2, "instruction": "Associe chaque mot à son sens.", "prompt": "Mots des lourdes et des gorges", "promptLanguage": "fr", "answer": "عيش = pain ; عيد = fête ; غدا = déjeuner ; غني = riche ; طير = oiseau", "acceptedAnswers": [], "explanation": "Cherche la tête ع, le point de غ, la boucle de ط.", "pairs": [{"left": "عيش", "right": "pain"}, {"left": "عيد", "right": "fête"}, {"left": "غدا", "right": "déjeuner"}, {"left": "غني", "right": "riche"}, {"left": "طير", "right": "oiseau"}], "pool": "lesson", "lessonId": "ar.l13", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e17', 'ar', 'ar.l13', 'ar.g13.forms_ayn_family', array['ar.g13.forms_ayn_family','ar.v.tah','ar.v.zah','ar.v.ayn','ar.v.ghayn']::text[], 'match', 'lesson', 'Les formes du début de ط ظ ع غ', '{}'::text[], 'La forme du début garde le dessin et le point, avec le trait ـ à gauche.', 2, '{"id": "ar.l13.e17", "type": "match", "unitIds": ["ar.g13.forms_ayn_family", "ar.v.tah", "ar.v.zah", "ar.v.ayn", "ar.v.ghayn"], "difficulty": 2, "instruction": "Associe chaque lettre isolée à sa forme du début.", "prompt": "Les formes du début de ط ظ ع غ", "promptLanguage": "fr", "answer": "ط = طـ ; ظ = ظـ ; ع = عـ ; غ = غـ", "acceptedAnswers": [], "explanation": "La forme du début garde le dessin et le point, avec le trait ـ à gauche.", "pairs": [{"left": "ط", "right": "طـ"}, {"left": "ظ", "right": "ظـ"}, {"left": "ع", "right": "عـ"}, {"left": "غ", "right": "غـ"}], "pool": "lesson", "lessonId": "ar.l13", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e18', 'ar', 'ar.l13', 'ar.g13.forms_ayn_family', array['ar.g13.forms_ayn_family','ar.v.tah','ar.v.zah','ar.v.ayn','ar.v.ghayn']::text[], 'match', 'lesson', 'Boucle ou tête, point ou non', '{}'::text[], 'Deux questions : un mât ou un œil ? Un point dessus ou non ?', 3, '{"id": "ar.l13.e18", "type": "match", "unitIds": ["ar.g13.forms_ayn_family", "ar.v.tah", "ar.v.zah", "ar.v.ayn", "ar.v.ghayn"], "difficulty": 3, "instruction": "Associe chaque lettre à son dessin.", "prompt": "Boucle ou tête, point ou non", "promptLanguage": "fr", "answer": "ط = boucle et mât, aucun point ; ظ = boucle et mât, 1 point dessus ; ع = œil, aucun point ; غ = œil, 1 point dessus", "acceptedAnswers": [], "explanation": "Deux questions : un mât ou un œil ? Un point dessus ou non ?", "pairs": [{"left": "ط", "right": "boucle et mât, aucun point"}, {"left": "ظ", "right": "boucle et mât, 1 point dessus"}, {"left": "ع", "right": "œil, aucun point"}, {"left": "غ", "right": "œil, 1 point dessus"}], "pool": "lesson", "lessonId": "ar.l13", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
