insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e20', 'ar', 'ar.l13', 'ar.g13.forms_ayn_family', array['ar.g13.forms_ayn_family','ar.v.ayiz']::text[], 'translation', 'lesson', 'عايز', array['je veux','veux','il veut','tu veux','je voudrais','il voudrait','tu voudrais','vouloir']::text[], 'عايز = عا | يز : ع (œil), le ا ferme le premier bloc, puis ي et ز. C''est « je veux » dans la bouche d''un homme.', 3, '{"id": "ar.l13.e20", "type": "translation", "unitIds": ["ar.g13.forms_ayn_family", "ar.v.ayiz"], "difficulty": 3, "instruction": "Écris le sens en français.", "prompt": "عايز", "promptLanguage": "ar", "answer": "je veux", "acceptedAnswers": ["je veux", "veux", "il veut", "tu veux", "je voudrais", "il voudrait", "tu voudrais", "vouloir"], "explanation": "عايز = عا | يز : ع (œil), le ا ferme le premier bloc, puis ي et ز. C''est « je veux » dans la bouche d''un homme.", "tip": "عايز s''adapte à celui qui parle : je veux, tu veux, il veut.", "extraExample": {"text": "إنت عايز إيه؟", "translation": "Tu veux quoi ?"}, "pool": "lesson", "lessonId": "ar.l13", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e21', 'ar', 'ar.l13', 'ar.g13.forms_ayn_family', array['ar.g13.forms_ayn_family','ar.v.yasou']::text[], 'translation', 'lesson', 'يسوع', array['jésus','jesus','jésus christ']::text[], 'يسوع = يسو | ع : le و ferme le premier bloc et le ع reste seul. C''est Jésus.', 2, '{"id": "ar.l13.e21", "type": "translation", "unitIds": ["ar.g13.forms_ayn_family", "ar.v.yasou"], "difficulty": 2, "instruction": "Écris le sens en français.", "prompt": "يسوع", "promptLanguage": "ar", "answer": "jésus", "acceptedAnswers": ["jésus", "jesus", "jésus christ"], "explanation": "يسوع = يسو | ع : le و ferme le premier bloc et le ع reste seul. C''est Jésus.", "tip": "يسو + ع : deux blocs.", "extraExample": {"text": "يسوع بيحبنا.", "translation": "Jésus nous aime."}, "pool": "lesson", "lessonId": "ar.l13", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e22', 'ar', 'ar.l13', 'ar.g13.forms_ayn_family', array['ar.g13.forms_ayn_family','ar.v.ghada']::text[], 'free_answer', 'lesson', 'Que veut dire غدا ?', array['déjeuner','dejeuner','le déjeuner','repas de midi','le repas de midi']::text[], 'غدا = غد | ا : غ (œil, 1 point dessus), د, ا. En Égypte, c''est le repas de midi.', 3, '{"id": "ar.l13.e22", "type": "free_answer", "unitIds": ["ar.g13.forms_ayn_family", "ar.v.ghada"], "difficulty": 3, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire غدا ?", "promptLanguage": "fr", "answer": "déjeuner", "acceptedAnswers": ["déjeuner", "dejeuner", "le déjeuner", "repas de midi", "le repas de midi"], "explanation": "غدا = غد | ا : غ (œil, 1 point dessus), د, ا. En Égypte, c''est le repas de midi.", "tip": "Le point sur la tête : غ. Pour « demain », on dit بكرة.", "extraExample": {"text": "الغدا جاهز.", "translation": "Le déjeuner est prêt."}, "errorPatterns": [{"equals": "pain", "category": "word_confusion", "feedback": "عيش (pain) commence par ع, sans point."}], "pool": "lesson", "lessonId": "ar.l13", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l13.e23', 'ar', 'ar.l13', 'ar.g13.forms_ayn_family', array['ar.g13.forms_ayn_family','ar.v.hazz']::text[], 'free_answer', 'lesson', 'Que veut dire حظ ?', array['chance','la chance','une chance','sort','le sort','bonne chance']::text[], 'حظ = ح + ظ : un crochet, puis une boucle avec mât et 1 point dessus. C''est la chance.', 3, '{"id": "ar.l13.e23", "type": "free_answer", "unitIds": ["ar.g13.forms_ayn_family", "ar.v.hazz"], "difficulty": 3, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire حظ ?", "promptLanguage": "fr", "answer": "chance", "acceptedAnswers": ["chance", "la chance", "une chance", "sort", "le sort", "bonne chance"], "explanation": "حظ = ح + ظ : un crochet, puis une boucle avec mât et 1 point dessus. C''est la chance.", "tip": "Le ظ final porte son point dessus.", "extraExample": {"text": "ده حظي.", "translation": "C''est ma chance."}, "pool": "lesson", "lessonId": "ar.l13", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e01', 'ar', 'ar.l14', 'ar.g14.forms_fa_lam', array['ar.g14.forms_fa_lam','ar.v.kaf']::text[], 'mcq', 'lesson', 'Laquelle de ces formes est la forme de la fin de ك ?', array['ـك']::text[], 'La forme de la fin s''accroche à la lettre d''avant : le trait ـ est à droite.', 1, '{"id": "ar.l14.e01", "type": "mcq", "unitIds": ["ar.g14.forms_fa_lam", "ar.v.kaf"], "difficulty": 1, "instruction": "Choisis la bonne forme.", "prompt": "Laquelle de ces formes est la forme de la fin de ك ?", "promptLanguage": "fr", "answer": "ـك", "acceptedAnswers": ["ـك"], "explanation": "La forme de la fin s''accroche à la lettre d''avant : le trait ـ est à droite.", "tip": "Fin = trait à droite.", "extraExample": {"text": "سكر", "translation": "sucre"}, "errorPatterns": [{"equals": "كـ", "category": "instruction", "feedback": "كـ a le trait à gauche : forme du début."}, {"equals": "ـكـ", "category": "instruction", "feedback": "ـكـ a un trait de chaque côté : forme du milieu."}, {"equals": "ك", "category": "instruction", "feedback": "ك sans trait : forme isolée."}], "options": ["ـك", "كـ", "ـكـ", "ك"], "pool": "lesson", "lessonId": "ar.l14", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e02', 'ar', 'ar.l14', 'ar.g14.forms_fa_lam', array['ar.g14.forms_fa_lam','ar.v.qaf']::text[], 'mcq', 'lesson', 'Quelle lettre a une tête ronde et 2 points dessus ?', array['ق']::text[], 'ق a une tête ronde et 2 points dessus. ف a la même tête mais 1 seul point ; ك et ل sont des bâtons.', 2, '{"id": "ar.l14.e02", "type": "mcq", "unitIds": ["ar.g14.forms_fa_lam", "ar.v.qaf"], "difficulty": 2, "instruction": "Choisis la bonne lettre.", "prompt": "Quelle lettre a une tête ronde et 2 points dessus ?", "promptLanguage": "fr", "answer": "ق", "acceptedAnswers": ["ق"], "explanation": "ق a une tête ronde et 2 points dessus. ف a la même tête mais 1 seul point ; ك et ل sont des bâtons.", "tip": "Boule + 2 points : ق.", "extraExample": {"text": "قلب", "translation": "cœur"}, "errorPatterns": [{"equals": "ف", "category": "spelling", "feedback": "ف a la même tête mais 1 seul point."}, {"equals": "ك", "category": "spelling", "feedback": "ك est un bâton, pas une tête ronde."}, {"equals": "ل", "category": "spelling", "feedback": "ل est un bâton, pas une tête ronde."}], "options": ["ق", "ف", "ك", "ل"], "pool": "lesson", "lessonId": "ar.l14", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e03', 'ar', 'ar.l14', 'ar.g14.forms_fa_lam', array['ar.g14.forms_fa_lam','ar.v.sukkar']::text[], 'mcq', 'lesson', 'سكر', array['sucre']::text[], 'Lettre par lettre : س (sans point), ك (sans point), ر (sans point) donne سكر, « sucre ». س + ك + ر : tout est attaché, 1 bloc.', 2, '{"id": "ar.l14.e03", "type": "mcq", "unitIds": ["ar.g14.forms_fa_lam", "ar.v.sukkar"], "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "سكر", "promptLanguage": "ar", "answer": "sucre", "acceptedAnswers": ["sucre"], "explanation": "Lettre par lettre : س (sans point), ك (sans point), ر (sans point) donne سكر, « sucre ». س + ك + ر : tout est attaché, 1 bloc.", "tip": "Lis de droite à gauche, lettre après lettre, puis dis le mot à voix haute.", "extraExample": {"text": "كوباية شاي بسكر.", "translation": "Un verre de thé avec du sucre."}, "errorPatterns": [{"equals": "lait", "category": "word_confusion", "feedback": "« lait » s''écrit لبن (ل + ب + ن). Ici tu lis س + ك + ر : سكر veut dire « sucre »."}, {"equals": "chaise", "category": "word_confusion", "feedback": "« chaise » s''écrit كرسي (ك + ر + س + ي). Ici tu lis س + ك + ر : سكر veut dire « sucre »."}, {"equals": "livre", "category": "word_confusion", "feedback": "« livre » s''écrit كتاب (ك + ت + ا + ب). Ici tu lis س + ك + ر : سكر veut dire « sucre »."}], "options": ["sucre", "lait", "chaise", "livre"], "pool": "lesson", "lessonId": "ar.l14", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e04', 'ar', 'ar.l14', 'ar.g14.forms_fa_lam', array['ar.g14.forms_fa_lam','ar.v.foul']::text[], 'mcq', 'lesson', 'فول', array['fèves']::text[], 'Lettre par lettre : ف (1 point dessus), و (sans point), ل (sans point) donne فول, « fèves ». Le و ferme le premier bloc : فو | ل.', 2, '{"id": "ar.l14.e04", "type": "mcq", "unitIds": ["ar.g14.forms_fa_lam", "ar.v.foul"], "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "فول", "promptLanguage": "ar", "answer": "fèves", "acceptedAnswers": ["fèves"], "explanation": "Lettre par lettre : ف (1 point dessus), و (sans point), ل (sans point) donne فول, « fèves ». Le و ferme le premier bloc : فو | ل.", "tip": "Lis de droite à gauche, lettre après lettre, puis dis le mot à voix haute.", "extraExample": {"text": "فول وطعمية.", "translation": "Du foul et des falafels."}, "errorPatterns": [{"equals": "riz", "category": "word_confusion", "feedback": "« riz » s''écrit رز (ر + ز). Ici tu lis ف + و + ل : فول veut dire « fèves »."}, {"equals": "lait", "category": "word_confusion", "feedback": "« lait » s''écrit لبن (ل + ب + ن). Ici tu lis ف + و + ل : فول veut dire « fèves »."}, {"equals": "sucre", "category": "word_confusion", "feedback": "« sucre » s''écrit سكر (س + ك + ر). Ici tu lis ف + و + ل : فول veut dire « fèves »."}], "options": ["fèves", "riz", "lait", "sucre"], "pool": "lesson", "lessonId": "ar.l14", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e05', 'ar', 'ar.l14', 'ar.g14.forms_fa_lam', array['ar.g14.forms_fa_lam','ar.v.quddas']::text[], 'mcq', 'lesson', 'Quel mot veut dire « liturgie » ?', array['قداس']::text[], '« liturgie » s''écrit ق + د + ا + س : قداس. قد | ا | س : 3 blocs. Le د et le ا ferment chacun un bloc.', 3, '{"id": "ar.l14.e05", "type": "mcq", "unitIds": ["ar.g14.forms_fa_lam", "ar.v.quddas"], "difficulty": 3, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « liturgie » ?", "promptLanguage": "fr", "answer": "قداس", "acceptedAnswers": ["قداس"], "explanation": "« liturgie » s''écrit ق + د + ا + س : قداس. قد | ا | س : 3 blocs. Le د et le ا ferment chacun un bloc.", "tip": "Compare les points et les attaches, lettre par lettre.", "extraExample": {"text": "القداس بيبدأ بدري.", "translation": "La liturgie commence tôt."}, "errorPatterns": [{"equals": "قربان", "category": "word_confusion", "feedback": "قربان (ق + ر + ب + ا + ن) veut dire « pain d''offrande ». Pour « liturgie », il faut ق + د + ا + س : قداس."}, {"equals": "قلب", "category": "word_confusion", "feedback": "قلب (ق + ل + ب) veut dire « cœur ». Pour « liturgie », il faut ق + د + ا + س : قداس."}, {"equals": "كرسي", "category": "word_confusion", "feedback": "كرسي (ك + ر + س + ي) veut dire « chaise ». Pour « liturgie », il faut ق + د + ا + س : قداس."}], "options": ["قداس", "قربان", "قلب", "كرسي"], "pool": "lesson", "lessonId": "ar.l14", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e06', 'ar', 'ar.l14', 'ar.g14.forms_fa_lam', array['ar.g14.forms_fa_lam','ar.v.injil']::text[], 'mcq', 'lesson', 'Quel mot veut dire « Évangile » ?', array['إنجيل']::text[], '« Évangile » s''écrit إ + ن + ج + ي + ل : إنجيل. Le إ (alif avec petit ء dessous) ferme le premier bloc : إ | نجيل.', 3, '{"id": "ar.l14.e06", "type": "mcq", "unitIds": ["ar.g14.forms_fa_lam", "ar.v.injil"], "difficulty": 3, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « Évangile » ?", "promptLanguage": "fr", "answer": "إنجيل", "acceptedAnswers": ["إنجيل"], "explanation": "« Évangile » s''écrit إ + ن + ج + ي + ل : إنجيل. Le إ (alif avec petit ء dessous) ferme le premier bloc : إ | نجيل.", "tip": "Compare les points et les attaches, lettre par lettre.", "extraExample": {"text": "إنجيل يوحنا.", "translation": "L''Évangile de Jean."}, "errorPatterns": [{"equals": "صليب", "category": "word_confusion", "feedback": "صليب (ص + ل + ي + ب) veut dire « croix ». Pour « Évangile », il faut إ + ن + ج + ي + ل : إنجيل."}, {"equals": "كتاب", "category": "word_confusion", "feedback": "كتاب (ك + ت + ا + ب) veut dire « livre ». Pour « Évangile », il faut إ + ن + ج + ي + ل : إنجيل."}, {"equals": "قربان", "category": "word_confusion", "feedback": "قربان (ق + ر + ب + ا + ن) veut dire « pain d''offrande ». Pour « Évangile », il faut إ + ن + ج + ي + ل : إنجيل."}], "options": ["إنجيل", "صليب", "كتاب", "قربان"], "pool": "lesson", "lessonId": "ar.l14", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e07', 'ar', 'ar.l14', 'ar.g14.forms_fa_lam', array['ar.g14.forms_fa_lam','ar.v.salib']::text[], 'mcq', 'lesson', 'Dans صليب, quelle forme prend la lettre ل ?', array['forme du milieu']::text[], 'Dans صليب, la lettre ل s''accroche des deux côtés : c''est la forme du milieu. Le ل est entre le ص et le ي : attaché des deux côtés. Il ne coupe pas le mot.', 3, '{"id": "ar.l14.e07", "type": "mcq", "unitIds": ["ar.g14.forms_fa_lam", "ar.v.salib"], "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Dans صليب, quelle forme prend la lettre ل ?", "promptLanguage": "fr", "answer": "forme du milieu", "acceptedAnswers": ["forme du milieu"], "explanation": "Dans صليب, la lettre ل s''accroche des deux côtés : c''est la forme du milieu. Le ل est entre le ص et le ي : attaché des deux côtés. Il ne coupe pas le mot.", "tip": "Regarde si la lettre s''accroche à celle d''avant (à droite) et à celle d''après (à gauche).", "extraExample": {"text": "صليب", "translation": "croix"}, "errorPatterns": [{"equals": "forme isolée", "category": "instruction", "feedback": "Sans trait ـ, la lettre est seule : c''est la forme isolée."}, {"equals": "forme du début", "category": "instruction", "feedback": "Le trait ـ est à gauche, vers la lettre suivante : c''est la forme du début."}, {"equals": "forme de la fin", "category": "instruction", "feedback": "Le trait ـ est à droite, vers la lettre précédente : c''est la forme de la fin."}], "options": ["forme isolée", "forme du début", "forme du milieu", "forme de la fin"], "pool": "lesson", "lessonId": "ar.l14", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e08', 'ar', 'ar.l14', 'ar.g14.forms_fa_lam', array['ar.g14.forms_fa_lam','ar.v.quddas']::text[], 'mcq', 'lesson', 'Combien de blocs compte قداس ?', array['3 blocs']::text[], 'قداس = قد | ا | س : 3 blocs. Le mot se coupe après د et après ا.', 3, '{"id": "ar.l14.e08", "type": "mcq", "unitIds": ["ar.g14.forms_fa_lam", "ar.v.quddas"], "difficulty": 3, "instruction": "Compte les blocs.", "prompt": "Combien de blocs compte قداس ?", "promptLanguage": "fr", "answer": "3 blocs", "acceptedAnswers": ["3 blocs"], "explanation": "قداس = قد | ا | س : 3 blocs. Le mot se coupe après د et après ا.", "tip": "Après chaque ا د ذ ر ز و, un nouveau bloc commence.", "extraExample": {"text": "قداس", "translation": "liturgie"}, "errorPatterns": [{"equals": "1 bloc", "category": "instruction", "feedback": "Tu as oublié une coupure : seules ا د ذ ر ز و ne s''attachent pas à la suivante. Ici : قد | ا | س."}, {"equals": "2 blocs", "category": "instruction", "feedback": "Tu as oublié une coupure : seules ا د ذ ر ز و ne s''attachent pas à la suivante. Ici : قد | ا | س."}, {"equals": "4 blocs", "category": "instruction", "feedback": "Tu as coupé trop de fois : seules ا د ذ ر ز و ne s''attachent pas à la suivante. Ici : قد | ا | س."}], "options": ["1 bloc", "2 blocs", "3 blocs", "4 blocs"], "pool": "lesson", "lessonId": "ar.l14", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e09', 'ar', 'ar.l14', 'ar.v.eid', array['ar.v.eid']::text[], 'mcq', 'lesson', 'Lis ce mot : عيد', array['fête']::text[], 'Lettre par lettre : ع (sans point), ي (2 points dessous), د (sans point) donne عيد, « fête ». ع + ي + د : tout est attaché, 1 bloc.', 2, '{"id": "ar.l14.e09", "type": "mcq", "unitIds": ["ar.v.eid"], "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "Lis ce mot : عيد", "promptLanguage": "fr", "answer": "fête", "acceptedAnswers": ["fête"], "explanation": "Lettre par lettre : ع (sans point), ي (2 points dessous), د (sans point) donne عيد, « fête ». ع + ي + د : tout est attaché, 1 bloc.", "tip": "Lis de droite à gauche, lettre après lettre, puis dis le mot à voix haute.", "extraExample": {"text": "عيد القيامة أجمل عيد.", "translation": "Pâques est la plus belle fête."}, "errorPatterns": [{"equals": "pain", "category": "word_confusion", "feedback": "« pain » s''écrit عيش (ع + ي + ش). Ici tu lis ع + ي + د : عيد veut dire « fête »."}, {"equals": "chance", "category": "word_confusion", "feedback": "« chance » s''écrit حظ (ح + ظ). Ici tu lis ع + ي + د : عيد veut dire « fête »."}, {"equals": "riche", "category": "word_confusion", "feedback": "« riche » s''écrit غني (غ + ن + ي). Ici tu lis ع + ي + د : عيد veut dire « fête »."}], "options": ["fête", "pain", "chance", "riche"], "pool": "lesson", "lessonId": "ar.l14", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e10', 'ar', 'ar.l14', 'ar.v.ghani', array['ar.v.ghani']::text[], 'mcq', 'lesson', 'Quel mot veut dire « riche » ?', array['غني']::text[], '« riche » s''écrit غ + ن + ي : غني. غ (1 point dessus) + ن + ي : 1 bloc.', 2, '{"id": "ar.l14.e10", "type": "mcq", "unitIds": ["ar.v.ghani"], "difficulty": 2, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « riche » ?", "promptLanguage": "fr", "answer": "غني", "acceptedAnswers": ["غني"], "explanation": "« riche » s''écrit غ + ن + ي : غني. غ (1 point dessus) + ن + ي : 1 bloc.", "tip": "Compare les points et les attaches, lettre par lettre.", "extraExample": {"text": "الغني والفقير سوا قدام ربنا.", "translation": "Le riche et le pauvre sont égaux devant Dieu."}, "errorPatterns": [{"equals": "عيد", "category": "word_confusion", "feedback": "عيد (ع + ي + د) veut dire « fête ». Pour « riche », il faut غ + ن + ي : غني."}, {"equals": "عيش", "category": "word_confusion", "feedback": "عيش (ع + ي + ش) veut dire « pain ». Pour « riche », il faut غ + ن + ي : غني."}, {"equals": "غدا", "category": "word_confusion", "feedback": "غدا (غ + د + ا) veut dire « déjeuner ». Pour « riche », il faut غ + ن + ي : غني."}], "options": ["غني", "عيد", "عيش", "غدا"], "pool": "lesson", "lessonId": "ar.l14", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e11', 'ar', 'ar.l14', 'ar.v.ayn', array['ar.v.ayn']::text[], 'mcq', 'lesson', 'Dans عايز, quelle forme prend la lettre ع ?', array['forme du début']::text[], 'Dans عايز (blocs : عا | يز), la lettre ع s''accroche à la lettre qui la suit, pas à celle d''avant : c''est la forme du début. Le ع s''attache au ا qui le suit : forme du début عـ.', 2, '{"id": "ar.l14.e11", "type": "mcq", "unitIds": ["ar.v.ayn"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Dans عايز, quelle forme prend la lettre ع ?", "promptLanguage": "fr", "answer": "forme du début", "acceptedAnswers": ["forme du début"], "explanation": "Dans عايز (blocs : عا | يز), la lettre ع s''accroche à la lettre qui la suit, pas à celle d''avant : c''est la forme du début. Le ع s''attache au ا qui le suit : forme du début عـ.", "tip": "Regarde si la lettre s''accroche à celle d''avant (à droite) et à celle d''après (à gauche).", "extraExample": {"text": "عايز", "translation": "je veux"}, "errorPatterns": [{"equals": "forme isolée", "category": "instruction", "feedback": "Sans trait ـ, la lettre est seule : c''est la forme isolée."}, {"equals": "forme du milieu", "category": "instruction", "feedback": "Un trait ـ de chaque côté : c''est la forme du milieu."}, {"equals": "forme de la fin", "category": "instruction", "feedback": "Le trait ـ est à droite, vers la lettre précédente : c''est la forme de la fin."}], "options": ["forme isolée", "forme du début", "forme du milieu", "forme de la fin"], "pool": "lesson", "lessonId": "ar.l14", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e12', 'ar', 'ar.l14', 'ar.v.yasou', array['ar.v.yasou']::text[], 'mcq', 'lesson', 'Combien de blocs compte يسوع ?', array['2 blocs']::text[], 'يسوع = يسو | ع : 2 blocs. Le mot se coupe après و.', 2, '{"id": "ar.l14.e12", "type": "mcq", "unitIds": ["ar.v.yasou"], "difficulty": 2, "instruction": "Compte les blocs.", "prompt": "Combien de blocs compte يسوع ?", "promptLanguage": "fr", "answer": "2 blocs", "acceptedAnswers": ["2 blocs"], "explanation": "يسوع = يسو | ع : 2 blocs. Le mot se coupe après و.", "tip": "Après chaque ا د ذ ر ز و, un nouveau bloc commence.", "extraExample": {"text": "يسوع", "translation": "Jésus"}, "errorPatterns": [{"equals": "1 bloc", "category": "instruction", "feedback": "Tu as oublié une coupure : seules ا د ذ ر ز و ne s''attachent pas à la suivante. Ici : يسو | ع."}, {"equals": "3 blocs", "category": "instruction", "feedback": "Tu as coupé trop de fois : seules ا د ذ ر ز و ne s''attachent pas à la suivante. Ici : يسو | ع."}, {"equals": "4 blocs", "category": "instruction", "feedback": "Tu as coupé trop de fois : seules ا د ذ ر ز و ne s''attachent pas à la suivante. Ici : يسو | ع."}], "options": ["1 bloc", "2 blocs", "3 blocs", "4 blocs"], "pool": "lesson", "lessonId": "ar.l14", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e13', 'ar', 'ar.l14', 'ar.g14.forms_fa_lam', array['ar.g14.forms_fa_lam','ar.v.kursi']::text[], 'fill_blank', 'lesson', '___ـرسـي', array['ك']::text[], 'كرسي commence par ك : un trait avec son petit zigzag. ل serait un bâton sans zigzag.', 2, '{"id": "ar.l14.e13", "type": "fill_blank", "unitIds": ["ar.g14.forms_fa_lam", "ar.v.kursi"], "difficulty": 2, "instruction": "Quelle lettre manque pour écrire « chaise » ?", "prompt": "___ـرسـي", "promptLanguage": "ar", "answer": "ك", "acceptedAnswers": ["ك"], "explanation": "كرسي commence par ك : un trait avec son petit zigzag. ل serait un bâton sans zigzag.", "tip": "Petit zigzag dans le trait : ك.", "extraExample": {"text": "اقعد على الكرسي.", "translation": "Assieds-toi sur la chaise."}, "errorPatterns": [{"equals": "ل", "category": "spelling", "feedback": "ل est un bâton sans zigzag."}], "options": ["ك", "ل", "ق", "ف"], "pool": "lesson", "lessonId": "ar.l14", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e14', 'ar', 'ar.l14', 'ar.g14.forms_fa_lam', array['ar.g14.forms_fa_lam','ar.v.qalb']::text[], 'fill_blank', 'lesson', '___ـلـب', array['ق']::text[], 'قلب commence par ق : une boule et 2 points dessus. ف n''a qu''un point.', 3, '{"id": "ar.l14.e14", "type": "fill_blank", "unitIds": ["ar.g14.forms_fa_lam", "ar.v.qalb"], "difficulty": 3, "instruction": "Quelle lettre manque pour écrire « cœur » ?", "prompt": "___ـلـب", "promptLanguage": "ar", "answer": "ق", "acceptedAnswers": ["ق"], "explanation": "قلب commence par ق : une boule et 2 points dessus. ف n''a qu''un point.", "tip": "2 points dessus : ق.", "extraExample": {"text": "بحبك من قلبي.", "translation": "Je t''aime de tout mon cœur."}, "errorPatterns": [{"equals": "ف", "category": "spelling", "feedback": "ف n''a qu''un point dessus ; il en faut deux."}, {"equals": "ك", "category": "spelling", "feedback": "ك est un bâton, pas une boule."}], "options": ["ق", "ف", "ك"], "pool": "lesson", "lessonId": "ar.l14", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e15', 'ar', 'ar.l14', 'ar.g14.forms_fa_lam', array['ar.g14.forms_fa_lam','ar.v.laban']::text[], 'fill_blank', 'lesson', '___ـبـن', array['ل']::text[], 'لبن commence par ل : un bâton qui s''attache au ب qui suit. Le ا, lui, couperait le mot après lui.', 3, '{"id": "ar.l14.e15", "type": "fill_blank", "unitIds": ["ar.g14.forms_fa_lam", "ar.v.laban"], "difficulty": 3, "instruction": "Quelle lettre manque pour écrire « lait » ?", "prompt": "___ـبـن", "promptLanguage": "ar", "answer": "ل", "acceptedAnswers": ["ل"], "explanation": "لبن commence par ل : un bâton qui s''attache au ب qui suit. Le ا, lui, couperait le mot après lui.", "tip": "ل s''attache, ا coupe.", "extraExample": {"text": "اللبن في التلاجة.", "translation": "Le lait est dans le frigo."}, "errorPatterns": [{"equals": "ا", "category": "instruction", "feedback": "ا ne s''attache pas au ب qui suit : le mot se couperait."}, {"equals": "ك", "category": "spelling", "feedback": "ك a un petit zigzag ; ici le bâton est lisse."}], "options": ["ل", "ا", "ك"], "pool": "lesson", "lessonId": "ar.l14", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e16', 'ar', 'ar.l14', 'ar.g14.forms_fa_lam', array['ar.g14.forms_fa_lam','ar.v.sukkar','ar.v.laban','ar.v.kursi','ar.v.foul','ar.v.kitab']::text[], 'match', 'lesson', 'Mots de la maison', '{}'::text[], 'Cherche les bâtons ك ل et les têtes rondes ف ق, puis le sens te revient.', 2, '{"id": "ar.l14.e16", "type": "match", "unitIds": ["ar.g14.forms_fa_lam", "ar.v.sukkar", "ar.v.laban", "ar.v.kursi", "ar.v.foul", "ar.v.kitab"], "difficulty": 2, "instruction": "Associe chaque mot à son sens.", "prompt": "Mots de la maison", "promptLanguage": "fr", "answer": "سكر = sucre ; لبن = lait ; كرسي = chaise ; فول = fèves ; كتاب = livre", "acceptedAnswers": [], "explanation": "Cherche les bâtons ك ل et les têtes rondes ف ق, puis le sens te revient.", "pairs": [{"left": "سكر", "right": "sucre"}, {"left": "لبن", "right": "lait"}, {"left": "كرسي", "right": "chaise"}, {"left": "فول", "right": "fèves"}, {"left": "كتاب", "right": "livre"}], "pool": "lesson", "lessonId": "ar.l14", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e17', 'ar', 'ar.l14', 'ar.g14.forms_fa_lam', array['ar.g14.forms_fa_lam','ar.v.quddas','ar.v.qurban','ar.v.salib','ar.v.injil','ar.v.qalb']::text[], 'match', 'lesson', 'Mots d''église', '{}'::text[], 'Ce sont des mots que tu entends à l''église : ici tu apprends à les lire.', 3, '{"id": "ar.l14.e17", "type": "match", "unitIds": ["ar.g14.forms_fa_lam", "ar.v.quddas", "ar.v.qurban", "ar.v.salib", "ar.v.injil", "ar.v.qalb"], "difficulty": 3, "instruction": "Associe chaque mot d''église à son sens.", "prompt": "Mots d''église", "promptLanguage": "fr", "answer": "قداس = liturgie ; قربان = pain d''offrande ; صليب = croix ; إنجيل = Évangile ; قلب = cœur", "acceptedAnswers": [], "explanation": "Ce sont des mots que tu entends à l''église : ici tu apprends à les lire.", "pairs": [{"left": "قداس", "right": "liturgie"}, {"left": "قربان", "right": "pain d''offrande"}, {"left": "صليب", "right": "croix"}, {"left": "إنجيل", "right": "Évangile"}, {"left": "قلب", "right": "cœur"}], "pool": "lesson", "lessonId": "ar.l14", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e18', 'ar', 'ar.l14', 'ar.g14.forms_fa_lam', array['ar.g14.forms_fa_lam','ar.v.fa','ar.v.qaf','ar.v.kaf','ar.v.lam']::text[], 'match', 'lesson', 'Les formes du début de ف ق ك ل', '{}'::text[], 'La forme du début garde le dessin et les points, avec le trait ـ à gauche.', 2, '{"id": "ar.l14.e18", "type": "match", "unitIds": ["ar.g14.forms_fa_lam", "ar.v.fa", "ar.v.qaf", "ar.v.kaf", "ar.v.lam"], "difficulty": 2, "instruction": "Associe chaque lettre isolée à sa forme du début.", "prompt": "Les formes du début de ف ق ك ل", "promptLanguage": "fr", "answer": "ف = فـ ; ق = قـ ; ك = كـ ; ل = لـ", "acceptedAnswers": [], "explanation": "La forme du début garde le dessin et les points, avec le trait ـ à gauche.", "pairs": [{"left": "ف", "right": "فـ"}, {"left": "ق", "right": "قـ"}, {"left": "ك", "right": "كـ"}, {"left": "ل", "right": "لـ"}], "pool": "lesson", "lessonId": "ar.l14", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e19', 'ar', 'ar.l14', 'ar.v.ghada', array['ar.v.ghada','ar.v.tayr','ar.v.hazz','ar.v.jaan','ar.v.tayyib']::text[], 'match', 'lesson', 'Mots de la leçon 13', '{}'::text[], 'Cherche la tête ع/غ, la boucle ط/ظ et les points dessus.', 2, '{"id": "ar.l14.e19", "type": "match", "unitIds": ["ar.v.ghada", "ar.v.tayr", "ar.v.hazz", "ar.v.jaan", "ar.v.tayyib"], "difficulty": 2, "instruction": "Révision : associe chaque mot à son sens.", "prompt": "Mots de la leçon 13", "promptLanguage": "fr", "answer": "غدا = déjeuner ; طير = oiseau ; حظ = chance ; جعان = affamé ; طيب = bon", "acceptedAnswers": [], "explanation": "Cherche la tête ع/غ, la boucle ط/ظ et les points dessus.", "pairs": [{"left": "غدا", "right": "déjeuner"}, {"left": "طير", "right": "oiseau"}, {"left": "حظ", "right": "chance"}, {"left": "جعان", "right": "affamé"}, {"left": "طيب", "right": "bon"}], "pool": "lesson", "lessonId": "ar.l14", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e20', 'ar', 'ar.l14', 'ar.g14.forms_fa_lam', array['ar.g14.forms_fa_lam','ar.v.qurban']::text[], 'translation', 'lesson', 'قربان', array['pain d''offrande','pain de l''offrande','le pain d''offrande','offrande','l''offrande','communion']::text[], 'قربان = قر | با | ن : ق (2 points dessus), ر, ب, ا, ن. C''est le pain de l''offrande de la liturgie.', 3, '{"id": "ar.l14.e20", "type": "translation", "unitIds": ["ar.g14.forms_fa_lam", "ar.v.qurban"], "difficulty": 3, "instruction": "Écris le sens en français.", "prompt": "قربان", "promptLanguage": "ar", "answer": "pain d''offrande", "acceptedAnswers": ["pain d''offrande", "pain de l''offrande", "le pain d''offrande", "offrande", "l''offrande", "communion"], "explanation": "قربان = قر | با | ن : ق (2 points dessus), ر, ب, ا, ن. C''est le pain de l''offrande de la liturgie.", "tip": "قر + با + ن : 3 blocs.", "extraExample": {"text": "الشعب بيتناول القربان.", "translation": "Les fidèles reçoivent la communion."}, "pool": "lesson", "lessonId": "ar.l14", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e21', 'ar', 'ar.l14', 'ar.g14.forms_fa_lam', array['ar.g14.forms_fa_lam','ar.v.kitab']::text[], 'translation', 'lesson', 'كتاب', array['livre','un livre','le livre']::text[], 'كتاب = كتا | ب : ك, ت, ا, ب. Le ا ferme le premier bloc. C''est un livre.', 2, '{"id": "ar.l14.e21", "type": "translation", "unitIds": ["ar.g14.forms_fa_lam", "ar.v.kitab"], "difficulty": 2, "instruction": "Écris le sens en français.", "prompt": "كتاب", "promptLanguage": "ar", "answer": "livre", "acceptedAnswers": ["livre", "un livre", "le livre"], "explanation": "كتاب = كتا | ب : ك, ت, ا, ب. Le ا ferme le premier bloc. C''est un livre.", "tip": "Le ا coupe le mot après ت.", "extraExample": {"text": "ده كتاب حلو.", "translation": "C''est un beau livre."}, "pool": "lesson", "lessonId": "ar.l14", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e22', 'ar', 'ar.l14', 'ar.g14.forms_fa_lam', array['ar.g14.forms_fa_lam','ar.v.quddas']::text[], 'free_answer', 'lesson', 'Que veut dire قداس ?', array['liturgie','la liturgie','une liturgie','messe','la messe']::text[], 'قداس = قد | ا | س : ق (2 points dessus), د, ا, س. C''est la liturgie, la grande prière du dimanche.', 3, '{"id": "ar.l14.e22", "type": "free_answer", "unitIds": ["ar.g14.forms_fa_lam", "ar.v.quddas"], "difficulty": 3, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire قداس ?", "promptLanguage": "fr", "answer": "liturgie", "acceptedAnswers": ["liturgie", "la liturgie", "une liturgie", "messe", "la messe"], "explanation": "قداس = قد | ا | س : ق (2 points dessus), د, ا, س. C''est la liturgie, la grande prière du dimanche.", "tip": "3 blocs : قد | ا | س.", "extraExample": {"text": "رحنا القداس يوم الأحد.", "translation": "Nous sommes allés à la liturgie dimanche."}, "pool": "lesson", "lessonId": "ar.l14", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l14.e23', 'ar', 'ar.l14', 'ar.g14.forms_fa_lam', array['ar.g14.forms_fa_lam','ar.v.laban']::text[], 'free_answer', 'lesson', 'Que veut dire لبن ?', array['lait','du lait','le lait']::text[], 'لبن = ل + ب + ن : un bâton, puis deux lettres à dents. Tout est attaché : c''est le lait.', 2, '{"id": "ar.l14.e23", "type": "free_answer", "unitIds": ["ar.g14.forms_fa_lam", "ar.v.laban"], "difficulty": 2, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire لبن ?", "promptLanguage": "fr", "answer": "lait", "acceptedAnswers": ["lait", "du lait", "le lait"], "explanation": "لبن = ل + ب + ن : un bâton, puis deux lettres à dents. Tout est attaché : c''est le lait.", "tip": "Le bâton ل s''attache : un seul bloc.", "extraExample": {"text": "عايز كوباية لبن.", "translation": "Je voudrais un verre de lait."}, "errorPatterns": [{"equals": "sucre", "category": "word_confusion", "feedback": "سكر (sucre) commence par س, trois dents."}], "pool": "lesson", "lessonId": "ar.l14", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e01', 'ar', 'ar.l15', 'ar.g15.forms_mim_ha', array['ar.g15.forms_mim_ha','ar.v.ta_marbuta']::text[], 'mcq', 'lesson', 'Laquelle de ces formes est la forme de la fin de ة ?', array['ـة']::text[], 'ة s''écrit ـة quand elle s''accroche à la lettre d''avant, avec ses 2 points dessus. ـه est un ه, sans point.', 1, '{"id": "ar.l15.e01", "type": "mcq", "unitIds": ["ar.g15.forms_mim_ha", "ar.v.ta_marbuta"], "difficulty": 1, "instruction": "Choisis la bonne forme.", "prompt": "Laquelle de ces formes est la forme de la fin de ة ?", "promptLanguage": "fr", "answer": "ـة", "acceptedAnswers": ["ـة"], "explanation": "ة s''écrit ـة quand elle s''accroche à la lettre d''avant, avec ses 2 points dessus. ـه est un ه, sans point.", "tip": "ة a toujours 2 points dessus.", "extraExample": {"text": "كنيسة", "translation": "église"}, "errorPatterns": [{"equals": "ة", "category": "instruction", "feedback": "ة sans trait est la forme isolée, pas celle de la fin."}, {"equals": "ـه", "category": "spelling", "feedback": "ـه est la forme de la fin de ه : il n''a aucun point."}, {"equals": "هـ", "category": "instruction", "feedback": "هـ est la forme du début de ه."}], "options": ["ـة", "ة", "ـه", "هـ"], "pool": "lesson", "lessonId": "ar.l15", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e02', 'ar', 'ar.l15', 'ar.g15.forms_mim_ha', array['ar.g15.forms_mim_ha','ar.v.mayya']::text[], 'mcq', 'lesson', 'مية', array['eau']::text[], 'Lettre par lettre : م (sans point), ي (2 points dessous), ة (2 points dessus) donne مية, « eau ». م + ي + ة : tout est attaché, 1 bloc.', 2, '{"id": "ar.l15.e02", "type": "mcq", "unitIds": ["ar.g15.forms_mim_ha", "ar.v.mayya"], "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "مية", "promptLanguage": "ar", "answer": "eau", "acceptedAnswers": ["eau"], "explanation": "Lettre par lettre : م (sans point), ي (2 points dessous), ة (2 points dessus) donne مية, « eau ». م + ي + ة : tout est attaché, 1 bloc.", "tip": "Lis de droite à gauche, lettre après lettre, puis dis le mot à voix haute.", "extraExample": {"text": "عايز كوباية مية.", "translation": "Je voudrais un verre d''eau."}, "errorPatterns": [{"equals": "pain", "category": "word_confusion", "feedback": "« pain » s''écrit عيش (ع + ي + ش). Ici tu lis م + ي + ة : مية veut dire « eau »."}, {"equals": "lait", "category": "word_confusion", "feedback": "« lait » s''écrit لبن (ل + ب + ن). Ici tu lis م + ي + ة : مية veut dire « eau »."}, {"equals": "thé", "category": "word_confusion", "feedback": "« thé » s''écrit شاي (ش + ا + ي). Ici tu lis م + ي + ة : مية veut dire « eau »."}], "options": ["eau", "pain", "lait", "thé"], "pool": "lesson", "lessonId": "ar.l15", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e03', 'ar', 'ar.l15', 'ar.g15.forms_mim_ha', array['ar.g15.forms_mim_ha','ar.v.qahwa']::text[], 'mcq', 'lesson', 'قهوة', array['café (boisson)']::text[], 'Lettre par lettre : ق (2 points dessus), ه (sans point), و (sans point), ة (2 points dessus) donne قهوة, « café (boisson) ». Le و ferme le bloc قهو : le ة reste seul, donc isolé.', 2, '{"id": "ar.l15.e03", "type": "mcq", "unitIds": ["ar.g15.forms_mim_ha", "ar.v.qahwa"], "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "قهوة", "promptLanguage": "ar", "answer": "café (boisson)", "acceptedAnswers": ["café (boisson)"], "explanation": "Lettre par lettre : ق (2 points dessus), ه (sans point), و (sans point), ة (2 points dessus) donne قهوة, « café (boisson) ». Le و ferme le bloc قهو : le ة reste seul, donc isolé.", "tip": "Lis de droite à gauche, lettre après lettre, puis dis le mot à voix haute.", "extraExample": {"text": "قهوة سادة.", "translation": "Un café sans sucre."}, "hint": "Cherche le ة à la fin.", "errorPatterns": [{"equals": "café (grains)", "category": "word_confusion", "feedback": "« café (grains) » s''écrit بن (ب + ن). Ici tu lis ق + ه + و + ة : قهوة veut dire « café (boisson) »."}, {"equals": "thé", "category": "word_confusion", "feedback": "« thé » s''écrit شاي (ش + ا + ي). Ici tu lis ق + ه + و + ة : قهوة veut dire « café (boisson) »."}, {"equals": "lait", "category": "word_confusion", "feedback": "« lait » s''écrit لبن (ل + ب + ن). Ici tu lis ق + ه + و + ة : قهوة veut dire « café (boisson) »."}], "options": ["café (boisson)", "café (grains)", "thé", "lait"], "pool": "lesson", "lessonId": "ar.l15", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e04', 'ar', 'ar.l15', 'ar.g15.forms_mim_ha', array['ar.g15.forms_mim_ha','ar.v.kanisa']::text[], 'mcq', 'lesson', 'كنيسة', array['église']::text[], 'Lettre par lettre : ك (sans point), ن (1 point dessus), ي (2 points dessous), س (sans point), ة (2 points dessus) donne كنيسة, « église ». Tout est attaché : 1 bloc. Le ـة final s''accroche au س.', 2, '{"id": "ar.l15.e04", "type": "mcq", "unitIds": ["ar.g15.forms_mim_ha", "ar.v.kanisa"], "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "كنيسة", "promptLanguage": "ar", "answer": "église", "acceptedAnswers": ["église"], "explanation": "Lettre par lettre : ك (sans point), ن (1 point dessus), ي (2 points dessous), س (sans point), ة (2 points dessus) donne كنيسة, « église ». Tout est attaché : 1 bloc. Le ـة final s''accroche au س.", "tip": "Lis de droite à gauche, lettre après lettre, puis dis le mot à voix haute.", "extraExample": {"text": "رايح الكنيسة.", "translation": "Je vais à l''église."}, "errorPatterns": [{"equals": "cloche", "category": "word_confusion", "feedback": "« cloche » s''écrit جرس (ج + ر + س). Ici tu lis ك + ن + ي + س + ة : كنيسة veut dire « église »."}, {"equals": "croix", "category": "word_confusion", "feedback": "« croix » s''écrit صليب (ص + ل + ي + ب). Ici tu lis ك + ن + ي + س + ة : كنيسة veut dire « église »."}, {"equals": "monastère", "category": "word_confusion", "feedback": "« monastère » s''écrit دير (د + ي + ر). Ici tu lis ك + ن + ي + س + ة : كنيسة veut dire « église »."}], "options": ["église", "cloche", "croix", "monastère"], "pool": "lesson", "lessonId": "ar.l15", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e05', 'ar', 'ar.l15', 'ar.g15.forms_mim_ha', array['ar.g15.forms_mim_ha','ar.v.arabiyya']::text[], 'mcq', 'lesson', 'Quel mot veut dire « voiture » ?', array['عربية']::text[], '« voiture » s''écrit ع + ر + ب + ي + ة : عربية. Le ر ferme le premier bloc : عر | بية.', 2, '{"id": "ar.l15.e05", "type": "mcq", "unitIds": ["ar.g15.forms_mim_ha", "ar.v.arabiyya"], "difficulty": 2, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « voiture » ?", "promptLanguage": "fr", "answer": "عربية", "acceptedAnswers": ["عربية"], "explanation": "« voiture » s''écrit ع + ر + ب + ي + ة : عربية. Le ر ferme le premier bloc : عر | بية.", "tip": "Compare les points et les attaches, lettre par lettre.", "extraExample": {"text": "ركبنا العربية.", "translation": "Nous sommes montés dans la voiture."}, "errorPatterns": [{"equals": "ترابيزة", "category": "word_confusion", "feedback": "ترابيزة (ت + ر + ا + ب + ي + ز + ة) veut dire « table ». Pour « voiture », il faut ع + ر + ب + ي + ة : عربية."}, {"equals": "أوضة", "category": "word_confusion", "feedback": "أوضة (أ + و + ض + ة) veut dire « chambre ». Pour « voiture », il faut ع + ر + ب + ي + ة : عربية."}, {"equals": "كرسي", "category": "word_confusion", "feedback": "كرسي (ك + ر + س + ي) veut dire « chaise ». Pour « voiture », il faut ع + ر + ب + ي + ة : عربية."}], "options": ["عربية", "ترابيزة", "أوضة", "كرسي"], "pool": "lesson", "lessonId": "ar.l15", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e06', 'ar', 'ar.l15', 'ar.g15.forms_mim_ha', array['ar.g15.forms_mim_ha','ar.v.bukra']::text[], 'mcq', 'lesson', 'Quel mot veut dire « demain » ?', array['بكرة']::text[], '« demain » s''écrit ب + ك + ر + ة : بكرة. Le ر ferme le bloc بكر : le ة reste seul, isolé.', 3, '{"id": "ar.l15.e06", "type": "mcq", "unitIds": ["ar.g15.forms_mim_ha", "ar.v.bukra"], "difficulty": 3, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « demain » ?", "promptLanguage": "fr", "answer": "بكرة", "acceptedAnswers": ["بكرة"], "explanation": "« demain » s''écrit ب + ك + ر + ة : بكرة. Le ر ferme le bloc بكر : le ة reste seul, isolé.", "tip": "Compare les points et les attaches, lettre par lettre.", "extraExample": {"text": "بكرة الأحد.", "translation": "Demain, c''est dimanche."}, "errorPatterns": [{"equals": "سكر", "category": "word_confusion", "feedback": "سكر (س + ك + ر) veut dire « sucre ». Pour « demain », il faut ب + ك + ر + ة : بكرة."}, {"equals": "بخور", "category": "word_confusion", "feedback": "بخور (ب + خ + و + ر) veut dire « encens ». Pour « demain », il faut ب + ك + ر + ة : بكرة."}, {"equals": "كرسي", "category": "word_confusion", "feedback": "كرسي (ك + ر + س + ي) veut dire « chaise ». Pour « demain », il faut ب + ك + ر + ة : بكرة."}], "options": ["بكرة", "سكر", "بخور", "كرسي"], "pool": "lesson", "lessonId": "ar.l15", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e07', 'ar', 'ar.l15', 'ar.g15.forms_mim_ha', array['ar.g15.forms_mim_ha','ar.v.qahwa']::text[], 'mcq', 'lesson', 'Dans قهوة, quelle forme prend la lettre ة ?', array['forme isolée']::text[], 'Dans قهوة (blocs : قهو | ة), la lettre ة ne s''accroche à aucune voisine : c''est la forme isolée. Le و qui précède ne s''attache pas : le ة reste isolé.', 3, '{"id": "ar.l15.e07", "type": "mcq", "unitIds": ["ar.g15.forms_mim_ha", "ar.v.qahwa"], "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Dans قهوة, quelle forme prend la lettre ة ?", "promptLanguage": "fr", "answer": "forme isolée", "acceptedAnswers": ["forme isolée"], "explanation": "Dans قهوة (blocs : قهو | ة), la lettre ة ne s''accroche à aucune voisine : c''est la forme isolée. Le و qui précède ne s''attache pas : le ة reste isolé.", "tip": "Regarde si la lettre s''accroche à celle d''avant (à droite) et à celle d''après (à gauche).", "extraExample": {"text": "قهوة", "translation": "café (boisson)"}, "errorPatterns": [{"equals": "forme du début", "category": "instruction", "feedback": "Le trait ـ est à gauche, vers la lettre suivante : c''est la forme du début."}, {"equals": "forme du milieu", "category": "instruction", "feedback": "Un trait ـ de chaque côté : c''est la forme du milieu."}, {"equals": "forme de la fin", "category": "instruction", "feedback": "Le trait ـ est à droite, vers la lettre précédente : c''est la forme de la fin."}], "options": ["forme isolée", "forme du début", "forme du milieu", "forme de la fin"], "pool": "lesson", "lessonId": "ar.l15", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e08', 'ar', 'ar.l15', 'ar.g15.forms_mim_ha', array['ar.g15.forms_mim_ha','ar.v.kanisa']::text[], 'mcq', 'lesson', 'Dans كنيسة, quelle forme prend la lettre ة ?', array['forme de la fin']::text[], 'Dans كنيسة, la lettre ة s''accroche seulement à la lettre d''avant : c''est la forme de la fin. Le ة s''accroche au س qui le précède.', 3, '{"id": "ar.l15.e08", "type": "mcq", "unitIds": ["ar.g15.forms_mim_ha", "ar.v.kanisa"], "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Dans كنيسة, quelle forme prend la lettre ة ?", "promptLanguage": "fr", "answer": "forme de la fin", "acceptedAnswers": ["forme de la fin"], "explanation": "Dans كنيسة, la lettre ة s''accroche seulement à la lettre d''avant : c''est la forme de la fin. Le ة s''accroche au س qui le précède.", "tip": "Regarde si la lettre s''accroche à celle d''avant (à droite) et à celle d''après (à gauche).", "extraExample": {"text": "كنيسة", "translation": "église"}, "errorPatterns": [{"equals": "forme isolée", "category": "instruction", "feedback": "Sans trait ـ, la lettre est seule : c''est la forme isolée."}, {"equals": "forme du début", "category": "instruction", "feedback": "Le trait ـ est à gauche, vers la lettre suivante : c''est la forme du début."}, {"equals": "forme du milieu", "category": "instruction", "feedback": "Un trait ـ de chaque côté : c''est la forme du milieu."}], "options": ["forme isolée", "forme du début", "forme du milieu", "forme de la fin"], "pool": "lesson", "lessonId": "ar.l15", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e09', 'ar', 'ar.l15', 'ar.g15.forms_mim_ha', array['ar.g15.forms_mim_ha','ar.v.tarabeza']::text[], 'mcq', 'lesson', 'Combien de blocs compte ترابيزة ?', array['4 blocs']::text[], 'ترابيزة = تر | ا | بيز | ة : 4 blocs. Le mot se coupe après ر et après ا et après ز.', 3, '{"id": "ar.l15.e09", "type": "mcq", "unitIds": ["ar.g15.forms_mim_ha", "ar.v.tarabeza"], "difficulty": 3, "instruction": "Compte les blocs.", "prompt": "Combien de blocs compte ترابيزة ?", "promptLanguage": "fr", "answer": "4 blocs", "acceptedAnswers": ["4 blocs"], "explanation": "ترابيزة = تر | ا | بيز | ة : 4 blocs. Le mot se coupe après ر et après ا et après ز.", "tip": "Après chaque ا د ذ ر ز و, un nouveau bloc commence.", "extraExample": {"text": "ترابيزة", "translation": "table"}, "errorPatterns": [{"equals": "1 bloc", "category": "instruction", "feedback": "Tu as oublié une coupure : seules ا د ذ ر ز و ne s''attachent pas à la suivante. Ici : تر | ا | بيز | ة."}, {"equals": "2 blocs", "category": "instruction", "feedback": "Tu as oublié une coupure : seules ا د ذ ر ز و ne s''attachent pas à la suivante. Ici : تر | ا | بيز | ة."}, {"equals": "3 blocs", "category": "instruction", "feedback": "Tu as oublié une coupure : seules ا د ذ ر ز و ne s''attachent pas à la suivante. Ici : تر | ا | بيز | ة."}], "options": ["1 bloc", "2 blocs", "3 blocs", "4 blocs"], "pool": "lesson", "lessonId": "ar.l15", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e10', 'ar', 'ar.l15', 'ar.v.qalb', array['ar.v.qalb']::text[], 'mcq', 'lesson', 'Quel mot veut dire « cœur » ?', array['قلب']::text[], '« cœur » s''écrit ق + ل + ب : قلب. ق (2 points dessus), ل (bâton), ب (1 point dessous) : 1 bloc.', 1, '{"id": "ar.l15.e10", "type": "mcq", "unitIds": ["ar.v.qalb"], "difficulty": 1, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « cœur » ?", "promptLanguage": "fr", "answer": "قلب", "acceptedAnswers": ["قلب"], "explanation": "« cœur » s''écrit ق + ل + ب : قلب. ق (2 points dessus), ل (bâton), ب (1 point dessous) : 1 bloc.", "tip": "Compare les points et les attaches, lettre par lettre.", "extraExample": {"text": "ربنا يفرح قلبك.", "translation": "Que Dieu réjouisse ton cœur."}, "errorPatterns": [{"equals": "قداس", "category": "word_confusion", "feedback": "قداس (ق + د + ا + س) veut dire « liturgie ». Pour « cœur », il faut ق + ل + ب : قلب."}, {"equals": "قربان", "category": "word_confusion", "feedback": "قربان (ق + ر + ب + ا + ن) veut dire « pain d''offrande ». Pour « cœur », il faut ق + ل + ب : قلب."}, {"equals": "كرسي", "category": "word_confusion", "feedback": "كرسي (ك + ر + س + ي) veut dire « chaise ». Pour « cœur », il faut ق + ل + ب : قلب."}], "options": ["قلب", "قداس", "قربان", "كرسي"], "pool": "lesson", "lessonId": "ar.l15", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e11', 'ar', 'ar.l15', 'ar.v.salib', array['ar.v.salib']::text[], 'mcq', 'lesson', 'Lis ce mot : صليب', array['croix']::text[], 'Lettre par lettre : ص (sans point), ل (sans point), ي (2 points dessous), ب (1 point dessous) donne صليب, « croix ». ص (boucle) + ل (bâton) + ي + ب : tout est attaché, 1 bloc.', 2, '{"id": "ar.l15.e11", "type": "mcq", "unitIds": ["ar.v.salib"], "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "Lis ce mot : صليب", "promptLanguage": "fr", "answer": "croix", "acceptedAnswers": ["croix"], "explanation": "Lettre par lettre : ص (sans point), ل (sans point), ي (2 points dessous), ب (1 point dessous) donne صليب, « croix ». ص (boucle) + ل (bâton) + ي + ب : tout est attaché, 1 bloc.", "tip": "Lis de droite à gauche, lettre après lettre, puis dis le mot à voix haute.", "extraExample": {"text": "الصليب على الحيطة.", "translation": "La croix est sur le mur."}, "errorPatterns": [{"equals": "cœur", "category": "word_confusion", "feedback": "« cœur » s''écrit قلب (ق + ل + ب). Ici tu lis ص + ل + ي + ب : صليب veut dire « croix »."}, {"equals": "chaise", "category": "word_confusion", "feedback": "« chaise » s''écrit كرسي (ك + ر + س + ي). Ici tu lis ص + ل + ي + ب : صليب veut dire « croix »."}, {"equals": "Évangile", "category": "word_confusion", "feedback": "« Évangile » s''écrit إنجيل (إ + ن + ج + ي + ل). Ici tu lis ص + ل + ي + ب : صليب veut dire « croix »."}], "options": ["croix", "cœur", "chaise", "Évangile"], "pool": "lesson", "lessonId": "ar.l15", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e12', 'ar', 'ar.l15', 'ar.v.qaf', array['ar.v.qaf']::text[], 'mcq', 'lesson', 'Dans قداس, quelle forme prend la lettre ق ?', array['forme du début']::text[], 'Dans قداس (blocs : قد | ا | س), la lettre ق s''accroche à la lettre qui la suit, pas à celle d''avant : c''est la forme du début. Le ق s''attache au د qui le suit : forme du début قـ.', 2, '{"id": "ar.l15.e12", "type": "mcq", "unitIds": ["ar.v.qaf"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Dans قداس, quelle forme prend la lettre ق ?", "promptLanguage": "fr", "answer": "forme du début", "acceptedAnswers": ["forme du début"], "explanation": "Dans قداس (blocs : قد | ا | س), la lettre ق s''accroche à la lettre qui la suit, pas à celle d''avant : c''est la forme du début. Le ق s''attache au د qui le suit : forme du début قـ.", "tip": "Regarde si la lettre s''accroche à celle d''avant (à droite) et à celle d''après (à gauche).", "extraExample": {"text": "قداس", "translation": "liturgie"}, "errorPatterns": [{"equals": "forme isolée", "category": "instruction", "feedback": "Sans trait ـ, la lettre est seule : c''est la forme isolée."}, {"equals": "forme du milieu", "category": "instruction", "feedback": "Un trait ـ de chaque côté : c''est la forme du milieu."}, {"equals": "forme de la fin", "category": "instruction", "feedback": "Le trait ـ est à droite, vers la lettre précédente : c''est la forme de la fin."}], "options": ["forme isolée", "forme du début", "forme du milieu", "forme de la fin"], "pool": "lesson", "lessonId": "ar.l15", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e13', 'ar', 'ar.l15', 'ar.g15.forms_mim_ha', array['ar.g15.forms_mim_ha','ar.v.mayya']::text[], 'fill_blank', 'lesson', '___ـيـة', array['م']::text[], 'مية commence par م : une boucle fermée, sans point. ن aurait un point dessus.', 2, '{"id": "ar.l15.e13", "type": "fill_blank", "unitIds": ["ar.g15.forms_mim_ha", "ar.v.mayya"], "difficulty": 2, "instruction": "Quelle lettre manque pour écrire « eau » ?", "prompt": "___ـيـة", "promptLanguage": "ar", "answer": "م", "acceptedAnswers": ["م"], "explanation": "مية commence par م : une boucle fermée, sans point. ن aurait un point dessus.", "tip": "Boule fermée, aucun point : م.", "extraExample": {"text": "المية باردة.", "translation": "L''eau est froide."}, "errorPatterns": [{"equals": "ن", "category": "spelling", "feedback": "ن a un point dessus ; م n''a aucun point."}, {"equals": "ه", "category": "spelling", "feedback": "ه a une autre forme au début : هـ."}], "options": ["م", "ن", "ه"], "pool": "lesson", "lessonId": "ar.l15", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e14', 'ar', 'ar.l15', 'ar.g15.forms_mim_ha', array['ar.g15.forms_mim_ha','ar.v.kanisa']::text[], 'fill_blank', 'lesson', 'كـنـيـسـ___', array['ة']::text[], 'كنيسة finit par ة : 2 points dessus, attachée au س. ت donnerait كنيست, qui n''existe pas : la finale de ce mot s''écrit ة.', 3, '{"id": "ar.l15.e14", "type": "fill_blank", "unitIds": ["ar.g15.forms_mim_ha", "ar.v.kanisa"], "difficulty": 3, "instruction": "Quelle lettre termine « église » ?", "prompt": "كـنـيـسـ___", "promptLanguage": "ar", "answer": "ة", "acceptedAnswers": ["ة"], "explanation": "كنيسة finit par ة : 2 points dessus, attachée au س. ت donnerait كنيست, qui n''existe pas : la finale de ce mot s''écrit ة.", "tip": "ة finale : un ه avec 2 points dessus.", "extraExample": {"text": "الكنيسة مفتوحة.", "translation": "L''église est ouverte."}, "errorPatterns": [{"equals": "ه", "category": "spelling", "feedback": "ه n''a aucun point ; ici il y en a deux : ة."}, {"equals": "ت", "category": "spelling", "feedback": "كنيست n''existe pas : il faut la forme arrondie de ة avec ses 2 points."}], "options": ["ة", "ه", "ت", "ث"], "pool": "lesson", "lessonId": "ar.l15", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e15', 'ar', 'ar.l15', 'ar.g15.forms_mim_ha', array['ar.g15.forms_mim_ha','ar.v.mish']::text[], 'fill_blank', 'lesson', 'مـ___', array['ش']::text[], 'مش finit par ش : trois dents et 3 points dessus. س n''a aucun point.', 3, '{"id": "ar.l15.e15", "type": "fill_blank", "unitIds": ["ar.g15.forms_mim_ha", "ar.v.mish"], "difficulty": 3, "instruction": "Quelle lettre termine « ne… pas » ?", "prompt": "مـ___", "promptLanguage": "ar", "answer": "ش", "acceptedAnswers": ["ش"], "explanation": "مش finit par ش : trois dents et 3 points dessus. س n''a aucun point.", "tip": "3 dents + 3 points : ش.", "extraExample": {"text": "مش عارف.", "translation": "Je ne sais pas."}, "errorPatterns": [{"equals": "س", "category": "spelling", "feedback": "س n''a aucun point ; ش en a trois."}, {"equals": "ص", "category": "spelling", "feedback": "ص a une boucle, pas des dents."}], "options": ["ش", "س", "ص", "ض"], "pool": "lesson", "lessonId": "ar.l15", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e16', 'ar', 'ar.l15', 'ar.g15.forms_mim_ha', array['ar.g15.forms_mim_ha','ar.v.mayya','ar.v.qahwa','ar.v.arabiyya','ar.v.tarabeza','ar.v.oda']::text[], 'match', 'lesson', 'Eau, café, voiture, table, chambre', '{}'::text[], 'Cherche le ة final, isolé ou attaché, et compte les blocs.', 2, '{"id": "ar.l15.e16", "type": "match", "unitIds": ["ar.g15.forms_mim_ha", "ar.v.mayya", "ar.v.qahwa", "ar.v.arabiyya", "ar.v.tarabeza", "ar.v.oda"], "difficulty": 2, "instruction": "Associe chaque mot à son sens.", "prompt": "Eau, café, voiture, table, chambre", "promptLanguage": "fr", "answer": "مية = eau ; قهوة = café (boisson) ; عربية = voiture ; ترابيزة = table ; أوضة = chambre", "acceptedAnswers": [], "explanation": "Cherche le ة final, isolé ou attaché, et compte les blocs.", "pairs": [{"left": "مية", "right": "eau"}, {"left": "قهوة", "right": "café (boisson)"}, {"left": "عربية", "right": "voiture"}, {"left": "ترابيزة", "right": "table"}, {"left": "أوضة", "right": "chambre"}], "pool": "lesson", "lessonId": "ar.l15", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e17', 'ar', 'ar.l15', 'ar.g15.forms_mim_ha', array['ar.g15.forms_mim_ha','ar.v.bukra','ar.v.mish','ar.v.kanisa','ar.v.shammas','ar.v.mazmur']::text[], 'match', 'lesson', 'Mots du quotidien et mots d''église', '{}'::text[], 'Lis lettre par lettre, puis bloc par bloc : بكر | ة, م + ش, كنيسة, شما | س, مز | مو | ر.', 3, '{"id": "ar.l15.e17", "type": "match", "unitIds": ["ar.g15.forms_mim_ha", "ar.v.bukra", "ar.v.mish", "ar.v.kanisa", "ar.v.shammas", "ar.v.mazmur"], "difficulty": 3, "instruction": "Associe chaque mot à son sens.", "prompt": "Mots du quotidien et mots d''église", "promptLanguage": "fr", "answer": "بكرة = demain ; مش = ne… pas ; كنيسة = église ; شماس = diacre ; مزمور = psaume", "acceptedAnswers": [], "explanation": "Lis lettre par lettre, puis bloc par bloc : بكر | ة, م + ش, كنيسة, شما | س, مز | مو | ر.", "pairs": [{"left": "بكرة", "right": "demain"}, {"left": "مش", "right": "ne… pas"}, {"left": "كنيسة", "right": "église"}, {"left": "شماس", "right": "diacre"}, {"left": "مزمور", "right": "psaume"}], "pool": "lesson", "lessonId": "ar.l15", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e18', 'ar', 'ar.l15', 'ar.g15.forms_mim_ha', array['ar.g15.forms_mim_ha','ar.v.mim','ar.v.heh','ar.v.kaf','ar.v.lam']::text[], 'match', 'lesson', 'Les formes du début de م ه ك ل', '{}'::text[], 'La forme du début garde le dessin de la lettre, avec le trait ـ à gauche.', 2, '{"id": "ar.l15.e18", "type": "match", "unitIds": ["ar.g15.forms_mim_ha", "ar.v.mim", "ar.v.heh", "ar.v.kaf", "ar.v.lam"], "difficulty": 2, "instruction": "Associe chaque lettre isolée à sa forme du début.", "prompt": "Les formes du début de م ه ك ل", "promptLanguage": "fr", "answer": "م = مـ ; ه = هـ ; ك = كـ ; ل = لـ", "acceptedAnswers": [], "explanation": "La forme du début garde le dessin de la lettre, avec le trait ـ à gauche.", "pairs": [{"left": "م", "right": "مـ"}, {"left": "ه", "right": "هـ"}, {"left": "ك", "right": "كـ"}, {"left": "ل", "right": "لـ"}], "pool": "lesson", "lessonId": "ar.l15", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e19', 'ar', 'ar.l15', 'ar.v.sukkar', array['ar.v.sukkar','ar.v.laban','ar.v.kursi','ar.v.foul','ar.v.kitab']::text[], 'match', 'lesson', 'Mots de la leçon 14', '{}'::text[], 'Bâtons ك ل, têtes rondes ف ق : cherche d''abord le dessin, puis les points.', 2, '{"id": "ar.l15.e19", "type": "match", "unitIds": ["ar.v.sukkar", "ar.v.laban", "ar.v.kursi", "ar.v.foul", "ar.v.kitab"], "difficulty": 2, "instruction": "Révision : associe chaque mot à son sens.", "prompt": "Mots de la leçon 14", "promptLanguage": "fr", "answer": "سكر = sucre ; لبن = lait ; كرسي = chaise ; فول = fèves ; كتاب = livre", "acceptedAnswers": [], "explanation": "Bâtons ك ل, têtes rondes ف ق : cherche d''abord le dessin, puis les points.", "pairs": [{"left": "سكر", "right": "sucre"}, {"left": "لبن", "right": "lait"}, {"left": "كرسي", "right": "chaise"}, {"left": "فول", "right": "fèves"}, {"left": "كتاب", "right": "livre"}], "pool": "lesson", "lessonId": "ar.l15", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e20', 'ar', 'ar.l15', 'ar.g15.forms_mim_ha', array['ar.g15.forms_mim_ha','ar.v.shammas']::text[], 'translation', 'lesson', 'شماس', array['diacre','un diacre','le diacre']::text[], 'شماس = شما | س : ش (3 dents, 3 points), م (la cerise), ا, س. C''est le diacre, celui qui sert à l''autel.', 3, '{"id": "ar.l15.e20", "type": "translation", "unitIds": ["ar.g15.forms_mim_ha", "ar.v.shammas"], "difficulty": 3, "instruction": "Écris le sens en français.", "prompt": "شماس", "promptLanguage": "ar", "answer": "diacre", "acceptedAnswers": ["diacre", "un diacre", "le diacre"], "explanation": "شماس = شما | س : ش (3 dents, 3 points), م (la cerise), ا, س. C''est le diacre, celui qui sert à l''autel.", "tip": "Le ا ferme le premier bloc.", "extraExample": {"text": "ابني بقى شماس.", "translation": "Mon fils est devenu diacre."}, "pool": "lesson", "lessonId": "ar.l15", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e21', 'ar', 'ar.l15', 'ar.g15.forms_mim_ha', array['ar.g15.forms_mim_ha','ar.v.mish']::text[], 'translation', 'lesson', 'مش', array['pas','ne pas','non','ne pas être','pas du tout']::text[], 'مش = م + ش : une cerise et trois dents. C''est la négation « ne… pas ».', 3, '{"id": "ar.l15.e21", "type": "translation", "unitIds": ["ar.g15.forms_mim_ha", "ar.v.mish"], "difficulty": 3, "instruction": "Écris le sens en français.", "prompt": "مش", "promptLanguage": "ar", "answer": "pas", "acceptedAnswers": ["pas", "ne pas", "non", "ne pas être", "pas du tout"], "explanation": "مش = م + ش : une cerise et trois dents. C''est la négation « ne… pas ».", "tip": "Deux lettres attachées : un seul bloc.", "extraExample": {"text": "ده مش بيتي.", "translation": "Ce n''est pas ma maison."}, "pool": "lesson", "lessonId": "ar.l15", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e22', 'ar', 'ar.l15', 'ar.g15.forms_mim_ha', array['ar.g15.forms_mim_ha','ar.v.oda']::text[], 'free_answer', 'lesson', 'Que veut dire أوضة ?', array['chambre','une chambre','la chambre','pièce','une pièce']::text[], 'أوضة = أ | و | ضة : alif, و, puis ض et ة attachés. C''est une chambre, une pièce.', 3, '{"id": "ar.l15.e22", "type": "free_answer", "unitIds": ["ar.g15.forms_mim_ha", "ar.v.oda"], "difficulty": 3, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire أوضة ?", "promptLanguage": "fr", "answer": "chambre", "acceptedAnswers": ["chambre", "une chambre", "la chambre", "pièce", "une pièce"], "explanation": "أوضة = أ | و | ضة : alif, و, puis ض et ة attachés. C''est une chambre, une pièce.", "tip": "3 blocs : أ | و | ضة.", "extraExample": {"text": "أوضتي صغيرة.", "translation": "Ma chambre est petite."}, "pool": "lesson", "lessonId": "ar.l15", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l15.e23', 'ar', 'ar.l15', 'ar.g15.forms_mim_ha', array['ar.g15.forms_mim_ha','ar.v.mazmur']::text[], 'free_answer', 'lesson', 'Que veut dire مزمور ?', array['psaume','un psaume','le psaume']::text[], 'مزمور = مز | مو | ر : م, ز, م, و, ر. Trois blocs. C''est un psaume.', 3, '{"id": "ar.l15.e23", "type": "free_answer", "unitIds": ["ar.g15.forms_mim_ha", "ar.v.mazmur"], "difficulty": 3, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire مزمور ?", "promptLanguage": "fr", "answer": "psaume", "acceptedAnswers": ["psaume", "un psaume", "le psaume"], "explanation": "مزمور = مز | مو | ر : م, ز, م, و, ر. Trois blocs. C''est un psaume.", "tip": "Deux م, séparés par un ز.", "extraExample": {"text": "بنقرا مزمور كل يوم.", "translation": "Nous lisons un psaume chaque jour."}, "pool": "lesson", "lessonId": "ar.l15", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e01', 'ar', 'ar.l16', 'ar.g16.article_and_ligature', array['ar.g16.article_and_ligature','ar.v.alif','ar.v.lam']::text[], 'mcq', 'lesson', 'Que veut dire ال devant un nom ?', array['le / la']::text[], 'ال (alif + lam) est l''article défini : il veut dire le / la. Pour « un / une », l''arabe n''ajoute rien.', 1, '{"id": "ar.l16.e01", "type": "mcq", "unitIds": ["ar.g16.article_and_ligature", "ar.v.alif", "ar.v.lam"], "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut dire ال devant un nom ?", "promptLanguage": "fr", "answer": "le / la", "acceptedAnswers": ["le / la"], "explanation": "ال (alif + lam) est l''article défini : il veut dire le / la. Pour « un / une », l''arabe n''ajoute rien.", "tip": "ال = le / la.", "extraExample": {"text": "الباب", "translation": "la porte"}, "errorPatterns": [{"equals": "un / une", "category": "grammar", "feedback": "L''arabe n''a pas de mot pour « un / une » : on écrit seulement le nom."}, {"equals": "mon / ma", "category": "grammar", "feedback": "« mon / ma » s''ajoute à la fin du nom (ي), pas au début."}, {"equals": "et", "category": "vocabulary", "feedback": "« et » s''écrit و, une seule lettre collée au mot suivant."}], "options": ["le / la", "un / une", "mon / ma", "et"], "pool": "lesson", "lessonId": "ar.l16", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e02', 'ar', 'ar.l16', 'ar.g16.article_and_ligature', array['ar.g16.article_and_ligature','ar.v.alif','ar.v.lam']::text[], 'mcq', 'lesson', 'Comment écrit-on « l''église » ?', array['الكنيسة']::text[], '« l''église » = ال + كنيسة : le ا devant le ل, puis le nom. كنيسة seul veut dire « église ».', 2, '{"id": "ar.l16.e02", "type": "mcq", "unitIds": ["ar.g16.article_and_ligature", "ar.v.alif", "ar.v.lam"], "difficulty": 2, "instruction": "Choisis la bonne écriture.", "prompt": "Comment écrit-on « l''église » ?", "promptLanguage": "fr", "answer": "الكنيسة", "acceptedAnswers": ["الكنيسة"], "explanation": "« l''église » = ال + كنيسة : le ا devant le ل, puis le nom. كنيسة seul veut dire « église ».", "tip": "ال = ا puis ل, toujours dans cet ordre.", "extraExample": {"text": "البيت", "translation": "la maison"}, "errorPatterns": [{"equals": "كنيسة", "category": "grammar", "feedback": "كنيسة sans ال veut dire « église » ; pour « l''église », ajoute ال devant."}, {"equals": "لكنيسة", "category": "spelling", "feedback": "Il manque le ا devant le ل : ال = ا + ل."}, {"equals": "اكنيسة", "category": "spelling", "feedback": "Il manque le ل : l''article s''écrit ا puis ل."}], "options": ["الكنيسة", "كنيسة", "لكنيسة", "اكنيسة"], "pool": "lesson", "lessonId": "ar.l16", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e03', 'ar', 'ar.l16', 'ar.g16.article_and_ligature', array['ar.g16.article_and_ligature','ar.v.masih']::text[], 'mcq', 'lesson', 'Combien de blocs compte المسيح ?', array['2 blocs']::text[], 'المسيح = ا | لمسيح : 2 blocs. Le mot se coupe après ا.', 2, '{"id": "ar.l16.e03", "type": "mcq", "unitIds": ["ar.g16.article_and_ligature", "ar.v.masih"], "difficulty": 2, "instruction": "Compte les blocs.", "prompt": "Combien de blocs compte المسيح ?", "promptLanguage": "fr", "answer": "2 blocs", "acceptedAnswers": ["2 blocs"], "explanation": "المسيح = ا | لمسيح : 2 blocs. Le mot se coupe après ا.", "tip": "Après chaque ا د ذ ر ز و, un nouveau bloc commence.", "extraExample": {"text": "المسيح", "translation": "le Christ"}, "errorPatterns": [{"equals": "1 bloc", "category": "instruction", "feedback": "Tu as oublié une coupure : seules ا د ذ ر ز و ne s''attachent pas à la suivante. Ici : ا | لمسيح."}, {"equals": "3 blocs", "category": "instruction", "feedback": "Tu as coupé trop de fois : seules ا د ذ ر ز و ne s''attachent pas à la suivante. Ici : ا | لمسيح."}, {"equals": "4 blocs", "category": "instruction", "feedback": "Tu as coupé trop de fois : seules ا د ذ ر ز و ne s''attachent pas à la suivante. Ici : ا | لمسيح."}], "options": ["1 bloc", "2 blocs", "3 blocs", "4 blocs"], "pool": "lesson", "lessonId": "ar.l16", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e04', 'ar', 'ar.l16', 'ar.g16.article_and_ligature', array['ar.g16.article_and_ligature','ar.v.adra']::text[], 'mcq', 'lesson', 'Combien de blocs compte العدرا ?', array['4 blocs']::text[], 'العدرا = ا | لعد | ر | ا : 4 blocs. Le mot se coupe après ا et après د et après ر.', 3, '{"id": "ar.l16.e04", "type": "mcq", "unitIds": ["ar.g16.article_and_ligature", "ar.v.adra"], "difficulty": 3, "instruction": "Compte les blocs.", "prompt": "Combien de blocs compte العدرا ?", "promptLanguage": "fr", "answer": "4 blocs", "acceptedAnswers": ["4 blocs"], "explanation": "العدرا = ا | لعد | ر | ا : 4 blocs. Le mot se coupe après ا et après د et après ر.", "tip": "Après chaque ا د ذ ر ز و, un nouveau bloc commence.", "extraExample": {"text": "العدرا", "translation": "la Vierge Marie"}, "errorPatterns": [{"equals": "1 bloc", "category": "instruction", "feedback": "Tu as oublié une coupure : seules ا د ذ ر ز و ne s''attachent pas à la suivante. Ici : ا | لعد | ر | ا."}, {"equals": "2 blocs", "category": "instruction", "feedback": "Tu as oublié une coupure : seules ا د ذ ر ز و ne s''attachent pas à la suivante. Ici : ا | لعد | ر | ا."}, {"equals": "3 blocs", "category": "instruction", "feedback": "Tu as oublié une coupure : seules ا د ذ ر ز و ne s''attachent pas à la suivante. Ici : ا | لعد | ر | ا."}], "options": ["1 bloc", "2 blocs", "3 blocs", "4 blocs"], "pool": "lesson", "lessonId": "ar.l16", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e05', 'ar', 'ar.l16', 'ar.g16.article_and_ligature', array['ar.g16.article_and_ligature','ar.v.malak']::text[], 'mcq', 'lesson', 'Quel mot veut dire « ange » ?', array['ملاك']::text[], '« ange » s''écrit م + ل + ا + ك : ملاك. ملا | ك : la ligature لا ferme le premier bloc.', 2, '{"id": "ar.l16.e05", "type": "mcq", "unitIds": ["ar.g16.article_and_ligature", "ar.v.malak"], "difficulty": 2, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « ange » ?", "promptLanguage": "fr", "answer": "ملاك", "acceptedAnswers": ["ملاك"], "explanation": "« ange » s''écrit م + ل + ا + ك : ملاك. ملا | ك : la ligature لا ferme le premier bloc.", "tip": "Compare les points et les attaches, lettre par lettre.", "extraExample": {"text": "ملاك الرب ظهر لهم.", "translation": "L''ange du Seigneur leur est apparu."}, "hint": "Cherche la ligature لا puis ك.", "errorPatterns": [{"equals": "سلام", "category": "word_confusion", "feedback": "سلام (س + ل + ا + م) veut dire « paix ». Pour « ange », il faut م + ل + ا + ك : ملاك."}, {"equals": "كلام", "category": "word_confusion", "feedback": "كلام (ك + ل + ا + م) veut dire « paroles ». Pour « ange », il faut م + ل + ا + ك : ملاك."}, {"equals": "صلاة", "category": "word_confusion", "feedback": "صلاة (ص + ل + ا + ة) veut dire « prière ». Pour « ange », il faut م + ل + ا + ك : ملاك."}], "options": ["ملاك", "سلام", "كلام", "صلاة"], "pool": "lesson", "lessonId": "ar.l16", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e06', 'ar', 'ar.l16', 'ar.g16.article_and_ligature', array['ar.g16.article_and_ligature','ar.v.amin']::text[], 'mcq', 'lesson', 'Quel mot veut dire « amen » ?', array['آمين']::text[], '« amen » s''écrit آ + م + ي + ن : آمين. آ | مين : le آ (alif surmonté d''une petite vague) ferme le premier bloc.', 3, '{"id": "ar.l16.e06", "type": "mcq", "unitIds": ["ar.g16.article_and_ligature", "ar.v.amin"], "difficulty": 3, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « amen » ?", "promptLanguage": "fr", "answer": "آمين", "acceptedAnswers": ["آمين"], "explanation": "« amen » s''écrit آ + م + ي + ن : آمين. آ | مين : le آ (alif surmonté d''une petite vague) ferme le premier bloc.", "tip": "Compare les points et les attaches, lettre par lettre.", "extraExample": {"text": "بنقول آمين بعد الصلاة.", "translation": "Nous disons amen après la prière."}, "errorPatterns": [{"equals": "المسيح", "category": "word_confusion", "feedback": "المسيح (ا + ل + م + س + ي + ح) veut dire « le Christ ». Pour « amen », il faut آ + م + ي + ن : آمين."}, {"equals": "ملاك", "category": "word_confusion", "feedback": "ملاك (م + ل + ا + ك) veut dire « ange ». Pour « amen », il faut آ + م + ي + ن : آمين."}, {"equals": "سلام", "category": "word_confusion", "feedback": "سلام (س + ل + ا + م) veut dire « paix ». Pour « amen », il faut آ + م + ي + ن : آمين."}], "options": ["آمين", "المسيح", "ملاك", "سلام"], "pool": "lesson", "lessonId": "ar.l16", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e07', 'ar', 'ar.l16', 'ar.g16.article_and_ligature', array['ar.g16.article_and_ligature','ar.v.la']::text[], 'mcq', 'lesson', 'Quand un ل est suivi d''un ا, quel signe les remplace ?', array['لا']::text[], 'ل + ا se fondent en un seul signe, la ligature لا. ال, c''est l''article : ا puis ل, dans l''autre ordre.', 2, '{"id": "ar.l16.e07", "type": "mcq", "unitIds": ["ar.g16.article_and_ligature", "ar.v.la"], "difficulty": 2, "instruction": "Choisis le bon signe.", "prompt": "Quand un ل est suivi d''un ا, quel signe les remplace ?", "promptLanguage": "fr", "answer": "لا", "acceptedAnswers": ["لا"], "explanation": "ل + ا se fondent en un seul signe, la ligature لا. ال, c''est l''article : ا puis ل, dans l''autre ordre.", "tip": "ل puis ا dans un mot = لا.", "extraExample": {"text": "سلام", "translation": "paix"}, "errorPatterns": [{"equals": "ال", "category": "word_confusion", "feedback": "ال est l''article (ا puis ل). La ligature, c''est ل puis ا : لا."}, {"equals": "ءا", "category": "spelling", "feedback": "ء est une autre lettre (la hamza)."}, {"equals": "لل", "category": "spelling", "feedback": "لل, ce sont deux ل."}], "options": ["لا", "ال", "ءا", "لل"], "pool": "lesson", "lessonId": "ar.l16", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e08', 'ar', 'ar.l16', 'ar.g16.article_and_ligature', array['ar.g16.article_and_ligature','ar.v.masih']::text[], 'mcq', 'lesson', 'Dans المسيح, quelle forme prend la lettre ل ?', array['forme du début']::text[], 'Dans المسيح (blocs : ا | لمسيح), la lettre ل s''accroche à la lettre qui la suit, pas à celle d''avant : c''est la forme du début. Le ا qui précède ne s''attache pas : le ل repart à neuf et s''accroche à la suite, forme du début لـ.', 3, '{"id": "ar.l16.e08", "type": "mcq", "unitIds": ["ar.g16.article_and_ligature", "ar.v.masih"], "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Dans المسيح, quelle forme prend la lettre ل ?", "promptLanguage": "fr", "answer": "forme du début", "acceptedAnswers": ["forme du début"], "explanation": "Dans المسيح (blocs : ا | لمسيح), la lettre ل s''accroche à la lettre qui la suit, pas à celle d''avant : c''est la forme du début. Le ا qui précède ne s''attache pas : le ل repart à neuf et s''accroche à la suite, forme du début لـ.", "tip": "Regarde si la lettre s''accroche à celle d''avant (à droite) et à celle d''après (à gauche).", "extraExample": {"text": "المسيح", "translation": "le Christ"}, "errorPatterns": [{"equals": "forme isolée", "category": "instruction", "feedback": "Sans trait ـ, la lettre est seule : c''est la forme isolée."}, {"equals": "forme du milieu", "category": "instruction", "feedback": "Un trait ـ de chaque côté : c''est la forme du milieu."}, {"equals": "forme de la fin", "category": "instruction", "feedback": "Le trait ـ est à droite, vers la lettre précédente : c''est la forme de la fin."}], "options": ["forme isolée", "forme du début", "forme du milieu", "forme de la fin"], "pool": "lesson", "lessonId": "ar.l16", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e09', 'ar', 'ar.l16', 'ar.v.shammas', array['ar.v.shammas']::text[], 'mcq', 'lesson', 'Quel mot veut dire « diacre » ?', array['شماس']::text[], '« diacre » s''écrit ش + م + ا + س : شماس. Le ا ferme le premier bloc : شما | س.', 2, '{"id": "ar.l16.e09", "type": "mcq", "unitIds": ["ar.v.shammas"], "difficulty": 2, "instruction": "Choisis le bon mot.", "prompt": "Quel mot veut dire « diacre » ?", "promptLanguage": "fr", "answer": "شماس", "acceptedAnswers": ["شماس"], "explanation": "« diacre » s''écrit ش + م + ا + س : شماس. Le ا ferme le premier bloc : شما | س.", "tip": "Compare les points et les attaches, lettre par lettre.", "extraExample": {"text": "ابني بقى شماس.", "translation": "Mon fils est devenu diacre."}, "errorPatterns": [{"equals": "مزمور", "category": "word_confusion", "feedback": "مزمور (م + ز + م + و + ر) veut dire « psaume ». Pour « diacre », il faut ش + م + ا + س : شماس."}, {"equals": "كنيسة", "category": "word_confusion", "feedback": "كنيسة (ك + ن + ي + س + ة) veut dire « église ». Pour « diacre », il faut ش + م + ا + س : شماس."}, {"equals": "قداس", "category": "word_confusion", "feedback": "قداس (ق + د + ا + س) veut dire « liturgie ». Pour « diacre », il faut ش + م + ا + س : شماس."}], "options": ["شماس", "مزمور", "كنيسة", "قداس"], "pool": "lesson", "lessonId": "ar.l16", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e10', 'ar', 'ar.l16', 'ar.v.injil', array['ar.v.injil']::text[], 'mcq', 'lesson', 'Lis ce mot : إنجيل', array['Évangile']::text[], 'Lettre par lettre : إ (alif + petit ء dessous), ن (1 point dessus), ج (1 point dessous), ي (2 points dessous), ل (sans point) donne إنجيل, « Évangile ». Le إ (alif avec petit ء dessous) ferme le premier bloc : إ | نجيل.', 2, '{"id": "ar.l16.e10", "type": "mcq", "unitIds": ["ar.v.injil"], "difficulty": 2, "instruction": "Lis le mot et choisis son sens.", "prompt": "Lis ce mot : إنجيل", "promptLanguage": "fr", "answer": "Évangile", "acceptedAnswers": ["Évangile"], "explanation": "Lettre par lettre : إ (alif + petit ء dessous), ن (1 point dessus), ج (1 point dessous), ي (2 points dessous), ل (sans point) donne إنجيل, « Évangile ». Le إ (alif avec petit ء dessous) ferme le premier bloc : إ | نجيل.", "tip": "Lis de droite à gauche, lettre après lettre, puis dis le mot à voix haute.", "extraExample": {"text": "الإنجيل بيتقرا في القداس.", "translation": "L''Évangile est lu à la liturgie."}, "errorPatterns": [{"equals": "croix", "category": "word_confusion", "feedback": "« croix » s''écrit صليب (ص + ل + ي + ب). Ici tu lis إ + ن + ج + ي + ل : إنجيل veut dire « Évangile »."}, {"equals": "livre", "category": "word_confusion", "feedback": "« livre » s''écrit كتاب (ك + ت + ا + ب). Ici tu lis إ + ن + ج + ي + ل : إنجيل veut dire « Évangile »."}, {"equals": "cœur", "category": "word_confusion", "feedback": "« cœur » s''écrit قلب (ق + ل + ب). Ici tu lis إ + ن + ج + ي + ل : إنجيل veut dire « Évangile »."}], "options": ["Évangile", "croix", "livre", "cœur"], "pool": "lesson", "lessonId": "ar.l16", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e11', 'ar', 'ar.l16', 'ar.v.ghada', array['ar.v.ghada']::text[], 'mcq', 'lesson', 'Combien de blocs compte غدا ?', array['2 blocs']::text[], 'غدا = غد | ا : 2 blocs. Le mot se coupe après د.', 2, '{"id": "ar.l16.e11", "type": "mcq", "unitIds": ["ar.v.ghada"], "difficulty": 2, "instruction": "Compte les blocs.", "prompt": "Combien de blocs compte غدا ?", "promptLanguage": "fr", "answer": "2 blocs", "acceptedAnswers": ["2 blocs"], "explanation": "غدا = غد | ا : 2 blocs. Le mot se coupe après د.", "tip": "Après chaque ا د ذ ر ز و, un nouveau bloc commence.", "extraExample": {"text": "غدا", "translation": "déjeuner"}, "errorPatterns": [{"equals": "1 bloc", "category": "instruction", "feedback": "Tu as oublié une coupure : seules ا د ذ ر ز و ne s''attachent pas à la suivante. Ici : غد | ا."}, {"equals": "3 blocs", "category": "instruction", "feedback": "Tu as coupé trop de fois : seules ا د ذ ر ز و ne s''attachent pas à la suivante. Ici : غد | ا."}, {"equals": "4 blocs", "category": "instruction", "feedback": "Tu as coupé trop de fois : seules ا د ذ ر ز و ne s''attachent pas à la suivante. Ici : غد | ا."}], "options": ["1 bloc", "2 blocs", "3 blocs", "4 blocs"], "pool": "lesson", "lessonId": "ar.l16", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e12', 'ar', 'ar.l16', 'ar.v.shay', array['ar.v.shay']::text[], 'mcq', 'lesson', 'Dans شاي, quelle forme prend la lettre ي ?', array['forme isolée']::text[], 'Dans شاي (blocs : شا | ي), la lettre ي ne s''accroche à aucune voisine : c''est la forme isolée. Le ا qui précède ne s''attache pas : le ي est seul, donc isolé.', 2, '{"id": "ar.l16.e12", "type": "mcq", "unitIds": ["ar.v.shay"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Dans شاي, quelle forme prend la lettre ي ?", "promptLanguage": "fr", "answer": "forme isolée", "acceptedAnswers": ["forme isolée"], "explanation": "Dans شاي (blocs : شا | ي), la lettre ي ne s''accroche à aucune voisine : c''est la forme isolée. Le ا qui précède ne s''attache pas : le ي est seul, donc isolé.", "tip": "Regarde si la lettre s''accroche à celle d''avant (à droite) et à celle d''après (à gauche).", "extraExample": {"text": "شاي", "translation": "thé"}, "errorPatterns": [{"equals": "forme du début", "category": "instruction", "feedback": "Le trait ـ est à gauche, vers la lettre suivante : c''est la forme du début."}, {"equals": "forme du milieu", "category": "instruction", "feedback": "Un trait ـ de chaque côté : c''est la forme du milieu."}, {"equals": "forme de la fin", "category": "instruction", "feedback": "Le trait ـ est à droite, vers la lettre précédente : c''est la forme de la fin."}], "options": ["forme isolée", "forme du début", "forme du milieu", "forme de la fin"], "pool": "lesson", "lessonId": "ar.l16", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e13', 'ar', 'ar.l16', 'ar.g16.article_and_ligature', array['ar.g16.article_and_ligature','ar.v.salat']::text[], 'fill_blank', 'lesson', 'صـ___ة', array['لا']::text[], 'صلاة contient la ligature لا : ص + لا + ة. Le ل et le ا sont fondus en un seul signe.', 3, '{"id": "ar.l16.e13", "type": "fill_blank", "unitIds": ["ar.g16.article_and_ligature", "ar.v.salat"], "difficulty": 3, "instruction": "Quel signe manque pour écrire « prière » ?", "prompt": "صـ___ة", "promptLanguage": "ar", "answer": "لا", "acceptedAnswers": ["لا"], "explanation": "صلاة contient la ligature لا : ص + لا + ة. Le ل et le ا sont fondus en un seul signe.", "tip": "ل puis ا = لا.", "extraExample": {"text": "صلاة الصبح.", "translation": "La prière du matin."}, "errorPatterns": [{"equals": "ال", "category": "word_confusion", "feedback": "ال, c''est ا puis ل ; dans صلاة, c''est ل puis ا : لا."}, {"equals": "ل", "category": "spelling", "feedback": "Seul, ل ne suffit pas : il manque le ا, fondu dans la ligature."}, {"equals": "ا", "category": "spelling", "feedback": "Seul, ا ne suffit pas : il manque le ل, fondu dans la ligature."}], "options": ["لا", "ال", "ل", "ا"], "pool": "lesson", "lessonId": "ar.l16", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e14', 'ar', 'ar.l16', 'ar.g16.article_and_ligature', array['ar.g16.article_and_ligature','ar.v.salam']::text[], 'fill_blank', 'lesson', 'سـ___م', array['لا']::text[], 'سلام s''écrit س + لا + م : la ligature لا ferme le premier bloc, puis م reste seul.', 3, '{"id": "ar.l16.e14", "type": "fill_blank", "unitIds": ["ar.g16.article_and_ligature", "ar.v.salam"], "difficulty": 3, "instruction": "Quel signe manque pour écrire « paix » ?", "prompt": "سـ___م", "promptLanguage": "ar", "answer": "لا", "acceptedAnswers": ["لا"], "explanation": "سلام s''écrit س + لا + م : la ligature لا ferme le premier bloc, puis م reste seul.", "tip": "Après لا, la lettre suivante repart à neuf.", "extraExample": {"text": "السلام لكم.", "translation": "La paix soit avec vous."}, "errorPatterns": [{"equals": "ال", "category": "word_confusion", "feedback": "ال est l''article ; ici il faut la ligature ل + ا : لا."}], "options": ["لا", "ال", "ل", "ا"], "pool": "lesson", "lessonId": "ar.l16", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e15', 'ar', 'ar.l16', 'ar.g16.article_and_ligature', array['ar.g16.article_and_ligature','ar.v.bab']::text[], 'fill_blank', 'lesson', 'ا___ـبـاب', array['ل']::text[], '« la porte » = ال + باب : ا, puis ل, puis باب. Le ل s''accroche à ce qui suit.', 2, '{"id": "ar.l16.e15", "type": "fill_blank", "unitIds": ["ar.g16.article_and_ligature", "ar.v.bab"], "difficulty": 2, "instruction": "Quelle lettre manque pour écrire « la porte » ?", "prompt": "ا___ـبـاب", "promptLanguage": "ar", "answer": "ل", "acceptedAnswers": ["ل"], "explanation": "« la porte » = ال + باب : ا, puis ل, puis باب. Le ل s''accroche à ce qui suit.", "tip": "ال : ا puis ل.", "extraExample": {"text": "الباب", "translation": "la porte"}, "errorPatterns": [{"equals": "ا", "category": "spelling", "feedback": "Le ا est déjà écrit au début ; il manque le ل."}, {"equals": "ن", "category": "spelling", "feedback": "ن a un point dessus ; l''article ne contient pas de ن."}], "options": ["ل", "ا", "ب", "ن"], "pool": "lesson", "lessonId": "ar.l16", "skill": "recall"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e16', 'ar', 'ar.l16', 'ar.g16.article_and_ligature', array['ar.g16.article_and_ligature','ar.v.salat','ar.v.salam','ar.v.kalam','ar.v.balash','ar.v.malak']::text[], 'match', 'lesson', 'Mots avec la ligature لا', '{}'::text[], 'Tous contiennent لا : cherche les lettres autour : ص, س, ك, ب, م.', 2, '{"id": "ar.l16.e16", "type": "match", "unitIds": ["ar.g16.article_and_ligature", "ar.v.salat", "ar.v.salam", "ar.v.kalam", "ar.v.balash", "ar.v.malak"], "difficulty": 2, "instruction": "Associe chaque mot à son sens.", "prompt": "Mots avec la ligature لا", "promptLanguage": "fr", "answer": "صلاة = prière ; سلام = paix ; كلام = paroles ; بلاش = gratuit ; ملاك = ange", "acceptedAnswers": [], "explanation": "Tous contiennent لا : cherche les lettres autour : ص, س, ك, ب, م.", "pairs": [{"left": "صلاة", "right": "prière"}, {"left": "سلام", "right": "paix"}, {"left": "كلام", "right": "paroles"}, {"left": "بلاش", "right": "gratuit"}, {"left": "ملاك", "right": "ange"}], "pool": "lesson", "lessonId": "ar.l16", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e17', 'ar', 'ar.l16', 'ar.g16.article_and_ligature', array['ar.g16.article_and_ligature','ar.v.masih','ar.v.adra','ar.v.amin','ar.v.qurban','ar.v.injil']::text[], 'match', 'lesson', 'Le Christ, la Vierge, amen, l''offrande, l''Évangile', '{}'::text[], 'Ce sont des mots que tu dis à l''église : lis-les bloc par bloc.', 3, '{"id": "ar.l16.e17", "type": "match", "unitIds": ["ar.g16.article_and_ligature", "ar.v.masih", "ar.v.adra", "ar.v.amin", "ar.v.qurban", "ar.v.injil"], "difficulty": 3, "instruction": "Associe chaque mot d''église à son sens.", "prompt": "Le Christ, la Vierge, amen, l''offrande, l''Évangile", "promptLanguage": "fr", "answer": "المسيح = le Christ ; العدرا = la Vierge Marie ; آمين = amen ; قربان = pain d''offrande ; إنجيل = Évangile", "acceptedAnswers": [], "explanation": "Ce sont des mots que tu dis à l''église : lis-les bloc par bloc.", "pairs": [{"left": "المسيح", "right": "le Christ"}, {"left": "العدرا", "right": "la Vierge Marie"}, {"left": "آمين", "right": "amen"}, {"left": "قربان", "right": "pain d''offrande"}, {"left": "إنجيل", "right": "Évangile"}], "pool": "lesson", "lessonId": "ar.l16", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e18', 'ar', 'ar.l16', 'ar.g16.article_and_ligature', array['ar.g16.article_and_ligature','ar.v.bayt','ar.v.kanisa','ar.v.salib','ar.v.eid']::text[], 'match', 'lesson', 'Ajouter ال devant un nom', '{}'::text[], 'ال se met devant le nom : ا + ل + nom. Le ل s''accroche au nom, le ا reste seul.', 2, '{"id": "ar.l16.e18", "type": "match", "unitIds": ["ar.g16.article_and_ligature", "ar.v.bayt", "ar.v.kanisa", "ar.v.salib", "ar.v.eid"], "difficulty": 2, "instruction": "Associe chaque mot à sa forme avec ال.", "prompt": "Ajouter ال devant un nom", "promptLanguage": "fr", "answer": "بيت = البيت ; كنيسة = الكنيسة ; صليب = الصليب ; عيد = العيد", "acceptedAnswers": [], "explanation": "ال se met devant le nom : ا + ل + nom. Le ل s''accroche au nom, le ا reste seul.", "pairs": [{"left": "بيت", "right": "البيت"}, {"left": "كنيسة", "right": "الكنيسة"}, {"left": "صليب", "right": "الصليب"}, {"left": "عيد", "right": "العيد"}], "pool": "lesson", "lessonId": "ar.l16", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
