insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e20', 'ar', 'ar.l16', 'ar.v.habibi', array['ar.v.habibi','ar.v.bakhur','ar.v.shay','ar.v.sabah','ar.v.jaras']::text[], 'match', 'lesson', 'Chéri, encens, thé, matin, cloche', '{}'::text[], 'Cherche le crochet ج ح خ, les dents س ش et la boucle ص ض.', 2, '{"id": "ar.l16.e20", "type": "match", "unitIds": ["ar.v.habibi", "ar.v.bakhur", "ar.v.shay", "ar.v.sabah", "ar.v.jaras"], "difficulty": 2, "instruction": "Révision : mots des leçons 11 et 12.", "prompt": "Chéri, encens, thé, matin, cloche", "promptLanguage": "fr", "answer": "حبيبي = mon chéri ; بخور = encens ; شاي = thé ; صباح = matin ; جرس = cloche", "acceptedAnswers": [], "explanation": "Cherche le crochet ج ح خ, les dents س ش et la boucle ص ض.", "pairs": [{"left": "حبيبي", "right": "mon chéri"}, {"left": "بخور", "right": "encens"}, {"left": "شاي", "right": "thé"}, {"left": "صباح", "right": "matin"}, {"left": "جرس", "right": "cloche"}], "pool": "lesson", "lessonId": "ar.l16", "skill": "recognition"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e21', 'ar', 'ar.l16', 'ar.g16.article_and_ligature', array['ar.g16.article_and_ligature','ar.v.la']::text[], 'translation', 'lesson', 'لا', array['non']::text[], 'لا est la ligature ل + ا, un seul signe. C''est le mot « non ».', 1, '{"id": "ar.l16.e21", "type": "translation", "unitIds": ["ar.g16.article_and_ligature", "ar.v.la"], "difficulty": 1, "instruction": "Écris le sens en français.", "prompt": "لا", "promptLanguage": "ar", "answer": "non", "acceptedAnswers": ["non"], "explanation": "لا est la ligature ل + ا, un seul signe. C''est le mot « non ».", "tip": "ل + ا = لا, et c''est aussi « non ».", "extraExample": {"text": "لا، شكرا.", "translation": "Non, merci."}, "pool": "lesson", "lessonId": "ar.l16", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e22', 'ar', 'ar.l16', 'ar.g16.article_and_ligature', array['ar.g16.article_and_ligature','ar.v.talata']::text[], 'translation', 'lesson', 'ثلاثة', array['trois','3']::text[], 'ثلاثة = ثلا | ثة : ث (3 points dessus), la ligature لا, puis ث et ة. C''est le chiffre trois.', 3, '{"id": "ar.l16.e22", "type": "translation", "unitIds": ["ar.g16.article_and_ligature", "ar.v.talata"], "difficulty": 3, "instruction": "Écris le sens en français.", "prompt": "ثلاثة", "promptLanguage": "ar", "answer": "trois", "acceptedAnswers": ["trois", "3"], "explanation": "ثلاثة = ثلا | ثة : ث (3 points dessus), la ligature لا, puis ث et ة. C''est le chiffre trois.", "tip": "Deux ث avec 3 points dessus, et la ligature au milieu.", "extraExample": {"text": "عندي ثلاثة أولاد.", "translation": "J''ai trois enfants."}, "pool": "lesson", "lessonId": "ar.l16", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e23', 'ar', 'ar.l16', 'ar.g16.article_and_ligature', array['ar.g16.article_and_ligature','ar.v.kalam']::text[], 'free_answer', 'lesson', 'Que veut dire كلام ?', array['paroles','parole','discours','mots','les paroles','le discours','propos']::text[], 'كلام = كلا | م : ك, la ligature لا, puis م. Ce sont les paroles, ce qu''on dit.', 3, '{"id": "ar.l16.e23", "type": "free_answer", "unitIds": ["ar.g16.article_and_ligature", "ar.v.kalam"], "difficulty": 3, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire كلام ?", "promptLanguage": "fr", "answer": "paroles", "acceptedAnswers": ["paroles", "parole", "discours", "mots", "les paroles", "le discours", "propos"], "explanation": "كلام = كلا | م : ك, la ligature لا, puis م. Ce sont les paroles, ce qu''on dit.", "tip": "كلا + م : la ligature ferme le premier bloc.", "extraExample": {"text": "كلامك صح.", "translation": "Ce que tu dis est juste."}, "pool": "lesson", "lessonId": "ar.l16", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('ar.l16.e24', 'ar', 'ar.l16', 'ar.g16.article_and_ligature', array['ar.g16.article_and_ligature','ar.v.balash']::text[], 'free_answer', 'lesson', 'Que veut dire بلاش ?', array['gratuit','gratuitement','gratis','pour rien','laisse tomber']::text[], 'بلاش = بلا | ش : ب, la ligature لا, puis ش (3 dents, 3 points). C''est « gratuit », « pour rien ».', 3, '{"id": "ar.l16.e24", "type": "free_answer", "unitIds": ["ar.g16.article_and_ligature", "ar.v.balash"], "difficulty": 3, "instruction": "Écris la réponse en français.", "prompt": "Que veut dire بلاش ?", "promptLanguage": "fr", "answer": "gratuit", "acceptedAnswers": ["gratuit", "gratuitement", "gratis", "pour rien", "laisse tomber"], "explanation": "بلاش = بلا | ش : ب, la ligature لا, puis ش (3 dents, 3 points). C''est « gratuit », « pour rien ».", "tip": "بلا + ش : la ligature ferme le premier bloc.", "extraExample": {"text": "الأكل ده بلاش.", "translation": "Ce repas est gratuit."}, "pool": "lesson", "lessonId": "ar.l16", "skill": "production"}'::jsonb, '3.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.alif', 'ar', 'ا', 'alif — son a long', 'Un bâton droit, sans point, qui ouvre l''alphabet. Il donne le a long de pâte.', '[{"text": "باب", "translation": "porte : ا au milieu du mot"}, {"text": "أبونا", "translation": "notre père (le prêtre) : ا avec une petite hamza au début"}]'::jsonb, null, '{"id": "ar.d.alif", "word": "ا", "translation": "alif — son a long", "partOfSpeech": "letter", "explanation": "Un bâton droit, sans point, qui ouvre l''alphabet. Il donne le a long de pâte.", "examples": [{"text": "باب", "translation": "porte : ا au milieu du mot"}, {"text": "أبونا", "translation": "notre père (le prêtre) : ا avec une petite hamza au début"}], "unitId": "ar.v.alif", "confusions": [{"word": "ل", "note": "ل a aussi un bâton, mais avec un pied qui tourne vers la gauche."}]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ba', 'ar', 'ب', 'bâ — son b', 'Une barque avec 1 point dessous. Elle se lit comme le b de bateau.', '[{"text": "باب", "translation": "porte : ب au début et à la fin"}, {"text": "بيت", "translation": "maison : ب au début"}]'::jsonb, null, '{"id": "ar.d.ba", "word": "ب", "translation": "bâ — son b", "partOfSpeech": "letter", "explanation": "Une barque avec 1 point dessous. Elle se lit comme le b de bateau.", "examples": [{"text": "باب", "translation": "porte : ب au début et à la fin"}, {"text": "بيت", "translation": "maison : ب au début"}], "unitId": "ar.v.ba", "confusions": [{"word": "ت", "note": "ت a 2 points dessus."}, {"word": "ث", "note": "ث a 3 points dessus."}, {"word": "ن", "note": "ن est un bol plus creux avec 1 point dessus."}]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ta', 'ar', 'ت', 'tâ — son t', 'La barque de ب avec 2 points dessus. Elle se lit comme le t de table.', '[{"text": "تمر", "translation": "dattes : ت au début"}, {"text": "تسبحة", "translation": "la louange chantée de la nuit à l''église : ت au début"}]'::jsonb, null, '{"id": "ar.d.ta", "word": "ت", "translation": "tâ — son t", "partOfSpeech": "letter", "explanation": "La barque de ب avec 2 points dessus. Elle se lit comme le t de table.", "examples": [{"text": "تمر", "translation": "dattes : ت au début"}, {"text": "تسبحة", "translation": "la louange chantée de la nuit à l''église : ت au début"}], "unitId": "ar.v.ta", "confusions": [{"word": "ب", "note": "ب a 1 point dessous."}, {"word": "ث", "note": "ث a 3 points dessus."}, {"word": "ق", "note": "ق a aussi 2 points dessus, mais une tête ronde et une queue profonde."}]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.tha', 'ar', 'ث', 'thâ — son t (ou s) en Égypte', 'La barque avec 3 points dessus. En arabe littéraire, c''est le th de l''anglais think ; en Égypte, un t, parfois un s.', '[{"text": "ثلاثة", "translation": "trois : ث au début (en Égypte, on le dit comme s''il y avait ت)"}, {"text": "ثانية", "translation": "seconde : ث au début"}]'::jsonb, null, '{"id": "ar.d.tha", "word": "ث", "translation": "thâ — son t (ou s) en Égypte", "partOfSpeech": "letter", "explanation": "La barque avec 3 points dessus. En arabe littéraire, c''est le th de l''anglais think ; en Égypte, un t, parfois un s.", "examples": [{"text": "ثلاثة", "translation": "trois : ث au début (en Égypte, on le dit comme s''il y avait ت)"}, {"text": "ثانية", "translation": "seconde : ث au début"}], "unitId": "ar.v.tha", "confusions": [{"word": "ت", "note": "ت a 2 points dessus."}, {"word": "ش", "note": "ش a aussi 3 points dessus, mais trois dents au lieu d''une barque."}]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.nun', 'ar', 'ن', 'nûn — son n', 'Un bol creux avec 1 point dessus. Elle se lit comme le n de nuit.', '[{"text": "نور", "translation": "lumière : ن au début"}, {"text": "نبوات", "translation": "les prophéties lues à l''église : ن au début"}]'::jsonb, null, '{"id": "ar.d.nun", "word": "ن", "translation": "nûn — son n", "partOfSpeech": "letter", "explanation": "Un bol creux avec 1 point dessus. Elle se lit comme le n de nuit.", "examples": [{"text": "نور", "translation": "lumière : ن au début"}, {"text": "نبوات", "translation": "les prophéties lues à l''église : ن au début"}], "unitId": "ar.v.nun", "confusions": [{"word": "ب", "note": "ب est une barque plate avec son point dessous."}, {"word": "ي", "note": "ي plonge sous la ligne et a 2 points dessous."}]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ya', 'ar', 'ي', 'yâ — son y ou i long', 'Une lettre dont la queue plonge sous la ligne, avec 2 points dessous. Elle donne le y de yaourt ou un i long.', '[{"text": "يد", "translation": "main : ي au début"}, {"text": "يسوع", "translation": "Jésus : ي au début"}]'::jsonb, null, '{"id": "ar.d.ya", "word": "ي", "translation": "yâ — son y ou i long", "partOfSpeech": "letter", "explanation": "Une lettre dont la queue plonge sous la ligne, avec 2 points dessous. Elle donne le y de yaourt ou un i long.", "examples": [{"text": "يد", "translation": "main : ي au début"}, {"text": "يسوع", "translation": "Jésus : ي au début"}], "unitId": "ar.v.ya", "confusions": [{"word": "ن", "note": "ن a 1 point dessus."}, {"word": "ى", "note": "ى est un ي sans ses 2 points."}]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.jim', 'ar', 'ج', 'gîm — son g (comme gâteau)', 'Un crochet avec 1 point dans le creux. En Égypte, elle se lit comme le g de gâteau.', '[{"text": "جمل", "translation": "chameau : ج au début (en Égypte, on dit g)"}, {"text": "جبنة", "translation": "fromage : ج au début"}]'::jsonb, null, '{"id": "ar.d.jim", "word": "ج", "translation": "gîm — son g (comme gâteau)", "partOfSpeech": "letter", "explanation": "Un crochet avec 1 point dans le creux. En Égypte, elle se lit comme le g de gâteau.", "examples": [{"text": "جمل", "translation": "chameau : ج au début (en Égypte, on dit g)"}, {"text": "جبنة", "translation": "fromage : ج au début"}], "unitId": "ar.v.jim", "confusions": [{"word": "ح", "note": "ح est le même crochet sans point."}, {"word": "خ", "note": "خ est le même crochet avec 1 point dessus."}]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ha', 'ar', 'ح', 'ḥâ — h appuyé du fond de la gorge', 'Le même crochet que ج, mais sans point. C''est un h appuyé, soufflé du fond de la gorge.', '[{"text": "حب", "translation": "amour : ح au début"}, {"text": "حلو", "translation": "joli ou sucré : ح au début"}]'::jsonb, null, '{"id": "ar.d.ha", "word": "ح", "translation": "ḥâ — h appuyé du fond de la gorge", "partOfSpeech": "letter", "explanation": "Le même crochet que ج, mais sans point. C''est un h appuyé, soufflé du fond de la gorge.", "examples": [{"text": "حب", "translation": "amour : ح au début"}, {"text": "حلو", "translation": "joli ou sucré : ح au début"}], "unitId": "ar.v.ha", "confusions": [{"word": "ج", "note": "ج a 1 point dans le creux."}, {"word": "ه", "note": "ه est un h léger et une tout autre forme."}]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.kha', 'ar', 'خ', 'khâ — ch allemand (Bach)', 'Le même crochet que ج et ح, avec 1 point dessus. Elle se lit comme le ch allemand de Bach.', '[{"text": "خمسة", "translation": "cinq : خ au début"}, {"text": "خروف", "translation": "agneau : خ au début"}]'::jsonb, null, '{"id": "ar.d.kha", "word": "خ", "translation": "khâ — ch allemand (Bach)", "partOfSpeech": "letter", "explanation": "Le même crochet que ج et ح, avec 1 point dessus. Elle se lit comme le ch allemand de Bach.", "examples": [{"text": "خمسة", "translation": "cinq : خ au début"}, {"text": "خروف", "translation": "agneau : خ au début"}], "unitId": "ar.v.kha", "confusions": [{"word": "ج", "note": "ج a 1 point dans le creux."}, {"word": "ح", "note": "ح n''a pas de point."}]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.dal', 'ar', 'د', 'dâl — son d', 'Un petit dos arrondi qui repose sur la ligne, sans point. Elle se lit comme le d de dent.', '[{"text": "دم", "translation": "sang : د au début"}, {"text": "دب", "translation": "ours : د au début"}]'::jsonb, null, '{"id": "ar.d.dal", "word": "د", "translation": "dâl — son d", "partOfSpeech": "letter", "explanation": "Un petit dos arrondi qui repose sur la ligne, sans point. Elle se lit comme le d de dent.", "examples": [{"text": "دم", "translation": "sang : د au début"}, {"text": "دب", "translation": "ours : د au début"}], "unitId": "ar.v.dal", "confusions": [{"word": "ذ", "note": "ذ est le même dos avec 1 point dessus."}, {"word": "ر", "note": "ر descend sous la ligne."}]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.dhal', 'ar', 'ذ', 'dhâl — son d ou z en Égypte', 'د avec 1 point dessus. En arabe littéraire, c''est le th de this ; en Égypte, un d, parfois un z.', '[{"text": "ذهب", "translation": "or (le métal) : ذ au début (en Égypte, on dit d)"}, {"text": "ذرة", "translation": "maïs : ذ au début"}]'::jsonb, null, '{"id": "ar.d.dhal", "word": "ذ", "translation": "dhâl — son d ou z en Égypte", "partOfSpeech": "letter", "explanation": "د avec 1 point dessus. En arabe littéraire, c''est le th de this ; en Égypte, un d, parfois un z.", "examples": [{"text": "ذهب", "translation": "or (le métal) : ذ au début (en Égypte, on dit d)"}, {"text": "ذرة", "translation": "maïs : ذ au début"}], "unitId": "ar.v.dhal", "confusions": [{"word": "د", "note": "د n''a pas de point."}, {"word": "ز", "note": "ز est une virgule avec un point, ذ est un dos avec un point."}]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
