insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ta_marbuta', 'ar', 'ة', 'tâ marbûta — a final', 'ه coiffé de 2 points dessus : le ت attaché au ه. Elle ne se trouve qu''à la fin des mots féminins, et se dit a.', '[{"text": "مدرسة", "translation": "école : ة à la fin"}, {"text": "كنيسة", "translation": "église : ة à la fin"}]'::jsonb, null, '{"id": "ar.d.ta_marbuta", "word": "ة", "translation": "tâ marbûta — a final", "partOfSpeech": "letter", "explanation": "ه coiffé de 2 points dessus : le ت attaché au ه. Elle ne se trouve qu''à la fin des mots féminins, et se dit a.", "examples": [{"text": "مدرسة", "translation": "école : ة à la fin"}, {"text": "كنيسة", "translation": "église : ة à la fin"}], "unitId": "ar.v.ta_marbuta", "confusions": [{"word": "ه", "note": "ه n''a pas de point."}, {"word": "ت", "note": "ت est une barque plate avec 2 points dessus."}]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.alif_maqsura', 'ar', 'ى', 'alif maqsûra — a long final', 'ي sans ses 2 points. Elle ne se trouve qu''à la fin d''un mot et donne un a long.', '[{"text": "على", "translation": "sur : ى à la fin"}, {"text": "مستشفى", "translation": "hôpital : ى à la fin"}]'::jsonb, null, '{"id": "ar.d.alif_maqsura", "word": "ى", "translation": "alif maqsûra — a long final", "partOfSpeech": "letter", "explanation": "ي sans ses 2 points. Elle ne se trouve qu''à la fin d''un mot et donne un a long.", "examples": [{"text": "على", "translation": "sur : ى à la fin"}, {"text": "مستشفى", "translation": "hôpital : ى à la fin"}], "unitId": "ar.v.alif_maqsura", "confusions": [{"word": "ي", "note": "ي a 2 points dessous."}]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.bayt', 'ar', 'بيت', 'maison', 'La maison, le chez-soi. Même mot pour la maison où l''on habite et pour « rentrer chez soi ».', '[{"text": "بيتنا قريب من الكنيسة.", "translation": "Notre maison est près de l''église."}, {"text": "أنا رايح البيت.", "translation": "Je rentre à la maison."}]'::jsonb, null, '{"id": "ar.d.bayt", "word": "بيت", "translation": "maison", "partOfSpeech": "noun", "explanation": "La maison, le chez-soi. Même mot pour la maison où l''on habite et pour « rentrer chez soi ».", "examples": [{"text": "بيتنا قريب من الكنيسة.", "translation": "Notre maison est près de l''église."}, {"text": "أنا رايح البيت.", "translation": "Je rentre à la maison."}], "unitId": "ar.v.bayt", "forms": {"plural": "بيوت"}, "confusions": [{"word": "بنت", "note": "Même début et même fin, mais le milieu a un point dessus (ن) au lieu de deux points dessous (ي)."}]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.bint', 'ar', 'بنت', 'fille', 'Une fille, une jeune fille ; aussi « ma fille » quand on ajoute ي à la fin : بنتي.', '[{"text": "البنت دي شاطرة.", "translation": "Cette fille est douée."}, {"text": "عندي بنتين.", "translation": "J''ai deux filles."}]'::jsonb, null, '{"id": "ar.d.bint", "word": "بنت", "translation": "fille", "partOfSpeech": "noun", "explanation": "Une fille, une jeune fille ; aussi « ma fille » quand on ajoute ي à la fin : بنتي.", "examples": [{"text": "البنت دي شاطرة.", "translation": "Cette fille est douée."}, {"text": "عندي بنتين.", "translation": "J''ai deux filles."}], "unitId": "ar.v.bint", "forms": {"plural": "بنات"}, "confusions": [{"word": "بيت", "note": "Le milieu de بيت porte deux points dessous (ي) ; celui de بنت un point dessus (ن)."}]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.tin', 'ar', 'تين', 'figues', 'Les figues. Dans l''Évangile, le figuier est l''arbre dont Jésus parle aux disciples.', '[{"text": "التين حلو أوي.", "translation": "Les figues sont très sucrées."}, {"text": "عايز كيلو تين.", "translation": "Je voudrais un kilo de figues."}]'::jsonb, null, '{"id": "ar.d.tin", "word": "تين", "translation": "figues", "partOfSpeech": "noun", "explanation": "Les figues. Dans l''Évangile, le figuier est l''arbre dont Jésus parle aux disciples.", "examples": [{"text": "التين حلو أوي.", "translation": "Les figues sont très sucrées."}, {"text": "عايز كيلو تين.", "translation": "Je voudrais un kilo de figues."}], "unitId": "ar.v.tin"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.nabi', 'ar', 'نبي', 'prophète', 'Un prophète, quelqu''un qui parle de la part de Dieu (Élie, Isaïe, Jérémie…).', '[{"text": "إيليا نبي كبير في الكتاب المقدس.", "translation": "Élie est un grand prophète dans la Bible."}, {"text": "النبي داود كتب المزامير.", "translation": "Le prophète David a écrit les psaumes."}]'::jsonb, null, '{"id": "ar.d.nabi", "word": "نبي", "translation": "prophète", "partOfSpeech": "noun", "explanation": "Un prophète, quelqu''un qui parle de la part de Dieu (Élie, Isaïe, Jérémie…).", "examples": [{"text": "إيليا نبي كبير في الكتاب المقدس.", "translation": "Élie est un grand prophète dans la Bible."}, {"text": "النبي داود كتب المزامير.", "translation": "Le prophète David a écrit les psaumes."}], "unitId": "ar.v.nabi", "forms": {"plural": "أنبياء"}}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.bunn', 'ar', 'بن', 'café (grains)', 'Le café avant d''être préparé : les grains ou la poudre. La boisson, elle, s''appelle قهوة.', '[{"text": "البن ده ريحته حلوة.", "translation": "Ce café sent bon."}, {"text": "اشتريت كيلو بن.", "translation": "J''ai acheté un kilo de café."}]'::jsonb, null, '{"id": "ar.d.bunn", "word": "بن", "translation": "café (grains)", "partOfSpeech": "noun", "explanation": "Le café avant d''être préparé : les grains ou la poudre. La boisson, elle, s''appelle قهوة.", "examples": [{"text": "البن ده ريحته حلوة.", "translation": "Ce café sent bon."}, {"text": "اشتريت كيلو بن.", "translation": "J''ai acheté un kilo de café."}], "unitId": "ar.v.bunn"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.bayna', 'ar', 'بين', 'entre', 'Entre deux choses ou deux personnes.', '[{"text": "الكنيسة بين البيت والمدرسة.", "translation": "L''église est entre la maison et l''école."}, {"text": "ده سر بيني وبينك.", "translation": "C''est un secret entre toi et moi."}]'::jsonb, null, '{"id": "ar.d.bayna", "word": "بين", "translation": "entre", "partOfSpeech": "preposition", "explanation": "Entre deux choses ou deux personnes.", "examples": [{"text": "الكنيسة بين البيت والمدرسة.", "translation": "L''église est entre la maison et l''école."}, {"text": "ده سر بيني وبينك.", "translation": "C''est un secret entre toi et moi."}], "unitId": "ar.v.bayna"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.tinnin', 'ar', 'تنين', 'dragon', 'Un dragon, comme celui qu''a vaincu saint Georges dans l''histoire que tout le monde raconte.', '[{"text": "مارجرجس قتل التنين.", "translation": "Saint Georges a tué le dragon."}, {"text": "التنين في الحدوتة بينفخ نار.", "translation": "Le dragon de l''histoire crache du feu."}]'::jsonb, null, '{"id": "ar.d.tinnin", "word": "تنين", "translation": "dragon", "partOfSpeech": "noun", "explanation": "Un dragon, comme celui qu''a vaincu saint Georges dans l''histoire que tout le monde raconte.", "examples": [{"text": "مارجرجس قتل التنين.", "translation": "Saint Georges a tué le dragon."}, {"text": "التنين في الحدوتة بينفخ نار.", "translation": "Le dragon de l''histoire crache du feu."}], "unitId": "ar.v.tinnin"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.bab', 'ar', 'باب', 'porte', 'La porte, d''une maison comme d''une église. Le ا ne s''attache pas au ب qui le suit : le mot se coupe en deux blocs.', '[{"text": "افتح الباب.", "translation": "Ouvre la porte."}, {"text": "باب الكنيسة كبير.", "translation": "La porte de l''église est grande."}]'::jsonb, null, '{"id": "ar.d.bab", "word": "باب", "translation": "porte", "partOfSpeech": "noun", "explanation": "La porte, d''une maison comme d''une église. Le ا ne s''attache pas au ب qui le suit : le mot se coupe en deux blocs.", "examples": [{"text": "افتح الباب.", "translation": "Ouvre la porte."}, {"text": "باب الكنيسة كبير.", "translation": "La porte de l''église est grande."}], "unitId": "ar.v.bab", "forms": {"plural": "أبواب"}}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.baba', 'ar', 'بابا', 'papa', 'Papa. Avec l''article, البابا désigne le Pape, chef de l''Église copte orthodoxe.', '[{"text": "بابا راجع من الشغل.", "translation": "Papa rentre du travail."}, {"text": "البابا راعي الكنيسة.", "translation": "Le Pape est le pasteur de l''Église."}]'::jsonb, null, '{"id": "ar.d.baba", "word": "بابا", "translation": "papa", "partOfSpeech": "noun", "explanation": "Papa. Avec l''article, البابا désigne le Pape, chef de l''Église copte orthodoxe.", "examples": [{"text": "بابا راجع من الشغل.", "translation": "Papa rentre du travail."}, {"text": "البابا راعي الكنيسة.", "translation": "Le Pape est le pasteur de l''Église."}], "unitId": "ar.v.baba"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ruzz', 'ar', 'رز', 'riz', 'Le riz, qui accompagne presque tous les repas égyptiens.', '[{"text": "الرز بالفراخ.", "translation": "Du riz au poulet."}, {"text": "عايز طبق رز.", "translation": "Je voudrais une assiette de riz."}]'::jsonb, null, '{"id": "ar.d.ruzz", "word": "رز", "translation": "riz", "partOfSpeech": "noun", "explanation": "Le riz, qui accompagne presque tous les repas égyptiens.", "examples": [{"text": "الرز بالفراخ.", "translation": "Du riz au poulet."}, {"text": "عايز طبق رز.", "translation": "Je voudrais une assiette de riz."}], "unitId": "ar.v.ruzz"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.zayt', 'ar', 'زيت', 'huile', 'L''huile, de cuisine ou d''olive. À l''église, on parle aussi d''huile sainte.', '[{"text": "زيت الزيتون.", "translation": "L''huile d''olive."}, {"text": "القنديل بيولع بالزيت.", "translation": "La lampe brûle à l''huile."}]'::jsonb, null, '{"id": "ar.d.zayt", "word": "زيت", "translation": "huile", "partOfSpeech": "noun", "explanation": "L''huile, de cuisine ou d''olive. À l''église, on parle aussi d''huile sainte.", "examples": [{"text": "زيت الزيتون.", "translation": "L''huile d''olive."}, {"text": "القنديل بيولع بالزيت.", "translation": "La lampe brûle à l''huile."}], "unitId": "ar.v.zayt"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ward', 'ar', 'ورد', 'fleurs', 'Les fleurs, les roses (une seule fleur : وردة).', '[{"text": "الورد ريحته حلوة.", "translation": "Les fleurs sentent bon."}, {"text": "جبت ورد لماما.", "translation": "J''ai apporté des fleurs à maman."}]'::jsonb, null, '{"id": "ar.d.ward", "word": "ورد", "translation": "fleurs", "partOfSpeech": "noun", "explanation": "Les fleurs, les roses (une seule fleur : وردة).", "examples": [{"text": "الورد ريحته حلوة.", "translation": "Les fleurs sentent bon."}, {"text": "جبت ورد لماما.", "translation": "J''ai apporté des fleurs à maman."}], "unitId": "ar.v.ward"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.dayr', 'ar', 'دير', 'monastère', 'Un monastère, comme celui d''Anba Bishoy à Wadi el-Natroun.', '[{"text": "دير الأنبا بيشوي في وادي النطرون.", "translation": "Le monastère d''Anba Bishoy est à Wadi el-Natroun."}, {"text": "رحنا الدير يوم الجمعة.", "translation": "Nous sommes allés au monastère vendredi."}]'::jsonb, null, '{"id": "ar.d.dayr", "word": "دير", "translation": "monastère", "partOfSpeech": "noun", "explanation": "Un monastère, comme celui d''Anba Bishoy à Wadi el-Natroun.", "examples": [{"text": "دير الأنبا بيشوي في وادي النطرون.", "translation": "Le monastère d''Anba Bishoy est à Wadi el-Natroun."}, {"text": "رحنا الدير يوم الجمعة.", "translation": "Nous sommes allés au monastère vendredi."}], "unitId": "ar.v.dayr", "forms": {"plural": "أديرة"}}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.abouna', 'ar', 'أبونا', 'notre père (le prêtre)', 'Notre père : c''est ainsi qu''on appelle un prêtre à l''église.', '[{"text": "أبونا بيصلي القداس.", "translation": "Le prêtre célèbre la liturgie."}, {"text": "صلي عشاني يا أبونا.", "translation": "Prie pour moi, mon père."}]'::jsonb, null, '{"id": "ar.d.abouna", "word": "أبونا", "translation": "notre père (le prêtre)", "partOfSpeech": "expression", "explanation": "Notre père : c''est ainsi qu''on appelle un prêtre à l''église.", "examples": [{"text": "أبونا بيصلي القداس.", "translation": "Le prêtre célèbre la liturgie."}, {"text": "صلي عشاني يا أبونا.", "translation": "Prie pour moi, mon père."}], "unitId": "ar.v.abouna"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.nabawat', 'ar', 'نبوات', 'prophéties', 'Les Prophéties : les lectures de l''Ancien Testament qu''on entend à l''église, surtout pendant la Semaine sainte.', '[{"text": "النبوات بتتقرا في الجمعة العظيمة.", "translation": "Les prophéties sont lues le Vendredi saint."}, {"text": "النبوات بتتكلم عن المسيح.", "translation": "Les prophéties parlent du Christ."}]'::jsonb, null, '{"id": "ar.d.nabawat", "word": "نبوات", "translation": "prophéties", "partOfSpeech": "noun", "explanation": "Les Prophéties : les lectures de l''Ancien Testament qu''on entend à l''église, surtout pendant la Semaine sainte.", "examples": [{"text": "النبوات بتتقرا في الجمعة العظيمة.", "translation": "Les prophéties sont lues le Vendredi saint."}, {"text": "النبوات بتتكلم عن المسيح.", "translation": "Les prophéties parlent du Christ."}], "unitId": "ar.v.nabawat"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.dhanb', 'ar', 'ذنب', 'faute', 'Une faute ; dans la prière, un péché. Le ذ est un د avec un point dessus.', '[{"text": "ده مش ذنبي.", "translation": "Ce n''est pas ma faute."}, {"text": "اغفر لنا ذنوبنا.", "translation": "Pardonne-nous nos fautes."}]'::jsonb, null, '{"id": "ar.d.dhanb", "word": "ذنب", "translation": "faute", "partOfSpeech": "noun", "explanation": "Une faute ; dans la prière, un péché. Le ذ est un د avec un point dessus.", "examples": [{"text": "ده مش ذنبي.", "translation": "Ce n''est pas ma faute."}, {"text": "اغفر لنا ذنوبنا.", "translation": "Pardonne-nous nos fautes."}], "unitId": "ar.v.dhanb", "otherTranslations": ["péché"]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.rabbina', 'ar', 'ربنا', 'notre Seigneur', 'Notre Seigneur : les Égyptiens disent ربنا pour parler de Dieu, tous les jours.', '[{"text": "ربنا يباركك.", "translation": "Que Dieu te bénisse."}, {"text": "ربنا كبير.", "translation": "Dieu est grand (ne t''inquiète pas)."}]'::jsonb, null, '{"id": "ar.d.rabbina", "word": "ربنا", "translation": "notre Seigneur", "partOfSpeech": "noun", "explanation": "Notre Seigneur : les Égyptiens disent ربنا pour parler de Dieu, tous les jours.", "examples": [{"text": "ربنا يباركك.", "translation": "Que Dieu te bénisse."}, {"text": "ربنا كبير.", "translation": "Dieu est grand (ne t''inquiète pas)."}], "unitId": "ar.v.rabbina", "otherTranslations": ["Dieu"]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.habibi', 'ar', 'حبيبي', 'mon chéri', 'Mot de tendresse qu''on dit à un ami, à un enfant, à un proche. Au féminin : حبيبتي. Le ي final veut dire « mon ».', '[{"text": "تعالى يا حبيبي.", "translation": "Viens, mon chéri."}, {"text": "إزيك يا حبيبي؟", "translation": "Comment vas-tu, mon cher ?"}]'::jsonb, null, '{"id": "ar.d.habibi", "word": "حبيبي", "translation": "mon chéri", "partOfSpeech": "expression", "explanation": "Mot de tendresse qu''on dit à un ami, à un enfant, à un proche. Au féminin : حبيبتي. Le ي final veut dire « mon ».", "examples": [{"text": "تعالى يا حبيبي.", "translation": "Viens, mon chéri."}, {"text": "إزيك يا حبيبي؟", "translation": "Comment vas-tu, mon cher ?"}], "unitId": "ar.v.habibi", "otherTranslations": ["mon cher"]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.khabar', 'ar', 'خبر', 'nouvelle', 'Une nouvelle, une information. Dans l''Église, la « bonne nouvelle », c''est l''Évangile.', '[{"text": "الخبر ده حلو.", "translation": "Cette nouvelle est bonne."}, {"text": "سمعت الخبر؟", "translation": "Tu as entendu la nouvelle ?"}]'::jsonb, null, '{"id": "ar.d.khabar", "word": "خبر", "translation": "nouvelle", "partOfSpeech": "noun", "explanation": "Une nouvelle, une information. Dans l''Église, la « bonne nouvelle », c''est l''Évangile.", "examples": [{"text": "الخبر ده حلو.", "translation": "Cette nouvelle est bonne."}, {"text": "سمعت الخبر؟", "translation": "Tu as entendu la nouvelle ?"}], "unitId": "ar.v.khabar", "forms": {"plural": "أخبار"}}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.jazar', 'ar', 'جزر', 'carottes', 'Les carottes, qu''on mange crues ou cuites.', '[{"text": "الجزر بيقوي النظر.", "translation": "Les carottes fortifient la vue."}, {"text": "عايز كيلو جزر.", "translation": "Je voudrais un kilo de carottes."}]'::jsonb, null, '{"id": "ar.d.jazar", "word": "جزر", "translation": "carottes", "partOfSpeech": "noun", "explanation": "Les carottes, qu''on mange crues ou cuites.", "examples": [{"text": "الجزر بيقوي النظر.", "translation": "Les carottes fortifient la vue."}, {"text": "عايز كيلو جزر.", "translation": "Je voudrais un kilo de carottes."}], "unitId": "ar.v.jazar"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.khawkh', 'ar', 'خوخ', 'pêches', 'Les pêches, fruit d''été très apprécié.', '[{"text": "الخوخ طعمه حلو.", "translation": "Les pêches sont délicieuses."}, {"text": "اشتريت خوخ من السوق.", "translation": "J''ai acheté des pêches au marché."}]'::jsonb, null, '{"id": "ar.d.khawkh", "word": "خوخ", "translation": "pêches", "partOfSpeech": "noun", "explanation": "Les pêches, fruit d''été très apprécié.", "examples": [{"text": "الخوخ طعمه حلو.", "translation": "Les pêches sont délicieuses."}, {"text": "اشتريت خوخ من السوق.", "translation": "J''ai acheté des pêches au marché."}], "unitId": "ar.v.khawkh"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.bakhur', 'ar', 'بخور', 'encens', 'L''encens qu''on fait monter pendant la prière à l''église.', '[{"text": "ريحة البخور في الكنيسة.", "translation": "L''odeur de l''encens dans l''église."}, {"text": "أبونا بيرفع البخور.", "translation": "Le prêtre fait monter l''encens."}]'::jsonb, null, '{"id": "ar.d.bakhur", "word": "بخور", "translation": "encens", "partOfSpeech": "noun", "explanation": "L''encens qu''on fait monter pendant la prière à l''église.", "examples": [{"text": "ريحة البخور في الكنيسة.", "translation": "L''odeur de l''encens dans l''église."}, {"text": "أبونا بيرفع البخور.", "translation": "Le prêtre fait monter l''encens."}], "unitId": "ar.v.bakhur"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.jayb', 'ar', 'جيب', 'poche', 'Une poche, de pantalon ou de veste.', '[{"text": "الموبايل في جيبي.", "translation": "Mon portable est dans ma poche."}, {"text": "الفلوس في الجيب.", "translation": "L''argent est dans la poche."}]'::jsonb, null, '{"id": "ar.d.jayb", "word": "جيب", "translation": "poche", "partOfSpeech": "noun", "explanation": "Une poche, de pantalon ou de veste.", "examples": [{"text": "الموبايل في جيبي.", "translation": "Mon portable est dans ma poche."}, {"text": "الفلوس في الجيب.", "translation": "L''argent est dans la poche."}], "unitId": "ar.v.jayb", "forms": {"plural": "جيوب"}}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.jiddu', 'ar', 'جدو', 'papy', 'Papy, le grand-père, comme les petits-enfants l''appellent.', '[{"text": "جدو بيحكي لنا حدوتة.", "translation": "Papy nous raconte une histoire."}, {"text": "رحنا نزور جدو.", "translation": "Nous sommes allés rendre visite à papy."}]'::jsonb, null, '{"id": "ar.d.jiddu", "word": "جدو", "translation": "papy", "partOfSpeech": "noun", "explanation": "Papy, le grand-père, comme les petits-enfants l''appellent.", "examples": [{"text": "جدو بيحكي لنا حدوتة.", "translation": "Papy nous raconte une histoire."}, {"text": "رحنا نزور جدو.", "translation": "Nous sommes allés rendre visite à papy."}], "unitId": "ar.v.jiddu", "otherTranslations": ["grand-père"]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.khud', 'ar', 'خد', 'prends', 'Prends ! (ordre adressé à un homme). Dans « خد بالك », il veut dire : fais attention.', '[{"text": "خد الكتاب ده.", "translation": "Prends ce livre."}, {"text": "خد بالك.", "translation": "Fais attention."}]'::jsonb, null, '{"id": "ar.d.khud", "word": "خد", "translation": "prends", "partOfSpeech": "verb", "explanation": "Prends ! (ordre adressé à un homme). Dans « خد بالك », il veut dire : fais attention.", "examples": [{"text": "خد الكتاب ده.", "translation": "Prends ce livre."}, {"text": "خد بالك.", "translation": "Fais attention."}], "unitId": "ar.v.khud", "confusions": [{"word": "حد", "note": "Même forme, mais حد n''a aucun point : il veut dire « quelqu''un »."}]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.hadd', 'ar', 'حد', 'quelqu''un', 'Quelqu''un, une personne. Dans une phrase négative, il veut dire « personne ».', '[{"text": "فيه حد هنا؟", "translation": "Il y a quelqu''un ici ?"}, {"text": "مفيش حد في البيت.", "translation": "Il n''y a personne à la maison."}]'::jsonb, null, '{"id": "ar.d.hadd", "word": "حد", "translation": "quelqu''un", "partOfSpeech": "pronoun", "explanation": "Quelqu''un, une personne. Dans une phrase négative, il veut dire « personne ».", "examples": [{"text": "فيه حد هنا؟", "translation": "Il y a quelqu''un ici ?"}, {"text": "مفيش حد في البيت.", "translation": "Il n''y a personne à la maison."}], "unitId": "ar.v.hadd", "confusions": [{"word": "خد", "note": "Même forme, mais خد a un point dessus : il veut dire « prends »."}]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.shay', 'ar', 'شاي', 'thé', 'Le thé, la boisson qu''on offre à chaque visite en Égypte.', '[{"text": "عايز كوباية شاي.", "translation": "Je voudrais un verre de thé."}, {"text": "الشاي بالنعناع.", "translation": "Le thé à la menthe."}]'::jsonb, null, '{"id": "ar.d.shay", "word": "شاي", "translation": "thé", "partOfSpeech": "noun", "explanation": "Le thé, la boisson qu''on offre à chaque visite en Égypte.", "examples": [{"text": "عايز كوباية شاي.", "translation": "Je voudrais un verre de thé."}, {"text": "الشاي بالنعناع.", "translation": "Le thé à la menthe."}], "unitId": "ar.v.shay"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.sabah', 'ar', 'صباح', 'matin', 'Le matin. On dit صباح الخير pour « bonjour » et on répond صباح النور.', '[{"text": "صباح الخير يا أبونا.", "translation": "Bonjour, mon père."}, {"text": "صباح النور.", "translation": "Bonjour ! (la réponse)"}]'::jsonb, null, '{"id": "ar.d.sabah", "word": "صباح", "translation": "matin", "partOfSpeech": "noun", "explanation": "Le matin. On dit صباح الخير pour « bonjour » et on répond صباح النور.", "examples": [{"text": "صباح الخير يا أبونا.", "translation": "Bonjour, mon père."}, {"text": "صباح النور.", "translation": "Bonjour ! (la réponse)"}], "unitId": "ar.v.sabah"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.abyad', 'ar', 'أبيض', 'blanc', 'Blanc, au masculin. Au féminin on dit بيضا.', '[{"text": "اللبن لونه أبيض.", "translation": "Le lait est blanc."}, {"text": "الشماس لابس أبيض.", "translation": "Le diacre est vêtu de blanc."}]'::jsonb, null, '{"id": "ar.d.abyad", "word": "أبيض", "translation": "blanc", "partOfSpeech": "adjective", "explanation": "Blanc, au masculin. Au féminin on dit بيضا.", "examples": [{"text": "اللبن لونه أبيض.", "translation": "Le lait est blanc."}, {"text": "الشماس لابس أبيض.", "translation": "Le diacre est vêtu de blanc."}], "unitId": "ar.v.abyad"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.hadir', 'ar', 'حاضر', 'entendu', 'Réponse typique : « entendu, tout de suite ! ». On la dit à ses parents, à son chef, à son prêtre.', '[{"text": "حاضر يا ماما.", "translation": "Entendu, maman."}, {"text": "حاضر، هعمله دلوقتي.", "translation": "Entendu, je le fais tout de suite."}]'::jsonb, null, '{"id": "ar.d.hadir", "word": "حاضر", "translation": "entendu", "partOfSpeech": "expression", "explanation": "Réponse typique : « entendu, tout de suite ! ». On la dit à ses parents, à son chef, à son prêtre.", "examples": [{"text": "حاضر يا ماما.", "translation": "Entendu, maman."}, {"text": "حاضر، هعمله دلوقتي.", "translation": "Entendu, je le fais tout de suite."}], "unitId": "ar.v.hadir"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.nuss', 'ar', 'نص', 'moitié', 'La moitié, ou « demi » : نص ساعة, une demi-heure.', '[{"text": "نص ساعة.", "translation": "Une demi-heure."}, {"text": "أكلت نص العيش.", "translation": "J''ai mangé la moitié du pain."}]'::jsonb, null, '{"id": "ar.d.nuss", "word": "نص", "translation": "moitié", "partOfSpeech": "noun", "explanation": "La moitié, ou « demi » : نص ساعة, une demi-heure.", "examples": [{"text": "نص ساعة.", "translation": "Une demi-heure."}, {"text": "أكلت نص العيش.", "translation": "J''ai mangé la moitié du pain."}], "unitId": "ar.v.nuss", "otherTranslations": ["demi"]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.sabt', 'ar', 'سبت', 'samedi', 'Samedi. Le Samedi de la Lumière (سبت النور) précède la fête de Pâques.', '[{"text": "السبت ده إجازة.", "translation": "Ce samedi est un jour de congé."}, {"text": "سبت النور قبل العيد.", "translation": "Le Samedi de la Lumière précède la fête."}]'::jsonb, null, '{"id": "ar.d.sabt", "word": "سبت", "translation": "samedi", "partOfSpeech": "noun", "explanation": "Samedi. Le Samedi de la Lumière (سبت النور) précède la fête de Pâques.", "examples": [{"text": "السبت ده إجازة.", "translation": "Ce samedi est un jour de congé."}, {"text": "سبت النور قبل العيد.", "translation": "Le Samedi de la Lumière précède la fête."}], "unitId": "ar.v.sabt"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.jaras', 'ar', 'جرس', 'cloche', 'Une cloche, ou une sonnette. Les cloches de l''église sonnent avant la liturgie.', '[{"text": "جرس الكنيسة بيرن.", "translation": "La cloche de l''église sonne."}, {"text": "سمعت الجرس.", "translation": "J''ai entendu la sonnette."}]'::jsonb, null, '{"id": "ar.d.jaras", "word": "جرس", "translation": "cloche", "partOfSpeech": "noun", "explanation": "Une cloche, ou une sonnette. Les cloches de l''église sonnent avant la liturgie.", "examples": [{"text": "جرس الكنيسة بيرن.", "translation": "La cloche de l''église sonne."}, {"text": "سمعت الجرس.", "translation": "J''ai entendu la sonnette."}], "unitId": "ar.v.jaras", "forms": {"plural": "أجراس"}}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.sayyad', 'ar', 'صياد', 'pêcheur', 'Un pêcheur. Les premiers disciples de Jésus étaient pêcheurs.', '[{"text": "الصياد رمى الشبكة.", "translation": "Le pêcheur a jeté le filet."}, {"text": "بطرس كان صياد.", "translation": "Pierre était pêcheur."}]'::jsonb, null, '{"id": "ar.d.sayyad", "word": "صياد", "translation": "pêcheur", "partOfSpeech": "noun", "explanation": "Un pêcheur. Les premiers disciples de Jésus étaient pêcheurs.", "examples": [{"text": "الصياد رمى الشبكة.", "translation": "Le pêcheur a jeté le filet."}, {"text": "بطرس كان صياد.", "translation": "Pierre était pêcheur."}], "unitId": "ar.v.sayyad"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.sirr', 'ar', 'سر', 'secret', 'Un secret ; dans l''Église, un sacrement (les sacrements s''appellent الأسرار).', '[{"text": "ما تقولش السر لحد.", "translation": "Ne dis le secret à personne."}, {"text": "المعمودية سر من أسرار الكنيسة.", "translation": "Le baptême est un sacrement de l''Église."}]'::jsonb, null, '{"id": "ar.d.sirr", "word": "سر", "translation": "secret", "partOfSpeech": "noun", "explanation": "Un secret ; dans l''Église, un sacrement (les sacrements s''appellent الأسرار).", "examples": [{"text": "ما تقولش السر لحد.", "translation": "Ne dis le secret à personne."}, {"text": "المعمودية سر من أسرار الكنيسة.", "translation": "Le baptême est un sacrement de l''Église."}], "unitId": "ar.v.sirr", "otherTranslations": ["sacrement"]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ahsan', 'ar', 'أحسن', 'mieux', 'Mieux, le meilleur. أحسن حاجة : la meilleure chose.', '[{"text": "أحسن حاجة إنك جيت.", "translation": "Le mieux, c''est que tu sois venu."}, {"text": "ده أحسن واحد.", "translation": "C''est le meilleur."}]'::jsonb, null, '{"id": "ar.d.ahsan", "word": "أحسن", "translation": "mieux", "partOfSpeech": "adjective", "explanation": "Mieux, le meilleur. أحسن حاجة : la meilleure chose.", "examples": [{"text": "أحسن حاجة إنك جيت.", "translation": "Le mieux, c''est que tu sois venu."}, {"text": "ده أحسن واحد.", "translation": "C''est le meilleur."}], "unitId": "ar.v.ahsan", "otherTranslations": ["le meilleur"]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.eish', 'ar', 'عيش', 'pain', 'Le pain. En Égypte, c''est le mot de tous les jours pour le pain ; le عيش البلدي est le pain plat traditionnel.', '[{"text": "عايز عيش وجبنة.", "translation": "Je voudrais du pain et du fromage."}, {"text": "العيش البلدي طعمه حلو.", "translation": "Le pain baladi est délicieux."}]'::jsonb, null, '{"id": "ar.d.eish", "word": "عيش", "translation": "pain", "partOfSpeech": "noun", "explanation": "Le pain. En Égypte, c''est le mot de tous les jours pour le pain ; le عيش البلدي est le pain plat traditionnel.", "examples": [{"text": "عايز عيش وجبنة.", "translation": "Je voudrais du pain et du fromage."}, {"text": "العيش البلدي طعمه حلو.", "translation": "Le pain baladi est délicieux."}], "unitId": "ar.v.eish"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ayiz', 'ar', 'عايز', 'je veux', 'Je veux, je voudrais (dit par un homme ; une femme dit عايزة). Selon qui parle, le même mot veut dire « tu veux » ou « il veut ».', '[{"text": "عايز مية.", "translation": "Je veux de l''eau."}, {"text": "إنت عايز إيه؟", "translation": "Tu veux quoi ?"}]'::jsonb, null, '{"id": "ar.d.ayiz", "word": "عايز", "translation": "je veux", "partOfSpeech": "verb", "explanation": "Je veux, je voudrais (dit par un homme ; une femme dit عايزة). Selon qui parle, le même mot veut dire « tu veux » ou « il veut ».", "examples": [{"text": "عايز مية.", "translation": "Je veux de l''eau."}, {"text": "إنت عايز إيه؟", "translation": "Tu veux quoi ?"}], "unitId": "ar.v.ayiz", "otherTranslations": ["tu veux", "il veut"]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.eid', 'ar', 'عيد', 'fête', 'Une fête, surtout religieuse : عيد الميلاد (Noël), عيد القيامة (Pâques).', '[{"text": "عيد القيامة أجمل عيد.", "translation": "Pâques est la plus belle fête."}, {"text": "كل سنة وإنت طيب في العيد.", "translation": "Bonne fête à toi !"}]'::jsonb, null, '{"id": "ar.d.eid", "word": "عيد", "translation": "fête", "partOfSpeech": "noun", "explanation": "Une fête, surtout religieuse : عيد الميلاد (Noël), عيد القيامة (Pâques).", "examples": [{"text": "عيد القيامة أجمل عيد.", "translation": "Pâques est la plus belle fête."}, {"text": "كل سنة وإنت طيب في العيد.", "translation": "Bonne fête à toi !"}], "unitId": "ar.v.eid", "forms": {"plural": "أعياد"}}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.jaan', 'ar', 'جعان', 'affamé', 'Qui a faim : أنا جعان, j''ai faim. Une femme dit جعانة.', '[{"text": "أنا جعان أوي.", "translation": "J''ai très faim."}, {"text": "إنتي جعانة؟", "translation": "Tu as faim ? (à une femme)"}]'::jsonb, null, '{"id": "ar.d.jaan", "word": "جعان", "translation": "affamé", "partOfSpeech": "adjective", "explanation": "Qui a faim : أنا جعان, j''ai faim. Une femme dit جعانة.", "examples": [{"text": "أنا جعان أوي.", "translation": "J''ai très faim."}, {"text": "إنتي جعانة؟", "translation": "Tu as faim ? (à une femme)"}], "unitId": "ar.v.jaan"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ghada', 'ar', 'غدا', 'déjeuner', 'Le déjeuner, le repas de midi. Pour dire « demain », on dit بكرة.', '[{"text": "الغدا جاهز.", "translation": "Le déjeuner est prêt."}, {"text": "بعد الغدا هنروح الكنيسة.", "translation": "Après le déjeuner, nous irons à l''église."}]'::jsonb, null, '{"id": "ar.d.ghada", "word": "غدا", "translation": "déjeuner", "partOfSpeech": "noun", "explanation": "Le déjeuner, le repas de midi. Pour dire « demain », on dit بكرة.", "examples": [{"text": "الغدا جاهز.", "translation": "Le déjeuner est prêt."}, {"text": "بعد الغدا هنروح الكنيسة.", "translation": "Après le déjeuner, nous irons à l''église."}], "unitId": "ar.v.ghada"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.ghani', 'ar', 'غني', 'riche', 'Riche. Sans son point, la première lettre serait ع.', '[{"text": "الراجل ده غني.", "translation": "Cet homme est riche."}, {"text": "الغني والفقير سوا قدام ربنا.", "translation": "Le riche et le pauvre sont égaux devant Dieu."}]'::jsonb, null, '{"id": "ar.d.ghani", "word": "غني", "translation": "riche", "partOfSpeech": "adjective", "explanation": "Riche. Sans son point, la première lettre serait ع.", "examples": [{"text": "الراجل ده غني.", "translation": "Cet homme est riche."}, {"text": "الغني والفقير سوا قدام ربنا.", "translation": "Le riche et le pauvre sont égaux devant Dieu."}], "unitId": "ar.v.ghani"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.tayyib', 'ar', 'طيب', 'bon', 'Bon, gentil ; en début de phrase, « d''accord, bon… ».', '[{"text": "إنت إنسان طيب.", "translation": "Tu es quelqu''un de bon."}, {"text": "طيب، هاجي بعد شوية.", "translation": "D''accord, je viens dans un moment."}]'::jsonb, null, '{"id": "ar.d.tayyib", "word": "طيب", "translation": "bon", "partOfSpeech": "adjective", "explanation": "Bon, gentil ; en début de phrase, « d''accord, bon… ».", "examples": [{"text": "إنت إنسان طيب.", "translation": "Tu es quelqu''un de bon."}, {"text": "طيب، هاجي بعد شوية.", "translation": "D''accord, je viens dans un moment."}], "unitId": "ar.v.tayyib", "otherTranslations": ["d''accord", "gentil"], "confusions": [{"word": "طير", "note": "طيب finit par ب (1 point dessous), طير par ر (aucun point)."}]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
