insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.yasou', 'ar', 'يسوع', 'Jésus', 'Jésus, le nom le plus important de l''Église.', '[{"text": "يسوع بيحبنا.", "translation": "Jésus nous aime."}, {"text": "اسم يسوع حلو.", "translation": "Le nom de Jésus est doux."}]'::jsonb, null, '{"id": "ar.d.yasou", "word": "يسوع", "translation": "Jésus", "partOfSpeech": "noun", "explanation": "Jésus, le nom le plus important de l''Église.", "examples": [{"text": "يسوع بيحبنا.", "translation": "Jésus nous aime."}, {"text": "اسم يسوع حلو.", "translation": "Le nom de Jésus est doux."}], "unitId": "ar.v.yasou"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.sukkar', 'ar', 'سكر', 'sucre', 'Le sucre, qu''on met dans le thé et dans le café.', '[{"text": "كوباية شاي بسكر.", "translation": "Un verre de thé avec du sucre."}, {"text": "ما تحطش سكر كتير.", "translation": "Ne mets pas trop de sucre."}]'::jsonb, null, '{"id": "ar.d.sukkar", "word": "سكر", "translation": "sucre", "partOfSpeech": "noun", "explanation": "Le sucre, qu''on met dans le thé et dans le café.", "examples": [{"text": "كوباية شاي بسكر.", "translation": "Un verre de thé avec du sucre."}, {"text": "ما تحطش سكر كتير.", "translation": "Ne mets pas trop de sucre."}], "unitId": "ar.v.sukkar"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.laban', 'ar', 'لبن', 'lait', 'Le lait.', '[{"text": "اللبن في التلاجة.", "translation": "Le lait est dans le frigo."}, {"text": "عايز كوباية لبن.", "translation": "Je voudrais un verre de lait."}]'::jsonb, null, '{"id": "ar.d.laban", "word": "لبن", "translation": "lait", "partOfSpeech": "noun", "explanation": "Le lait.", "examples": [{"text": "اللبن في التلاجة.", "translation": "Le lait est dans le frigo."}, {"text": "عايز كوباية لبن.", "translation": "Je voudrais un verre de lait."}], "unitId": "ar.v.laban"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.kursi', 'ar', 'كرسي', 'chaise', 'Une chaise, un siège.', '[{"text": "اقعد على الكرسي.", "translation": "Assieds-toi sur la chaise."}, {"text": "الكرسي ده مكسور.", "translation": "Cette chaise est cassée."}]'::jsonb, null, '{"id": "ar.d.kursi", "word": "كرسي", "translation": "chaise", "partOfSpeech": "noun", "explanation": "Une chaise, un siège.", "examples": [{"text": "اقعد على الكرسي.", "translation": "Assieds-toi sur la chaise."}, {"text": "الكرسي ده مكسور.", "translation": "Cette chaise est cassée."}], "unitId": "ar.v.kursi", "forms": {"plural": "كراسي"}}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.foul', 'ar', 'فول', 'fèves', 'Les fèves, plat national égyptien du petit-déjeuner, souvent mangé avec du pain. C''est aussi un plat classique des jours de jeûne.', '[{"text": "فول وطعمية.", "translation": "Du foul et des falafels."}, {"text": "الفول بالزيت والليمون.", "translation": "Les fèves à l''huile et au citron."}]'::jsonb, null, '{"id": "ar.d.foul", "word": "فول", "translation": "fèves", "partOfSpeech": "noun", "explanation": "Les fèves, plat national égyptien du petit-déjeuner, souvent mangé avec du pain. C''est aussi un plat classique des jours de jeûne.", "examples": [{"text": "فول وطعمية.", "translation": "Du foul et des falafels."}, {"text": "الفول بالزيت والليمون.", "translation": "Les fèves à l''huile et au citron."}], "unitId": "ar.v.foul"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.kitab', 'ar', 'كتاب', 'livre', 'Un livre. الكتاب المقدس, « le Livre saint », est la Bible.', '[{"text": "الكتاب المقدس.", "translation": "La Sainte Bible (le Livre saint)."}, {"text": "ده كتاب حلو.", "translation": "C''est un beau livre."}]'::jsonb, null, '{"id": "ar.d.kitab", "word": "كتاب", "translation": "livre", "partOfSpeech": "noun", "explanation": "Un livre. الكتاب المقدس, « le Livre saint », est la Bible.", "examples": [{"text": "الكتاب المقدس.", "translation": "La Sainte Bible (le Livre saint)."}, {"text": "ده كتاب حلو.", "translation": "C''est un beau livre."}], "unitId": "ar.v.kitab", "forms": {"plural": "كتب"}}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.qalb', 'ar', 'قلب', 'cœur', 'Le cœur, au sens propre et au sens figuré.', '[{"text": "بحبك من قلبي.", "translation": "Je t''aime de tout mon cœur."}, {"text": "ربنا يفرح قلبك.", "translation": "Que Dieu réjouisse ton cœur."}]'::jsonb, null, '{"id": "ar.d.qalb", "word": "قلب", "translation": "cœur", "partOfSpeech": "noun", "explanation": "Le cœur, au sens propre et au sens figuré.", "examples": [{"text": "بحبك من قلبي.", "translation": "Je t''aime de tout mon cœur."}, {"text": "ربنا يفرح قلبك.", "translation": "Que Dieu réjouisse ton cœur."}], "unitId": "ar.v.qalb", "forms": {"plural": "قلوب"}}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.quddas', 'ar', 'قداس', 'liturgie', 'La liturgie, la messe copte : la grande prière du dimanche, avec la communion.', '[{"text": "رحنا القداس يوم الأحد.", "translation": "Nous sommes allés à la liturgie dimanche."}, {"text": "القداس بيبدأ بدري.", "translation": "La liturgie commence tôt."}]'::jsonb, null, '{"id": "ar.d.quddas", "word": "قداس", "translation": "liturgie", "partOfSpeech": "noun", "explanation": "La liturgie, la messe copte : la grande prière du dimanche, avec la communion.", "examples": [{"text": "رحنا القداس يوم الأحد.", "translation": "Nous sommes allés à la liturgie dimanche."}, {"text": "القداس بيبدأ بدري.", "translation": "La liturgie commence tôt."}], "unitId": "ar.v.quddas", "otherTranslations": ["messe"]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.qurban', 'ar', 'قربان', 'pain d''offrande', 'Le pain de l''offrande, préparé à l''église pour la liturgie ; القربان المقدس désigne la communion.', '[{"text": "القربان بيتعمل في الكنيسة.", "translation": "Le pain d''offrande est préparé à l''église."}, {"text": "الشعب بيتناول القربان.", "translation": "Les fidèles reçoivent la communion."}]'::jsonb, null, '{"id": "ar.d.qurban", "word": "قربان", "translation": "pain d''offrande", "partOfSpeech": "noun", "explanation": "Le pain de l''offrande, préparé à l''église pour la liturgie ; القربان المقدس désigne la communion.", "examples": [{"text": "القربان بيتعمل في الكنيسة.", "translation": "Le pain d''offrande est préparé à l''église."}, {"text": "الشعب بيتناول القربان.", "translation": "Les fidèles reçoivent la communion."}], "unitId": "ar.v.qurban", "otherTranslations": ["offrande"]}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
