insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('ar.d.amin', 'ar', 'آمين', 'amen', 'Amen : « qu''il en soit ainsi », la réponse de tout le peuple à la fin d''une prière.', '[{"text": "آمين، ربنا يسمعك.", "translation": "Amen, que Dieu t''exauce."}, {"text": "بنقول آمين بعد الصلاة.", "translation": "Nous disons amen après la prière."}]'::jsonb, null, '{"id": "ar.d.amin", "word": "آمين", "translation": "amen", "partOfSpeech": "interjection", "explanation": "Amen : « qu''il en soit ainsi », la réponse de tout le peuple à la fin d''une prière.", "examples": [{"text": "آمين، ربنا يسمعك.", "translation": "Amen, que Dieu t''exauce."}, {"text": "بنقول آمين بعد الصلاة.", "translation": "Nous disons amen après la prière."}], "unitId": "ar.v.amin"}'::jsonb, '3.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
